local E = ns.DB.entries
E["item:barrow-key"] = {t="item",n="Barrow Key",z="stonetalon",s="The Barrow Key is one of three druidic keys hidden within the Talon Den atop Stonetalon Peak. It is kept locked inside a barrow cache to guard the ancient treasures sealed within the den's hoard.",h="The Barrow Key is one of three druidic keys hidden within the Talon Den atop Stonetalon Peak.",sec={{t="A Guardian's Safeguard",b="Within the subterranean barrows of the Talon Den, night elf druids established elaborate wards to protect their relics from interlopers. The Barrow Key is one piece of this multi-layered lock, concealed inside a specialized cache hidden among the subterranean passages. Accessing it requires the Gatekeeper's Key, ensuring that only those with knowledge of the druids' defensive network can ever hope to claim it.",sp=0},{t="Unlocking the Hoard",b="Together with the Claw Key and the Sleepers' Key, the Barrow Key corresponds to three intricately carved keyholes set into a stone altar deep in the Talon Den. When all three are turned in unison, the protective enchantments dispel, revealing the hidden hoard of druidic relics to whoever manages to crack the ward.",sp=1}},faq={{q="What is the Barrow Key used for?",a="The Barrow Key is used alongside the Claw Key and the Sleepers' Key to unlock the Talon Den Hoard, a stone chest holding protected druidic relics deep within Stonetalon Peak.",al={"barrow key purpose","what does barrow key open","use of barrow key"},it="purpose"},{q="Where is the Barrow Key hidden?",a="It is locked inside a barrow cache—resembling a concealed wall torch—located deep within the winding tunnels of the Talon Den on Stonetalon Peak.",al={"barrow key location","where is barrow key","find barrow key"},it="place",gp=true},{q="How do you open the cache containing the Barrow Key?",a="You must first retrieve the Gatekeeper's Key, which the druids concealed inside a small lantern near the main entrance of the Talon Den.",al={"open barrow cache","unlock barrow key","gatekeeper key barrow"},it="item",gp=true},{q="Who hidden the Barrow Key in the Talon Den?",a="The night elf druids residing in Stonetalon Peak devised the elaborate security system to keep their powerful artifacts out of hostile hands, concealing individual keys across different corners of the den.",al={"who made barrow key","who hid the keys in talon den"},it="origin"},{q="What is the Barrow Key?",a="The Barrow Key is one of three enchanted keys fashioned by the night elf druids within the Talon Den atop Stonetalon Peak. It serves as part of an intricate security ward designed to protect their most prized and powerful relics from falling into enemy hands.",al={"what is barrow key","barrow key info","talon den barrow key"},it="identity",add=true},{q="Why does anyone want the Barrow Key?",a="Horde forces in the Stonetalon Mountains seek the Barrow Key alongside its sister keys, the Claw Key and the Sleepers' Key. Together, the three keys break the druidic wards sealing the Talon Den Hoard, unlocking the cache of powerful items preserved deep inside the barrow.",al={"why find barrow key","why want barrow key","who wants the barrow key"},it="why_wanted",add=true}},ang={["class:Druid"]="The key is part of an ancient security rite designed by the druids of the Talon Den to safeguard sacred belongings within their underground sanctuary.",["faction:Horde"]="Horde operatives in Stonetalon Mountains pry information from captured night elves to locate this key and plunder the druids' private hoard."},kw={"barrow key","claw key","gatekeeper's key","sleepers' key","stonetalon peak","talon den","talon den hoard","the den"},rel={"quest:1089","item:claw-key","item:sleepers-key","subzone:stonetalon-peak","zone:stonetalon","topic:druid","quest:1088","quest:1087"},src={"Barrow Key","The Den (quest)"}}
E["item:besseleth-s-fang"] = {t="item",n="Besseleth's Fang",z="stonetalon",s="Besseleth's Fang is the massive venomous tooth harvested from the giant spider Besseleth in Sishir Canyon. Carried as proof of her demise, it represents the removal of a deadly threat stalking the trails of Stonetalon Mountains.",h="Besseleth's Fang is the massive venomous tooth harvested from the giant spider Besseleth in Sishir Canyon.",sec={{t="Trophy of the Canyon Stalker",b="Sishir Canyon has long been infested by aggressive arachnids, but none strike more terror into travelers than Besseleth. Growing to monstrous proportions, she and her brood turned the gorge into a death trap for wanderers navigating the Webwinder Path at night. The fang itself measures nearly two feet in length and drips with potent venom, making it an unmistakable signature of the broodmother's slaughter. Presenting this grisly trophy brings relief to local defenders who have suffered her venomous strikes.",sp=0}},faq={{q="What is Besseleth's Fang used for?",a="The fang serves as physical proof that the spider matriarch Besseleth has been slain. Maggran Earthbinder at Sun Rock Retreat placed a bounty on the beast after surviving a near-fatal attack by her fangs, and he rewards anyone who brings the trophy to him.",al={"besseleth fang purpose","who wants besseleth's fang","fang turn in"},it="item",gp=true},{q="Where does this fang come from?",a="The fang is harvested directly from Besseleth, a giant predatory spider dwelling inside Sishir Canyon, located west of the main road south of Windshear Crag in the Stonetalon Mountains.",al={"how to get besseleth fang","where is besseleth","besseleth location"},it="origin"},{q="Why did Maggran Earthbinder want Besseleth dead?",a="Besseleth and her brood regularly prey upon travelers heading along the roads toward Sun Rock Retreat, especially under cover of night. Maggran Earthbinder was personally ambushed and wounded by her fangs, prompting him to issue a bounty to secure the trails.",al={"why kill besseleth","maggran bounty spider","why bounty on besseleth"},it="motive"},{q="Who posted the bounty for the fang?",a="The bounty was authorized by Maggran Earthbinder and posted on a wanted sign situated along the main roadway south of the Windshear Crag fork, warning passing travelers of Sishir Canyon's hazards.",al={"wanted poster stonetalon spider","arachnophobia quest giver"},it="why_wanted"},{q="What is Besseleth's Fang?",a="Besseleth's Fang is a massive, two-foot tooth taken from the predatory spider Besseleth. She and her brood stalk Sishir Canyon and prey upon travelers along the Webwinder Path at night. The fang serves as undeniable physical proof that the feared arachnid terrorizing the trails of Stonetalon has finally been slain.",al={"what is besseleths fang","besseleth tooth","fang of besseleth"},it="identity",add=true}},ang={["faction:Horde"]="Clearing out the canyon spider helps safeguard the precarious mountain trails connecting the Barrens border with Sun Rock Retreat.",["class:Hunter"]="Harvesting the two-foot venomous tooth of an apex arachnid matriarch serves as an undisputed testament to a hunter's tracking and combat prowess."},kw={"arachnophobia","besseleth","besseleth's fang","maggran earthbinder","sishir canyon","stonetalon mountains","sun rock retreat","webwinder path"},rel={"quest:6284","npc:maggran-earthbinder","subzone:sishir-canyon","subzone:sun-rock-retreat","subzone:webwinder-path","zone:stonetalon","subzone:windshear-crag"},src={"Besseleth's Fang","Arachnophobia (quest)"}}
E["item:bloodfury-ripper-s-remains"] = {t="item",n="Bloodfury Ripper's Remains",z="stonetalon",s="Bloodfury Ripper's Remains are the physical proof recovered from the matriarch of the Bloodfury harpies in the Charred Vale. Sought by Maggran Earthbinder at Sun Rock Retreat, this trophy confirms the death of the brood's ferocious leader, dealing a decisive blow to the harpy presence threatening the local tauren settlement.",h="Bloodfury Ripper's Remains are the physical proof recovered from the matriarch of the Bloodfury harpies in...",sec={{t="Severing the Bloodline",b="The Bloodfury harpies nesting within the scorched ruins of the Charred Vale have long posed a savage threat to the travelers and shamans of the Stonetalon Mountains. While culling their numbers thins the immediate danger, Maggran Earthbinder of Sun Rock Retreat recognizes that true reprieve requires eliminating their leadership. Bloodfury Ripper rules her flock almost as a queen, guiding their territorial aggression. Taking her remains is essential proof of her demise, scattering the remaining harpies into disarray and granting peace of mind to the tauren striving to heal and secure their rugged lands.",sp=0}},faq={{q="What are Bloodfury Ripper's Remains used for?",a="They serve as undeniable physical proof of the death of Bloodfury Ripper. Maggran Earthbinder at Sun Rock Retreat requests them to confirm that the queen-like leader of the local harpies has been permanently removed.",al={"what do remains do","remains purpose","who wants the remains"},it="item",gp=true},{q="Where can Bloodfury Ripper be found?",a="Bloodfury Ripper prowls the western and northwestern hill lines of the Charred Vale in southern Stonetalon Mountains, distinguished from her crimson-and-white flock by her distinct blue plumage.",al={"bloodfury ripper location","where is ripper","find bloodfury ripper"},it="target",gp=true},{q="Why does Maggran Earthbinder want her dead?",a="Maggran believes that merely culling ordinary harpies will never stop their raids on the surrounding lands. Slaying their matriarch breaks their hierarchy and diminishes their ability to rally against Sun Rock Retreat.",al={"why kill bloodfury ripper","maggran motivation","why ripper dead"},it="motive"},{q="What are Bloodfury Ripper's Remains?",a="These gruesome remains are the physical proof taken from the body of Bloodfury Ripper, the matriarch and leader of the Bloodfury harpies infesting the Charred Vale. She acts almost as a queen to her flock, guiding their aggressive spread across Stonetalon. Her slain body serves as undeniable evidence that her reign over the vale's harpies has been brought to a bloody end.",al={"what are bloodfury ripper's remains","bloodfury ripper remains what is this","who is bloodfury ripper"},it="identity",add=true},{q="Where do Bloodfury Ripper's Remains come from?",a="These remains are carved from Bloodfury Ripper herself after slaying her among the western hills of the Charred Vale. Unlike her red and white kin, this distinctive blue-feathered harpy leads the Bloodfury brood from the vale's desolate cliffs, making her a prized target for anyone seeking to break the flock's command.",al={"where do bloodfury rippers remains come from","who drops bloodfury rippers remains","bloodfury rippers remains origin"},it="origin",add=true},{q="Why does Maggran Earthbinder want Bloodfury Ripper's Remains?",a="Maggran Earthbinder at Sun Rock Retreat demands these remains as proof that the Bloodfury harpies' matriarch is truly dead. Simply culling their numbers was never going to suffice; Maggran believes striking down their queen will leave the surviving harpies helpless and cause their numbers to wither away, freeing him from the bitter anger that consumed his thoughts.",al={"why does maggran want bloodfury rippers remains","why are bloodfury rippers remains wanted","who wants bloodfury ripper's remains"},it="why_wanted",add=true}},ang={["race:Tauren"]="The Bloodfury harpies directly threaten the safety of Sun Rock Retreat, making the collection of their leader's remains an act of devotion toward protecting peaceful tauren settlements in Stonetalon.",["faction:Horde"]="Clearing out wild perils like the Bloodfury matriarch ensures safe passage for Horde caravans and scouts moving between the Barrens and Stonetalon."},kw={"bloodfury ripper","charred vale","harpies","maggran earthbinder","remains","stonetalon","sun rock retreat"},rel={"quest:6283","quest:6282","npc:maggran-earthbinder","subzone:charred-vale","subzone:sun-rock-retreat","zone:stonetalon","topic:tauren"},src={"Bloodfury Ripper's Remains","Bloodfury Bloodline"}}
E["item:claw-key"] = {t="item",n="Claw Key",z="stonetalon",s="The Claw Key is one of three druidic keys hidden within the Talon Den atop Stonetalon Peak. Alongside the Barrow Key and Sleepers' Key, it is required to unlock the enchanted Talon Den Hoard.",h="The Claw Key is one of three druidic keys hidden within the Talon Den atop Stonetalon Peak.",sec={{t="Wards of the Talon Den",b="The night elf druids established the Talon Den high upon Stonetalon Peak as a sanctuary and repository for powerful relics. To ensure these treasures remained safe from trespassers, they hid them behind a layered security system. The hoard itself is sealed by three distinct enchanted locks: the Barrow Key, the Sleepers' Key, and the Claw Key. Each key is concealed inside a specialized druidic cache resembling a torch within the winding tunnels of the barrow den.",sp=0},{t="Breaching the Caches",b="The druids did not leave the keys unguarded or freely accessible. Opening the cache that holds the Claw Key requires first acquiring the Gatekeeper's Key, which is tucked away near the barrow entrance. Once retrieved, the Claw Key serves as a vital component in breaking the druids' seal and claiming the riches hidden deep within the mountain.",sp=0}},faq={{q="What is the Claw Key used for?",a="The Claw Key is one of three keys needed to unlock the Talon Den Hoard, a warded stone chest resting in the heart of the Talon Den on Stonetalon Peak.",al={"claw key purpose","what does claw key open","talon den hoard key"},it="purpose",gp=true},{q="Where can the Claw Key be found?",a="It is stashed inside a druid cache disguised as a torch within the Talon Den tunnels on Stonetalon Peak. Opening the cache requires the Gatekeeper's Key from the den entrance.",al={"claw key location","where is claw key","find claw key"},it="place",gp=true},{q="What other keys are needed alongside the Claw Key?",a="To unlock the Talon Den Hoard, you must collect the Claw Key, the Barrow Key, and the Sleepers' Key, all found in separate caches throughout the den.",al={"other keys","talon den keys","keys for the den"},gp=true},{q="Why did the druids hide these keys?",a="The night elf druids constructed the Talon Den to store powerful relics away from prying eyes, using a complex system of keys and concealed caches to deter intruders.",al={"why are keys hidden","talon den lore"},it="motive"},{q="What is the Claw Key?",a="The Claw Key is one of three enchanted keys crafted by the night elf druids of Stonetalon Peak. Locked away within a concealed cache inside the subterranean Talon Den, it forms an integral part of an intricate security ward designed to protect their most valued treasures from intrusion.",al={"what is claw key","claw key info","what kind of key is claw key"},it="identity",add=true},{q="Where does the Claw Key come from, and who made it?",a="The key was fashioned by the druids who established the Talon Den high upon Stonetalon Peak. To safeguard their relics, they created this key alongside the Barrow and Sleepers' keys, locking it inside a ward cache that requires the Gatekeeper's Key to open.",al={"who made claw key","claw key origin","where did claw key come from"},it="origin",add=true},{q="Why does anyone want the Claw Key?",a="The Claw Key is sought because it is required to breach the Talon Den Hoard. The druids locked away many powerful artifacts inside the cavern's depths behind three specialized keyholes, ensuring that only someone who gathers all three keys can claim the hoard's concealed relics.",al={"why find claw key","why get claw key","claw key purpose lore"},it="why_wanted",add=true}},ang={["faction:Horde"]="Interrogating captured night elves allows the Horde to bypass the druids' ancient defenses and pillage the sacred artifacts stored atop Stonetalon Peak.",["class:Druid"]="Named after the iconic Druids of the Claw, this key reflects the sacred traditions and protective wards crafted by night elf barrow dwellers."},kw={"barrow den","claw key","druids' cache","gatekeeper's key","stonetalon peak","talon den","talon den hoard","the den"},rel={"quest:1089","item:barrow-key","item:sleepers-key","subzone:stonetalon-peak","zone:stonetalon","quest:1088","quest:1087","topic:druid"},src={"Claw Key","The Den (quest)"}}
E["item:corroded-shrapnel"] = {t="item",n="Corroded Shrapnel",z="stonetalon",s="Corroded Shrapnel consists of jagged metal fragments lodged deep within the corrupted treants of the Stonetalon Mountains. Recovered from fallen protectors like Charred and Blackened Ancients, this debris provides physical evidence of the foul weaponry used by the Venture Company during their retreat.",h="Corroded Shrapnel consists of jagged metal fragments lodged deep within the corrupted treants of the...",sec={{t="Remnants of Industrial Ruin",b="When the Venture Company was driven back from the groves of Stonetalon, the goblins unleashed brutal, reckless munitions to cover their escape. Shrapnel from these explosive weapons tore into the valley's defending treants, embedding jagged metal deep within their bark and core. Rather than healing, the ancient guardians slowly fell to corruption, their wood blackening and their fury turning upon anyone who stepped into the vale. The rusted, tainted fragments recovered from these wounded protectors are sought by Kaela Shadowspear so the gnome Gaxim Rustfizzle can analyze the exact mechanisms of the corruption.",sp=0}},faq={{q="Where does this shrapnel come from?",a="Corroded Shrapnel is salvaged from the bodies of corrupted treants in Stonetalon Mountains, including Charred Ancients, Blackened Ancients, and Vengeful Ancients.",al={"where do i find shrapnel","corroded shrapnel drop","who drops shrapnel"},it="origin"},{q="Why is the shrapnel embedded in the treants?",a="The Venture Company fired explosive, jagged munitions at the treants when the forest guardians rose up to drive the goblin loggers out of the vale. The metal shards lodged into their bark during the battle and never came out.",al={"how did shrapnel get in treants","why are treants full of metal"}},{q="Is the shrapnel responsible for corrupting the forest ancients?",a="According to Kaela Shadowspear, the gnome Gaxim believes the corruption sickening the treants is directly tied to the foul chemical or metallic composition of the weapons used by the retreating goblins.",al={"did shrapnel corrupt treants","why are treants mad"}},{q="Who wants to inspect the shrapnel?",a="The night elf Kaela Shadowspear asks for a sample so she can pass it along to the gnome inventor Gaxim, who intends to study its properties to uncover the nature of the treants' affliction.",al={"who needs the shrapnel","shrapnel turn in"},it="why_wanted"},{q="What is Corroded Shrapnel?",a="Corroded Shrapnel consists of jagged metal fragments left behind from goblin weaponry. Embedded deep inside the scarred bark of Stonetalon's treants, these degraded, rusted bits of explosive munitions are thought to carry a lingering poison or foul taint that afflicts the forest's protectors.",al={"what is corroded shrapnel","corroded shrapnel lore","corroded shrapnel item"},it="identity",add=true}},ang={["class:Druid"]="Seeing the majestic ancients of Kalimdor warped by industrial goblin munitions and festering metal shards is a sharp reminder of the toll unchecked exploitation takes on the wild.",["race:Gnome"]="Gaxim's pursuit of the tainted shrapnel shows the practical, scientific approach gnomes take toward solving ecological anomalies that baffle traditional woodland sentinels."},kw={"charred ancient","corroded shrapnel","gaxim","kaela shadowspear","stonetalon","treant","venture co"},rel={"quest:1084","npc:kaela-shadowspear","zone:stonetalon","quest:764","topic:goblin","topic:gnome"},src={"Corroded Shrapnel","Wounded Ancients"}}
E["item:courser-eye"] = {t="item",n="Courser Eye",z="stonetalon",s="Courser Eyes are biological reagents harvested from the antlered coursers roaming the highlands of Stonetalon Mountains. Witch Doctor Jin'Zil in Malaka'jin seeks a large quantity of them to prepare a concoction he mockingly refers to as forest magic.",h="Courser Eyes are biological reagents harvested from the antlered coursers roaming the highlands of Stonetalon...",sec={{t="A Troll's Concoction",b="In the remote outpost of Malaka'jin, Witch Doctor Jin'Zil concocts various tribal mixtures to deal with the night elves contesting the region. While stag eyes are not an uncommon component in voodoo and folk alchemy, Jin'Zil demands thirty courser eyes at once—far more than typical spellcraft requires. Blended with fey dragon scales, sap, and feline whiskers, the eyes serve as a base for a lethal brew intended for the night elf prisoners locked in cages at the back of his den.",sp=1}},faq={{q="Where are courser eyes found?",a="They are harvested from the various coursers—both Antlered Coursers and Great Coursers—native to the higher altitudes of the Stonetalon Mountains, particularly around Mirkfallon Lake and Stonetalon Peak.",al={"courser eye locations","where to get courser eye","how to get courser eye"},it="place",gp=true},{q="Why does Witch Doctor Jin'Zil need so many eyes?",a="Jin'Zil claims that one can never have enough eyes when preparing a proper brew. He combines them with native fauna parts to brew a potent concoction that he unleashes upon his captured night elf prisoners.",al={"why 30 eyes","why does jinzil need eyes","what does jinzil do with courser eyes"},sp=1,it="why_wanted"},{q="What happens when Jin'Zil completes his forest magic potion?",a="Once the courser eyes and other ingredients are delivered, Jin'Zil releases the toxic brew inside his cave. The concoction lethally poisons the caged night elf prisoners, whose spirits rise as wisps and depart into the wild.",al={"jinzil forest magic result","what happens to the prisoners in malakajin"},sp=1,it="power"},{q="What is a Courser Eye?",a="A Courser Eye is an alchemical reagent harvested from the native stag-like coursers roaming the Stonetalon Mountains. To most woodland inhabitants, they are merely part of the local wildlife, but in the hands of a cunning practitioner, these numerous eyes serve as a raw ingredient for potent concoctions.",al={"what is courser eye","courser eye item","what are courser eyes"},it="identity",add=true},{q="Where does a Courser Eye come from?",a="These eyes are gathered directly from the antlered coursers and great coursers that graze across the Stonetalon Mountains, particularly around Mirkfallon Lake and near Stonetalon Peak. They are natural parts taken from the mountain's wild beasts rather than crafted or enchanted artifacts.",al={"where do courser eyes come from","who made courser eye","courser eye origin"},it="origin",add=true}},ang={["race:Troll"]="Witch Doctor Jin'Zil's crude application of animal components reflects the darker, practical side of troll alchemy and mojo craft used against enemies of the Horde.",["race:NightElf"]="Slaughtering the sacred coursers of Stonetalon simply to poison captured Sentinels is considered a profound sacrilege against Elune and nature."},kw={"antlered courser","courser eye","forest magic","great courser","jin'zil","malaka'jin","stonetalon"},rel={"npc:witch-doctor-jin-zil","quest:1058","item:fey-dragon-scale","item:stonetalon-sap","item:twilight-whisker","subzone:malaka-jin","subzone:mirkfallon-lake","zone:stonetalon"},src={"Courser Eye","Jin'Zil's Forest Magic"}}
E["item:covert-ops-pack"] = {t="item",n="Covert Ops Pack",z="stonetalon",s="The Covert Ops Pack is a kit of specialized demolitions gear and operational schematics assembled for Alliance espionage in the Stonetalon Mountains. Designed to dismantle the Venture Company's rapacious presence in Windshear Crag, the satchel equips agents to trigger coordinated sabotage while securing high-value technical intelligence.",h="The Covert Ops Pack is a kit of specialized demolitions gear and operational schematics assembled for...",sec={{t="Sabotage by Design",b="Issued for clandestine strikes deep within Venture Company territory, the Covert Ops Pack pairs brute destructive power with tactical precision. Inside are color-coded NG-5 explosives matched to remote triggers, alongside thorough instructions designated Plan Alpha and Plan Beta. The strategy relies on triggering high-yield distractions at key infrastructure nodes—namely the Cragpool Lake lumber mill and the eastern mine. While goblins scramble to extinguish blazes and assess mechanical failures, an infiltrator slips past the chaos to pilfer critical documents and schematics.",sp=0},{t="A Confluence of Interests",b="The contents of the pack serve a dual purpose for the Alliance in Stonetalon. For the night elf Sentinels, the detonations and theft disrupt the merciless clear-cutting and gouging of the sacred mountainside. For Alliance tinkers, the primary reward lies in the documents themselves. Recovering Venture Company engineering schematics offers rare insights into goblin heavy machinery, revealing mechanical weak points to exploit and allowing Alliance engineers to adapt industrial innovations into their own designs.",sp=0}},faq={{q="What is inside the Covert Ops Pack?",a="The pack contains two pairs of colored demolition charges: red and blue NG-5 explosives with their matching remote detonators. It also holds written mission briefings detailing Plan Alpha and Plan Beta.",al={"covert ops pack contents","what does the pack contain","items in covert ops pack"},it="item"},{q="What is the tactical purpose of the explosives?",a="The NG-5 explosives are planted at Venture Company work sites to create loud, violent distractions. They are not intended as the end goal itself, but rather to draw security away so an operative can infiltrate the lumber mill and the mine undetected.",al={"why use bombs","what are ng-5 explosives for","alpha beta demolition"},it="purpose"},{q="What intelligence does this operation target?",a="The mission targets Venture Company engineering plans from the lumber mill south of Cragpool Lake, followed by executive letters kept inside the Windshear Mine at the eastern end of the crag.",al={"what do we steal","pack mission objective","covert ops goals"},it="target"},{q="Who benefits from the materials recovered using this pack?",a="Both the night elf Sentinels guarding Stonetalon and Alliance engineers benefit. The Sentinels see the deforestation effort crippled, while Alliance artificers study the captured schematics to pinpoint flaws in Venture Company shredders and harvest ideas for their own technology.",al={"who wants the venture plans","who is the pack for","sentinels covert ops"},it="ties"},{q="What is the Covert Ops Pack?",a="The Covert Ops Pack is a specialized sabotage kit prepared for infiltration operations in Windshear Crag. It contains color-coded NG-5 explosives, matching remote detonators, and detailed mission plans designed to stage timed distractions while crucial Venture Company documents are retrieved under their noses.",al={"what is covert ops pack","covert ops pack info","covert ops kit"},it="identity",add=true},{q="Where does the Covert Ops Pack come from, and who made it?",a="The pack is assembled by an Alliance tinkerer assisting the night elf Sentinels in Stonetalon Mountains. Combining precision engineering with tactical demolition, they crafted the volatile NG-5 charges and remote triggers specifically to aid operative strikes against Venture Company installations.",al={"who made covert ops pack","where did covert ops pack come from","covert ops pack creator"},it="origin",add=true},{q="Why is the Covert Ops Pack needed?",a="Directly assaulting fortified Venture Company sites like their lumber mill and mine would be suicidal or alert guards before vital intelligence can be seized. The pack provides the tools to plant remote explosives and trigger controlled chaos elsewhere, drawing defenders away so you can slip inside and recover their engineering plans and correspondence.",al={"why do i need covert ops pack","why covert ops pack","covert ops pack purpose"},it="why_wanted",add=true}},ang={["profession:Engineering"]="The pack represents fine gnomish ingenuity turned against goblin industry, utilizing customized NG-5 charges to uncover the secrets behind Venture Company machinery.",["faction:Alliance"]="The covert operation orchestrated with this pack directly supports the Sentinels' struggle against commercial despoilment in the Stonetalon Mountains."},kw={"covert ops pack","cragpool lake","ng-5 explosives","plan alpha","plan beta","venture co","windshear crag"},rel={"quest:1079","quest:1080","item:ng-5","item:venture-co-engineering-plans","item:venture-co-letters","subzone:windshear-crag","topic:sentinels","zone:stonetalon"},src={"Covert Ops Pack","Covert Ops - Alpha","Covert Ops - Beta"}}
E["item:crystalized-scales"] = {t="item",n="Crystalized Scales",z="stonetalon",s="Crystalized Scales are the hardened, mineralized hides harvested from basilisks dwelling in harsh Kalimdor environments such as the Charred Vale and Thousand Needles. When ground into a fine powder, these unusual scales serve as an exotic magical reagent coveted by spellcasters in Stormwind.",h="Crystalized Scales are the hardened, mineralized hides harvested from basilisks dwelling in harsh Kalimdor...",sec={{t="A Rare Kalimdor Reagent",b="Basilisks that endure extreme environmental heat and ash—particularly those dwelling within Stonetalon's Charred Vale or the shimmering salt flats of Thousand Needles—develop rigid, crystal-encrusted hides. These crystalized scales possess latent arcane resonance, making them exceptionally valuable to scholarly wizards across the Great Sea who experiment with rare spellcraft.",sp=0},{t="Mauren's Arcane Work",b="In the human kingdom of Stormwind, the mage Collin Mauren actively seeks out adventurers journeying into the Kalimdor frontier to secure these scales. By pulverizing the crystalline mineral layers into dust, Mauren utilizes the particulate material as a vital reagent for newly conceived spells and personal arcane research.",sp=0}},faq={{q="What creatures yield crystalized scales?",a="They are harvested primarily from basilisks adapted to harsh regions, such as the scorched, singed, and blackened basilisks of Stonetalon's Charred Vale, as well as the saltstone basilisks found in Thousand Needles.",al={"where do scales drop","who drops crystalized scales","basilisk scales source"},it="origin",gp=true},{q="Who is seeking these scales in Stormwind?",a="Collin Mauren, a wizard residing in Stormwind City, commissions travelers heading into Stonetalon to collect them for his magical experiments.",al={"who wants crystalized scales","collin mauren scales","who uses these scales"},it="why_wanted"},{q="How are the scales used in spellcasting?",a="According to Collin Mauren, grinding the crystalline scales down to a fine dust provides a potent reagent needed to power specialized spells of his own creation.",al={"why are crystalized scales magic","scale spell reagent"},it="purpose"},{q="Can crystalized scales only be found in Stonetalon?",a="While Mauren specifically asks adventurers venturing toward the Charred Vale in Stonetalon, similar crystalline hides can also be harvested from saltstone basilisks in Thousand Needles.",al={"thousand needles scales","other places to get scales"},it="place",gp=true},{q="What are crystalized scales?",a="Crystalized scales are hardened, crystalline outer plates harvested from certain species of basilisks. Notably found on basilisks dwelling in harsh regions like the Charred Vale within the Stonetalon Mountains, these tough scales possess unique mineral-like properties that make them valuable to scholars and spellcasters.",al={"what are crystalized scales","crystalized scales lore","about crystalized scales"},it="identity",add=true},{q="Where do crystalized scales come from?",a="These scales naturally grow on specific varieties of basilisks. They are commonly harvested from the scorched, blackened, and singed basilisks roaming the fiery wastes of Stonetalon's Charred Vale, as well as saltstone basilisks found in the salt flats of Thousand Needles.",al={"crystalized scales origin","where to get crystalized scales","source of crystalized scales"},it="origin",add=true}},ang={["class:Mage"]="For practitioners of the arcane, these scales demonstrate how environmental exposure alters the magical composition of beasts, yielding specialized reagents for unique spell formulas.",["faction:Alliance"]="Procuring these scales bridges the expansive distance between the Alliance capital of Stormwind and the untamed wilds of Kalimdor."},kw={"basilisk","charred vale","collin mauren","crystalized scales","reagent","stonetalon mountains","stormwind","thousand needles"},rel={"npc:collin-mauren","quest:1078","subzone:charred-vale","zone:stonetalon","zone:thousandneedles","topic:stormwind-kingdom"},src={"Crystalized Scales","Retrieval for Mauren"}}
E["item:enchanted-gaea-seeds"] = {t="item",n="Enchanted Gaea Seeds",z="stonetalon",s="Enchanted Gaea Seeds are specially prepared botanical seeds meant to bring revitalization to the ravaged landscapes of Kalimdor. Empowered through druidic magic and gathered at Sun Rock Retreat, they are planted directly into the ash-choked soil of the Charred Vale to counteract devastation and rekindle natural growth.",h="Enchanted Gaea Seeds are specially prepared botanical seeds meant to bring revitalization to the ravaged...",sec={{t="A Spark in the Ashes",b="The Enchanted Gaea Seeds represent the Horde's druidic efforts to mend the deep scars left across Stonetalon Mountains. After raw Gaea Seeds are gathered and ritually enchanted by Tammra Windfield at Sun Rock Retreat, they carry sufficient resilience to overcome pervasive corruption and elemental blight. When pressed into the fertile dirt mounds that still survive beneath the soot of the Charred Vale, these seeds take root against the harsh conditions, anchoring new life in a landscape dominated by hostile fire elementals and invasive harpies.",sp=0},{t="The Promise of Renewal",b="The goal of planting these enchanted seeds extends beyond simple gardening; it is an active effort to turn the tide in the struggle for Stonetalon's future. The magic woven into the husks allows them to resist lingering corruption and establish a foothold for native flora. As they flourish, the restored vegetation is intended to soothe the agitated fire elementals, crowd out feral harpies, and counter the rampant deforestation driven by the Venture Company's relentless logging operations.",sp=0}},faq={{q="What are Enchanted Gaea Seeds used for?",a="They are planted into fertile dirt mounds within the Charred Vale. Their purpose is to sprout resilient flora that resists environmental corruption and begins healing the land destroyed by fire and warfare.",al={"gaea seeds purpose","what do enchanted gaea seeds do","why plant gaea seeds"},it="purpose"},{q="Who created or enchanted these seeds?",a="Raw Gaea seeds are collected from the surrounding wilderness and brought to Tammra Windfield at Sun Rock Retreat. She enchants them so they can survive the hostile, ash-laden soil of the Charred Vale.",al={"who made the seeds","tammra windwhisper seeds","how are gaea seeds made"},it="origin"},{q="Why must they be planted in the Charred Vale?",a="The Charred Vale is the center of ecological destruction in the Stonetalon Mountains, overrun by angry fire elementals and harpies. Planting the seeds directly in its surviving soil mounds introduces vital life that works to soothe the region's turmoil.",al={"where do i plant them","why charred vale","charred vale planting"},it="place"},{q="What threats face the planted seeds?",a="The Charred Vale is heavily plagued by hostile fire elementals born of the blaze, aggressive Bloodfury harpies nesting in the ruins, and encroaching industrial destruction from the Venture Company nearby.",al={"dangers in charred vale","what is destroying the land"},it="threat"},{q="What are Enchanted Gaea Seeds?",a="Enchanted Gaea Seeds are resilient, magically treated seeds prepared by Tammra Windwhisper at Sun Rock Retreat. Designed to withstand environmental blight, they serve as a powerful catalyst for rebirth, capable of taking root in devastated earth and initiating the long process of healing scorched terrain.",al={"what are enchanted gaea seeds","enchanted gaea seed lore","what is enchanted gaea seeds"},it="identity",add=true}},ang={["class:Druid"]="The seeds showcase the fundamental druidic duty of nurturing the cycle of rebirth, actively coaxing resilient life back into a realm consumed by ruin and wildfire.",["race:Tauren"]="For the Shu'halo of Sun Rock Retreat, planting the enchanted seeds is an act of spiritual stewardship to honor the Earth Mother and reclaim wounded land."},kw={"charred vale","enchanted gaea seeds","gaea seed","rebirth","stonetalon","sun rock retreat","tammra windwhisper"},rel={"quest:6381","quest:6301","item:gaea-seed","subzone:charred-vale","subzone:sun-rock-retreat","zone:stonetalon","quest:6282","quest:764"},src={"Enchanted Gaea Seeds","New Life"}}
E["item:enchanted-resonite-crystal"] = {t="item",n="Enchanted Resonite Crystal",z="stonetalon",s="The Enchanted Resonite Crystal is an alchemically altered mineral infused with shamanic magic by Mor'rogal in the Stonetalon Mountains. It is crafted specifically to shatter the Resonite cask binding a slumbering, ancient Earthen named Goggeroc.",h="The Enchanted Resonite Crystal is an alchemically altered mineral infused with shamanic magic by Mor'rogal in...",sec={{t="Breaker of Ancient Stone",b="Raw resonite crystals gathered from the deep caverns of the Stonetalon Mountains possess unusual harmonic and earthen properties. Recognizing the danger slumbering within a sealed subterranean cask, the shaman Mor'rogal altered the raw minerals using his elemental powers. The resulting Enchanted Resonite Crystal serves as a precise tool: when struck against the reinforced Resonite cask, it disrupts the housing and forcibly rouses the giant Earthen Goggeroc while he is still disoriented from his long sleep.",sp=0},{t="The Threat of Goggeroc",b="Mor'rogal believed that leaving an ancient Earthen unchecked would spell catastrophe for the fragile balance of Stonetalon and greater Kalimdor. By shattering the cask with the enchanted crystal, Mor'rogal aims to force the creature awake in a weakened state, offering a narrow window of opportunity to destroy Goggeroc before his full elemental might returns.",sp=1}},faq={{q="What is the Enchanted Resonite Crystal used for?",a="It is used to shatter the Resonite cask deep within the kobold-infested caves of the Stonetalon Mountains, releasing the slumbering Earthen known as Goggeroc.",al={"enchanted resonite crystal use","what does crystal do","break resonite cask"},it="purpose"},{q="Who created this enchanted crystal?",a="The Tauren shaman Mor'rogal created it by infusing raw resonite crystals with his shamanistic powers to weaken and expose the sleeping entity inside the cask.",al={"who made crystal","mor'rogal crystal","enchanted resonite creator"},it="origin"},{q="Why must Goggeroc be awakened and destroyed?",a="Mor'rogal fears that the unmatched might of an ancient Earthen running rampant would endanger all of Stonetalon and Kalimdor. Awakening him with the crystal leaves him temporarily weakened, making it possible to defeat him.",al={"why kill goggeroc","is goggeroc dangerous","goggeroc threat"},it="threat"},{q="What should I do with the crystal after defeating Goggeroc?",a="You must bring the Enchanted Resonite Crystal back to Mor'rogal along with confirmation that Goggeroc has been slain.",al={"return resonite crystal","turn in enchanted resonite crystal"},it="next_step"},{q="What is the Enchanted Resonite Crystal?",a="It is an altered mineral talisman imbued with shamanistic power by Mor'rogal at Malaka'jin. Resonite crystals are naturally occurring minerals found in the caves of Stonetalon Mountains. Once magically transformed, this crystal serves as a key and a hammer designed specifically to shatter the Resonite cask holding the slumbering earthen giant, Goggeroc.",al={"what is enchanted resonite crystal","enchanted resonite crystal lore","resonite crystal meaning"},it="identity",add=true},{q="Why does Mor'rogal want the Enchanted Resonite Crystal?",a="Mor'rogal needs the crystal to free and eliminate Goggeroc before the earthen awakens at full strength. He fears that an unleashed earthen poses an unmatched peril that could devastate all of Stonetalon Mountains. Shattering the cask forces Goggeroc awake in a severely weakened state, giving you the only viable chance to strike him down.",al={"why want enchanted resonite crystal","why does morrogal need crystal","why enchanted resonite crystal"},it="why_wanted",add=true}},ang={["class:Shaman"]="The crystal demonstrates how elemental manipulation can destabilize even the ancient titan-forged earth magic binding living stone.",["faction:Horde"]="Stonetalon's balance is precarious, and Mor'rogal relies on Horde champions to neutralize ancient threats before they endanger regional outposts."},kw={"earthen arise","enchanted resonite crystal","goggeroc","mor'rogal","resonite cask","resonite crystal","stonetalon mountains"},rel={"quest:6481","npc:mor-rogal","item:resonite-crystal","zone:stonetalon","zone:thunderbluff","topic:shaman","topic:kobold"},src={"Enchanted Resonite Crystal","Earthen Arise"}}
E["item:fey-dragon-scale"] = {t="item",n="Fey Dragon Scale",z="stonetalon",s="A Fey Dragon Scale is a shimmering woodland relic harvested from the elusive faerie dragons living around Stonetalon Peak. It is sought after by the Darkspear witch doctor Jin'Zil, who uses it as an exotic reagent in an alchemical brew mocking night elven nature magic.",h="A Fey Dragon Scale is a shimmering woodland relic harvested from the elusive faerie dragons living around...",sec={{t="A Rare Forest Harvest",b="Faerie dragons are mysterious, elusive creatures tied closely to the wild groves of Kalimdor, particularly the untouched forests around Stonetalon Peak. Their scales carry a natural magical luster reminiscent of the deep woods they guard. While revered by the night elves as harmless woodland spirits and allies, outsiders view them as an untamed source of rare magical ingredients.",sp=0},{t="A Mocking Concoction",b="In the Horde settlement of Malaka'jin, Witch Doctor Jin'Zil concocts a sinister mixture that parodies the sacred traditions of the kaldorei. By combining a fey dragon scale with tree sap, feline whiskers, and dozen upon dozen of courser eyes, Jin'Zil brews what he mockingly calls 'forest magic.' Far from a benign nature blessing, the resulting concoction proves to be a lethal airborne poison intended for his captured night elf prisoners.",sp=1}},faq={{q="Where does this scale come from?",a="The scale is harvested from faerie dragons flitting through the highland groves around Stonetalon Peak, including elusive creatures like Wily Fey Dragons and Nal'taszar.",al={"fey dragon scale drop","where to find fey dragon scale","who drops fey dragon scale"},it="origin"},{q="Why does Witch Doctor Jin'Zil want a fey dragon scale?",a="Witch Doctor Jin'Zil in Malaka'jin requests the scale alongside other woodland reagents to brew what he sneeringly terms 'forest magic' for his caged night elf prisoners.",al={"why does jin'zil want this","what is the scale used for","jin'zil forest magic reagent"},it="why_wanted"},{q="What happens when Jin'Zil finishes his brew?",a="Once assembled, Jin'Zil unleashes his finished concoction inside his cave. Rather than harmless woodland magic, the mixture is a lethal poison that kills the three imprisoned night elves, leaving only their wisps to float away into the wild.",al={"what does jin'zil do with the brew","jin'zil magic result","prisoners of jin'zil"},sp=1},{q="What is a Fey Dragon Scale?",a="A Fey Dragon Scale is a shimmering, iridescent scale harvested from the elusive faerie dragons of Stonetalon Peak. These mystical creatures are deeply tied to the natural energies of the wild. To an alchemist or witch doctor, the scale serves as a potent, magically attuned reagent steeped in the raw essence of the ancient forest.",al={"what is fey dragon scale","fey dragon scale lore","about fey dragon scales"},it="identity",add=true}},ang={["race:NightElf"]="Faerie dragons are treasured companions and forest guardians of the kaldorei; seeing their scales plucked for a troll witch doctor's deadly mockery is an outrage to nature.",["faction:Horde"]="Assisting Jin'Zil secures the Horde's footing in the Stonetalon Mountains, striking directly at the night elven presence entrenched higher up the slopes."},kw={"faerie dragon","fey dragon scale","forest magic","jin'zil","malaka'jin","nal'taszar","stonetalon peak"},rel={"npc:witch-doctor-jin-zil","quest:1058","subzone:stonetalon-peak","subzone:malaka-jin","item:stonetalon-sap","item:twilight-whisker","item:courser-eye","zone:stonetalon"},src={"Fey Dragon Scale","Jin'Zil's Forest Magic"}}
E["item:gaea-seed"] = {t="item",n="Gaea Seed",z="stonetalon",s="Gaea Seeds are hardy plant kernels found along the water's edge of Mirkfallon Lake in the Stonetalon Mountains. Treasured by tauren shamans, they are imbued with elemental blessings to help replenish areas ravaged by war and industry.",h="Gaea Seeds are hardy plant kernels found along the water's edge of Mirkfallon Lake in the Stonetalon...",sec={{t="Vessels of Renewal",b="Gaea Seeds are native to Stonetalon Mountains, naturally washing up or growing around the shores of Mirkfallon Lake. While modest in appearance—resembling small, fibrous coconuts—they carry an inherent resilience. As industrial exploitation and conflict scar Stonetalon, shamanic practitioners view these seeds as vital conduits for healing the wounded earth.",sp=0},{t="Blessings of the Earthmother",b="At Sun Rock Retreat, the tauren shaman Tammra Windfield gathers Gaea Seeds to counter the destruction spreading across the peaks. Through traditional chants and elemental rituals, shamans imbue these dormant husks with the Earthmother's blessing. This spiritual infusion drastically accelerates their natural growth, transforming simple seeds into hardy saplings capable of taking root in scorched, barren ground like the Charred Vale.",sp=1}},faq={{q="Where are Gaea Seeds found?",a="Gaea Seeds are found scattered along the shoreline of Mirkfallon Lake, situated in the mountains north of Sun Rock Retreat in Stonetalon.",al={"gaea seed location","where to find gaea seeds","how to get gaea seed"},it="place",gp=true},{q="What are Gaea Seeds used for?",a="Tammra Windfield collects them at Sun Rock Retreat to perform an elemental blessing. Once imbued with shamanistic power, the seeds are used to restore plant life to devastated areas like the Charred Vale.",al={"gaea seed purpose","why collect gaea seeds","what does tammra do with gaea seeds"},it="purpose"},{q="Why do shamans need to imbue the seeds?",a="The land in parts of Stonetalon has been severely degraded by fire, warfare, and logging. Channeling the power of the Earthmother into the seeds accelerates their germination and strengthens them enough to grow in hostile, ruined soil.",al={"why bless the seeds","shaman gaea seed magic"},it="power"},{q="What do Gaea Seeds look like?",a="They lie near the water's edge around Mirkfallon Lake and look like small, brown, rounded husks or coconuts resting on the bank.",al={"gaea seed appearance","how to spot gaea seeds"},it="item",gp=true},{q="What is a Gaea Seed?",a="A Gaea Seed is a hardy, coconut-like kernel of life native to the Stonetalon Mountains. Blessed with natural resilience, these seeds hold potent vegetative potential that tauren shamans draw upon through the blessings of the Earthmother to bring restorative growth to lands scarred by industrial greed and warfare.",al={"what are gaea seeds","gaea seed info","what is gaea seed"},it="identity",add=true},{q="Where does a Gaea Seed come from?",a="Gaea Seeds are natural botanical wonders found solely along the water's edge of Mirkfallon Lake, nestled high in the Stonetalon Mountains north of Sun Rock Retreat. They are not crafted by mortal hands, but rather are natural gifts of the Earthmother, flourishing naturally around the lake's shores.",al={"who made gaea seed","gaea seed origin","where do gaea seeds come from"},it="origin",add=true},{q="Why does Tammra Windfield want Gaea Seeds?",a="Tammra Windfield, a shaman at Sun Rock Retreat, seeks Gaea Seeds to heal the scarred Stonetalon wilderness. Continuous logging and fighting have devastated the region, particularly the scorched earth of the Charred Vale. By gathering these seeds, she can channel the Earthmother's blessing and shamanistic power into them, accelerating their growth to replenish the ruined land.",al={"why gather gaea seeds","who wants gaea seeds","why does anyone want gaea seed"},it="why_wanted",add=true}},ang={["class:Shaman"]="The seeds represent practical earth restoration, demonstrating how shamanistic rituals and the Earthmother's blessing can speed natural growth in damaged environments.",["race:Tauren"]="For the tauren of Sun Rock Retreat, cultivating Gaea Seeds is a sacred obligation to heal the balance of the land disrupted by outside warfare and lumber exploitation."},kw={"charred vale","cycle of rebirth","earthmother","gaea seed","mirkfallon lake","stonetalon","sun rock retreat","tammra windfield"},rel={"quest:6301","quest:6381","npc:tammra-windfield","subzone:mirkfallon-lake","subzone:sun-rock-retreat","subzone:charred-vale","zone:stonetalon","topic:shaman"},src={"Gaea Seed","Cycle of Rebirth"}}
E["item:gerenzo-s-mechanical-arm"] = {t="item",n="Gerenzo's Mechanical Arm",z="stonetalon",s="Gerenzo's Mechanical Arm is the grafted prosthetic limb taken from the rogue engineer Gerenzo Wrenchwhistle in the Stonetalon Mountains. It serves as unmistakable proof of his demise for goblin operatives seeking to clear out competition.",h="Gerenzo's Mechanical Arm is the grafted prosthetic limb taken from the rogue engineer Gerenzo Wrenchwhistle...",sec={{t="A Bizarre Invention",b="Gerenzo Wrenchwhistle took self-modification to a grotesque extreme, grafting whirring gears and metal directly onto his failing body. Perched above Cragpool Lake, the renegade gnome replaced natural limbs with intricate machinery. When the goblin tinker Ziz Fizziks seeks Gerenzo's elimination to impress his superiors, this distinctive mechanical arm is the only trophy unique enough to serve as indisputable evidence of the engineer's death.",sp=0},{t="Gnomish Philosophy, Goblin Critique",b="To the goblin mind, amputating a perfectly functioning arm simply to attach a mechanical replacement makes little sense. Ziz Fizziks famously remarked that a proper goblin engineer would simply keep both biological arms and mount a mechanical third one instead. Despite the philosophical rift, delivering the severed limb satisfies Sputtervalve and helps Ziz petition for an assignment in Gadgetzan or Undermine.",sp=1}},faq={{q="Where does Gerenzo's Mechanical Arm come from?",a="It is taken from Gerenzo Wrenchwhistle, who oversees logging and engineering operations high above Cragpool Lake near the water wheel in the Stonetalon Mountains.",al={"who drops gerenzo arm","gerenzo arm location","where get gerenzo mechanical arm"},it="origin"},{q="Why does Ziz Fizziks want this arm?",a="Ziz needs definitive proof for his superior, Sputtervalve, that Gerenzo is dead. Because Gerenzo heavily altered his own body, his unique prosthetic arm is impossible to forge or mistake for anyone else's.",al={"why ziz want arm","arm quest turn in","proof of gerenzo death"},it="why_wanted"},{q="Why did Gerenzo replace his own arm?",a="According to Ziz Fizziks, Gerenzo's flesh appeared to be rotting away. Driven by desperation or obsessive gnomish experimentation, Gerenzo grafted machinery and replaced his failing limbs with mechanical counterparts.",al={"why is gerenzo a cyborg","gerenzo rotting flesh","why mechanical arm"}},{q="What is Gerenzo's Mechanical Arm?",a="It is the crude cybernetic prosthetic grafted directly onto the body of Gerenzo Wrenchwhistle, a diseased gnome overseer lurking near the water wheel above Cragpool Lake. Rather than living with natural flesh, Gerenzo augmented his rotting frame with clockwork gears and metal plating, making this intricate mechanical limb his most recognizable feature.",al={"what is gerenzos arm","gerenzo arm item","gerenzos mechanical arm"},it="identity",add=true}},ang={["profession:Engineering"]="The arm illustrates the contrasting mentalities of the two engineering traditions: gnomes willingly sacrifice their own biology for mechanical precision, whereas goblins prefer external additions and brute firepower.",["race:Gnome"]="Gerenzo represents a grim extreme of gnomish ingenuity, taking mechanical replacement far beyond conventional medical prosthetics into morbid self-augmentation."},kw={"arm","cragpool lake","gerenzo","mechanical arm","sputtervalve","stonetalon","wrenchwhistle","ziz fizziks"},rel={"quest:1096","quest:1483","subzone:cragpool-lake","npc:sputtervalve","zone:stonetalon","subzone:gadgetzan","topic:gnome"},src={"Gerenzo's Mechanical Arm","Gerenzo Wrenchwhistle (quest)"}}
E["item:ken-zigla-s-draught"] = {t="item",n="Ken'zigla's Draught",z="stonetalon",s="Ken'zigla's Draught is a potent, foul-tasting medicinal tonic prepared by Ken'zigla in the Stonetalon Mountains. It is formulated to restore enough strength to critically wounded individuals so they can move without bleeding out.",h="Ken'zigla's Draught is a potent, foul-tasting medicinal tonic prepared by Ken'zigla in the Stonetalon...",sec={{t="A Bitter Remedy",b="Prepared by Ken'zigla in the Stonetalon Mountains, this potent brew serves as an emergency restorative for those on the verge of death. The tonic is extremely strong and must be measured carefully; drinking more than half a dose at once risks causing the patient to bleed out as their circulation surges. Administering half provides enough raw vigor to move and flee imminent danger, while the remainder must wait until the body stabilizes after a full night's rest.",sp=0},{t="Mercy in the Barrens",b="The draught plays a vital role in the search for Dogran, an operative captured and tortured by quilboar north of Camp Taurajo. Carried by Horde warlocks seeking a soul devourer's token, the bitter mixture is delivered directly into the hostile razormane encampment. Drinking it provides Dogran just enough vitality to hobble away from his captors, even though severe wounds have permanently cost him the use of his limbs.",sp=1}},faq={{q="What is Ken'zigla's Draught used for?",a="It is a potent medicinal brew crafted to restore strength to dying or grievously injured individuals. Administered properly, it gives a wounded person enough stamina to stand and escape captivity without causing fatal hemorrhaging.",al={"what does kenziglas draught do","draught purpose","why do i need kenziglas draught"},it="purpose"},{q="Who makes the draught?",a="It is brewed by Ken'zigla, an apothecary or herbalist residing in the Stonetalon Mountains who prepared it anticipating that someone would arrive seeking aid for Dogran.",al={"who brews the draught","who is kenzigla","kenzigla location"},it="origin"},{q="Why must the draught only be taken half at a time?",a="The concoction is exceptionally harsh on the body. A half dose imparts just enough vigor to move without causing severe bleeding, while the second half must wait until the patient rests for a night to avoid fatal strain.",al={"how to take kenziglas draught","half dose draught","draught instructions"},it="power"},{q="Who receives the draught?",a="It is ultimately brought to Dogran, an operative held prisoner and badly injured in a quilboar camp north of Camp Taurajo in the Barrens.",al={"who drinks the draught","who is dogran","where to deliver draught"},it="target"},{q="Why are warlocks sent to retrieve this medicine?",a="Horde warlocks seeking to bind a succubus are guided toward Dogran, who possesses an item of deep emotional resonance. Helping deliver the draught is necessary to reach him and secure what is needed for the summoning ritual.",al={"why do warlocks need this","succubus quest draught","warlock quest kenzigla"},it="why_me"},{q="What is Ken'zigla's Draught?",a="It is a potent, foul-tasting medicinal brew prepared by the troll apothecary Ken'zigla in the Stonetalon Mountains. Crafted to sustain severe trauma, the concoction is powerful enough to restore a mortally wounded soldier's vitality and allow them to move, though it must be administered with great caution.",al={"what is the draught","kenziglas draught","kenzigla potion"},it="identity",add=true},{q="Why is Ken'zigla's Draught needed?",a="An orc named Dogran was captured and brutally tortured by quilboar in the Barrens. Bleeding out and near death in captivity, he cannot survive or escape without the draught's restorative magic. Grunt Logmar at Camp Taurajo desperately requires the remedy so Dogran can withstand his injuries long enough to flee his captors.",al={"why do they need the draught","who needs kenziglas draught","why make the draught"},sp=1,it="why_wanted",add=true}},ang={["class:Warlock"]="Procuring and delivering this draught is an essential step during the trials to summon and bind a succubus, proving a warlock's resourcefulness and tracking abilities across the Barrens.",["faction:Horde"]="With Camp Taurajo undermanned due to foraging patrols, the draught represents the only lifeline for an operative captured behind enemy quilboar lines."},kw={"camp taurajo","dogran","grunt logmar","ken'zigla's draught","kenzigla","stonetalon mountains","succubus quest","the barrens"},rel={"quest:1511","quest:1515","quest:1509","quest:1512","quest:1471","npc:grunt-logmar","subzone:camp-taurajo","topic:quilboar"},src={"Ken'zigla's Draught","Ken'zigla's Draught (quest)","Dogran's Captivity"}}
E["item:letter-to-jin-zil"] = {t="item",n="Letter to Jin'Zil",z="stonetalon",s="The Letter to Jin'Zil is a piece of correspondence penned by the orc Darsok Swiftdagger at the Crossroads. Entrusted to an adventurer after the defeat of Serena Bloodfeather, it bears word to the Darkspear witch doctor Jin'Zil in the Stonetalon Mountains that the northern Barrens have been purged of the Bloodfeather threat.",h="The Letter to Jin'Zil is a piece of correspondence penned by the orc Darsok Swiftdagger at the Crossroads.",sec={{t="A Messenger to Stonetalon",b="Following the eradication of the harpy infestation at the Dry Hills and the slaying of Serena Bloodfeather, Darsok Swiftdagger drafts this missive to an old comrade. Recognizing that the harpies of the Barrens originally roosted within the peaks of Stonetalon Mountains, Darsok uses the dispatch to introduce a promising warrior to the wider frontier while notifying the witch doctor Jin'Zil that the harpy matron has fallen.",sp=0},{t="Old Memories in Malaka'jin",b="Upon delivery to the cave at Malaka'jin, Jin'Zil welcomes the news with nostalgic satisfaction. The death of Serena reminds the old witch doctor of the founding of Durotar after the Third War, when his friend Rokhan joined the Mok'Nathal beastmaster Rexxar to strike down Serena's elder sister, Bloodfeather. With Serena now slain as well, Jin'Zil considers the Bloodfeather line's vengeance thoroughly extinguished.",sp=1}},faq={{q="Who wrote the Letter to Jin'Zil?",a="The letter is written by Darsok Swiftdagger, an orc stationed at the Crossroads in the Barrens who coordinates the defense against marauding harpy covens.",al={"who wrote this","letter sender","darsok letter"},it="origin"},{q="Where is Jin'Zil located?",a="Witch Doctor Jin'Zil resides inside a cave within Malaka'jin, a Darkspear troll outpost nestled in the southeast crags of the Stonetalon Mountains.",al={"where is jinzil","jin'zil location","find jinzil"},it="place",gp=true},{q="What is the news contained in the letter?",a="The message informs Jin'Zil that Serena Bloodfeather, the leader of the harpies descending into the northern Barrens, has been slain, securing the perimeter north of the Crossroads.",al={"what does the letter say","letter message"},it="identity"},{q="Why does Jin'Zil care about the Bloodfeathers?",a="Jin'Zil remembers the founding of Durotar after the Third War, when his companion Rokhan and the Mok'Nathal warrior Rexxar killed Serena's elder sister. Serena sought revenge against the Horde ever since, making her downfall a welcome resolution.",al={"why jinzil harpies","bloodfeather history","rokhan and bloodfeather"},it="ties"},{q="Why does Jin'Zil want the Letter to Jin'Zil delivered to him?",a="The letter brings long-awaited news from his old friend Darsok Swiftdagger in the Barrens. Jin'Zil has not heard from Darsok in many years, and the missive confirms the death of Serena Bloodfeather, putting an end to the harpy matriarchs who troubled both the Barrens and Stonetalon.",al={"why deliver letter to jinzil","who wants letter to jinzil","why does jinzil care about the letter"},it="why_wanted",add=true}},ang={["faction:Horde"]="The letter acts as a bridge for Horde adventurers transitioning from policing the Barrens to tackling the deeper conflicts brewing in the Stonetalon Mountains.",["race:Troll"]="Delivering the letter leads Darkspear travelers directly to Witch Doctor Jin'Zil, an elder practitioner carrying on traditional voodoo outside of the Echo Isles."},kw={"darsok swiftdagger","harpies","jin'zil","letter to jin'zil","malaka'jin","rokhan","serena bloodfeather","stonetalon"},rel={"quest:1060","quest:876","subzone:malaka-jin","zone:stonetalon","zone:barrens","topic:harpy","quest:875","quest:867"},src={"Letter to Jin'Zil","Letter to Jin'Zil (quest)"}}
E["item:maggran-s-reserve-letter"] = {t="item",n="Maggran's Reserve Letter",z="stonetalon",s="Maggran's Reserve Letter is an official dispatch written by Maggran Earthbinder at Sun Rock Retreat. Carried across Kalimdor to the Great Lift, it grants a stationed sentry long-awaited relief so he may return home to visit his family.",h="Maggran's Reserve Letter is an official dispatch written by Maggran Earthbinder at Sun Rock Retreat.",sec={{t="A Sentry Relieved",b="Maintaining outposts across the rugged expanse of Kalimdor demands vigilance, but the leaders of the Horde recognize that prolonged watch duty takes a heavy toll on morale. Penned by Maggran Earthbinder in the high crags of Sun Rock Retreat, this simple missive serves as official orders notifying Grish Longrunner that a replacement warrior has been dispatched to take over his post at the Great Lift. For a lonely guard watching over the towering wooden winches far to the south, the letter promises something rare in troubled times: an honorable leave of absence to reunite with family.",sp=0}},faq={{q="What is the purpose of Maggran's Reserve Letter?",a="The letter contains official orders from Maggran Earthbinder relieving the sentry Grish Longrunner from his post at the Great Lift in the southern Barrens, allowing him to return home and visit his family.",al={"what does this letter do","maggran letter purpose","why deliver letter"},it="purpose"},{q="Who wrote the letter?",a="The letter was written by Maggran Earthbinder, an elder residing at Sun Rock Retreat in the Stonetalon Mountains.",al={"who wrote it","author of reserve letter","maggran earthbinder"},it="origin"},{q="Who is meant to receive it?",a="It is addressed to Grish Longrunner, a Horde guard stationed at the top of the Great Lift connecting the southern Barrens to Thousand Needles.",al={"who gets the letter","letter recipient","where does it go"},it="target"},{q="Where is the letter delivered?",a="It must be carried south across the Barrens to the edge of the Thousand Needles canyon, where the Great Lift stands.",al={"delivery location","where is grish","great lift location"},it="place"},{q="What is Maggran's Reserve Letter?",a="It is an official written dispatch penned by Maggran Earthbinder at Sun Rock Retreat in the Stonetalon Mountains. The message informs a stationed Horde guard, Grish Longrunner, that a relief warrior from the reserves is being dispatched to take over his post, granting him leave to visit his family.",al={"what is maggrans reserve letter","maggrans letter","reserve letter"},it="identity",add=true},{q="Why does Grish Longrunner want Maggran's Reserve Letter?",a="Grish requested relief from his post long ago and is eager for news. Guarding the Great Lift in the southern Barrens is a monotonous duty, and this letter formally authorizes his replacement by a reserve warrior, finally granting him long-awaited time away to visit his family.",al={"why does grish want the letter","why is the reserve letter wanted","why need maggrans reserve letter"},it="why_wanted",add=true}},ang={["faction:Horde"]="The missive highlights the Horde's post-war efforts to care for its scattered forces by cycling fresh reserves into remote outposts across Kalimdor."},kw={"barrens","earthbinder","grish","letter","lift","longrunner","maggran","reserve","stonetalon"},rel={"quest:5881","npc:maggran-earthbinder","npc:grish-longrunner","subzone:great-lift","subzone:sun-rock-retreat","zone:stonetalon","zone:barrens","zone:thousandneedles"},src={"Maggran's Reserve Letter","Calling in the Reserves"}}
E["item:ng-5"] = {t="item",n="NG-5",z="stonetalon",s="NG-5 is the shorthand designation for Nitromirglyceronium, a notoriously volatile chemical compound. Procured for the gnome tinkerer Gaxim Rustfizzle in the Stonetalon Mountains, it serves as the essential catalyst for his explosive engineering schemes.",h="NG-5 is the shorthand designation for Nitromirglyceronium, a notoriously volatile chemical compound.",sec={{t="A Volatile Reagent",b="Known formally as Nitromirglyceronium, NG-5 is an exceptionally hazardous chemical solution handled only with extreme caution—or reckless gnomish enthusiasm. Gaxim Rustfizzle, an operative stationed in the Stonetalon Mountains, requires the substance as a critical ignition compound. According to Gaxim, NG-5 provides the exact reaction necessary to detonate entire wagons loaded with dynamite, orchestrating a massive explosion meant to serve as a chaotic distraction against his adversaries in the region.",sp=0}},faq={{q="What is NG-5?",a="NG-5 stands for Nitromirglyceronium, a highly unstable and volatile chemical concoction used primarily as an explosive ignition reagent in advanced demolition and gnomish engineering.",al={"what is ng5","what is nitromirglyceronium","ng 5 item"},it="identity"},{q="Who wants NG-5 and why?",a="The gnome engineer Gaxim Rustfizzle in the Stonetalon Mountains requires the chemical. It serves as the vital component needed to reliably ignite several wagons packed full of dynamite, intended as a spectacular distraction.",al={"who needs ng-5","gaxim rustfizzle ng-5","why get ng5"},it="why_wanted"},{q="Is NG-5 dangerous to handle?",a="Extremely dangerous. The supplier warns couriers to handle the compound with absolute care, joking that anyone who is not an ally of Gaxim will likely end up blowing themselves to pieces.",al={"is ng5 safe","ng-5 explosive","will ng5 blow up"},it="danger"},{q="Where does NG-5 come from, and who made it?",a="NG-5, also known as Nitromirglyceronium, is obtained from an acquaintance of Gaxim Rustfizzle who brews specialized chemical compounds. It is an extremely volatile alchemical mixture concocted specifically for explosive reactions, handed over only with stern warnings about how easily it can blow an unwary courier to pieces.",al={"who made ng-5","where do you get ng-5","ng5 creator"},it="origin",add=true}},ang={["profession:Engineering"]="Engineers will recognize NG-5 as Nitromirglyceronium, a temperamental chemical catalyst prized by tinkers when ordinary black powder lacks the punch needed to ignite heavy ordinance.",["race:Gnome"]="Using an unstable chemical solution to blow up whole wagons of dynamite for a simple distraction is classic, high-risk gnomish problem-solving at its finest."},kw={"dynamite","explosives","gaxim rustfizzle","gnome","ng-5","ng5","nitromirglyceronium","stonetalon"},rel={"quest:1073","npc:gaxim-rustfizzle","zone:stonetalon"},src={"NG-5","Ineptitude + Chemicals = Fun (2)"}}
E["item:ordanus-head"] = {t="item",n="Ordanus' Head",z="stonetalon",s="Ordanus' Head is the grisly trophy taken from Keeper Ordanus at Raynewood Retreat in Ashenvale. Claimed on behalf of the blood elf magi Braelyn Firehand, it serves as undeniable proof that one of Cenarius's eldest sons has fallen to arcane vengeance.",h="Ordanus' Head is the grisly trophy taken from Keeper Ordanus at Raynewood Retreat in Ashenvale.",sec={{t="A Grudge from the Past",b="Keeper Ordanus was an ancient keeper of the grove, one of the elder scions of the forest god Cenarius. When Braelyn Firehand climbed the heights of Stonetalon Mountains on orders from her master, she sought to cleanse the sacred Highborne ruins from night elven presence and exact vengeance on Ordanus. However, the keeper was spirited away to the heart of Ashenvale before she could strike. Using arcane scrying to peer through the forest canopy, Firehand located his sanctuary in the boughs of Raynewood Retreat, demanding his severed head as proof that the wild demigod's arrogance had finally been answered.",sp=0},{t="The Price of Hubris",b="Braelyn holds a centuries-deep grievance against Ordanus and the druids who dared condemn arcane casting while occupying ruins once sanctified to Queen Azshara. In life, Ordanus considered himself superior even to the ancient Highborne nobility. By taking his head, Firehand symbolically strikes back against the legacy of Cenarius, declaring that no guardian of the wild can stem the return of raw magical power.",sp=1}},faq={{q="Who was Keeper Ordanus?",a="Keeper Ordanus was an ancient keeper of the grove and an elder son of Cenarius. Long ago, he clashed with the arcane practitioners of the night elven nobility, holding a reputation for deep arrogance toward those who practiced the arcane arts.",al={"who is ordanus","ordanus lore","what is ordanus"},it="identity"},{q="Where is this head collected?",a="The head is claimed from Keeper Ordanus atop the elevated wooden platform at Raynewood Retreat, a fortified night elven canopy enclave situated in central Ashenvale.",al={"where to find ordanus head","ordanus location","raynewood retreat ordanus"},it="place",gp=true},{q="Why does Braelyn Firehand want his head?",a="Braelyn Firehand seeks vengeance for an ancient feud dating back to before the Great Sundering, when Ordanus and his kin looked down upon the Highborne. She also despises the night elves for defiling the ancient ruins of Azshara atop Stonetalon Peak.",al={"why braelyn wants ordanus head","braelyn grudge","why kill ordanus"},it="why_wanted"},{q="What happens after the head is delivered?",a="Delivering Ordanus' Head to Braelyn at Sunrock Retreat satisfies her blood debt, prompting her to reward the mercenary handsomely before directing her wrath toward deeper druidic strongholds in the region.",al={"ordanus head turn in","after ordanus dies","braelyn firehand quest reward"},sp=1,it="next_step"},{q="Where does Ordanus' Head come from?",a="This grim trophy is taken directly from Keeper Ordanus, one of the eldest sons of the forest demigod Cenarius. Though once thought safe atop Stonetalon Peak, Ordanus fled into Ashenvale and took refuge high within Raynewood Retreat before being hunted down.",al={"ordanus head origin","where did ordanus head come from","who does ordanus head belong to"},it="origin",add=true}},ang={["faction:Horde"]="Striking down Ordanus and delivering his head to Braelyn helps cement the Horde's foothold across the contested borders of Stonetalon and Ashenvale, weakening local night elf leadership.",["class:Druid"]="For a druid, carrying the severed head of an elder son of Cenarius serves as a stark reminder of the bitter, bloody animosity that arcane sorcerers still bear toward the protectors of the wild."},kw={"ashenvale","braelyn firehand","cenarius","keeper of the grove","ordanus","ordanus' head","raynewood retreat","stonetalon","sunrock retreat"},rel={"quest:1088","npc:braelyn-firehand","subzone:raynewood-retreat","zone:ashenvale","zone:stonetalon","quest:1087","quest:1089","topic:cenarius"},src={"Ordanus' Head","Ordanus (quest)"}}
E["item:resonite-crystal"] = {t="item",n="Resonite Crystal",z="stonetalon",s="Resonite Crystals are strange, glowing mineral samples found deep within Boulderslide Cavern in the Stonetalon Mountains. Frantically mined by local kobolds, these rare stones hum with the ancient magical residue of the Titan-forged Earthen.",h="Resonite Crystals are strange, glowing mineral samples found deep within Boulderslide Cavern in the...",sec={{t="Ancient Resonance",b="Hidden away in the depths of Boulderslide Ravine, Resonite Crystals have become the focal point of sudden, frantic kobold excavation. While common cave miners usually seek mundane ores or shiny trinkets, the kobolds' obsession with these specific formations immediately alarmed the shamans of Sun Rock Retreat. Upon close examination, the stones hum with a subtle magical resonance tied to the primordial shaping of the world. Mor'rogal identified these faint energies as traces of Earthen magic, indicating that the burrowing creatures broke into an ancient layer crafted by the Titans.",sp=0},{t="Tapping the Earth",b="The discovery of Resonite confirms troubling news for the Horde presence in Stonetalon: the kobold diggers have struck deep enough to disturb the ancient Earthen. Because the Earthen were shaped directly by the Titans to carve and mold the world's foundations, residual magic clings stubbornly to the surrounding rock. By gathering these crystals, Horde agents hope to decipher the kobolds' frantic intentions and turn the very power of the enchanted stone against whatever slumbering forces have been disturbed below.",sp=1}},faq={{q="Where are Resonite Crystals found?",a="Resonite Crystals are found inside Boulderslide Cavern, a deep cave located within Boulderslide Ravine in the southeastern reaches of the Stonetalon Mountains.",al={"resonite location","where to get resonite","resonite crystal farm"},it="place",gp=true},{q="Why are the kobolds mining Resonite Crystals?",a="The kobolds in Boulderslide Ravine began frantically excavating these crystals after their deep mining broke into subterranean chambers containing ancient Earthen relics. They harvest the mineral to tap into the strange power permeating the rock.",al={"why kobolds mining","kobold crystal plot","boulderslide kobolds"},it="motive"},{q="What kind of power is in a Resonite Crystal?",a="Resonite Crystals carry lingering traces of Earthen magic. According to the tauren shaman Mor'rogal, this primordial power dates back to the Titans, who forged the stone-skinned Earthen to shape the subterranean layers of the world.",al={"resonite crystal magic","what is resonite","is resonite magical"},it="power"},{q="Who is studying these crystals?",a="Mor'rogal, a tauren stationed at Sun Rock Retreat in the Stonetalon Mountains, investigates the crystals to understand the sudden surge in kobold activity and find a way to counter whatever evil has been uncovered.",al={"who wants resonite","mor'rogal crystals","sun rock retreat resonite"},it="people"},{q="What are the Earthen mentioned in connection to the crystal?",a="The Earthen are an ancient race created by the Titans to sculpt and excavate the deep earth. Uncovering their presence in the Stonetalon depths explains the rare, residual Titan magic clinging to the Resonite Crystals.",al={"what are earthen","earthen titan connection"},it="origin"},{q="What is Resonite Crystal?",a="Resonite is a rare mineral crystal embedded deep underground within Stonetalon Mountains. Notable for holding lingering traces of ancient Earthen magic, it has drawn both frantic mining efforts from subterranean tunnelers and grave concern from scholars monitoring unnatural disturbances in the crags.",al={"what is resonite","resonite crystal lore","resonite ore"},it="identity",add=true},{q="Why does anyone want Resonite Crystal?",a="While the Boulderslide kobolds frantically extract the crystals from their deep cavern, the Horde seeks them out to uncover what evil is stirring beneath the peaks. Shamanic scholars like Mor'rogal study the samples to discern the nature of the unearthed Earthen magic and harness enchanted wards against whatever subterranean threat looms.",al={"why gather resonite crystals","who wants resonite crystal","resonite crystal purpose"},it="why_wanted",add=true}},ang={["class:Shaman"]="The Resonite Crystals carry an unsettling resonance for shamans, who can recognize the dormant, primordial earth magic left behind by Titan creations long buried under the mountains.",["profession:Mining"]="Unlike standard copper or tin veins, Resonite is an intensely concentrated mineral formation whose extraction requires delving past aggressive kobolds into the deepest subterranean strata."},kw={"boulderslide","crystal","earthen","kobold","mor'rogal","resonite","stonetalon","titans"},rel={"subzone:boulderslide-cavern","quest:6421","npc:mor-rogal","subzone:sun-rock-retreat","zone:stonetalon","topic:kobold","topic:titan","zone:thunderbluff"},src={"Resonite Crystal","Boulderslide Ravine (quest)"}}
E["item:scroll-of-messaging"] = {t="item",n="Scroll of Messaging",z="stonetalon",s="The Scroll of Messaging is an enchanted parchment carrying a specific magical sending spell. Acquired for the gnome engineer Gaxim Rustfizzle in the Stonetalon Mountains, it serves an unusual purpose: providing the magical trigger needed to detonate remote explosives.",h="The Scroll of Messaging is an enchanted parchment carrying a specific magical sending spell.",sec={{t="A Volatile Message",b="While ostensibly an arcane script meant for long-distance communication, Gaxim Rustfizzle has a far more disruptive application in mind for the Scroll of Messaging. By combining its transmission incantation with volatile NG-5 charges, the gnome plans to create a remotely detonated explosive. The resulting blast is intended to trigger a massive distraction at the Venture Company's logging operation in Stonetalon, granting operatives a window to slip past guards and pilfer proprietary engineering schematics and confidential correspondence.",sp=0}},faq={{q="What is the Scroll of Messaging used for?",a="Although written as a messaging spell, Gaxim Rustfizzle uses its transmission magic to craft a remote trigger. When combined with explosive NG-5, it allows him to set off a blast from a safe distance.",al={"scroll of messaging use","what does scroll of messaging do","why gaxim wants scroll"},it="purpose"},{q="Who receives this scroll?",a="The scroll is delivered to Gaxim Rustfizzle, an Alliance-aligned gnome engineer operating in the Stonetalon Mountains.",al={"who gets scroll of messaging","where do i bring scroll of messaging","scroll recipient"},it="target"},{q="Why does Gaxim need a remote explosive?",a="Gaxim needs a major diversion at the local Venture Company operation. The resulting chaos provides cover to infiltrate their compound, steal valuable engineering plans, and recover documents to halt their aggressive clear-cutting of the forest.",al={"gaxim explosive reason","why blow up venture co","stonetalon distraction"},it="motive"},{q="What is NG-5?",a="NG-5 is an explosive chemical charge utilized by Gaxim Rustfizzle. Paired with the magical signal inscribed upon the Scroll of Messaging, it forms an improvised remote-detonation device.",al={"ng-5","what is ng-5","ng5 explosive"},it="item"},{q="What is the Scroll of Messaging?",a="The Scroll of Messaging is an enchanted parchment bearing an arcane spell. Gaxim Rustfizzle sought it out as an unconventional catalyst to combine with his volatile explosive compound, NG-5, enabling him to craft a remotely triggered charge against Venture Company operations in Stonetalon.",al={"what is scroll of messaging","scroll of messaging lore","about scroll of messaging"},it="identity",add=true}},ang={["profession:Engineering"]="True to gnomish innovation, this scroll demonstrates how theoretical arcane magic can be repurposed as a remote receiver for mechanical demolitions.",["faction:Alliance"]="The scroll plays a critical part in helping Alliance operatives sabotage Venture Company machinery and stall their environmental devastation in Stonetalon."},kw={"explosives","gaxim rustfizzle","ng-5","remote detonator","scroll of messaging","stonetalon","venture co"},rel={"quest:1077","npc:gaxim-rustfizzle","item:ng-5","zone:stonetalon","quest:764"},src={"Scroll of Messaging","Special Delivery for Gaxim"}}
E["item:sealed-envelope"] = {t="item",n="Sealed Envelope",z="stonetalon",s="This tightly sealed packet contains confidential Venture Company technical documents and stolen schematics. Assembled by the exiled goblin engineer Fizziks, it holds proprietary designs meant for delivery to Sputtervalve in Ratchet.",h="This tightly sealed packet contains confidential Venture Company technical documents and stolen schematics.",sec={{t="Corporate Espionage",b="When the goblin engineer Fizziks was abruptly ejected from the Venture Company's logging operations in the Stonetalon Mountains, he did not leave empty-handed. Stuffing internal manuals, operating procedures, and technical specifications into this envelope, he managed to smuggle out company secrets under the noses of his former overseers. Most prized among these stolen records are the technical schematics for the Super Reaper 6000, a devastating piece of industrial clear-cutting machinery.",sp=0},{t="Delivery to Ratchet",b="Rather than keeping the dangerous trade secrets buried, Fizziks sends the packet south to Sputtervalve, an engineer residing in the neutral goblin port of Ratchet. While business rivals in the Steamwheedle Cartel have little personal love or trust for Fizziks, the engineering value of the designs inside the envelope is undeniable. The documents provide a clear window into Venture Company mechanical ingenuity and give independent engineers a chance to exploit the cartel's advanced logging technologies.",sp=0}},faq={{q="What is inside the Sealed Envelope?",a="The envelope contains internal Venture Company documents, technical operating manuals, and the blueprints for the Super Reaper 6000 wood-clearing machine, all snatched by Fizziks during his hasty departure.",al={"envelope contents","what is in sealed envelope","sealed envelope items"},it="identity"},{q="Who prepared this packet?",a="The envelope was prepared by Fizziks, a disgruntled goblin engineer who was booted out by the Venture Company at their logging operation in the Stonetalon Mountains.",al={"who made the envelope","who gave sealed envelope","fizziks envelope"},it="origin"},{q="Who is intended to receive it?",a="It is addressed to Sputtervalve, a goblin tinkerer residing in the port town of Ratchet within the Barrens.",al={"who gets the envelope","where does envelope go","sputtervalve delivery"},it="target"},{q="Why does Sputtervalve want these documents?",a="Though Sputtervalve dislikes the Venture Company and is wary of Fizziks, the documents contain valuable improvements and schematics that allow outside tinkerers to understand and adopt the company's powerful mechanical designs.",al={"why sputtervalve wants it","venture company tech ratchet"},it="why_wanted"}},ang={["profession:Engineering"]="The envelope holds technical drawings for the Super Reaper 6000, representing some of the most destructive and lucrative mechanical automation devised by goblin hands.",["faction:Horde"]="Carrying these papers south from Stonetalon aids the neutral goblins of Ratchet in undermining the aggressive, exploitative logging operations of the Venture Company."},kw={"blueprints","fizziks","ratchet","sealed envelope","sputtervalve","stonetalon","super reaper 6000","venture company"},rel={"quest:1094","item:super-reaper-6000-blueprints","npc:sputtervalve","topic:venture-company","zone:stonetalon","subzone:ratchet","zone:barrens","quest:1093"},src={"Sealed Envelope","Further Instructions"}}
E["item:sleepers-key"] = {t="item",n="Sleepers' Key",z="stonetalon",s="The Sleepers' Key is one of three enchanted keys crafted by night elf druids to seal their sacred vault within the Talon Den atop Stonetalon Peak. Kept safe inside a hidden cache locked by the Gatekeeper's Key, it represents the slumbering druids of the wild who guard the mountain's deepest secrets.",h="The Sleepers' Key is one of three enchanted keys crafted by night elf druids to seal their sacred vault...",sec={{t="A Druidic Safeguard",b="Carved into the heights of Stonetalon Peak, the Talon Den serves as a redoubt and sanctum for the druids of Kalimdor. Aware that their sacred relics and potent treasures might draw unwanted attention, the night elf keepers devised an intricate system of locks and hidden caches to protect their hoard. The Sleepers' Key is one third of that protective ward. Placed within a secluded cache in the den's depths, it can only be retrieved using the Gatekeeper's Key hidden near the threshold. Alongside the Claw Key and the Barrow Key, the Sleepers' Key must be set into the stone locks of the Talon Den Hoard to disperse the ward and reveal the ancient items held within.",sp=0}},faq={{q="What is the Sleepers' Key used for?",a="The Sleepers' Key is used alongside the Barrow Key and Claw Key to open the Talon Den Hoard, a warded stone vault hidden deep within the barrow den at Stonetalon Peak.",al={"what does sleepers key do","sleepers key purpose","talon den hoard keys"},it="purpose"},{q="How was the Sleepers' Key locked away?",a="The druids placed it inside the Sleepers' Cache in the northwestern tunnels of the Talon Den. Opening that cache requires the Gatekeeper's Key, which the druids concealed within an unassuming lantern near the den's entrance.",al={"where is sleepers key","opening sleepers cache","gatekeepers key requirement"}},{q="Why did the druids hide their relics with multiple keys?",a="The night elf druids crafted complex safeguards so that their powerful items and sacred heirlooms would never fall into enemy hands if the den were attacked. Dispersing the keys among hidden caches ensured that intruders could not easily plunder their hoard.",al={"why so many keys","talon den defense","druid hoard puzzle"},it="motive"},{q="Why is it called the Sleepers' Key?",a="It is named after the sleeping druids who enter deep trances to wander the Emerald Dream. Much like the Barrow Key and Claw Key, its name honors the sacred duties and traditions of the night elf circles stationed in the mountains.",al={"who are the sleepers","sleepers key name meaning"},it="name"},{q="What is the Sleepers' Key?",a="The Sleepers' Key is one of three specialized keys crafted by the night elf druids of Stonetalon Peak. Concealed within a locked cache deep inside the Talon Den, it forms an essential component of the warding system guarding the druids' central hoard of sacred relics.",al={"what is sleepers key","sleepers key lore","about sleepers key"},it="identity",add=true},{q="Where does the Sleepers' Key come from, and who made it?",a="The key was fashioned by the druids who established the Talon Den on Stonetalon Peak. To safeguard their potent artifacts from intruders, they devised an intricate security scheme, securing the key inside a dedicated chest called the Sleepers' Cache.",al={"who made sleepers key","sleepers key origin","where did sleepers key come from"},it="origin",add=true},{q="Why does anyone want the Sleepers' Key?",a="The Horde seeks the key to bypass the druids' layered defenses and unlock the Talon Den Hoard. Together with the Claw Key and the Barrow Key, it opens the stone vault holding the powerful relics the druids stashed away on Stonetalon Peak.",al={"why find sleepers key","why need sleepers key","who wants sleepers key"},it="why_wanted",add=true}},ang={["class:Druid"]="The keys and caches of the Talon Den showcase the night elf druids' layered defenses, utilizing their ancient knowledge of the Emerald Dream and the barrows to seal away relics of power.",["faction:Horde"]="Acquiring the Sleepers' Key is part of an orchestrated raid into Stonetalon Peak's heart, stripping away the defensive wards of the night elves to claim the relics sealed in their hoard."},kw={"gatekeeper's key","sleepers cache","sleepers key","sleepers' key","stonetalon peak","talon den","talon den hoard","the den"},rel={"quest:1089","item:barrow-key","item:claw-key","subzone:stonetalon-peak","zone:stonetalon","quest:1088","quest:1087","topic:druid"},src={"Sleepers' Key","The Den (quest)"}}
E["item:smoldering-embers"] = {t="item",n="Smoldering Embers",z="stonetalon",s="Smoldering Embers are the glowing, heat-baked remnants retrieved from the raging fire elementals of the Charred Vale. Night elf Sentinels track these cinders as physical proof that the fiery terrors overrunning the devastated woodland are being subdued.",h="Smoldering Embers are the glowing, heat-baked remnants retrieved from the raging fire elementals of the...",sec={{t="Remnants of the Charred Vale",b="The Venture Company's relentless clear-cutting and industrial devastation tore through the Charred Vale, setting the forest ablaze and unleashing destructive fury from deep within the earth. In their wake, elementals of living fire—Burning Ravagers, Burning Destroyers, and wandering Rogue Flame Spirits—surged across the scorched basin. These Smoldering Embers are the lingering, ash-covered cores left behind when an elemental is extinguished, serving as proof that the rampant fires of the vale are being systematically suppressed.",sp=0}},faq={{q="Where do Smoldering Embers come from?",a="Smoldering Embers are gathered from the fiery elementals haunting the Charred Vale in southern Stonetalon Mountains, including Burning Ravagers, Burning Destroyers, and Rogue Flame Spirits.",al={"where do i find smoldering embers","who drops smoldering embers","smoldering ember source"},it="origin"},{q="Why does Kaela Shadowspear want these embers?",a="Kaela Shadowspear seeks them as undeniable proof that the rampant fire elementals in the Charred Vale are being culled. She believes the scarred land can never heal under Elune's grace while these violent spirits roam unchecked.",al={"why collect smoldering embers","kaela shadowspear embers","enraged spirits goal"},it="why_wanted"},{q="What caused the fire elementals to appear in the Charred Vale?",a="The Venture Company used aggressive machinery and indiscriminate burning to clear the ancient forest. Their reckless exploitation destabilized the land, unearthing and unleashing hostile elementals of flame and stone that ultimately drove the goblins out.",al={"what happened to charred vale","why are there fire elementals in stonetalon","venture co fire spirits"},it="history"},{q="What are Smoldering Embers?",a="Smoldering Embers are the burning physical remains left behind by the destructive fire elementals infesting the Charred Vale. These glowing remnants linger after creatures like Burning Ravagers, Rogue Flame Spirits, and Burning Destroyers are slain, serving as tangible proof that their fiery rampage across the ruined forest has been quelled.",al={"what are smoldering embers","smoldering embers lore","what is smoldering ember"},it="identity",add=true}},ang={["race:NightElf"]="For the night elves, seeing the Charred Vale in flames is a heartbreaking wound upon Kalimdor. Gathering these embers is a solemn duty to purge foreign desecration and bring peace back under Elune's gaze.",["class:Druid"]="Druids view the embers as tragic proof of nature unbalanced by industrial greed, where untamed elemental fury prevents the ash-choked soil from ever regenerating."},kw={"burning destroyer","burning ravager","charred vale","enraged spirits","kaela shadowspear","rogue flame spirit","smoldering embers","stonetalon","venture co"},rel={"quest:1083","subzone:charred-vale","npc:kaela-shadowspear","zone:stonetalon","quest:764","topic:elune"},src={"Smoldering Embers","Enraged Spirits"}}
E["item:stonetalon-sap"] = {t="item",n="Stonetalon Sap",z="stonetalon",s="Stonetalon Sap is a sticky, potent substance harvested directly from the lumbering sap beasts that roam the craggy heights of the Stonetalon Mountains. It serves as a key reagent for the Darkspear witch doctor Jin'Zil, who uses its raw woodland properties to concoct a spiteful brew.",h="Stonetalon Sap is a sticky, potent substance harvested directly from the lumbering sap beasts that roam the...",sec={{t="A Bitter Harvest",b="Found dripping from the arboreal sap beasts near Mirkfallon Lake and Stonetalon Peak, this heavy fluid carries the concentrated essence of the mountain's ancient flora. While harmless when dormant in nature, the sap can easily be turned into something far darker in the hands of an experienced alchemist or witch doctor. Jin'Zil of Malaka'jin covets it to brew what he mockingly dubs 'forest magic'—a deadly draught intended to torment captured night elf sentinels with the very essence of their cherished wilderness.",sp=1}},faq={{q="What creatures carry Stonetalon Sap?",a="It is gathered from sap beasts, the strange woodland creatures found near Mirkfallon Lake and higher up along the slopes leading to Stonetalon Peak.",al={"where do you get stonetalon sap","who drops stonetalon sap","sap beasts"},it="origin",gp=true},{q="What does Witch Doctor Jin'Zil use the sap for?",a="Jin'Zil combines the sap with courser eyes, twilight whiskers, and a fey dragon scale to produce a toxic brew that he unleashes upon his caged night elf prisoners.",al={"why does jin'zil want sap","jin'zil forest magic recipe"},sp=1,it="why_wanted"},{q="Where is the best place to find sap beasts?",a="Sap beasts inhabit the groves surrounding Mirkfallon Lake and the lush paths climbing toward Stonetalon Peak.",al={"sap beast location","mirkfallon lake sap beasts"},it="place",gp=true},{q="Is the sap magical on its own?",a="It is naturally infused with the primordial vitality of the Stonetalon highlands, but it takes troll mojo and specific reagents to twist it into a lethal venom.",al={"is stonetalon sap magic","properties of stonetalon sap"},it="power"},{q="What is Stonetalon Sap?",a="Stonetalon Sap is a sticky, natural resin gathered from the sap beasts that roam the Stonetalon Mountains, particularly around places like Mirkfallon Lake and Stonetalon Peak. It is thick, viscous, and full of raw natural essence, making it an ideal component for concoctions and voodoo brews that tap into the peculiar magic of the local wilderness.",al={"what is stonetalon sap","stonetalon sap item","about stonetalon sap"},it="identity",add=true},{q="Where does Stonetalon Sap come from?",a="This amber sap is harvested directly from the living sap beasts that wander the forests and lake shores of the Stonetalon Mountains. It is not manufactured or distilled by any mortal craftsman, but rather secreted naturally by these bizarre, primordial plant creatures.",al={"stonetalon sap source","where to get sap","origin of stonetalon sap"},it="origin",add=true}},ang={["race:Troll"]="Witch Doctor Jin'Zil demonstrates the Darkspear talent for turning the enemy's beloved environment into a lethal instrument of voodoo.",["race:NightElf"]="The desecration of Stonetalon's native elements by a Horde witch doctor to poison captive sentinels is an outrage against nature and Elune."},kw={"jin'zil","malaka'jin","mirkfallon lake","sap beast","stonetalon peak","stonetalon sap"},rel={"npc:witch-doctor-jin-zil","quest:1058","subzone:mirkfallon-lake","subzone:stonetalon-peak","subzone:malaka-jin","item:courser-eye","item:fey-dragon-scale","item:twilight-whisker"},src={"Stonetalon Sap","Jin'Zil's Forest Magic"}}
E["item:super-reaper-6000-blueprints"] = {t="item",n="Super Reaper 6000 Blueprints",z="stonetalon",s="The Super Reaper 6000 Blueprints are the technical schematics for an enormous mechanized woodcutter deployed by the Venture Company in Stonetalon Mountains. Designed under the supervision of the gnome engineer Gerenzo Wrenchwhistle, the plans are heavily coveted by his disgruntled goblin rivals.",h="The Super Reaper 6000 Blueprints are the technical schematics for an enormous mechanized woodcutter deployed...",sec={{t="Industrial Espionage in Windshear Crag",b="The Venture Company's relentless clear-cutting operation in Windshear Crag relies on massive mechanized lumber harvesters known as Super Reapers. To the utter dismay of traditional goblin engineers, the company placed a gnome named Gerenzo in charge of designing the Super Reaper 6000 model. These blueprints contain the schematics for the contraption, carried by Venture Co. operators working the machinery across the crag. When the goblin engineer Ziz Fizziks was ousted from the operation, he was quickly hired by Sputtervalve to steal the designs. However, deciphering Gerenzo's dense, eccentric gnomish technical notations proves to be almost as difficult as taking the blueprints by force.",sp=0}},faq={{q="What is the Super Reaper 6000?",a="It is an enormous mechanized woodcutting device developed for the Venture Company's clear-cutting operations in the Stonetalon Mountains, designed to fell and process timber with ruthless industrial efficiency.",al={"what is super reaper","super reaper machine"},it="identity"},{q="Who designed the Super Reaper 6000?",a="The plans were drafted under Gerenzo Wrenchwhistle, a gnome engineer hired by the Venture Company to lead their mechanical efforts in Windshear Crag, much to the annoyance of local goblin mechanics.",al={"who made blueprints","who designed super reaper"},it="origin"},{q="Why does Ziz Fizziks want these blueprints?",a="Ziz was sacked from the Venture Company and immediately hired by Sputtervalve. Stealing the Super Reaper plans is Ziz's ticket to proving his worth and mechanical genius to his new boss.",al={"why does ziz want plans","who wants blueprints"},it="why_wanted"},{q="Who holds the blueprints in Windshear Crag?",a="The physical schematics are carried by Venture Co. Operators actively overseeing machinery and deforesting timber throughout Windshear Crag.",al={"where do blueprints drop","who drops blueprints"},it="target"}},ang={["profession:Engineering"]="The blueprints reflect a bizarre blend of crude goblin corporate muscle and meticulous gnomish mechanical design, featuring technical schematics that baffle ordinary tinkers.",["race:Gnome"]="Gerenzo Wrenchwhistle's blueprints prove that even cutthroat goblin syndicates like the Venture Company ultimately rely on gnomish ingenuity to construct complex heavy machinery."},kw={"blueprints","gerenzo","sputtervalve","stonetalon","super reaper 6000","venture company","windshear crag","ziz fizziks"},rel={"quest:1093","subzone:windshear-crag","zone:stonetalon","npc:sputtervalve","topic:venture-company","topic:gnome","topic:goblin","quest:1483"},src={"Super Reaper 6000 Blueprints","Super Reaper 6000 (quest)"}}
E["item:toxic-fogger"] = {t="item",n="Toxic Fogger",z="stonetalon",s="The Toxic Fogger is a specialized dispersal device filled with lethal poison, concocted by the Forsaken Royal Apothecary Society. It is designed to contaminate the Venture Company's air transit operations in the Stonetalon Mountains.",h="The Toxic Fogger is a specialized dispersal device filled with lethal poison, concocted by the Forsaken Royal...",sec={{t="A Forsaken Solution",b="Developed by Apothecary Zamah in Thunder Bluff, the Toxic Fogger serves as biological sabotage aimed directly at the Venture Company's strip-mining efforts. Suspecting that the goblins rely on courier flying machines to shuttle messages and light cargo between Stonetalon and their headquarters, Zamah engineered the fogger to release an airborne poison right where machines land and refuel. Rather than engaging in prolonged skirmishes with endless mercenary crews, the Forsaken method strikes at the logistical spine of the operation, ensuring that the poison travels directly back to corporate leadership.",sp=0},{t="Sabotage at Cragpool Lake",b="The intended target for the Toxic Fogger is the secluded copter pad constructed near Cragpool Lake. Perched high above the deforested hills and guarded by corporate muscle, the landing pad acts as an aerial link between remote crews and outside hubs. Deploying the fogger releases a billowing toxic vapor across the staging ground, catching returning pilots unawares. While some within the Horde may recoil at resorting to poison, Zamah urges her agents to discard guilt, declaring that no path is too dark if it secures victory against exploiters.",sp=1}},faq={{q="What is the Toxic Fogger used for?",a="The Toxic Fogger is used to poison the Venture Company's sky port at Cragpool Lake in the Stonetalon Mountains, contaminating light cargo and couriers headed back to their headquarters.",al={"what does toxic fogger do","fogger purpose","why use toxic fogger"},it="purpose"},{q="Who created the Toxic Fogger?",a="It was created by Apothecary Zamah, an envoy of the Royal Apothecary Society stationed on the Pools of Vision beneath Thunder Bluff.",al={"who made the fogger","toxic fogger creator","apothecary zamah poison"},it="origin"},{q="Where does the Toxic Fogger need to be placed?",a="It must be planted atop the elevated Venture Company copter pad located near Cragpool Lake in the Stonetalon Mountains, south of the large waterwheel.",al={"where do i put the fogger","copter pad location","sky port location"},it="target",gp=true},{q="Why does the Horde resort to using poison against the Venture Company?",a="The Venture Company's logging and mining heavily ravage the land in Stonetalon. Apothecary Zamah believes conventional combat is too slow, arguing that the Horde must embrace ruthless methods to eradicate the goblins before irreparable harm is done.",al={"why poison goblins","is poison allowed in horde","forsaken methods in stonetalon"},it="motive"},{q="What is the Toxic Fogger?",a="The Toxic Fogger is a specialized dispersal device filled with a lethal concoction crafted by the Forsaken. Designed to release a noxious cloud upon deployment, it serves as an instrument of sabotage intended to contaminate the Venture Company's logistics network and disrupt their operations in Stonetalon.",al={"what is toxic fogger","toxic fogger item","toxic fogger device"},it="identity",add=true},{q="Why does Apothecary Zamah want the Toxic Fogger deployed?",a="Apothecary Zamah intends to strike directly at the Venture Company's supply chain. By deploying the fogger at their small sky port, the toxin can coat departing flying machines and cargo, carrying the poison back to the goblins' headquarters and delivering devastating payback for their unchecked exploitation.",al={"why use toxic fogger","why want toxic fogger","why toxic fogger needed"},it="why_wanted",add=true}},ang={["race:Undead"]="The Toxic Fogger represents classic Royal Apothecary Society field strategy: disrupting enemy supply chains with aerosol toxins while showing allies that dark methods produce undeniable results.",["race:Tauren"]="While relying on lethal vapors may test traditional tauren codes of honor, the catastrophic industrial damage wrought by the Venture Company drives many in Thunder Bluff to tolerate Zamah's harsh measures."},kw={"apothecary zamah","copter pad","cragpool lake","sky port","stonetalon","toxic fogger","venture company"},rel={"quest:1086","quest:853","subzone:cragpool-lake","zone:stonetalon","topic:venture-company","topic:forsaken","zone:thunderbluff"},src={"Toxic Fogger","The Flying Machine Airport"}}
E["item:twilight-whisker"] = {t="item",n="Twilight Whisker",z="stonetalon",s="Twilight Whiskers are harvested from twilight runners prowling the northern heights of the Stonetalon Mountains. In the settlement of Malaka'jin, Witch Doctor Jin'Zil covets them as an ingredient in a cruel, venomous concoction he mockingly names forest magic.",h="Twilight Whiskers are harvested from twilight runners prowling the northern heights of the Stonetalon...",sec={{t="A Witch Doctor's Reagent",b="The high crags near Stonetalon Peak are home to twilight runners, predatory felines attuned to the deep shadows of the ancient groves. While hunters prize their pelts, Witch Doctor Jin'Zil of Malaka'jin seeks their stiff whiskers for a far darker purpose. Seeking vengeance upon captured night elves who once defended these woodlands, Jin'Zil gathers components of the forest—resinous sap, countless eyes, fey dragon scales, and twilight whiskers—to brew a lethal draught intended to mock and poison his captives.",sp=0}},faq={{q="Where are Twilight Whiskers found?",a="They are gathered from the twilight runners stalking the slopes around Stonetalon Peak in northern Stonetalon Mountains.",al={"twilight whisker location","who drops twilight whiskers","where to get twilight whiskers"},it="place",gp=true},{q="Why does Witch Doctor Jin'Zil want them?",a="Witch Doctor Jin'Zil uses them alongside sap, courser eyes, and a fey dragon scale to brew a deadly concoction that poisons his night elf captives in Malaka'jin.",al={"jinzil whiskers","why does jinzil want twilight whiskers","jin'zil forest magic ingredients"},it="why_wanted"},{q="What happens after Jin'Zil receives the whiskers?",a="Once provided with the ingredients, Jin'Zil unleashes his brew within his cave. The mixture swiftly kills the caged night elf prisoners, releasing their spirits as wisps that drift away.",al={"forest magic outcome","what happens to the prisoners"},sp=1,it="next_step"},{q="What is a Twilight Whisker?",a="A Twilight Whisker is a stiff facial hair harvested from the twilight runners prowling the heights of Stonetalon Mountains. To most, it is merely beast offal, but to practitioners of voodoo and alchemy, it serves as a potent reagent carrying the wild essence of the local predators.",al={"what is twilight whisker","twilight whisker info","what are twilight whiskers"},it="identity",add=true},{q="Where does a Twilight Whisker come from?",a="Twilight Whiskers are plucked from twilight runners, predatory felines native to the Stonetalon Mountains. They are not crafted by mortal hands, but rather taken directly from the beasts roaming near Stonetalon Peak.",al={"twilight whisker origin","where to get twilight whisker","who drops twilight whisker"},it="origin",add=true}},ang={["race:Troll"]="Jin'Zil's utilization of local beast reagents reflects classic Darkspear voodoo traditions, twisting the natural essence of the forest against his enemies.",["race:NightElf"]="The desecration of sacred woodland creatures like twilight runners and fey dragons to poison night elf captives embodies the brutal conflict waging in Kalimdor's forests."},kw={"forest magic","malaka'jin","stonetalon mountains","stonetalon peak","twilight runner","twilight whisker","witch doctor jin'zil"},rel={"quest:1058","npc:witch-doctor-jin-zil","item:stonetalon-sap","item:fey-dragon-scale","item:courser-eye","subzone:stonetalon-peak","subzone:malaka-jin","zone:stonetalon"},src={"Twilight Whisker","Jin'Zil's Forest Magic"}}
E["item:unidentified-ore"] = {t="item",n="Unidentified Ore",z="stonetalon",s="Unidentified Ore is a peculiar mineral sample unearthed by Venture Company operations in the crags of the Stonetalon Mountains. Recovered by the disgruntled laborer Piznik, it was smuggled away to be analyzed by goblin tinker Ziz Fizziks and forwarded to engineers in Undermine.",h="Unidentified Ore is a peculiar mineral sample unearthed by Venture Company operations in the crags of the...",sec={{t="A Curious Strike in Windshear",b="The Venture Company's relentless clear-cutting and strip mining in Windshear Crag tore deep into the crags of the Stonetalon Mountains, exposing unusual mineral strata. Among the debris, the goblin worker Piznik stumbled across a strange, unclassified specimen. Recognizing its potential value—or at least its leverage—Piznik held onto the sample while plotting his exit from the logging outfit. Handed off to a traveler bound for the western ridge of the crag, the sample made its way into the hands of Ziz Fizziks, who planned to ship the prize back to Undermine for study, keeping a pocket-sized cut for personal profit.",sp=0}},faq={{q="What is the Unidentified Ore?",a="It is an unclassified geological specimen dug up during Venture Company operations within Windshear Crag. Its exact composition is mysterious enough to attract the curiosity of tinker Ziz Fizziks and the mining engineers back in Undermine.",al={"what is this ore","unidentified ore lore","what rock is this"},it="identity"},{q="Who found the ore?",a="Piznik, a Venture Company goblin stationed in Windshear Crag, salvaged the sample. Fearing retribution from company supervisors after recent mishaps, he used the rock as an opportunity to flee and secure new employment.",al={"who dug it up","who gives the ore","piznik ore"}},{q="Who is trying to study this sample?",a="Ziz Fizziks, an enterprising goblin camped along the western edge of Windshear Crag, takes delivery of the mineral. He intends to pass the bulk of it along to engineers in Undermine while shaving off a small portion for himself.",al={"who wants the ore","who analyzes it","ziz fizziks ore"}},{q="Why does Undermine care about this stone?",a="Goblins are always scouting for new explosive, metallurgical, or combustible materials. A strange mineral unearthed in the ancient mountains of Kalimdor holds immense industrial and commercial potential for the trade cartels.",al={"undermine interest","why do goblins want it"},it="why_wanted"},{q="Where does the Unidentified Ore come from?",a="The sample was uncovered during Venture Company excavation operations within the Windshear Crag of the Stonetalon Mountains. While the goblins were digging out the crag, their workers unearthed strange, unfamiliar veins of mineral that their standard mining manifests could not account for, prompting Piznik to hide a sample away.",al={"unidentified ore origin","where was unidentified ore found","where did the ore come from"},it="origin",add=true}},ang={["profession:Mining"]="Miners picking through Windshear Crag will find standard veins everywhere, but this peculiar mineral sample defies common trade knowledge, intriguing even Undermine's best appraisers.",["profession:Engineering"]="Goblincraft relies on discovering raw compounds with unique reactive properties, making unclassified ores from untamed crags prime research material for innovative tinkers."},kw={"piznik","stonetalon","undermine","unidentified ore","venture company","windshear crag","ziz fizziks"},rel={"quest:1090","npc:piznik","quest:1483","subzone:windshear-crag","zone:stonetalon"},src={"Unidentified Ore","Gerenzo's Orders (2)"}}
E["item:venture-co-engineering-plans"] = {t="item",n="Venture Co. Engineering Plans",z="stonetalon",s="The Venture Co. Engineering Plans are mechanical schematics kept inside the goblin logging mill in Windshear Crag. Recovered by Alliance operatives, they detail the inner workings of the heavy machinery devastating the Stonetalon Mountains.",h="The Venture Co.",sec={{t="Industrial Secrets",b="Windshear Crag is choked with smoke and logging machinery as the Venture Company strips the forests of Stonetalon. Hidden inside their lumber mill south of Cragpool Lake, these engineering blueprints lay out the exact construction, strengths, and flaws of their specialized timber-harvesting contraptions.",sp=0},{t="Gnomish Espionage",b="Gnome engineer Gaxim Rustfizzle orchestrated a covert operation to sabotage the Venture Company's logging works while securing these documents. While planting explosives offers immediate disruption, acquiring the blueprints allows Alliance craftspeople to systematically exploit structural weaknesses in goblin equipment and adapt their innovative designs for Alliance projects.",sp=1}},faq={{q="Where are the Venture Co. Engineering Plans located?",a="The plans are kept inside the Venture Company's primary lumber mill located in Windshear Crag, south of Cragpool Lake in the Stonetalon Mountains.",al={"where to find engineering plans","plans location stonetalon","where are the plans"},gp=true},{q="Who wants these engineering plans?",a="Gaxim Rustfizzle, an Alliance gnome coordinating covert actions in the Stonetalon Mountains, sends agents to recover them.",al={"who needs the plans","who turns in engineering plans","gaxim rustfizzle plans"},it="why_wanted"},{q="Why are these blueprints important to the Alliance?",a="The schematics reveal critical design flaws in the Venture Company's logging machinery, allowing operatives to break them down more effectively, while also providing Alliance gnomes with industrial designs they can incorporate into their own inventions.",al={"why steal the plans","what do the plans do"},it="why_wanted"},{q="What operation is tied to stealing these plans?",a="Securing these plans is the primary objective of Covert Ops - Alpha. While the mission involves setting detonators throughout the site, returning with the blueprints defines the operation's true success.",al={"covert ops alpha objective","what quest is this for"},it="purpose"},{q="What are the Venture Co. Engineering Plans?",a="These documents contain detailed technical schematics and blueprints created by the Venture Company's engineers in Stonetalon Mountains. Kept inside their lumber mill near Cragpool Lake, they outline the construction, wiring, and operational designs behind the deforesting machinery and industrial contraptions the company relies upon to clear Windshear Crag.",al={"what are venture co engineering plans","venture company engineering plans","venture co plans"},it="identity",add=true},{q="Where do the Venture Co. Engineering Plans come from?",a="The plans originated from the Venture Company's industrial operations in Windshear Crag. Developed by their own engineers and operators to oversee logging and mechanical construction, they were kept secure within the main lumber mill located just south of Cragpool Lake before being targeted by Alliance covert operatives.",al={"where did the engineering plans come from","who made venture co engineering plans","origin of venture co plans"},it="origin",add=true}},ang={["race:Gnome"]="For gnome tinkerers, capturing rival goblin schematics is both an intellectual victory and a treasure trove of industrial ideas ripe for adaptation.",["profession:Engineering"]="The Venture Company's brutal, resource-hungry contraptions may lack refinement, but their mechanical blueprints hold valuable insights into heavy industrial machinery."},kw={"covert ops","cragpool lake","engineering plans","gaxim rustfizzle","stonetalon","venture co.","windshear crag"},rel={"quest:1079","npc:gaxim-rustfizzle","item:covert-ops-pack","subzone:windshear-crag","subzone:cragpool-lake","zone:stonetalon","quest:764"},src={"Venture Co. Engineering Plans","Covert Ops - Alpha"}}
E["item:venture-co-letters"] = {t="item",n="Venture Co. Letters",z="stonetalon",s="The Venture Co. Letters are internal correspondence recovered from Windshear Mine in Stonetalon Mountains. Stolen under the cover of explosive distractions, they provide the night elf Sentinels with crucial intelligence on goblin industrial operations in the region.",h="The Venture Co.",sec={{t="Industrial Intelligence",b="Windshear Crag has been overrun by the Venture Company, whose logging machines and strip-mining operations tear through the ancient woodland. To uncover the full scope of the cartel's ambitions, Alliance operatives deployed covert sabotage to create distractions and infiltrate Windshear Mine. These retrieved letters contain private communications and logistical records detailing the company's local activities, giving Sentinel leadership insight into how the defilers organize their workforce and supply lines.",sp=0},{t="Delivery to the Sentinels",b="Once secured from deep inside the mine, the missives are rushed back to Sentinel commander Kaela Shadowspear. Facing pressure from both goblin defilers and Horde incursions across Stonetalon, the Sentinels rely on this stolen correspondence to predict the Venture Company's next moves and safeguard what remains of the sacred mountains.",sp=1}},faq={{q="What are the Venture Co. Letters?",a="They are internal operational documents and correspondence kept by the Venture Company at Windshear Mine in Stonetalon Mountains.",al={"venture co letters","what are the letters","stonetalon letters"},it="identity"},{q="Where are the letters found?",a="They are located within Venture Co. Documents stored inside Windshear Mine, situated at the eastern end of Windshear Crag.",al={"where are the letters","letters location","windshear mine letters"},it="origin",gp=true},{q="Who wants these letters?",a="Gnome operative Gaxim Rustfizzle oversees the covert operation to steal them, and they are ultimately delivered to Kaela Shadowspear, who leads the local night elf Sentinels.",al={"who gets the letters","who wants them","turn in letters"},it="why_wanted"},{q="Why do the Sentinels need this correspondence?",a="The Sentinels are fighting to halt the rampant deforestation and excavation of Stonetalon. The letters reveal Venture Company logistical planning and operational priorities, helping the defenders strategize against them.",al={"why do sentinels want letters","sentinel interest"},it="why_wanted"},{q="Where do the Venture Co. Letters come from, and who wrote them?",a="These documents originate from the Venture Company's mining operation at Windshear Mine, situated at the far eastern edge of Windshear Crag. They comprise internal corporate correspondence kept among the documents at the site, written by the company's regional operators and overseers to coordinate their aggressive extraction and logging efforts across Stonetalon.",al={"venture co letters origin","who wrote the venture co letters","where do the letters come from"},it="origin",add=true}},ang={["race:NightElf"]="The desecration of Stonetalon by goblin lumber machines strikes at the heart of Kalimdor's wilderness, making intelligence on Venture Company schemes vital to the Sentinels.",["faction:Alliance"]="Alliance scouts coordinate covert missions against the Venture Company to protect night elf holdings in Stonetalon from rapacious industrial exploitation."},kw={"kaela shadowspear","sentinels","stonetalon mountains","venture co","venture co. letters","windshear crag","windshear mine"},rel={"quest:1080","quest:1091","npc:kaela-shadowspear","item:venture-co-documents","item:covert-ops-pack","subzone:windshear-crag","zone:stonetalon","topic:sentinels"},src={"Venture Co. Letters","Covert Ops - Beta","Kaela's Update"}}
E["npc:braelyn-firehand"] = {t="npc",n="Braelyn Firehand",z="stonetalon",s="Braelyn Firehand is an elven practitioner of the arcane residing quietly among the Horde at Sun Rock Retreat in the Stonetalon Mountains. Claiming an interest in clearing mystical obstructions across the highlands, she enlists travelers to strike against the night elven guardians of Stonetalon Peak.",h="Braelyn Firehand is an elven practitioner of the arcane residing quietly among the Horde at Sun Rock Retreat...",sec={{t="An Unlikely Guest",b="Standing out amidst the tauren lodges and rustic orcish tents of Sun Rock Retreat, Braelyn Firehand is a rare sight: a blood elf dwelling openly within a remote Horde settlement. The shaman and chieftains of the retreat tolerate her presence, seemingly oblivious to her true loyalties. Braelyn presents herself as an observer fascinated by the flow of regional magic, eager to hire passing Horde mercenaries to handle dangerous field assignments across the crags.",sp=0},{t="A Grudge Against the Grove",b="Braelyn directs her allies against the night elven druids and the sacred offspring of Cenarius stationed high above at Stonetalon Peak. She claims the druids choke the ambient ley lines and stifle the flow of arcane energy throughout the peaks. Her true focus, however, is intensely personal: she harbors bitter memories of Keeper Ordanus, recalling an ancient arrogance where he held himself above even the Highborne. She willingly pays Horde travelers to hunt down Ordanus and return with his head.",sp=1},{t="Ties to Jaedenar",b="Braelyn's resentment is more than idle lingering hatred; her aims align directly with the Shadow Council sect operating out of Jaedenar in Felwood. By encouraging Horde champions to systematically slaughter the night elves and the keepers holding the sacred peaks, she clears the way for darker powers while masking her sinister affiliation under the guise of ordinary frontier skirmishing.",sp=2}},faq={{q="Who is Braelyn Firehand?",a="Braelyn Firehand is an elven mage living at Sun Rock Retreat in the Stonetalon Mountains. Though surrounded by the Horde, she pursues her own arcane agenda against the night elves guarding Stonetalon Peak.",al={"who is braelyn","braelyn firehand lore","elf in sun rock retreat"},it="identity"},{q="Why is an elf staying in Sun Rock Retreat?",a="Sun Rock Retreat serves as a bustling, isolated frontier haven. Braelyn uses the camp's tolerance and its steady stream of Horde warriors to contract out her personal strikes against the night elves without arousing immediate suspicion from the settlement's leadership.",al={"why is she with the horde","why is braelyn in sun rock","blood elf in stonetalon"},it="why_here"},{q="What does she want done at Stonetalon Peak?",a="Braelyn instructs adventurers to infiltrate Stonetalon Peak to kill night elf druids, slay the sons of Cenarius, and decapitate their leader, Keeper Ordanus, ostensibly to reopen the suppressed flows of magic in the mountains.",al={"braelyn quest goals","why kill ordanus","braelyn firehand tasks"},it="wants"},{q="What is her history with Keeper Ordanus?",a="Braelyn claims to have known Keeper Ordanus personally in the distant past. She resents him bitterly, alleging that he carried immense arrogance and regarded himself as superior even to the ancient Highborne.",al={"braelyn and ordanus","how does she know ordanus","ordanus backstory"},it="history"},{q="Who does Braelyn Firehand actually serve?",a="Beneath her claims of restoring arcane balance, Braelyn is an operative working on behalf of the Shadow Council sect rooted in Jaedenar, weaponizing Horde adventurers against the demonic cult's natural enemies.",al={"braelyn true faction","braelyn shadow council","who does she work for"},sp=2,it="side"},{q="Is Braelyn a mage or a warlock?",a="While affiliated with the demon-worshiping Shadow Council, Braelyn hurls fireballs like a traditional mage rather than drawing upon demonic fel or curses.",al={"braelyn class","is braelyn a warlock","braelyn firehand spells"},sp=2},{q="Who is Braelyn Firehand tied to?",a="Braelyn Firehand is secretly allied with the Shadow Council sect lurking within Jaedenar in Felwood. While she stays among the Horde in Sun Rock Retreat posing as a simple blood elf traveler seeking arcane balance, her real allegiance and assignments tie her directly to the demonic cultists operating out of Jaedenar.",al={"braelyn firehand ties","who is braelyn affiliated with","braelyn firehand allies"},sp=1,it="ties",add=true}},ang={["faction:Horde"]="Braelyn gladly hires Horde wanderers to strike at the night elves, turning the ongoing territorial clashes in Kalimdor into cover for a deeper, darker agenda.",["class:Mage"]="Braelyn speaks readily of ley energies and mystical blockages, appealing to fellow practitioners who understand the flow of arcane magic through the land.",["class:Druid"]="Her deliberate slaughter of the sons of Cenarius and the desecration of the Barrow Dens stand as an abhorrent crime against the balance of nature."},kw={"braelyn","cenarius","firehand","highborne","ordanus","stonetalon","sun rock retreat"},rel={"subzone:sun-rock-retreat","quest:1088","quest:1087","quest:1089","subzone:stonetalon-peak","topic:shadow-council","subzone:jaedenar","topic:highborne"},src={"Braelyn Firehand"}}
E["npc:darn-talongrip"] = {t="npc",n="Darn Talongrip",z="stonetalon",s="Darn Talongrip is an orc scout stationed along the frontier of the Stonetalon Mountains near Malaka'jin. He monitors local threats in the crags and helps coordinate Horde communication between forward outposts and regional commanders.",h="Darn Talongrip is an orc scout stationed along the frontier of the Stonetalon Mountains near Malaka'jin.",sec={{t="Frontier Scout of Stonetalon",b="Darn Talongrip watches the rugged ascents leading into Stonetalon from the southern Barrens. Perched near the settlement of Malaka'jin and the perilous Webwinder Path, Darn contends with regional dangers such as the aggressive local spiders that choke the ravine paths. His post serves as an early line of contact for travelers winding upward into contested peaks.",sp=0},{t="Eyes for the Command",b="Beyond monitoring venomous beasts in the nearby crags, Darn ensures messages and frontline reports reach key commanders like Kadrak at the watch tower in the northern Barrens. Outlying encampments in these mountains operate under constant pressure, making Darn's role as a sentry and courier essential to keeping the Horde vanguard informed.",sp=0}},faq={{q="Who is Darn Talongrip?",a="Darn Talongrip is an orc scout stationed along Webwinder Path near Malaka'jin in the southern reaches of the Stonetalon Mountains.",al={"who is darn talongrip","darn talongrip identity","who is this orc"},it="identity"},{q="Where can Darn Talongrip be found?",a="He can be found watching the trails near the troll settlement of Malaka'jin, along Webwinder Path in the Stonetalon Mountains.",al={"darn talongrip location","where is darn talongrip","darn talongrip coordinates"},it="place",gp=true},{q="What is his role in Stonetalon?",a="Darn serves as an outpost scout, warning travelers of dangerous predators like local spider broods and passing messages to military liaisons such as Kadrak.",al={"what does darn talongrip do","darn talongrip purpose"},it="purpose"},{q="Who is Kadrak, and why does Darn send travelers to him?",a="Kadrak is a Horde commander stationed at the watch tower in the northern Barrens, heading up the Horde's Ashenvale campaign. Darn directs new recruits to him to help defend the Horde's new fronts in Ashenvale.",al={"who is kadrak","report to kadrak"},it="ties"},{q="Whose side is Darn Talongrip on?",a="Darn Talongrip stands firmly with the Horde. Operating out of Stonetalon Mountains near Malaka'jin, he works alongside fellow orcs to secure the rugged trails and further the Horde's foothold across Kalimdor.",al={"darn talongrip faction","is darn talongrip horde","who does darn talongrip serve"},it="side",add=true},{q="What does Darn Talongrip want?",a="Darn Talongrip looks to protect the Horde's presence along the pass and direct able-bodied adventurers where their strength is needed most, particularly by dispatching travelers to assist Kadrak with urgent Horde operations nearby.",al={"what is darn talongrip looking for","darn talongrip goals","what does darn want"},it="wants",add=true},{q="Why is Darn Talongrip here in Stonetalon?",a="Stationed around Malaka'jin and the surrounding passes of the Stonetalon Mountains, Darn Talongrip maintains the Horde's frontier presence, keeping watch over the mountain roads and ensuring reports flow swiftly between outpost sentries.",al={"why is darn talongrip in stonetalon","why is darn here","darn talongrip stonetalon reason"},it="why_here",add=true}},ang={["faction:Horde"]="Darn Talongrip keeps early watch along the ascent into Stonetalon, acting as a valuable contact for Horde adventurers fresh from the Barrens.",["race:Orc"]="Like many orc scouts, Darn embraces the harsh conditions of the frontier, standing watch amid jagged rocks and hostile wildlife."},kw={"darn talongrip","kadrak","malakajin","orc scout","stonetalon","webwinder path"},rel={"subzone:malaka-jin","subzone:webwinder-path","npc:kadrak","quest:6541","zone:stonetalon"},src={"Darn Talongrip"}}
E["npc:falfindel-waywarder"] = {t="npc",n="Falfindel Waywarder",z="stonetalon",s="Falfindel Waywarder is a night elf sentinel stationed at Thalanaar, the outpost guarding the border between Feralas and the Thousand Needles. From this frontier watchpost, he works to heal corrupted lands and safeguard the southern wilderness of Kalimdor. Travelers wandering down from Stonetalon or the Barrens often find him seeking aid to restore balance to the wild.",h="Falfindel Waywarder is a night elf sentinel stationed at Thalanaar, the outpost guarding the border between...",sec={{t="Watch at the Southern Border",b="Thalanaar marks the gateway where the lush forests of Feralas descend into the towering mesas and dry salt plains of Thousand Needles. Falfindel Waywarder stands watch at this remote outpost, greeting weary travelers who have ventured far across the continent. Surrounded by natural grandeur and lurking dangers, he serves as a point of contact for the night elves seeking to monitor both local threats and broader environmental calamities across Kalimdor.",sp=0},{t="Healing the Charred Vale",b="Despite his southern post, Falfindel remains deeply concerned with the devastation far to the north in Stonetalon Mountains. The Charred Vale, ruined by dark sorcery and fiery destruction, stands as a painful scar upon Kalimdor's wilderness. When adventurers deliver aid to Falfindel to assist in its recovery, he calls upon the spirits of the forest. Summoning forth swarms of wisps, he directs them to make haste north to Stonetalon to begin mending the scorched earth.",sp=0},{t="Eyes on the Quillboar and the Wastes",b="In addition to coordinating restoration efforts, Falfindel keeps a close watch on the surrounding region, including the quilboar dens of Razorfen Kraul. By reviewing recovered journals and gathering intelligence on quilboar leadership, Falfindel ensures that the Alliance understands the rising dangers threatening the passes between Feralas and the central deserts.",sp=0}},faq={{q="Where is Falfindel Waywarder located?",a="Falfindel is stationed at Thalanaar, the night elf outpost situated on the border between Feralas and Thousand Needles.",al={"falfindel location","where is falfindel","falfindel waywarder map"},it="place",gp=true},{q="What is Falfindel's role at Thalanaar?",a="He serves as a sentinel and guide at the outpost, monitoring regional threats such as the quilboar in Thousand Needles and coordinating restoration efforts for ruined lands like the Charred Vale.",al={"what does falfindel do","falfindel purpose","falfindel quests"},it="purpose"},{q="How does Falfindel help the Charred Vale?",a="When adventurers assist in efforts to reclaim the Charred Vale, Falfindel channels an incantation to summon forest wisps, dispatching them north to Stonetalon to heal the blighted land.",al={"falfindel stonetalon","falfindel charred vale","reclaiming the charred vale falfindel"}},{q="Why is Falfindel interested in Razorfen Kraul?",a="He studies the threat posed by the quilboar of the Kraul and inspects items like Lonebrow's journal to track the influence of their leaders, such as the Crone of the Kraul.",al={"crone of the kraul falfindel","lonebrow journal falfindel","falfindel quilboar"},it="motive"},{q="Is Falfindel aligned with the Alliance or neutral?",a="Falfindel is a member of the night elf sentinels and is allied with the Alliance. Horde travelers approaching Thalanaar will find the outpost hostile.",al={"is falfindel alliance","falfindel faction"},it="side"},{q="What does Falfindel say to travelers?",a="He warmly greets friendly visitors by acknowledging their long journey, remarking, 'You look as though you have traveled from afar.'",al={"falfindel gossip","falfindel quote"}},{q="Who is Falfindel Waywarder?",a="Falfindel Waywarder is a night elf stationed at the outpost of Thalanaar, bordering Feralas and the Thousand Needles. Attuned to the health of the land and the perils facing the southern reaches of Kalimdor, he watches over travelers and works closely with fellow night elves to counter emerging threats to the wilderness.",al={"who is falfindel","falfindel waywarder lore","who is falfindel waywarder"},it="identity",add=true},{q="What does Falfindel Waywarder want?",a="Falfindel seeks to protect the fragile wilderness and aid the healing of devastated lands. He directs allies to summon forest spirits to revitalize the Charred Vale, coordinates deliveries to keep local outposts supplied, and seeks to eliminate the corrupted quilboar crone lurking within Razorfen Kraul.",al={"what does falfindel want","falfindel goals","falfindel quests purpose"},it="wants",add=true},{q="Why is Falfindel Waywarder here?",a="Falfindel serves as a sentinel and guide at Thalanaar, guarding the passage between Thousand Needles and Feralas. From this remote outpost, he monitors the rising quilboar threat spilling from the Barrens and coordinates efforts to restore balance to blighted forests across central and southern Kalimdor.",al={"why is falfindel here","why is falfindel at thalanaar","falfindel purpose"},it="why_here",add=true}},ang={["race:NightElf"]="Falfindel represents your people's vigilance on the frontiers of Kalimdor, striving to mend nature's scars and guard against encroaching wilderness perils.",["class:Druid"]="His efforts to send forest spirits and wisps to heal the scorched soils of Stonetalon reflect the sacred druidic mission of restoration.",["faction:Alliance"]="For Alliance travelers making the long trek south from the Barrens or Stonetalon, Falfindel and the watch at Thalanaar offer a welcoming sanctuary."},kw={"charred vale","falfindel","feralas","stonetalon","thalanaar","thousand needles","waywarder","wisps"},rel={"subzone:thalanaar","quest:1057","quest:1100","quest:1101","zone:feralas","zone:thousandneedles","subzone:charred-vale","topic:night-elf"},src={"Falfindel Waywarder"}}
E["npc:gaxim-rustfizzle"] = {t="npc",n="Gaxim Rustfizzle",z="stonetalon",s="Gaxim Rustfizzle is an ambitious gnome scholar and tinker stationed at a small Alliance camp along the Webwinder Path in Stonetalon Mountains. A representative of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, he seeks to prove to skeptical night elves that advanced artifice and alchemy can preserve their woodland realm. His scientific curiosity is matched by a fierce vendetta against the destructive operations of the Venture Company.",h="Gaxim Rustfizzle is an ambitious gnome scholar and tinker stationed at a small Alliance camp along the...",sec={{t="A Scientific Emissary",b="While night elves traditionally rely on ancient druidism and nature magic, Gaxim Rustfizzle arrived in the craggy passes of Stonetalon to demonstrate a radically different perspective. Representing the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, he genuinely believes that calculated mechanisms and chemical solutions can defend and restore Kalimdor's wilderness just as effectively as prayers to Elune. Camped alongside the sentinel Kaela Shadowspear on the Webwinder Path, he works tirelessly to convince his tall, reclusive allies of engineering's ecological merits.",sp=0},{t="Sabotaging the Saws",b="Much of Gaxim's energy is channeled against the Venture Company, whose clear-cutting and industrial greed desecrate nearby Windshear Crag. Believing that crude goblin machinery deserves neither respect nor mercy, Gaxim coordinates covert operations and volatile chemical sabotage against their logging operations. To him, crippling their shredders and stealing their schematics is not merely tactical warfare—it is a practical demonstration that superior gnomish intellect always triumphs over careless corporate plunder.",sp=0}},faq={{q="Who is Gaxim Rustfizzle?",a="Gaxim Rustfizzle is a gnome scholar and inventor stationed at an Alliance lookout along the Webwinder Path in the Stonetalon Mountains. He serves as an emissary for the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences.",al={"who is gaxim","gaxim rustfizzle lore","gnome in stonetalon"},it="identity"},{q="What is the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences?",a="It is an academic and scientific society of gnomes dedicated to blending the disciplines of arcane magic, alchemical mixtures, and mechanical engineering. Gaxim represents their ideals abroad in Kalimdor.",al={"enlightened assembly","gaxim faction","gaxim group"},it="ties"},{q="Why is Gaxim working with the night elves?",a="Gaxim wants to demonstrate to the night elves that gnomish science and alchemy can actively protect and heal natural woodlands, offering a modern Alliance answer to forest conservation alongside traditional druidism.",al={"why is gaxim here","gaxim night elves","gaxim purpose"},it="why_here"},{q="Why does Gaxim hate the Venture Company?",a="The Venture Company is ruthlessly clear-cutting Windshear Crag with crude machines and toxic pollution. Gaxim despises their reckless exploitation and relishes turning volatile chemicals and sabotage against their operations.",al={"gaxim venture co","gaxim vs venture company","why fight venture co"},it="wants"},{q="Who is camped with Gaxim on Webwinder Path?",a="He shares his small outpost with Kaela Shadowspear, a night elf sentinel watching over the trails leading into Windshear Crag.",al={"gaxim companion","who is with gaxim","gaxim and kaela"}},{q="Where can Gaxim Rustfizzle be found?",a="He is located at a modest Alliance camp along the Webwinder Path, just southwest of the industrial logging pits of Windshear Crag in the Stonetalon Mountains.",al={"gaxim location","where is gaxim","gaxim rustfizzle map"},it="place",gp=true},{q="Whose side is Gaxim Rustfizzle on?",a="Gaxim is loyal to the Alliance and works directly alongside the night elves in Stonetalon. Representing the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, he acts as an emissary of gnomish ingenuity, aiming to prove to skeptical kaldorei allies that combining arcane lore, chemical mixtures, and mechanical craft can preserve nature rather than destroy it.",al={"gaxim rustfizzle faction","is gaxim alliance","who does gaxim work for"},it="side",add=true}},ang={["race:Gnome"]="Gaxim represents gnomish academic pride at its finest, showing Kalimdor's ancient cultures that gears and reagents can save a forest just as well as nature magic.",["race:NightElf"]="Though traditionalists may scoff at his whirring gadgets and bubbling vials, Gaxim is a steadfast ally actively defending Ashenvale and Stonetalon borders from goblin industry.",["profession:Engineering"]="Gaxim puts engineering principles to work in the field, designing covert operations and tactical devices specifically tuned to disrupt crude Venture Company machinery.",["faction:Alliance"]="Perched on the perilous Webwinder Path, Gaxim provides crucial scouting, intelligence, and sabotage missions to check aggressive industrial incursions in Stonetalon."},kw={"assembly","gaxim","gnome","kaela","rustfizzle","stonetalon","venture company","webwinder","windshear"},rel={"zone:stonetalon","subzone:webwinder-path","subzone:windshear-crag","npc:kaela-shadowspear","topic:venture-company","quest:1073","quest:1079","quest:1080"},src={"Gaxim Rustfizzle"}}
E["npc:grish-longrunner"] = {t="npc",n="Grish Longrunner",z="stonetalon",s="Grish Longrunner is a tauren scout and messenger stationed near the Great Lift, the vital mechanical crossing connecting the southern Barrens with the canyons of Thousand Needles. Serving the interests of the Horde along this bustling boundary, he keeps watch over travelers and coordinates military movement across the frontier.",h="Grish Longrunner is a tauren scout and messenger stationed near the Great Lift, the vital mechanical crossing...",sec={{t="Watcher at the Lift",b="Positioned right beside the towering machinery of the Great Lift, Grish Longrunner stands watch over one of central Kalimdor's most precarious border crossings. The platform elevator is a lifeline connecting the arid wastes of the southern Barrens to the windswept mesas of Thousand Needles below. Between roving quilboar packs and competing territorial threats, travel along this vertical boundary is dangerous, making scouts like Grish essential for keeping the Horde informed and summoning reinforcements where they are sorely needed.",sp=0}},faq={{q="Who is Grish Longrunner?",a="Grish Longrunner is a tauren scout aligned with the Horde who is stationed at the rim of the Great Lift, which descends from the Barrens down into Thousand Needles.",al={"who is grish","grish longrunner identity","what does grish do"},it="identity"},{q="Where can I find Grish Longrunner?",a="He is located in the southern reaches of the Barrens, right near the mechanical entrance of the Great Lift leading down to Thousand Needles.",al={"grish longrunner location","where is grish","find grish"},it="place",gp=true},{q="What role does he play in the area?",a="Grish acts as a point of contact for Horde messengers and travelers, notably assisting in rallying and directing local reinforcements through requests like Calling in the Reserves.",al={"grish purpose","grish quests","calling in the reserves grish"},it="purpose"},{q="Whose side is Grish Longrunner on?",a="Grish is a proud member of the tauren tribes and is loyal to the Horde. Operating around the borders of the Barrens and the descent into Thousand Needles, he serves as a point of contact for Horde travelers navigating the dangerous passages between regions.",al={"grish longrunner faction","is grish horde","grish longrunner allegiance"},it="side",add=true}},ang={["faction:Horde"]="For Horde couriers and warriors journeying south toward Thousand Needles or returning north into the Barrens, Grish serves as an important lookout and point of contact at the lift.",["race:Tauren"]="Bearing the proud Longrunner name, Grish represents the endurance and vigilance of the shu'halo as they secure vital routes across their ancestral homelands."},kw={"barrens","calling in the reserves","great lift","grish","longrunner","tauren","thousand needles"},rel={"subzone:great-lift","quest:5881","zone:barrens","zone:thousandneedles","topic:tauren","topic:quilboar"},src={"Grish Longrunner"}}
E["npc:grunt-logmar"] = {t="npc",n="Grunt Logmar",z="stonetalon",s="Grunt Logmar is an orc warrior of the Horde stationed in the southern Barrens at Camp Taurajo. Dutiful and vigilant, he monitors threats surrounding the camp and coordinates efforts to locate and aid missing Horde scouts in the region.",h="Grunt Logmar is an orc warrior of the Horde stationed in the southern Barrens at Camp Taurajo.",sec={{t="Duty at Camp Taurajo",b="Stationed among the tauren at Camp Taurajo, Grunt Logmar serves as a watchful orc guard on the southern Barrens frontier. The settlement sits close to hostile quilboar grounds and the mountain passes leading into Stonetalon and Mulgore, requiring constant vigilance. Logmar coordinates scouting reports and reaches out to capable Horde travelers when his comrades find themselves ambushed or captured by local hostiles.",sp=0}},faq={{q="Who is Grunt Logmar?",a="Grunt Logmar is an orc soldier stationed at Camp Taurajo in the southern Barrens, serving the Horde by securing the settlement and overseeing rescue and reconnaissance tasks.",al={"grunt logmar","who is logmar","logmar barrens"},it="identity"},{q="Where can Grunt Logmar be found?",a="He is located in Camp Taurajo, an outpost situated in the southern plains of the Barrens along the road leading toward the Great Lift and Thousand Needles.",al={"where is logmar","logmar location","find grunt logmar"},it="place",gp=true},{q="What matters does Logmar oversee?",a="Logmar deals with the safety of missing Horde scouts, notably tasking travelers to investigate the disappearance and captivity of fellow grunt Dogran and secure vital supplies like Ken'zigla's draught.",al={"logmar quests","what does logmar want","dogran rescue"},it="purpose"},{q="Whose side is Grunt Logmar on?",a="Grunt Logmar is a loyal soldier of the Horde. Stationed out among the tauren settlements, he serves the Warchief by keeping watch over the southern frontiers and supporting Horde operations across the plains.",al={"is logmar horde","grunt logmar faction","grunt logmar side"},it="side",add=true},{q="Why is Grunt Logmar here?",a="Logmar is stationed as a vanguard guard to bolster defense and maintain military communication. The surrounding wilderness poses constant threats from hostile wildlife, centaur marauders, and nearby quilboar, requiring steadfast soldiers to safeguard travelers and secure the southern Barrens.",al={"why is grunt logmar here","why is logmar in taurajo","logmar post"},it="why_here",add=true},{q="What does Grunt Logmar want?",a="Logmar seeks aid in resolving pressing military emergencies in the region, particularly the rescue and recovery of captured comrades such as Dogran, and securing restorative draughts needed to sustain his fellow fighters in the field.",al={"what does logmar want","grunt logmar goal","what does grunt logmar need"},it="wants",add=true}},ang={["faction:Horde"]="Logmar represents the frontline military presence supporting the tauren in the Barrens, relying on Horde champions to look after fallen and captured scouts.",["race:Orc"]="As an orc grunt stationed far from Orgrimmar, Logmar demonstrates the Horde's commitment to standing shoulder-to-shoulder with their tauren allies."},kw={"camp taurajo","dogran","grunt logmar","ken'zigla's draught","orc grunt","taurajo","the barrens"},rel={"subzone:camp-taurajo","zone:barrens","quest:1515","quest:1511","zone:stonetalon","topic:alliance"},src={"Grunt Logmar"}}
E["npc:kaela-shadowspear"] = {t="npc",n="Kaela Shadowspear",z="stonetalon",s="Kaela Shadowspear is a night elf sentinel stationed southwest of Windshear Crag in the Stonetalon Mountains. From her small outpost, she coordinates with fellow sentinels to monitor escalating tensions and regional disruptions in the wilderness. She relies on brave travelers to scout dangerous territory and bring aid to the land's wounded defenders.",h="Kaela Shadowspear is a night elf sentinel stationed southwest of Windshear Crag in the Stonetalon Mountains.",sec={{t="A Scout on the Frontier",b="Positioned just southwest of the industrial devastation of Windshear Crag, Kaela Shadowspear keeps a watchful vigil over the surrounding passes. The Stonetalon Mountains are fraught with danger as the Horde encroaches and goblin operations exploit the land's natural bounty. Operating alongside the gnome Gaxim Rustfizzle, Kaela acts as an essential forward liaison for the night elves, tracking threats that push deeper into ancestral territory.",sp=0},{t="Healing the Land",b="The unrest in Stonetalon goes far beyond territorial skirmishes. The violent disruption of nature has agitated the elementals and brought harm to ancient guardians of the forest. Kaela works tirelessly to dispatch adventurers against raging elemental spirits and to tend to the wounded ancients suffering in the crossfire of the region's conflicts, striving to restore peace before the land is irrevocably scarred.",sp=0}},faq={{q="Who is Kaela Shadowspear?",a="Kaela Shadowspear is a night elf quest giver stationed in a frontier camp southwest of Windshear Crag in the Stonetalon Mountains. She oversees regional scouting and aids in protecting the local wildlife and spirits.",al={"who is kaela","kaela shadowspear identity","kaela npc"},it="identity"},{q="Where can Kaela Shadowspear be found?",a="She is located in a small Alliance camp situated southwest of Windshear Crag along the road in the Stonetalon Mountains, sharing the camp with the gnome engineer Gaxim Rustfizzle.",al={"kaela shadowspear location","where is kaela","kaela stonetalon camp"},it="place",gp=true},{q="Who does Kaela report to?",a="Kaela coordinates closely with Sentinel Thenysil, regularly sending and receiving intelligence updates on enemy movements and local threats across Stonetalon.",al={"kaela reports to who","kaela thenysil","kaela's commander"},it="ties"},{q="Why is Kaela concerned about the elementals?",a="Intense logging, mining, and military encroachment in Stonetalon have deeply disturbed the natural balance, causing elemental spirits to fly into a rage and attack anyone nearby.",al={"enraged spirits quest","why are spirits angry","kaela elemental spirits"},it="threat"},{q="What is happening to the ancients near Windshear Crag?",a="The regional conflicts and rapid deforestation have left ancient protectors wounded and suffering. Kaela seeks the aid of travelers to find and heal these fallen protectors of the wild.",al={"wounded ancients quest","kaela ancients","stonetalon wounded ancients"},it="danger"},{q="Why is a gnome stationed with Kaela?",a="Kaela shares her camp with Gaxim Rustfizzle, an Alliance gnome. While Kaela focuses on the spiritual and tactical balance of the wilderness, Gaxim is concerned with counteracting the hostile goblin machinery and operations nearby.",al={"gaxim rustfizzle kaela","why is gaxim with kaela","gnome and night elf camp"},it="allies"},{q="Whose side is Kaela Shadowspear on?",a="Kaela stands firmly with the night elves and the Alliance. Stationed in Stonetalon, she serves Darnassus and sentinel command, coordinating closely with fellow Alliance scouts to defend the land against encroaching adversaries.",al={"kaela shadowspear faction","is kaela alliance","kaela shadowspear allegiance"},it="side",add=true},{q="What does Kaela Shadowspear want?",a="Kaela aims to protect the Stonetalon Mountains from devastation. She seeks to soothe the enraged elemental spirits, tend to the wounded ancients suffering in the area, and keep her commanders informed of regional threats.",al={"kaela shadowspear goal","what does kaela want","kaela objectives"},it="wants",add=true},{q="Why is Kaela Shadowspear here?",a="Kaela is deployed southwest of Windshear Crag as a sentinel scout. From this outpost, she monitors disturbances across Stonetalon, particularly the plight of the corrupted local spirits and the distress of the nearby ancients.",al={"why is kaela shadowspear in stonetalon","kaela shadowspear mission","why is kaela here"},it="why_here",add=true}},ang={["faction:Alliance"]="Kaela Shadowspear serves as a crucial point of contact for Alliance adventurers venturing into the contested reaches of Stonetalon, coordinating intelligence between distant outposts.",["race:NightElf"]="For the night elves, Kaela represents the steadfast defense of sacred ground, laboring to soothe outraged spirits and safeguard the revered ancients of Kalimdor.",["class:Druid"]="Druids will find common cause with Kaela's efforts to nurse injured ancients back to health and silence the agony of disturbed nature spirits."},kw={"ancients","kaela","rustfizzle","sentinel","shadowspear","spirits","stonetalon","thenysil","windshear"},rel={"subzone:windshear-crag","npc:sentinel-thenysil","npc:gaxim-rustfizzle","quest:1084","quest:1083","quest:1091","quest:1082","zone:stonetalon"},src={"Kaela Shadowspear"}}
E["npc:keeper-albagorm"] = {t="npc",n="Keeper Albagorm",z="stonetalon",s="Keeper Albagorm is a keeper of the grove stationed at the idyllic sanctuary of Stonetalon Peak. Deeply concerned by the devastation corrupting the southern reaches of the mountains, he enlists travelers to help heal the scorched wilderness of the Charred Vale.",h="Keeper Albagorm is a keeper of the grove stationed at the idyllic sanctuary of Stonetalon Peak.",sec={{t="A Guardian on the Peak",b="Perched within the peaceful boughs of Stonetalon Peak, Keeper Albagorm stands vigil over one of Kalimdor's sacred elven refuges. Like many sons of Cenarius, he feels the pain of the natural world acutely. His attention is drawn southward toward the smoldering ruins of the Charred Vale, set afire by a greedy mechanized army of industrialists and now held by Bloodfury harpies who block any regrowth. From his sanctuary, Albagorm works tirelessly to halt the spread of the corruption and restore balance to the wounded forest.",sp=0}},faq={{q="Who is Keeper Albagorm?",a="He is a keeper of the grove—one of the demigod offspring of Cenarius—stationed at Stonetalon Peak in the Stonetalon Mountains. He serves as an ally to the night elves and natural guardians of Kalimdor.",al={"keeper albagorm","who is albagorm","albagorm stonetalon"},it="identity"},{q="Where can I find Keeper Albagorm?",a="He resides at Stonetalon Peak, an Alliance-aligned druidic refuge nestled high in the northwestern corner of the Stonetalon Mountains.",al={"keeper albagorm location","where is albagorm","albagorm coords"},it="place",gp=true},{q="What does Keeper Albagorm want help with?",a="Albagorm seeks to mend the devastation of the Charred Vale. He sends capable adventurers into the ash-choked basin to cleanse the blighted landscape and drive out the Bloodfury harpies preventing natural regrowth.",al={"keeper albagorm quests","what does albagorm want","reclaiming the charred vale"},it="wants"},{q="Whose side is Keeper Albagorm on?",a="Keeper Albagorm is aligned with the night elves and the Cenarion druids of Stonetalon Peak, offering his counsel and guidance to champions of the Alliance. Like all sons of Cenarius, his deeper loyalty lies with the balance of nature, seeking out allies who are willing to aid in healing Kalimdor's scarred landscapes.",al={"keeper albagorm faction","albagorm alliance or horde","is albagorm friendly"},it="side",add=true},{q="Why is Keeper Albagorm here at Stonetalon Peak?",a="Keeper Albagorm watches over the sanctuary of Stonetalon Peak, a vital bastion of nature tucked high in the mountains. From this haven, he observes the corruption and destruction spreading across the region, directing trustworthy travelers to push back the blight and mend the devastation threatening the Charred Vale nearby.",al={"why is albagorm at stonetalon peak","albagorm purpose stonetalon","keeper albagorm role"},it="why_here",add=true},{q="Who is Keeper Albagorm tied to?",a="As a keeper of the grove, Albagorm is one of the revered sons of Cenarius, linking him by sacred bloodline directly to the Demigod of the Moon and the natural order. In Stonetalon, he stands closely alongside the local night elven sentinels and Cenarion protectors stationed at the mountain's peak.",al={"keeper albagorm ties","albagorm connections","who does albagorm answer to"},it="ties",add=true}},ang={["class:Druid"]="As a keeper of the grove, Albagorm shares a direct connection to the Cenarion lineage, making his efforts to cleanse the Charred Vale deeply personal to druids.",["faction:Alliance"]="Albagorm offers shelter and guidance to Alliance forces navigating through the night elven sanctuary at Stonetalon Peak."},kw={"cenarius","charred vale","keeper albagorm","keeper of the grove","stonetalon","stonetalon peak"},rel={"subzone:stonetalon-peak","quest:1057","subzone:charred-vale","zone:stonetalon"},src={"Keeper Albagorm"}}
E["npc:lomac-gearstrip"] = {t="npc",n="Lomac Gearstrip",z="stonetalon",s="Lomac Gearstrip is an ambitious gnome inventor based in Tinker Town within Ironforge. Renowned for formulating the devastating NG-5 explosive, he liaises with fellow gnomish researchers operating across Kalimdor.",h="Lomac Gearstrip is an ambitious gnome inventor based in Tinker Town within Ironforge.",sec={{t="A Spark in Tinker Town",b="Amid the clanging gears and hissing pipes of Ironforge's Tinker Town, Lomac Gearstrip pursues the finer points of gnomish ordnance. Like many exiled gnomes who fled the tragedy at Gnomeregan, Lomac has integrated his tinkering operations directly into the dwarven capital. His workshop focuses on volatile chemical mixtures and specialized munitions designed to overcome heavily defended enemy strongholds.",sp=0},{t="The NG-5 Explosive",b="Lomac's proudest contribution to modern combat engineering is the NG-5 explosive. Formulated for maximum destructive yield, the compound demands precise handling and rare chemical reagents. To refine and deploy such hazardous inventions in the field, Lomac maintains contact with old colleagues stationed in distant theaters, exchanging technical orders and dangerous supplies across the Great Sea.",sp=0}},faq={{q="Where can I find Lomac Gearstrip?",a="Lomac Gearstrip resides in Tinker Town, the gnomish quarter located in the eastern portion of the mountain city of Ironforge.",al={"lomac gearstrip location","where is lomac","find lomac gearstrip"},it="place",gp=true},{q="What is Lomac Gearstrip famous for inventing?",a="Lomac is best known as the creator of the NG-5 explosive, a potent ordnance formula designed to provide devastating firepower for gnomish endeavors.",al={"what did lomac make","lomac invention","ng-5 explosive creator"},it="fame"},{q="Why does Lomac deal with contacts in Kalimdor?",a="Lomac keeps in touch with former research peers and colleagues working in frontier regions like Stonetalon Mountains, coordinating the procurement of hazardous chemical ingredients and testing his high-yield explosives in active operations.",al={"lomac stonetalon","why stonetalon quest","lomac colleagues"},it="why_here"},{q="What kind of tasks does Lomac offer to adventurers?",a="Lomac tasks trustworthy Alliance couriers with transporting purchase orders and volatile chemical reagents between Ironforge and researchers stationed abroad, often involving his NG-5 explosive experiments.",al={"lomac quests","ineptitude chemicals fun","an old colleague quest"},it="purpose",gp=true},{q="What is the Purchase Order Receipt tied to Lomac?",a="Lomac authored the Purchase Order Receipt, a manifest used to organize and document shipments of specialized equipment and dangerous volatile reagents between tinkerers.",al={"purchase order receipt","lomac receipt"},it="item",gp=true},{q="Is Lomac affiliated with Gnomeregan's refugees?",a="Yes. Like the rest of the residents of Tinker Town, Lomac is part of the displaced Gnomeregan community living under the hospitality of the Ironforge dwarves while continuing his engineering work.",al={"is lomac from gnomeregan","lomac faction"},it="side"},{q="Who is Lomac Gearstrip?",a="Lomac Gearstrip is an ambitious gnomish inventor and tinker operating out of Tinker Town within the dwarven stronghold of Ironforge. Deeply engrossed in volatile experimentation and chemical engineering, he is best known for developing potent ordnances like the NG-5 explosive. Despite the distance across the Great Sea, he maintains contacts and business arrangements stretching as far as Kalimdor to acquire the rare materials and field testing he needs.",al={"who is lomac","who is gearstrip","lomac gearstrip lore"},it="identity",add=true},{q="What does Lomac Gearstrip want?",a="Lomac Gearstrip is driven by his explosive engineering projects, most notably the refinement of his prized NG-5 charge. To keep his chemical trials moving forward, he requires couriers, volatile compounds, and field tests conducted with his concoctions. He relies on travelers and old acquaintances across the world to fulfill purchase orders and procure the rare reagents necessary to perfect his volatile inventions.",al={"what does lomac want","lomac gearstrip goals","why does lomac need help"},it="wants",add=true},{q="Who is Lomac Gearstrip tied to?",a="Lomac maintains ties with distant associates and fellow tinkers, including an old colleague based abroad who assists with orders and specialized testing. Working from Tinker Town, he operates comfortably alongside both the Gnomeregan exiles and Ironforge's resident craftsmen, directing couriers and adventurers to liaise between his workbench in the Eastern Kingdoms and testing grounds across Kalimdor.",al={"who does lomac work with","lomac gearstrip associates","lomac old colleague"},it="ties",add=true}},ang={["profession:Engineering"]="Lomac's NG-5 explosive represents the cutting edge of gnomish pyrotechnics, serving as inspiration for tinkerers interested in high-yield blasting compounds.",["race:Gnome"]="Lomac embodies the resilient drive of Tinker Town's gnomes, maintaining high-stakes technical research even while living in exile from Gnomeregan.",["faction:Alliance"]="Alliance operatives moving between Ironforge and expedition outposts in Kalimdor often handle sensitive munitions and volatile formulas on Lomac's behalf."},kw={"an old colleague","gnome engineer","ineptitude + chemicals = fun","ironforge","lomac gearstrip","ng-5 explosive","stonetalon","tinker town"},rel={"subzone:tinker-town","zone:ironforge","quest:1072","quest:1073","zone:stonetalon","topic:gnome"},src={"Lomac Gearstrip"}}
E["npc:maggran-earthbinder"] = {t="npc",n="Maggran Earthbinder",z="stonetalon",s="Maggran Earthbinder is a grizzled tauren veteran appointed by High Chieftain Cairne Bloodhoof to lead the Horde encampment at Sun Rock Retreat. Hardened by a lifetime of brutal conflict, he oversees the defense of the craggy valleys of Stonetalon against ravenous beasts and aggressive harpy covens. Though wearied by countless battles, he remains a steadfast guardian of the settlement.",h="Maggran Earthbinder is a grizzled tauren veteran appointed by High Chieftain Cairne Bloodhoof to lead the...",sec={{t="A Veteran's Haven",b="Maggran Earthbinder was sent into the Stonetalon Mountains by High Chieftain Cairne Bloodhoof himself. A veteran of countless skirmishes and bloody campaigns, Maggran admits that age and violence have hardened his heart, stripping away the natural gentleness typical of his people. Sun Rock Retreat was meant to be both an outpost under his steady command and a place of respite, where warm winds and mountain sunshine might soothe his battle-worn spirit.",sp=0},{t="Threats in the Crags",b="Even in Stonetalon, Maggran finds little peace. As overseer of Sun Rock Retreat, he coordinates defense efforts against the Bloodfury harpies nesting in the peaks and marshals fighters to counter predatory perils across the crags. Having once survived an ambush by the giant spider Besseleth herself, Maggran holds no illusions about the deadly wilderness around them and frequently enlists travelers to eliminate deadly regional predators before they overrun the outpost.",sp=0}},faq={{q="Who is Maggran Earthbinder?",a="Maggran Earthbinder is the commanding tauren elder at Sun Rock Retreat in the Stonetalon Mountains. Hardened by countless battles, he was stationed here by Cairne Bloodhoof to watch over the settlement and keep its supply roads and borders secure.",al={"maggran","who is maggran","sun rock retreat leader"},it="identity"},{q="Why was Maggran sent to Sun Rock Retreat?",a="Cairne Bloodhoof appointed him to lead Sun Rock Retreat partly for his seasoned military leadership and partly as a retreat. Maggran's body and soul have been heavily worn by a lifetime of combat, and the quiet mountain sun offers him a measure of healing.",al={"why is maggran here","maggran background","cairne and maggran"},it="why_here"},{q="What threats does Maggran ask adventurers to deal with?",a="Maggran directs defense efforts against the savage Bloodfury harpies infesting the mountains and sends warriors to eliminate the giant spider matriarch Besseleth, a terrifying predator he narrowly escaped earlier in his travels.",al={"maggran quests","what does maggran want","harpies stonetalon"},it="wants"},{q="What happened between Maggran and Besseleth?",a="Maggran was previously bitten by the colossal spider Besseleth. Though he managed to fend her off and escape with his life, he sends capable adventurers to slay the beast so no one else falls victim to her web.",al={"maggran besseleth","spider quest maggran","arachnophobia lore"},it="history"},{q="Does Maggran have a role in Thunder Bluff?",a="Maggran serves directly at the behest of Thunder Bluff's High Chieftain, Cairne Bloodhoof. While stationed out in the field at Sun Rock Retreat, his authority and orders stem straight from the capital.",al={"maggran thunder bluff","maggran cairne"},it="ties"},{q="Is Maggran Earthbinder friendly to Alliance players?",a="No. Maggran is a staunch leader of the Horde and remains fully hostile to any Alliance adventurers who stumble into Sun Rock Retreat.",al={"can alliance talk to maggran","maggran hostile"},it="side"}},ang={["race:Tauren"]="Maggran embodies the heavy toll warfare takes on the shu'halo spirit, serving as a reminder of how conflict can harden even the most grounded children of the Earth Mother.",["faction:Horde"]="For travelers navigating the steep climbs of Stonetalon, Maggran is the primary authority coordinating local Horde patrols and keeping supply routes clear of beasts and harpies."},kw={"besseleth","bloodfury","cairne bloodhoof","earthbinder","harpies","maggran","stonetalon","sun rock retreat"},rel={"subzone:sun-rock-retreat","zone:stonetalon","quest:6284","quest:6282","quest:6283","quest:5881","topic:tauren","zone:thunderbluff"},src={"Maggran Earthbinder"}}
E["npc:makaba-flathoof"] = {t="npc",n="Makaba Flathoof",z="stonetalon",s="Makaba Flathoof is a tauren survivor hailing from Camp Aparaje in the Stonetalon Mountains. Having witnessed the devastation of his home and people at the hands of the Grimtotem clan, he seeks brave champions of the Horde to bring vengeance upon the attackers and ensure his family's safety.",h="Makaba Flathoof is a tauren survivor hailing from Camp Aparaje in the Stonetalon Mountains.",sec={{t="Tragedy at Camp Aparaje",b="Makaba Flathoof represents the tragic toll of internal strife among the tauren. His home, Camp Aparaje in the Stonetalon Mountains, fell victim to a ruthless surprise attack by the Grimtotem clan. While many tauren strive for peace and unity under the leadership of Cairne Bloodhoof, the treacherous Grimtotem continually sow discord and violence, leaving survivors like Makaba displaced and grieving.",sp=0},{t="A Plea for Vengeance",b="Unable to retake his fallen settlement alone, Makaba calls upon travelers of the Horde to strike back. He directs fierce retaliation against the Grimtotem renegades who overran his home, demanding justice for the slaughter of his kin. His most urgent concerns center on confronting the warlord responsible, Grundig Darkcloud, and finding word of his missing family member, Kaya.",sp=1}},faq={{q="Who is Makaba Flathoof?",a="Makaba Flathoof is a tauren refugee from Camp Aparaje in the Stonetalon Mountains. His village was overrun and sacked by the Grimtotem clan, driving him to seek help from Horde adventurers.",al={"makaba","who is makaba flathoof","makaba flathoof lore"},it="identity"},{q="Where did Makaba come from?",a="Makaba hails from Camp Aparaje, a small tauren settlement located in the Stonetalon Mountains that was attacked and devastated by the Grimtotem.",al={"makaba origin","where is makaba from","camp aparaje makaba"},it="origin"},{q="Who attacked Makaba's village?",a="Camp Aparaje was sacked by the Grimtotem clan, an aggressive and treacherous faction of tauren led locally by figures like Grundig Darkcloud.",al={"who attacked camp aparaje","makaba enemies","who sacked aparaje"},it="conflict"},{q="What does Makaba want Horde adventurers to do?",a="Makaba seeks vengeance for his fallen home, asking capable warriors to cut down the Grimtotem forces at Camp Aparaje, eliminate their leader Grundig Darkcloud, and discover the fate of Kaya Flathoof.",al={"makaba quests","what does makaba ask for","makaba tasks"},it="wants"},{q="Who is Kaya to Makaba?",a="Kaya Flathoof is a relative of Makaba who went missing during the attack on Camp Aparaje. Makaba desperately hopes to learn if she survived the assault.",al={"kaya flathoof","who is kaya","makaba relative kaya"},it="ties"},{q="Is Makaba related to Dim Flathoof?",a="Both Makaba and Dim share the Flathoof family surname, indicating they are part of the same tauren lineage, though their specific degree of relation is not deeply detailed.",al={"dim flathoof","makaba and dim","flathoof family"},it="ties"},{q="Whose side is Makaba Flathoof on?",a="Makaba Flathoof is a loyal member of the Horde and the tauren people. Fleeing the violence that struck his home, he seeks assistance exclusively from Horde travelers and champions to protect his kin and strike back against their attackers.",al={"makaba flathoof faction","is makaba horde","who does makaba serve"},it="side",add=true},{q="Why is Makaba Flathoof here?",a="Makaba has taken refuge in Stonetalon after tragedy struck his home at Camp Aparaje. Driven from his settlement by violent raiders, he now stays here seeking aid to avenge his fallen kin and ensure the safety of survivors like Kaya.",al={"why is makaba flathoof here","why is makaba in stonetalon","makaba flathoof purpose"},it="why_here",add=true}},ang={["race:Tauren"]="For tauren heroes, Makaba's plight highlights the bitter treachery of the Grimtotem, serving as a reminder that not all of their kin honor the ways of peace and unity.",["faction:Horde"]="Makaba's calls for aid allow Horde champions to prove their loyalty to their tauren allies by punishing those who butcher peaceful encampments."},kw={"camp aparaje","flathoof","grimtotem","grundig darkcloud","kaya","makaba","stonetalon"},rel={"subzone:camp-aparaje","quest:6548","quest:6629","quest:6523","quest:6401","zone:stonetalon","topic:tauren"},src={"Makaba Flathoof"}}
E["npc:mor-rogal"] = {t="npc",n="Mor'rogal",z="stonetalon",s="Mor'rogal is a tauren resident of Sun Rock Retreat in the Stonetalon Mountains. He serves as an advisor and guide for travelers seeking glory and peril within the rugged subterranean reaches of the crags.",h="Mor'rogal is a tauren resident of Sun Rock Retreat in the Stonetalon Mountains.",sec={{t="Watcher in the Crags",b="Perched within the refuge of Sun Rock Retreat, Mor'rogal takes a keen interest in the deep crevices and caverns that cut through the Stonetalon Mountains. Recognizing that the region's twisting subterranean passes offer both great riches and lethal danger, he directs brave Horde wanderers to investigate troubled areas like the Boulderslide Ravine. For Mor'rogal, delving into these treacherous depths is not merely a matter of survival, but a test of spirit for those who follow their heart and soul in search of glory.",sp=0}},faq={{q="Who is Mor'rogal?",a="Mor'rogal is a tauren quest giver residing in Sun Rock Retreat within the Stonetalon Mountains. He acts as a local guide, urging Horde adventurers to test their mettle in the dangerous caves and ravines scattered across the craggy mountain range.",al={"morrogal","who is mor'rogal","mor rogal lore"},it="identity"},{q="Where can I find Mor'rogal?",a="He can be found standing in Sun Rock Retreat, the primary Horde outpost situated around the peaceful mountain lake in the central Stonetalon Mountains.",al={"mor'rogal location","where is mor'rogal","morrogal spot"},it="place",gp=true},{q="What tasks does Mor'rogal offer?",a="Mor'rogal enlists capable champions to venture into the cave at Boulderslide Ravine, where kobolds are frantically mining Resonite crystals, and then to slay Goggeroc, a slumbering Earthen the kobolds dug up.",al={"mor'rogal quests","what does mor'rogal want"},it="purpose",gp=true},{q="Why is Mor'rogal focused on caves and ravines?",a="Mor'rogal believes that the perilous subterranean caverns of Stonetalon hold true adventures and tests of spiritual resolve, offering glory and riches to those willing to risk their lives.",al={"why caves","mor'rogal caves"},it="why_here"},{q="Whose side is Mor'rogal on?",a="Mor'rogal is aligned with the Horde and his fellow tauren. Stationed within Sun Rock Retreat, a secluded Horde outpost high in the Stonetalon Mountains, he offers guidance and assignments to adventurers who serve the Horde's interests in the region.",al={"mor'rogal faction","mor'rogal horde or alliance","mor'rogal loyalty"},it="side",add=true},{q="What does Mor'rogal want?",a="Mor'rogal seeks brave adventurers willing to brave the perilous caves and ravines of the Stonetalon Mountains. He directs scouts into hostile places like Boulderslide Ravine, urging bold spirits to confront the earthen dangers lurking underground in exchange for honor and riches.",al={"mor'rogal goals","what is mor'rogal doing","mor'rogal quests purpose"},it="wants",add=true}},ang={["race:Tauren"]="Mor'rogal embodies the tauren respect for physical and spiritual testing, viewing the deep stone hollows of Kalimdor as sacred ground to prove one's worth.",["faction:Horde"]="For travelers reaching the haven of Sun Rock Retreat, Mor'rogal provides crucial intelligence on the threats lurking in the crags beyond the settlement's borders."},kw={"boulderslide ravine","earthen arise","mor'rogal","morrogal","stonetalon","sun rock retreat","tauren"},rel={"subzone:sun-rock-retreat","zone:stonetalon","quest:6421","quest:6481","topic:tauren","zone:thunderbluff"},src={"Mor'rogal"}}
E["npc:piznik"] = {t="npc",n="Piznik",z="stonetalon",s="Piznik is a disgruntled goblin surveyor hiding deep within Windshear Mine in the Stonetalon Mountains. Once a high-ranking overseer in the local Venture Company operations, he was sidelined by the ruthless Gerenzo Wrenchwhistle. Now nurseing a grudge, Piznik secretly gathers intel to undermine his former workplace.",h="Piznik is a disgruntled goblin surveyor hiding deep within Windshear Mine in the Stonetalon Mountains.",sec={{t="Fallen from Grace",b="Before Gerenzo Wrenchwhistle seized supreme authority over Windshear Crag, Piznik held the enviable title of second-in-command across the entire operation. However, corporate restructuring in the Venture Company is unforgiving. Once Gerenzo took full control, Piznik found himself pushed aside and relegated to the murky depths of Windshear Mine. Rather than accepting his demotion quietly, Piznik bides his time underground, keeping a watchful eye on mine movements and quietly plotting revenge against the boss who demoted him.",sp=0},{t="Corporate Espionage",b="Piznik's quiet rebellion took a practical turn through an alliance with Ziz Fizziks, an operative stationed outside who was similarly cast out by Gerenzo. Operating as Ziz's inside man, Piznik gathers what he can about Gerenzo's plans. By smuggling out a sample of the mysterious gold-green ore Gerenzo has ordered mined in bulk and sending it on to Ziz, Piznik works to disrupt the Venture Company's deforestation and mining efforts from the shadows, ensuring that Gerenzo's ambitious leadership faces constant, agonizing setbacks.",sp=1}},faq={{q="Where can I find Piznik?",a="Piznik is tucked away inside Windshear Mine, a cavern complex carved into the slopes of Windshear Crag in the Stonetalon Mountains. You will find him deep within the tunnels surrounded by Venture Company workers.",al={"piznik location","where is piznik","find piznik stonetalon"},it="place",gp=true},{q="What is Piznik's grudge against Gerenzo Wrenchwhistle?",a="Piznik was formerly the second-highest authority in Windshear Crag. When Gerenzo Wrenchwhistle took total command of the logging and mining project, he demoted Piznik, leaving the former supervisor resentful and eager to see Gerenzo ruined.",al={"why does piznik hate gerenzo","piznik gerenzo feud"},it="conflict"},{q="How does Piznik fit into Ziz Fizziks' plans?",a="Ziz Fizziks was fired outright by Gerenzo, whereas Piznik was merely demoted. Piznik uses his remaining access deep inside Windshear Mine to act as an informant, gathering word of Gerenzo's plans and getting a sample of the mysterious ore Gerenzo has ordered mined out to Ziz.",al={"piznik and ziz","who does piznik work with"},it="ties"},{q="Is Piznik still loyal to the Venture Company?",a="Only on paper. While he still wears the mantle of a Venture Company employee to remain within the mine, Piznik's true allegiance is entirely to his own self-interest and his desire to sabotage Gerenzo.",al={"is piznik venture co","piznik faction"},it="side"},{q="Who is Piznik?",a="Piznik is a goblin operative hiding deep inside Windshear Mine within the Stonetalon Mountains. He was once the second-in-command of the entire Venture Company operation across Windshear Crag, enjoying considerable status and influence until Gerenzo Wrenchwhistle arrived, took control, and systematically stripped him of his position.",al={"who is piznik","piznik lore","piznik background"},it="identity",add=true},{q="What does Piznik want?",a="Piznik wants payback against Gerenzo Wrenchwhistle for ruining his standing in the Venture Company. Rather than confronting Gerenzo openly, he seeks to sabotage his rival from the shadows, secretly gathering Gerenzo's orders and confidential documents to aid allies who are working to undermine Gerenzo's hold over Windshear Crag.",al={"what does piznik want","piznik goal","piznik motive"},it="wants",add=true},{q="Why is Piznik in Windshear Mine?",a="After Gerenzo Wrenchwhistle seized control of the Venture Company's local enterprise, Piznik retreated into the depths of Windshear Mine. He remains hidden inside the tunnels to stay out of Gerenzo's sight while acting as an internal informant, quietly collecting intelligence without alerting the rest of the operation.",al={"why is piznik here","why is piznik in windshear mine","piznik location reason"},it="why_here",add=true}},ang={["profession:Mining"]="Miners traversing Windshear Mine will cross paths with Piznik, a living example of how rapidly organizational rank can plummet beneath the weight of corporate greed."},kw={"gerenzo wrenchwhistle","piznik","stonetalon","venture co","windshear crag","windshear mine","ziz fizziks"},rel={"quest:1090","quest:1096","quest:1483","subzone:windshear-crag","zone:stonetalon","topic:goblin"},src={"Piznik"}}
E["npc:sentinel-thenysil"] = {t="npc",n="Sentinel Thenysil",z="stonetalon",s="Sentinel Tara Thenysil is a night elf sentinel stationed in Astranaar within the ancient forest of Ashenvale. Vigilant over the surrounding wilderness, she keeps close tabs on military operations in the region and coordinates scouts watching neighboring territories. Her attention is particularly focused on allied movements pushing south into the contested Stonetalon Mountains.",h="Sentinel Tara Thenysil is a night elf sentinel stationed in Astranaar within the ancient forest of Ashenvale.",sec={{t="Watching the Borders",b="From her post in the fortified settlement of Astranaar, Sentinel Thenysil helps secure Ashenvale against growing hostility. Night elf holdings throughout the region face relentless encroachment, making communications between distant outposts vital. While much of the local garrison focuses directly on defending the forest road, Thenysil directs Alliance volunteers beyond Ashenvale's borders to ensure distant allies remain supported.",sp=0},{t="Ties to Stonetalon",b="Thenysil maintains a close personal and military friendship with Kaela Shadowspear, an operative deployed south into the crags of the Stonetalon Mountains. Learning that Kaela was dispatched alongside an eccentric gnome mage, Thenysil considered the unorthodox pairing an unmistakable sign of serious trouble brewing in the peaks. Wary of what dangers her comrade might face, she recruits capable adventurers to journey south, deliver support, and report on the unfolding mission.",sp=0},{t="Audience in the Canopy",b="When scouts return from Stonetalon with word of successful strikes against the defiling Venture Company, Thenysil ensures their deeds do not go unnoticed. Recognizing that repelling mechanized exploitation in the mountains protects the sanctity of all neighboring wilds, she grants reliable heroes a formal commendation. Rather than hoarding credit in Astranaar, she directs them up to the Temple of the Moon in Darnassus for a personal reception before High Priestess Tyrande Whisperwind.",sp=1}},faq={{q="Where can Sentinel Thenysil be found?",a="Sentinel Thenysil is stationed in Astranaar, the primary night elf stronghold located along the central road in Ashenvale.",al={"thenysil location","where is sentinel thenysil","thenysil astranaar"},it="place",gp=true},{q="Why does Thenysil send travelers to Stonetalon Mountains?",a="Her friend, Kaela Shadowspear, was deployed to Stonetalon alongside a gnome mage. Viewing that unusual assignment as an omen of dangerous trouble, Thenysil sends dependable adventurers to reinforce Kaela's mission.",al={"why stonetalon","thenysil quest stonetalon","on guard in stonetalon why"},it="wants"},{q="Who is Kaela Shadowspear?",a="Kaela Shadowspear is a night elf scout and a close friend of Sentinel Thenysil. She is stationed in the Stonetalon Mountains investigating threats to the land.",al={"who is kaela","kaela shadowspear relation","thenysil friend"},it="ties"},{q="What threats are being fought in Stonetalon?",a="Beyond skirmishes with local adversaries, the Venture Company has established invasive, destructive industrial operations in the Stonetalon Mountains, strip-mining and deforesting the landscape.",al={"stonetalon threat","what is happening in stonetalon","venture co stonetalon"},it="threat"},{q="Why does Thenysil send adventurers to Tyrande Whisperwind?",a="After adventurers successfully assist Kaela Shadowspear in halting the Venture Company's schemes in Stonetalon, Thenysil sends them to Darnassus so that High Priestess Tyrande Whisperwind can personally acknowledge their service to the night elves.",al={"reception from tyrande","why see tyrande","thenysil darnassus referral"},sp=1,it="motive"},{q="What is Sentinel Thenysil's role in Astranaar?",a="She serves as a sentinel coordinator in Astranaar, helping organize regional intelligence, monitor borders, and dispatch reliable Alliance recruits to support distant garrisons.",al={"thenysil rank","what does thenysil do","sentinel thenysil duties"},it="identity"},{q="Whose side is Sentinel Thenysil on?",a="Sentinel Thenysil is dedicated to the night elves and the Alliance. As an active soldier in the Sentinels based in Astranaar, she guards the borders of Ashenvale and coordinates support for night elf outposts and operations across Kalimdor.",al={"sentinel thenysil faction","who does thenysil serve","is thenysil alliance"},it="side",add=true},{q="Why is Sentinel Thenysil in Astranaar?",a="Astranaar is the primary night elf hub in Ashenvale, serving as a frontline command post for defending the forest. Sentinel Thenysil is stationed there to help maintain vigil over the region, watch trade routes, and recruit capable travelers when neighboring lands require urgent reinforcement.",al={"why is thenysil in astranaar","thenysil post ashenvale","why is sentinel thenysil here"},it="why_here",add=true}},ang={["race:NightElf"]="Thenysil represents the diligent watch of the Sentinels, working tirelessly to shield Kalimdor's sacred groves and keep allied operatives safe across border frontiers.",["faction:Alliance"]="Serving as an early bridge between Ashenvale and the Stonetalon Mountains, Thenysil provides Alliance adventurers an opportunity to earn direct favor with the leadership in Darnassus.",["race:Gnome"]="Thenysil finds the deployment of an alliance gnome mage to Stonetalon to be an unusual and alarming sign, highlighting how curious night elves still find their diminutive allies."},kw={"ashenvale","astranaar","kaela shadowspear","sentinels","stonetalon","tara thenysil","thenysil","tyrande whisperwind"},rel={"subzone:astranaar","npc:kaela-shadowspear","quest:1070","quest:1082","quest:1081","zone:ashenvale","zone:stonetalon","npc:tyrande-whisperwind"},src={"Sentinel Thenysil"}}
E["npc:tammra-windfield"] = {t="npc",n="Tammra Windfield",z="stonetalon",s="Tammra Windfield is a tauren resident of Sun Rock Retreat, nestled within the heights of the Stonetalon Mountains. Deeply attuned to the balance of the land, she guides Horde travelers in honoring the natural cycle of renewal and keeping hope alive amid the peaks. Her concerns lie with both the health of the untamed wilderness and the safety of her kin.",h="Tammra Windfield is a tauren resident of Sun Rock Retreat, nestled within the heights of the Stonetalon...",sec={{t="A Warden of Sun Rock",b="Sun Rock Retreat serves as a vital sanctuary for the Horde within the craggy peaks of Stonetalon, surrounded by hostile harpies, Venture Company loggers, and lurking predators. Tammra Windfield stands among the settlement's caretakers, keeping a watchful eye on both the mountain wilderness and travelers who cross its threshold. Her gentle demeanor belies the resolve necessary to maintain a home in such rugged terrain.",sp=0},{t="Nurturing the Land",b="Like many of her people, Tammra honors the Earth Mother by observing the constant rhythm of growth and decay in nature. Through the tasks she entrusts to travelers—such as tending the cycle of rebirth and bringing forth new life—she works to counter the ravages that conflict and exploitation bring upon Stonetalon. To Tammra, protecting the land requires active healing, ensuring that life flourishes even in scarred mountain soil.",sp=0},{t="Kinship and Vigilance",b="Beyond her spiritual duties to the surrounding wild, Tammra bears deep concern for the companions and kin who brave the treacherous trails of the Stonetalon Mountains. When word spreads that travelers or family have vanished along the crags, she is among the first to seek out reliable aid. For Tammra, the endurance of Sun Rock Retreat depends as much on mutual protection and loyalty as it does on harmony with nature.",sp=0}},faq={{q="Who is Tammra Windfield?",a="Tammra Windfield is a tauren quest giver residing at Sun Rock Retreat in the Stonetalon Mountains. She is dedicated to the well-being of the settlement, the natural cycle of the mountain landscape, and the survival of her fellow travelers.",al={"who is tammra","tammra windfield","sun rock retreat tammra"},it="identity"},{q="Where can I find Tammra Windfield?",a="She is located inside Sun Rock Retreat, the Horde encampment tucked away in the western heights of the Stonetalon Mountains, accessed via a mountain trail branching off the main valley road.",al={"tammra windfield location","where is tammra","find tammra windfield"},it="place",gp=true},{q="What quests does Tammra offer?",a="Tammra is involved in tasks focusing on renewal and the welfare of her kin, including 'Cycle of Rebirth' and 'New Life', and she receives travelers reporting on the survival of kin in 'Kaya's Alive'.",al={"tammra quests","tammra windfield quest list"},gp=true},{q="What is Tammra's role in Sun Rock Retreat?",a="Tammra acts as a community anchor and spiritual caretaker, directing adventurers to restore vitality to the surrounding wilderness and tending to the bonds that keep the remote outpost safe.",al={"what does tammra do","tammra role"},it="purpose"},{q="Why does Tammra care about the natural cycle?",a="In tauren culture, maintaining balance requires nurturing the Earth Mother's cycles of death and regeneration. With outside forces and mountain beasts threatening the region, Tammra seeks to cultivate new life to heal the bruised wilderness.",al={"cycle of rebirth lore","why rebirth stonetalon"},it="wants"},{q="Is Tammra friendly to Alliance players?",a="No. Sun Rock Retreat is a dedicated Horde outpost, and Tammra is aligned with Thunder Bluff and the Horde, making her hostile to Alliance intruders.",al={"is tammra hostile","can alliance talk to tammra"},it="side"},{q="Why is Tammra Windfield in Sun Rock Retreat?",a="Tammra resides in Sun Rock Retreat to tend to the spirits of the land and observe the natural cycle of life in the Stonetalon Mountains. From this high sanctuary, she watches over the troubled crags and reaches out to travelers who can assist in nurturing renewal amidst the region's hardships.",al={"why is tammra here","tammra windfield sun rock retreat why","why is tammra in stonetalon"},it="why_here",add=true}},ang={["race:Tauren"]="Tammra exemplifies the tauren commitment to the Earth Mother, demonstrating how spiritual reverence translates into real-world restoration even far from Mulgore.",["class:Druid"]="Her emphasis on the cycle of rebirth and cultivating new life mirrors the central tenets of druidism, making her requests deeply resonant with caretakers of the wild.",["faction:Horde"]="In the contested territory of Stonetalon, Tammra helps maintain Sun Rock Retreat as a secure, enduring foothold for Horde travelers."},kw={"cycle of rebirth","kaya","new life","stonetalon","sun rock retreat","tammra","tauren","windfield"},rel={"subzone:sun-rock-retreat","zone:stonetalon","quest:6301","quest:6381","quest:6401","topic:tauren","zone:thunderbluff"},src={"Tammra Windfield"}}
E["npc:tyrande-whisperwind"] = {t="npc",n="Tyrande Whisperwind",z="stonetalon",s="Tyrande Whisperwind is the High Priestess of Elune and the supreme leader of the night elves. Alongside her beloved, the Archdruid Malfurion Stormrage, she guided her people through the cataclysmic War of the Ancients and ten millennia of the Long Vigil. Now governing from the sacred boughs of Teldrassil, she commands the Sisterhood of Elune and directs the Sentinel army in defense of Kalimdor's sacred wilderness.",h="Tyrande Whisperwind is the High Priestess of Elune and the supreme leader of the night elves.",sec={{t="Chosen of the Moon Goddess",b="Born in the ancient city of Suramar, Tyrande grew up alongside the twin brothers Malfurion and Illidan Stormrage. While the brothers followed druidism and sorcery, Tyrande entered the service of Elune as a novice in the sisterhood. When the demonic Burning Legion first invaded Azeroth during the War of the Ancients, the dying High Priestess Dejahna chose Tyrande as her successor. Blessed with direct favor from the Moon Goddess, Tyrande transformed the Sisterhood into a radiant fighting force, wielding both divine restoration and searing lunar wrath to deliver her people from the brink of total annihilation.",sp=0},{t="The Long Vigil and the Sentinels",b="Following the Great Sundering and the sealing of the Well of Eternity, Malfurion and the druids entered the Emerald Dream for deep, prolonged hibernations. Tyrande took upon herself the lonely burden of defending their recovering realm. She organized the Sentinels—an elite cadre of warrior-women who patrolled Kalimdor's forests for ten thousand years. Throughout this Long Vigil, she stood watchful guard over ancient evils and lingering demonic remnants, maintaining unbroken faith in Elune while she waited centuries between brief reunions with Malfurion.",sp=0},{t="The Third War and a New Haven",b="When the Burning Legion returned during the Third War, Tyrande acted decisively to wake the sleeping druids and face the catastrophic threat. Overcoming fierce mistrust toward the newly arrived orcs and humans, she helped forge the desperate coalition at Mount Hyjal, sacrificing the night elves' immortality atop Nordrassil to shatter Archimonde. With Mount Hyjal scarred and Malfurion once again occupied with safeguarding the Emerald Dream, Tyrande governs the kaldorei from the grand Temple of the Moon in Darnassus, watching cautiously over both Horde incursions and the growing Alliance alliance.",sp=0}},faq={{q="Who is Tyrande Whisperwind?",a="Tyrande Whisperwind is the High Priestess of Elune and the supreme spiritual and political leader of the night elves. She has guided her people for over ten thousand years from the War of the Ancients through the Third War, and currently leads the kaldorei from the Temple of the Moon in Darnassus.",al={"who is tyrande","tyrande whisperwind lore","night elf leader"},it="identity"},{q="Where does Tyrande reside right now?",a="Tyrande resides in the capital city of Darnassus, situated high in the branches of the world tree Teldrassil. She presides from the upper sanctuary of the Temple of the Moon, surrounded by the Priestesses of Elune and Sentinel guards.",al={"where is tyrande","tyrande location","where to find tyrande"},it="place"},{q="What is the relationship between Tyrande and Malfurion?",a="Tyrande and Malfurion Stormrage are lifelong partners who have guided the night elf civilization together for ten millennia. Though both Malfurion and his twin brother Illidan sought her love in their youth, Tyrande chose Malfurion, whose deep devotion to balance and nature mirrored her faith in Elune.",al={"tyrande malfurion","is tyrande married","tyrande and illidan"},it="ties"},{q="What is the Sisterhood of Elune?",a="The Sisterhood of Elune is the ancient religious order of night elf priestesses dedicated to worshiping the Moon Goddess. Under Tyrande's leadership as High Priestess, the sisters serve not only as healers and spiritual guides, but also as fierce martial commanders and combatants.",al={"sisterhood of elune","priestesses of elune","tyrande priests"}},{q="What role did Tyrande play in the Long Vigil?",a="During the ten thousand years after the Sundering, while Malfurion and the male druids slumbered in the Emerald Dream, Tyrande established and commanded the Sentinels. She patrolled the wilds of Kalimdor, hunted remaining satyrs and demons, and kept her people safe in isolation.",al={"what was the long vigil","tyrande long vigil","sentinel leader"},it="history"},{q="Why is Tyrande wary of the Horde?",a="During the Third War, the orcs entered Ashenvale and began clear-cutting sacred forests, slaying the demigod Cenarius under the influence of demon blood. While an uneasy truce was struck at Mount Hyjal, the Horde's ongoing logging operations in Ashenvale ensure Tyrande keeps her Sentinels on high alert.",al={"tyrande horde","why does tyrande hate orcs","night elves vs horde"},it="hostile"},{q="Whose side is Tyrande Whisperwind on?",a="Tyrande stands as the supreme leader of the night elves and a core pillar of the Grand Alliance. She leads the Sisterhood of Elune and guides her people from the Temple of the Moon in Darnassus, committed utterly to protecting Kalimdor and her kin from external threats.",al={"what faction is tyrande","is tyrande alliance","tyrande loyalty"},it="side",add=true},{q="What does Tyrande Whisperwind want?",a="Her primary duty is safeguarding the kaldorei and the sacred forests of Kalimdor from corrupting forces, whether demonic remains or foreign invaders. With Malfurion slumbering in the Emerald Dream, she also shoulders the burden of guiding and defending their newly founded home on Teldrassil.",al={"what are tyrande goals","tyrande motivation","what is tyrande trying to do"},it="wants",add=true},{q="Why is Tyrande Whisperwind famous?",a="Tyrande is revered as Elune's chosen High Priestess who helped defeat the Burning Legion in the War of the Ancients ten thousand years ago. For millennia during the Long Vigil, she commanded the Sentinels to defend Kalimdor, later standing firm alongside mortal races at the Battle of Mount Hyjal.",al={"why is tyrande revered","tyrande legends","tyrande reputation"},it="fame",add=true}},ang={["race:NightElf"]="Tyrande is your supreme leader and High Priestess. For over ten thousand years, she has kept vigil over your race, championing the light of Elune through every trial.",["class:Priest"]="As the living vessel of Elune's divine favor, Tyrande embodies the pinnacle of kaldorei priesthood, calling down lunar stars and mending wounds through pure faith.",["faction:Alliance"]="Though historically reclusive and fiercely independent, Tyrande leads the night elves within the Alliance to secure mutual defense against Kalimdor's growing perils.",["class:Druid"]="While Malfurion slumbers in the Emerald Dream, Tyrande coordinates closely with the Cenarion Circle to protect sacred groves and nurture Teldrassil.",["faction:Horde"]="To the Horde, Tyrande is a formidable, uncompromising adversary who has commanded the Sentinels to violently resist resource harvesting across Ashenvale."},kw={"darnassus","elune","kaldorei","malfurion","priestess","sentinels","teldrassil","tyrande","whisperwind"},rel={"npc:malfurion-stormrage","npc:shandris-feathermoon","quest:940","topic:night-elf","topic:elune","topic:sentinels","topic:war-of-the-ancients","zone:ashenvale"},src={"Tyrande Whisperwind"}}
E["npc:witch-doctor-jin-zil"] = {t="npc",n="Witch Doctor Jin'Zil",z="stonetalon",s="Witch Doctor Jin'Zil is a Darkspear troll mystic dwelling in a cave at Malaka'jin in the southern Stonetalon Mountains. A longtime comrade of Darsok Swiftdagger and the shadow hunter Rokhan, he turns dark voodoo and ritual sorcery against the Horde's local enemies.",h="Witch Doctor Jin'Zil is a Darkspear troll mystic dwelling in a cave at Malaka'jin in the southern Stonetalon...",sec={{t="The Hermit of Malaka'jin",b="Secluded inside an eastern cavern above the camp of Malaka'jin, Jin'Zil practices ancient jungle troll arts away from the coastal home of his tribe. Surrounded by bubbling cauldrons and captive prisoners, he gathers exotic reagents from the crags of the Stonetalon Mountains—such as ram horns, resonite crystals, and fierce stormer hearts—to weave potent blessings and curses in defense of the Horde's mountain encampment.",sp=0},{t="A Trusted Veteran",b="Jin'Zil is no ordinary hedge wizard; he shares a storied history with senior Horde scouts, counting both Darsok Swiftdagger and the renowned shadow hunter Rokhan among his old friends. While Darsok coordinates frontline skirmishes against night elves and harpies, Jin'Zil fights the war spiritually and alchemically, using his forest magic and volatile voodoo to undermine threats before they ever reach the camp gates.",sp=0}},faq={{q="Where can I find Witch Doctor Jin'Zil?",a="He resides inside a cave on the eastern side of Malaka'jin, a Horde settlement nestled in the southern pass of the Stonetalon Mountains.",al={"jin'zil location","where is jinzil","jinzil cave"},it="place",gp=true},{q="What is Jin'Zil's connection to Rokhan and Darsok Swiftdagger?",a="Jin'Zil is an old, trusted friend to both Darsok Swiftdagger and the shadow hunter Rokhan. Because of these long-standing ties, scouts throughout Stonetalon rely on his magical expertise when dealing with unusual threats.",al={"jin'zil friends","darsok and jinzil","rokhan connection"},it="ties"},{q="Why does Jin'Zil have prisoners in his cave?",a="Jin'Zil keeps captive enemies caged within his cavern workshop. As a traditional witch doctor, he employs captives and raw reagents to test curses, divine portents, and craft defensive voodoo for the settlement.",al={"prisoners of jinzil","jinzil cages","why does jinzil have captives"},it="motive"},{q="What kind of tasks does he give to Horde adventurers?",a="He sends travelers across Stonetalon to collect mystical components, including creature organs, ram horns, and resonite crystals, using them to concoct defensive wards and powerful blessings for the war effort.",al={"jinzil quests","what does jinzil want"},it="purpose",gp=true},{q="Who is Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil is a Darkspear jungle troll mystic residing in the craggy hills of Stonetalon Mountains. Lurking in a shadowed cave overlooking the settlement of Malaka'jin, he practices deep voodoo rituals and brews potent forest magic, lending his ancient craft and spiritual foresight to the Horde's frontier struggles.",al={"who is jinzil","jin'zil lore","witch doctor jinzil identity"},it="identity",add=true},{q="Whose side is Witch Doctor Jin'Zil on?",a="Jin'Zil stands firmly with the Horde, specifically maintaining deep ties to his Darkspear troll brethren and their allies carving out footholds in Kalimdor. He directs his magical rites and strategic aid toward supporting local outposts, aiding champions sent across the mountain paths on behalf of the Warchief.",al={"is jinzil horde","witch doctor jinzil faction","jinzil loyalty"},it="side",add=true},{q="What does Witch Doctor Jin'Zil want?",a="Jin'Zil seeks potent reagents from Stonetalon's wildlife and magical phenomena, including resonant crystals and beast components, to fuel his voodoo charms and hexes. Through these brewed blessings, he aims to empower the Horde's presence and secure the mountain passes against encroaching threats.",al={"what does jinzil want","jinzil goals","why gather ingredients jinzil"},it="wants",add=true},{q="Why is Witch Doctor Jin'Zil in Stonetalon?",a="He has established his secluded den at Malaka'jin to observe the volatile spirits and raw natural magic of the Stonetalon Mountains. From this rocky outpost, he weaves spells and monitors southern paths, providing supernatural insight and enchanted aid directly to Horde scouts defending the region.",al={"why is jinzil in stonetalon","why malakajin jinzil","why is jinzil here"},it="why_here",add=true}},ang={["race:Troll"]="Jin'Zil represents traditional Darkspear witch doctor practices transplanted into the rugged wilderness of Kalimdor, maintaining deep ties to prominent figures like Rokhan.",["faction:Horde"]="As the Horde secures Stonetalon's southern paths, Jin'Zil provides essential occult defense and intelligence support alongside the outpost's scouts."},kw={"darsok","jin'zil","jinzil","malaka'jin","rokhan","stonetalon","voodoo","witch doctor"},rel={"subzone:malaka-jin","npc:darsok-swiftdagger","quest:1058","quest:1060","zone:stonetalon","topic:troll"},src={"Witch Doctor Jin'Zil"}}
E["quest:1057"] = {t="quest",n="Reclaiming the Charred Vale",z="stonetalon",s="Reclaiming the Charred Vale is an Alliance quest offered by Keeper Albagorm atop Stonetalon Peak. It charges adventurers with culling the aggressive Bloodfury harpies who occupy the ruined valley of the Charred Vale, clearing a path so druids and caretakers can begin healing the scorched landscape.",h="Reclaiming the Charred Vale is an Alliance quest offered by Keeper Albagorm atop Stonetalon Peak.",sec={{t="The Wounded Valley",b="To the south of Stonetalon Peak lies the Charred Vale, a once-lush alpine haven reduced to ash and smoldering ruins. The devastation began when a mechanized logging and mining army swept through the sacred crags, stripping trees and fueling uncontrolled blazes. For the guardians stationed around Stonetalon, watching ancient woodland succumb to industrial greed is an intolerable wound upon the wilderness.",sp=0},{t="The Harpy Menace",b="While mechanical fires sparked the ruin, an opportunistic infestation took root in the ashes. The vicious Bloodfury harpies swarmed into the smoking lowlands, establishing nests and aggressively ambushing anyone approaching the valley. Keeper Albagorm and his allies cannot even walk the soil to sow the seeds of renewal, as the Bloodfuries violently refuse passage to all outsiders.",sp=0},{t="Clearing the Path to Renewal",b="Before any meaningful restoration can take place, the roosts of the Bloodfury tribe must be broken. Albagorm tasks seasoned Alliance fighters with carving deep into their numbers—slaying hunters, ambushers, and roguefeathers alike. Thinning their predatory flocks is the vital first step toward reclaiming what belongs to nature and giving the forest spirits room to breathe once more.",sp=0}},faq={{q="What is the Charred Vale?",a="The Charred Vale is a valley nestled in the southwestern heights of the Stonetalon Mountains. Once a lush, verdant forest, it was consumed by fire and scorched to bedrock during the unchecked exploitation of the land by industrial logging forces.",al={"charred vale lore","what happened to charred vale","why is it burned"},it="place"},{q="Who is Keeper Albagorm?",a="Keeper Albagorm is a woodland keeper and caretaker residing at the Alliance settlement on Stonetalon Peak. As a protector of nature and forest spirits, he dedicates himself to curbing desolation in the mountains and driving back encroaching beasts.",al={"keeper albagorm","who gives reclaiming the charred vale","albagorm lore"},it="identity"},{q="Why are harpies living in the Charred Vale?",a="The Bloodfury harpies are aggressive, opportunistic scavengers who thrive in disrupted and blighted territory. When fire leveled the valley, the flock moved in to dominate the desolate basin, attacking anyone attempting to enter.",al={"bloodfury harpies","why harpies here","bloodfuries in stonetalon"},it="target"},{q="Who set fire to the Charred Vale in the first place?",a="Keeper Albagorm identifies the culprits as a greedy mechanized army of industrialists who tore into the hills. Unchecked logging machinery and explosive expansion caused devastating blazes that consumed the woodland.",al={"who burned charred vale","mechanized army industrialists","venture company charred vale"},it="history"},{q="What must be done after thinning the harpies?",a="Clearing out the harpies is merely securing the perimeter. Once the Bloodfury numbers are curbed, Keeper Albagorm shifts focus toward planting seeds and channeling restorative magic to coax new life from the scorched soil.",al={"next quest charred vale","reclaiming the charred vale part 2","what happens next"},sp=1,it="next_step"},{q="Is this quest available to Horde adventurers?",a="No. Keeper Albagorm operates out of the Alliance-aligned redoubt atop Stonetalon Peak, meaning this specific task to purge the Bloodfury harpies is restricted to Alliance heroes.",al={"can horde do this quest","horde reclaiming charred vale"},it="side",gp=true},{q="Why does Keeper Albagorm want the Bloodfuries culled?",a="As a keeper of the grove and protector of forest spirits, Albagorm seeks to heal and restore the scarred, burnt landscape of the Charred Vale to the lush sanctuary it once was. However, the aggressive Bloodfury harpies who swarmed the ruins vigorously block any entry, actively preventing the Cenarion Circle from initiating their sacred rites of renewal and regrowth.",al={"why clear the charred vale","keeper albagorm motive","why kill the harpies charred vale"},it="motive",add=true}},ang={["race:NightElf"]="Night elves revere the wild forests of Stonetalon; purging the vile harpies from sacred groves defiled by foreign engines is an urgent calling.",["class:Druid"]="As stewards of the Cenarion circle and defenders of natural harmony, druids directly aid the Keepers in clearing out blighted nests to permit magical reforestation.",["faction:Alliance"]="Securing the high passes and southern valleys protects the vulnerable night elf settlements and sanctuaries across Stonetalon Peak from predatory threats."},kw={"bloodfury","charred vale","harpies","keeper albagorm","reclaiming the charred vale","stonetalon","stonetalon peak"},rel={"subzone:charred-vale","subzone:stonetalon-peak","npc:keeper-albagorm","topic:harpy","zone:stonetalon"},m={start="Keeper Albagorm",level="27",faction="Alliance",id=1057},src={"Reclaiming the Charred Vale"}}
E["quest:1058"] = {t="quest",n="Jin'Zil's Forest Magic",z="stonetalon",s="At the small outpost of Malaka'jin, Witch Doctor Jin'Zil has captured three night elven scouts in crude iron cages. Rather than executing them outright or holding them for ransom, the eccentric troll tasks Horde adventurers with gathering wilderness reagents from Stonetalon Peak to concoct a gruesome dose of 'forest magic.'",h="At the small outpost of Malaka'jin, Witch Doctor Jin'Zil has captured three night elven scouts in crude iron...",sec={{t="A Bitter Brew",b="In the red-rock defile of Malaka'jin, Witch Doctor Jin'Zil conducts his craft under the watchful gaze of the Horde. When three night elf captives fall into his clutches, Jin'Zil decides against ordinary butchery, concocting instead a mocking ritual tailored specifically for his captive woodland foes. He directs travelers north into the untamed peaks to collect an array of indigenous parts: thick tree sap, feline whiskers from predatory twilight runners, a shimmering fey dragon scale, and scores of eyes plucked from the local forest coursers.",sp=0},{t="A Taste of Home",b="Behind Jin'Zil's playful demeanor lies a cruel troll sense of humor. Under the pretense of making the imprisoned elves 'feel right at home' without a forest to frolic in, the mixture of magical fauna and concentrated sap forms a lethal, volatile venom. When released within the cave, the noxious concoction chokes the life from the caged captives on the spot. As their physical bodies perish, the elves' ancestral spirits dissolve into luminous wisps that float out into the mountains, leaving their empty cages behind.",sp=1}},faq={{q="Who is Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil is a Darkspear troll stationed at Malaka'jin in the southern Stonetalon Mountains. He serves the Horde war effort against the night elves by practicing traditional troll alchemy, voodoo, and interrogation.",al={"who is jin'zil","witch doctor jin'zil","jinzil lore"},it="identity"},{q="Why does Jin'Zil want so many courser eyes?",a="Jin'Zil claims that you simply cannot brew fierce forest magic without an abundance of eyes. While troll witch doctors often utilize strange organic components in their potions, the absurd quantity also reflects his eccentric and vindictive personality.",al={"why courser eyes","30 courser eyes","why so many eyes"},it="item"},{q="What happens to the caged night elves when the quest finishes?",a="Upon delivering the reagents, Jin'Zil releases the toxic brew throughout his cave. The concoction lethally poisons the three captives, killing them and releasing their spirits as wisps that drift away into the wild.",al={"what happens to the elves","caged elves fate","prisoners of jin'zil"},sp=1},{q="Where are all these reagents found?",a="The courser eyes and Stonetalon sap can be gathered around Mirkfallon Lake and the northern highlands. The twilight whiskers and the rare fey dragon scale are found farther north near Stonetalon Peak, where the mountain's magical beasts roam.",al={"where to find forest magic reagents","stonetalon sap location","fey dragon scale spot"},it="place",gp=true},{q="Why is the Horde fighting night elves in Stonetalon?",a="The Horde's logging in neighboring Ashenvale has triggered fierce resistance from the Sentinels, and the night elves still hold Stonetalon Peak and its sacred groves above Horde outposts like Malaka'jin.",al={"why fight night elves in stonetalon","horde night elf conflict stonetalon","stonetalon war"},it="conflict"},{q="Why do the dying elves turn into wisps?",a="Wisps are the spirits of deceased night elves who remain intimately bonded to nature. Upon death, their souls take on this glowing arboreal form rather than lingering as ordinary ghosts or shades.",al={"why do elves become wisps","elven wisps in cave","wisp lore"}},{q="Why does Witch Doctor Jin'Zil want this done?",a="Witch Doctor Jin'Zil has captured three night elf sentinels and locked them in cages within his cavern at Malaka'jin. Rather than simply executing them, he wants to concoct a spiteful brew mockingly termed \"forest magic.\" By combining raw, potent essences from their beloved wilderness, he intends to create a lethal poison that turns the forest's own natural gifts against his prisoners.",al={"jinzil forest magic why","why make forest magic","jin'zil motive"},sp=1,it="motive",add=true},{q="What is the Stonetalon Sap for?",a="Taken from the living wood and sap beasts of the region, the thick resin serves as a viscous, sticky base for Jin'Zil's concoction. It traps and blends the other woodland reagents together, grounding his toxic brew in the raw essence of the mountains.",al={"stonetalon sap use","why collect sap","what is the sap for"},it="item",add=true},{q="What is the Fey Dragon Scale for?",a="Fey dragons are mystical creatures deeply intertwined with the emerald power of Stonetalon Peak and the Kaldorei. Jin'Zil requires a scale to infuse his brew with their innate magical warding and wild energies, warping it into a lethal agent specifically tuned to harm night elves.",al={"fey dragon scale use","why need fey dragon scale","what is the fey dragon scale for"},it="item",add=true},{q="What is the Twilight Whisker for?",a="Harvested from the prowling twilight runners lurking in the woods, these whiskers contribute the feral, predatory instinct of Stonetalon's native predators into the mixture, sharpening the brew into an aggressive poison.",al={"twilight whisker use","why twilight whiskers","what are twilight whiskers for"},it="item",add=true}},ang={["race:Troll"]="Jin'Zil's macabre humor and practical application of voodoo alchemy are classic hallmarks of Darkspear witch doctor craft.",["race:NightElf"]="The agonizing execution of night elven captives through twisted woodland materials stands as one of the crueler Horde acts in Stonetalon.",["class:Druid"]="Seeing sacred fey drakes, majestic coursers, and ancient forest sap harvested to brew a lethal poison is a grim perversion of nature's balance.",["faction:Horde"]="Securing Malaka'jin means subduing night elf resistance across the range, even through the unorthodox methods of a recluse witch doctor."},kw={"courser eye","fey dragon","forest magic","jin'zil","malaka'jin","prisoners","stonetalon","twilight runner","witch doctor"},rel={"npc:witch-doctor-jin-zil","subzone:malaka-jin","subzone:stonetalon-peak","subzone:mirkfallon-lake","zone:stonetalon"},m={start="Witch Doctor Jin'Zil",level="26",faction="Horde",id=1058,ri={"Courser Eye","Fey Dragon Scale","Stonetalon Sap","Twilight Whisker"}},src={"Jin'Zil's Forest Magic"}}
E["quest:1059"] = {t="quest",n="Reclaiming the Charred Vale",z="stonetalon",s="Reclaiming the Charred Vale is a messenger quest tasked by Keeper Albagorm in Stonetalon Peak. Having temporarily suppressed the local harpies, Albagorm sends an Alliance traveler far south to Feralas to recruit the aid of the druid Falfindel Waywarder.",h="Reclaiming the Charred Vale is a messenger quest tasked by Keeper Albagorm in Stonetalon Peak.",sec={{t="The Scars of the Vale",b="The Charred Vale in southern Stonetalon Mountains remains an ash-choked reminder of catastrophic devastation. While Alliance forces under Keeper Albagorm have struck back against the rampant Bloodfury harpies nesting in the ruins, driving them off is merely a holding action. Albagorm recognizes that physical force alone cannot mend the ravaged earth before the harpies rally and reclaim their dominance.",sp=0},{t="A Plea to the South",b="To permanently restore the scorched lands, the grove tenders need mystical intervention beyond their current means. Albagorm dispatches a courier far to the south, skirting past the salt flats and canyons of Thousand Needles to Forest's Edge on the border of Feralas. There waits Falfindel Waywarder, a night elf druid reputed to possess the rare power to call forth primordial forest spirits capable of rejuvenating the dead soil.",sp=0}},faq={{q="Who is Keeper Albagorm?",a="Keeper Albagorm is a keeper of the grove stationed at Stonetalon Peak who oversees Alliance efforts to cleanse and restore the blighted Charred Vale.",al={"who is albagorm","keeper albagorm"},it="identity"},{q="Where is Falfindel Waywarder located?",a="Falfindel Waywarder is stationed at the Forest's Edge, positioned on the western border where Thousand Needles transitions into the lush wilderness of Feralas.",al={"where is falfindel","falfindel waywarder location","find waywarder"},gp=true},{q="Why send for a druid all the way in Feralas?",a="Keeper Albagorm considers Falfindel uniquely capable of summoning powerful ancient forest spirits that can reverse the deep ecological devastation of the Charred Vale.",al={"why go to feralas","why falfindel"},it="purpose"},{q="What threat resides in the Charred Vale?",a="The valley is overrun by hostile Bloodfury harpies alongside fire elementals and wild beasts that thrived in the wake of the land's burning.",al={"charred vale enemies","what is attacking the vale"},it="threat"},{q="Does this quest require combat?",a="No. The second part of Reclaiming the Charred Vale is purely an overland travel quest requiring you to deliver Albagorm's message across central and southern Kalimdor.",al={"is this quest hard","combat in charred vale quest"},gp=true},{q="How do you reach Thousand Needles from Stonetalon?",a="Travelers must journey east out of Stonetalon Mountains into the Barrens, head south along the Great Divide, descend the Great Lift into Thousand Needles, and continue west toward Feralas.",al={"how to get to thousand needles","travel route to feralas"},gp=true},{q="Why does Keeper Albagorm want this done?",a="Though you struck down many of the Bloodfury harpies, Keeper Albagorm knows they will quickly regroup and reclaim their hold over the Charred Vale if no lasting action is taken. The land remains ruined and vulnerable, and culling beasts alone cannot heal the scorched earth. He urgently needs the powerful forest spirits that only a druid like Falfindel Waywarder can summon to restore life to the vale before the harpies rally and undo your progress.",al={"keeper albagorm motive","why send for falfindel","why reclaim charred vale"},it="motive",add=true}},ang={["class:Druid"]="This mission highlights the Cenarion duty to reach beyond local garrisons and summon primal nature spirits to heal lands scarred by unnatural ruin.",["faction:Alliance"]="The Alliance's foothold at Stonetalon Peak relies on connecting frontier outposts across vast, contested stretches of Kalimdor."},kw={"bloodfuries","charred vale","falfindel waywarder","feralas","forest's edge","keeper albagorm","stonetalon peak","thousand needles"},rel={"quest:1057","npc:keeper-albagorm","npc:falfindel-waywarder","subzone:charred-vale","subzone:forest-s-edge","zone:stonetalon","zone:feralas","zone:thousandneedles"},m={start="Keeper Albagorm",["end"]="Falfindel Waywarder",level="27",faction="Alliance",id=1059},src={"Reclaiming the Charred Vale (2)"}}
E["quest:1060"] = {t="quest",n="Letter to Jin'Zil",z="stonetalon",s="Letter to Jin'Zil is a Horde delivery quest entrusted to adventurers who have slain Serena Bloodfeather in the northern Barrens. Orc rogue Darsok Swiftdagger sends you across the border into the rugged crags of Stonetalon Mountains to deliver word of the harpy matriarch's demise to his old friend, Witch Doctor Jin'Zil.",h="Letter to Jin'Zil is a Horde delivery quest entrusted to adventurers who have slain Serena Bloodfeather in...",sec={{t="A Message into the Mountains",b="After the harpy threat around the northern Barrens is systematically dismantled, Darsok Swiftdagger reveals that the winged raiders were never native to the scrublands. The Witchwing and Bloodfeather broods descended from the rugged ridges of the Stonetalon Mountains to the northwest. Impressed by your prowess in dispatching Serena Bloodfeather, Darsok sends you into those dangerous peaks to carry news of her death to an old acquaintance, Witch Doctor Jin'Zil, residing at the troll settlement of Malaka'jin.",sp=0},{t="Echoes of the Bloodfury Claws",b="Reaching Jin'Zil in his shaded cave reveals an older chapter of Horde history. Upon hearing that Serena Bloodfeather has fallen, the troll witch doctor recalls the earlier campaign when the shadow hunter Rokhan and the wandering Beastmaster Rexxar slew Serena's elder sister, Bloodfeather. The eradication of Serena brings a sense of finality to the longstanding feud between the Horde's frontier outposts and the bloodthirsty harpies of Kalimdor.",sp=1}},faq={{q="Who gives the quest Letter to Jin'Zil?",a="Darsok Swiftdagger gives the quest at the Crossroads in the Barrens. He offers it only after you complete the hunt for Serena Bloodfeather.",al={"quest giver","where to get quest","who starts letter to jin'zil"},it="identity",gp=true},{q="Where can I find Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil resides inside a cave at Malaka'jin, a Darkspear troll encampment located just off the main path entering the Stonetalon Mountains from the Barrens.",al={"where is jin'zil","jin'zil location","malaka'jin location"},it="place",gp=true},{q="Why does Darsok send you to Stonetalon Mountains?",a="Darsok wants to inform his old friend Jin'Zil that the harpy threat has been broken with Serena Bloodfeather's death, while also steering a capable adventurer toward the wider challenges awaiting the Horde in the Stonetalon peaks.",al={"why go to stonetalon","why darsok sends letter"},it="motive"},{q="What previous sister of Serena is Jin'Zil referring to?",a="Jin'Zil mentions Bloodfeather, an elder harpy who terrorized Kalimdor years earlier. She was slain by the Shadow Hunter Rokhan and the Mok'Nathal warrior Rexxar during their travels alongside the founding Horde.",al={"serena older sister","rokhan and rexxar harpy","bloodfury"},it="history"},{q="Is this quest part of a larger chain?",a="Yes. It serves as the conclusion to the northern Barrens harpy hunting chain, following Harpy Raiders, Harpy Lieutenants, and Serena Bloodfeather, while acting as a breadcrumb into the Stonetalon Mountains.",al={"quest chain","prerequisites","what leads to this"},it="next_step",gp=true},{q="What faction can undertake this task?",a="This is strictly a Horde quest, as both Darsok Swiftdagger and Witch Doctor Jin'Zil serve the interests of the Horde frontier.",al={"is this horde only","can alliance do this quest"},it="side",gp=true},{q="Why does Darsok need you to deliver the letter to Jin'Zil?",a="Darsok Swiftdagger remains stationed at the Crossroads maintaining watch over the northern Barrens. Having watched you successfully purge the witchwing harpies and slay their leader Serena Bloodfeather, he views you as a proven, capable messenger who can handle the dangerous journey into Stonetalon Mountains. Passing word of Serena's downfall also gives you a worthy pretext to explore lands beyond the arid plains.",al={"why send me letter to jinzil","why cant darsok deliver the letter","why me letter to jinzil"},it="why_me",add=true}},ang={["faction:Horde"]="Delivering this letter transitions Horde warriors from pacifying the internal trade routes of the Barrens into establishing footholds in the contentious Stonetalon Mountains.",["race:Troll"]="Jin'Zil's cave at Malaka'jin serves as a key spiritual and tactical outpost for Darkspear trolls seeking to secure the mountain approaches."},kw={"bloodfury","darsok swiftdagger","harpies","letter to jin'zil","malaka'jin","serena bloodfeather","stonetalon mountains","witch doctor jin'zil"},rel={"quest:876","npc:witch-doctor-jin-zil","npc:darsok-swiftdagger","subzone:malaka-jin","zone:stonetalon","quest:875","quest:867","zone:barrens"},m={start="Darsok Swiftdagger",["end"]="Witch Doctor Jin'Zil",level="20",faction="Horde",id=1060},src={"Letter to Jin'Zil (quest)"}}
E["quest:1062"] = {t="quest",n="Goblin Invaders",z="stonetalon",s="Goblin Invaders is a Horde quest tasked by Seereth Stonebreak at the border between the Barrens and the Stonetalon Mountains. It directs warriors of the Horde into Windshear Crag to strike directly at the Venture Company loggers despoiling the region's ancient woodlands.",h="Goblin Invaders is a Horde quest tasked by Seereth Stonebreak at the border between the Barrens and the...",sec={{t="A Forest in Agony",b="The Venture Company has pushed deep into the Stonetalon Mountains, carving wide swaths of destruction through the crags and valleys. Their logging operations strip the hillsides of timber and set fire to underbrush, leaving behind smoldering scars. To the tauren and their allies, this is not merely an unsightly mining and lumber operation; the primal spirits bound to Stonetalon are howling in torment. Seereth Stonebreak, stationed along the mountain border, observes that these spirits have grown blind with agony and fury under the goblins' relentless assault.",sp=0},{t="The Language of Force",b="Appeals to reason or diplomacy mean nothing to the cutthroat executives and hirelings of the Venture Company, whose sole concern is raw profit. Recognizing this, Seereth orders travelers to venture past Greatwood Vale and directly into Windshear Crag to cull fifteen loggers. By meeting corporate greed with armed force, the Horde aims to halt the deforestation in its tracks and buy time for tauren elders to soothe the agitated spirits of the land.",sp=0}},faq={{q="Who is Seereth Stonebreak?",a="Seereth Stonebreak is an orc shaman stationed near the southern boundary between the Barrens and the Stonetalon Mountains. She monitors the encroachment of hostile factions and works to protect the spiritual balance of the region.",al={"seereth stonebreak","quest giver","who gives goblin invaders"},it="identity"},{q="Why are the goblins deforesting Stonetalon Mountains?",a="The Venture Company is an unscrupulous, profit-driven enterprise. They see Stonetalon's dense ancient forests and mineral-rich hills purely as raw materials to be harvested, processed, and sold to the highest bidder, completely indifferent to the natural and spiritual devastation left behind.",al={"why venture co logging","venture company motivation stonetalon","why cut trees"},it="why_here"},{q="Where is Windshear Crag located?",a="Windshear Crag lies in the central portion of the Stonetalon Mountains. To reach it from the Barrens border, travel northwest up the mountain road through Greatwood Vale until the vibrant green forest gives way to the mechanical logging camps and clear-cut hills of the Venture Company.",al={"windshear crag location","where are loggers","where to find venture co loggers"},it="place",gp=true},{q="How do the spirits react to the Venture Company's presence?",a="According to Seereth Stonebreak, the land spirits are driven near madness with rage and pain from the rampant logging and burning of the woodlands. Their suffering disrupts the natural balance, posing a spiritual threat to the entire region.",al={"stonetalon spirits angry","spirits of stonetalon reaction"},it="conflict"},{q="What happens after culling the Venture Company loggers?",a="Eliminating the loggers is only the initial blow against the operation. Seereth next turns the Horde's attention toward dismantling the company's mechanized infrastructure, while also recommending that the champion seek the guidance of tauren elders to help soothe the wounded spirits.",al={"after goblin invaders","next quest after loggers"},sp=1,it="next_step"},{q="Why does the Horde care about logging in Stonetalon?",a="The Stonetalon Mountains hold deep cultural and spiritual significance for the tauren, while the Horde as a whole views the unbridled aggression and resource theft of the Venture Company as a threat to their territorial influence and spiritual harmony.",al={"horde interest stonetalon","why horde fight venture co"},it="threat"},{q="Why does Seereth Stonebreak want the Venture Company loggers killed?",a="The Venture Company is ruthlessly clear-cutting and burning large tracts of the Stonetalon Mountains. Their reckless destruction has driven the local nature spirits mad with agonizing pain and fury. Seereth wants the loggers struck down to halt the relentless pillaging and prove that the Horde will not tolerate the defilement of these sacred grounds.",al={"seereth stonebreak motive","why kill loggers","why does seereth care about goblins"},it="motive",add=true},{q="Who are the Venture Co. Loggers?",a="The Venture Co. Loggers are hired laborers and technicians employed by the notorious goblin syndicate. Driven purely by profit, they have pushed past Greatwood Vale into Windshear Crag, clear-cutting ancient timber and operating heavy machinery with complete disregard for the land or the wrath of its native spirits.",al={"who are the loggers","venture co loggers","venture company workers"},it="target",add=true}},ang={["race:Tauren"]="The desecration of Stonetalon's forests and the agony of its earth spirits make confronting the Venture Company an urgent duty for every tauren who honors the Earth Mother.",["class:Druid"]="The mindless destruction of living groves and slaughter of ancient trees in Windshear Crag represent a direct violation of the natural order that druids are sworn to defend.",["class:Shaman"]="Shaman can acutely feel the cries of the local elementals and nature spirits, who have been driven blind with fury by the smoke and devastation of goblin machinery.",["faction:Horde"]="Halting the Venture Company secures the borderlands between the Barrens and the higher passes, ensuring hostile commercial syndicates do not fortify central Kalimdor."},kw={"goblin","greatwood vale","logger","seereth stonebreak","spirits","stonetalon mountains","venture company","windshear crag"},rel={"npc:seereth-stonebreak","subzone:windshear-crag","quest:1061","subzone:greatwood-vale","zone:stonetalon","topic:venture-company","topic:tauren","topic:horde"},m={start="Seereth Stonebreak",level="19",faction="Horde",id=1062},src={"Goblin Invaders"}}
E["quest:1068"] = {t="quest",n="Shredding Machines",z="stonetalon",s="Shredding Machines is a Horde quest tasking adventurers with hunting down two specialized Venture Company logging mechs in Windshear Crag. Directed by the shaman Seereth Stonebreak, players strike against the mechanical deforestation that torments Stonetalon's native spirits.",h="Shredding Machines is a Horde quest tasking adventurers with hunting down two specialized Venture Company...",sec={{t="A Vision of Deforestation",b="Stationed along the dusty border between the Barrens and the Stonetalon Mountains, the orc shaman Seereth Stonebreak listens closely to the unseen realm. While much of Stonetalon's spiritual voice is drowned out by chaos, one vision came to her with harrowing clarity: man-shaped contraptions tearing through ancient woods with unnatural haste. Marked with the mechanical designations XT:4 and XT:9, these goblin-engineered shredders butcher the timberlands of Windshear Crag, sending waves of distress through the surrounding nature spirits.",sp=0},{t="Silencing the Saws",b="To stem the devastation, Horde champions venture deep into Windshear Crag, northwest of Greatwood Vale, where the Venture Company operates. Tracking down and wrecking these specific logging constructs deals a sharp blow to the commercial deforestation of the mountains. Though bringing down XT:4 and XT:9 calms the immediate cries of the wounded tree spirits, Seereth warns that unless the Venture Company abandons Stonetalon entirely, far darker atrocities await the land.",sp=0}},faq={{q="Who is Seereth Stonebreak?",a="Seereth Stonebreak is an orc shaman posted at the southern border of the Stonetalon Mountains near the Barrens. Attuned to the elemental and spiritual forces of the land, she acts as a conduit for the anguished forest spirits protesting the rapid expansion of the Venture Company.",al={"who is seereth","quest giver seereth","seereth stonebreak lore"},it="identity"},{q="What are XT:4 and XT:9?",a="XT:4 and XT:9 are specialized, designated logging shredders operated by the Venture Company in Windshear Crag. Powered by steam engines and piloted by goblin operators, these mechanized walkers cut down ancient timber far faster than manual laborers ever could.",al={"what are the shredders","xt4 and xt9","shredder targets"},it="target"},{q="Where is Windshear Crag?",a="Windshear Crag lies in the northern reaches of the Stonetalon Mountains, situated northwest of Greatwood Vale. It has been transformed into a massive industrial logging basin by the Venture Company.",al={"windshear crag location","where do i find the shredders","where are the machines"},it="place",gp=true},{q="Why does a shaman care about trees and druidic magic?",a="As Seereth explains, shamanistic communion with spirits shares close ties with druidic nature magic. The trauma inflicted upon living forests echoes into the spiritual realm, enabling perceptive shaman to hear the wails of slaughtered tree spirits alongside elemental unrest.",al={"why do shaman care about trees","shaman druid connection","nature spirits shaman"},it="purpose"},{q="Who owns and operates these shredders?",a="The shredders belong to the Venture Company, an unscrupulous goblin-run commercial conglomerate infamous across Azeroth for ruthlessly stripping valuable natural resources with no regard for the local ecosystem or ancestral inhabitants.",al={"who made xt4","who runs the shredders","venture company shredders"},it="people"},{q="Does destroying XT:4 and XT:9 drive the Venture Company away?",a="No. While destroying these flagship machines calms the weeping tree spirits and sets back local logging efforts, the Venture Company maintains an extensive industrial foothold across Windshear Crag, requiring ongoing resistance from defenders of the wild.",al={"does the venture company leave","after shredding machines","quest outcome"},it="next_step"},{q="Why does Seereth Stonebreak want XT:4 and XT:9 destroyed?",a="As a shaman attuned to the spirit world, Seereth hears the agonizing cries of Stonetalon's battered land. The natural connection between shamanic spirituality and nature's balance allows her to perceive the tree spirits wailing as the Venture Company tears through the mountains. In a clear spiritual vision, she witnessed these two specific mechanical terrors felling the ancient timber at unnatural speed. To her, destroying them is vital spiritual stewardship; if these machines continue their unchecked slaughter of the forest, the land's wounds may never heal.",al={"why kill the shredders","seereth stonebreak motive","why destroy xt4 and xt9"},it="motive",add=true}},ang={["class:Shaman"]="Seereth highlights the profound resonance between spiritual magic and nature, reminding shaman that elemental balance relies on defending the spirits inhabiting the land.",["race:Tauren"]="The desecration of Stonetalon's ancient forests by soulless goblin machinery directly violates the tauren devotion to the Earth Mother.",["profession:Engineering"]="The XT-series logging mechs showcase advanced goblin shredder design, balancing mechanical hydraulic saws with raw steam locomotion.",["faction:Horde"]="As the Horde establishes footholds across Kalimdor, checking the unregulated greed of the Venture Company is critical to preserving the land and securing safe transit through Stonetalon."},kw={"logging","seereth stonebreak","shredder","shredding machines","stonetalon mountains","venture company","windshear crag","xt:4","xt:9"},rel={"npc:seereth-stonebreak","subzone:windshear-crag","topic:venture-company","zone:stonetalon","quest:1061","subzone:greatwood-vale","topic:druid","zone:barrens"},m={start="Seereth Stonebreak",level="23",faction="Horde",id=1068},src={"Shredding Machines"}}
E["quest:1070"] = {t="quest",n="On Guard in Stonetalon",z="stonetalon",s="On Guard in Stonetalon is an Alliance breadcrumb quest directing adventurers south from Ashenvale into the rugged Stonetalon Mountains. Sentinel Thenysil dispatches travelers to check on her scout friend, Kaela Shadowspear, who was sent into the crags alongside a gnome mage to monitor industrial incursions by the Venture Company.",h="On Guard in Stonetalon is an Alliance breadcrumb quest directing adventurers south from Ashenvale into the...",sec={{t="A Scout Sent South",b="Stationed in Astranaar, Sentinel Thenysil keeps a close watch on threats pressing toward the ancient forest. Deeply concerned for her friend Kaela Shadowspear, Thenysil asks passing Alliance champions to track her down. Kaela was dispatched into the Stonetalon Mountains by Sentinel Wolfrunner to survey rising turmoil in the heights, but communication has fallen silent, leaving Thenysil anxious for her safety.",sp=0},{t="Uneasy Partnerships in the Crags",b="Thenysil's concern is heightened by Kaela's assigned companion: a gnome mage deployed alongside her by the Alliance leadership. While the night elves have joined the Grand Alliance out of strategic necessity, many Sentinels remain deeply skeptical of arcane practitioners and tinkering gnomes operating in pristine wilderness. Finding Kaela perched on the bluffs above Windshear Crag reveals an outpost keeping vigil over widespread environmental devastation wrought by the Venture Company.",sp=0}},faq={{q="Who gives this quest?",a="The quest is offered by Sentinel Thenysil, a night elf sentinel stationed in Astranaar in Ashenvale.",al={"quest giver","where to start","who starts on guard in stonetalon"},it="identity"},{q="Where can I find Kaela Shadowspear?",a="Kaela Shadowspear is encamped high on a rocky ridge overlooking the valley entrance into Windshear Crag within the Stonetalon Mountains.",al={"kaela location","find kaela","kaela shadowspear spot"},it="place",gp=true},{q="Why is Sentinel Thenysil worried about Kaela?",a="Kaela was sent to investigate dangerous hostile incursions in Stonetalon and has not sent word back. Furthermore, Thenysil is wary because the Alliance paired Kaela with a gnome mage, a pairing she considers an omen of trouble.",al={"why worry","thenysil concern"},it="motive"},{q="What threats are active in the Stonetalon Mountains?",a="The mountains suffer heavily from the Venture Company, an unscrupulous goblin mining and logging cartel tearing up the wilderness, alongside aggressive native beasts and rival Horde forces encroaching from the south.",al={"stonetalon enemies","who is in stonetalon"},it="threat"},{q="Who is Tara?",a="Tara is Sentinel Thenysil's first name. When you meet Kaela, she fondly refers to her old friend as Tara and expresses pride that she is coordinating scouts and adventurers.",al={"who is tara","tara mentioned"},it="identity"},{q="What happens after finding Kaela Shadowspear?",a="Reaching Kaela completes the journey and leads into further tasks assisting her and her gnome partner with keeping watch over the encroaching threats in Windshear Crag.",al={"next quest","what comes next"},it="next_step"},{q="Why does Sentinel Thenysil need an adventurer to find Kaela?",a="Sentinel Thenysil is stationed on duty in Ashenvale and cannot simply abandon her post to ride into neighboring lands. When she sees a capable traveler displaying wanderlust, she seizes the chance to recruit an independent scout who can slip across the border into Stonetalon without disrupting local Sentinel defenses.",al={"why send me","why doesnt thenysil go","why an adventurer"},it="why_me",add=true}},ang={["faction:Alliance"]="This task marks the southward expansion of Alliance frontier security, linking defense outposts in Ashenvale to isolated scouting perches in the Stonetalon Mountains.",["race:NightElf"]="The mission illustrates the friction between traditional night elf Sentinels and the arcane, mechanical practices of their Eastern Kingdom allies, particularly gnomes.",["race:Gnome"]="Sentinels view gnomish magic and contraptions with deep skepticism, seeing the inclusion of a gnome mage as an odd, unpredictable variable in Kalimdor's wilderness."},kw={"ashenvale","kaela shadowspear","on guard in stonetalon","sentinel thenysil","stonetalon mountains","venture co","windshear crag"},rel={"npc:sentinel-thenysil","npc:kaela-shadowspear","zone:stonetalon","subzone:windshear-crag","zone:ashenvale","topic:sentinels","topic:gnome","quest:764"},m={start="Sentinel Thenysil",["end"]="Kaela Shadowspear",level="21",faction="Alliance",id=1070},src={"On Guard in Stonetalon"}}
E["quest:1071"] = {t="quest",n="A Gnome's Respite",z="stonetalon",s="A Gnome's Respite is an Alliance quest offered by the eccentric tinkerer Gaxim Rustfizzle in the Stonetalon Mountains. Overwhelmed by the Venture Company's rapid industrial push into Windshear Crag, Gaxim hires adventurers to cull their loggers and deforesters so he can buy enough breathing room to invent new deterrents.",h="A Gnome's Respite is an Alliance quest offered by the eccentric tinkerer Gaxim Rustfizzle in the Stonetalon...",sec={{t="A Clashing Alliance",b="Gaxim Rustfizzle represents the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences. Stationed among the ancient groves of Stonetalon, his stated duty is proving to the nature-worshipping night elves that modern gnomish invention—blending magic, chemical brews, and mechanics—can actively protect their threatened lands. However, the relentless pace of the Venture Company has left him with barely any time to prototype his defensive devices.",sp=0},{t="Buying Time in Windshear Crag",b="To stem the tide, Gaxim sends adventurers directly into the smoking operations at Windshear Crag. By targeting the frontline Venture Co. Loggers and Deforesters, travelers give Gaxim the respite he needs to organize his workshop and devise his next line of defense: strategic, controlled high explosives.",sp=0}},faq={{q="Who is Gaxim Rustfizzle?",a="Gaxim Rustfizzle is an Alliance gnome mage and tinkerer located in the Stonetalon Mountains. He serves as an operative of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, attempting to aid the night elves against industrial invaders.",al={"gaxim","who is gaxim rustfizzle","quest giver gaxim"},it="identity"},{q="Why is a gnome trying to protect night elf forests?",a="Gaxim believes it is his duty to prove to the skeptical night elves that advanced gnomish sciences—specifically arcanology, alchemy, and engineering—can coexist with nature and actively help defend their wilderness from unchecked industrial exploitation.",al={"why gnome in stonetalon","why help night elves","gnome ecology"},it="why_here"},{q="Who are the Venture Company in Windshear Crag?",a="The Venture Company is a ruthless goblin-run merchant syndicate strip-mining and clear-cutting Windshear Crag. Driven purely by profit, they have overrun the valley with loggers, deforesters, and heavy logging machinery.",al={"venture co stonetalon","who are venture co","windshear crag goblins"},it="target"},{q="Where can the loggers and deforesters be found?",a="They operate throughout Windshear Crag, the heavily industrialized basin located directly east of Gaxim's position along the main road in the Stonetalon Mountains.",al={"where are loggers","where to find deforesters","windshear crag location"},it="place",gp=true},{q="What does Gaxim plan to do once he gets time to think?",a="With the goblin workers driven back, Gaxim intends to replenish his stock of high explosives, using targeted mountain detonations to herd and frighten the Venture Company away from the groves.",al={"gaxim plan","gnome respite continuation","explosives plan"},it="next_step"},{q="What is the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences?",a="It is a gnomish academic society that explores the integration of arcane spellcraft, chemical mixtures, and mechanical engineering to solve practical problems across Azeroth.",al={"gnomish assembly","arcanology assembly","what is enlightened assembly"},it="allies"},{q="Why does Gaxim Rustfizzle want the Venture Company culled?",a="Gaxim Rustfizzle feels it is his duty as a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences to prove that gnomish ingenuity can protect the night elves' sacred forests. The Venture Company's relentlessly rapid deforestation keeps him constantly overwhelmed, leaving him no breathing room to devise, organize, and assemble the inventive devices and explosives he needs to turn the tide.",al={"why kill loggers","gaxim motive","why cull venture co"},it="motive",add=true},{q="Why does Gaxim Rustfizzle need you to fight the goblins?",a="Gaxim is an inventor and researcher rather than an army of one, and he is working without major Alliance military support in Stonetalon. Between keeping his camp secure and attempting to draft new mechanical schematics, he simply cannot fight off the endlessly swarming Venture Company loggers alone. He relies on capable adventurers like you to thin their ranks so he can focus on building his countermeasures.",al={"why me gaxim","why does gaxim need help","why send an adventurer"},it="why_me",add=true}},ang={["race:Gnome"]="Gaxim's mission represents classic gnomish ambition: solving ancient, philosophical conflicts between nature and civilization through superior ingenuity and a bit of high explosives.",["race:NightElf"]="While Kaldorei sentinels typically view gnomish machinery with deep suspicion, the relentless advance of the Venture Company makes any effective deterrent welcome in Stonetalon.",["profession:Engineering"]="Engineers will appreciate Gaxim's philosophy that mechanisms and chemistry can solve environmental crises, as well as his fondness for high explosives."},kw={"deforester","explosives","gaxim rustfizzle","gnome","logger","stonetalon","venture co","windshear crag"},rel={"npc:gaxim-rustfizzle","subzone:windshear-crag","zone:stonetalon","topic:goblin","quest:1070"},m={start="Gaxim Rustfizzle",level="21",faction="Alliance",id=1071},src={"A Gnome's Respite"}}
E["quest:1072"] = {t="quest",n="An Old Colleague",z="stonetalon",s="An Old Colleague is an Alliance quest given by the gnome engineer Gaxim Rustfizzle in the Stonetalon Mountains. Looking to construct an extraordinarily potent device, Gaxim sends an adventurer all the way across the sea to Ironforge to track down an old acquaintance capable of synthesizing a hazardous explosive concoction. Completing this errand opens the door to procuring the volatile chemical compound known as Nitromirglyceronium.",h="An Old Colleague is an Alliance quest given by the gnome engineer Gaxim Rustfizzle in the Stonetalon...",sec={{t="A Volatile Recipe",b="While stationed among the peaks of Stonetalon, Gaxim Rustfizzle conceives of his most ambitious engineering endeavor yet. Creating a mechanism of that scale requires specialized fuel far beyond typical gunpowder or crude oil. Specifically, Gaxim requires Nitromirglyceronium, also designated as NG-5, an explosive mix potent enough to guarantee destructive results should everything go according to plan.",sp=0},{t="Tinker Town Connection",b="Formulating NG-5 is no simple task, and Gaxim knows of only one mind skilled enough to refine it: an old acquaintance named Lomac Gearstrip. Lomac resides far to the east in the gnome quarter of Tinker Town, tucked deep within the mountain stronghold of Ironforge. Entrusted with the long journey, the courier arrives only to be greeted by Lomac's immediate suspicion and paranoid questioning.",sp=0}},faq={{q="Who gives the quest An Old Colleague?",a="The quest is provided by Gaxim Rustfizzle, a gnome engineer stationed in the Stonetalon Mountains.",al={"quest giver","who starts an old colleague","gaxim quest"},gp=true},{q="Where can I find Lomac Gearstrip?",a="Lomac Gearstrip can be found within Tinker Town, the gnomish quarter located in the eastern portion of the dwarven city of Ironforge.",al={"where is lomac","lomac gearstrip location","ironforge lomac"},gp=true},{q="What is Nitromirglyceronium?",a="Nitromirglyceronium, also known as NG-5, is an extremely volatile chemical explosive engineered by Lomac Gearstrip and coveted by Gaxim Rustfizzle for his high-powered devices.",al={"what is ng-5","nitromirglyceronium","ng 5"},it="item"},{q="Why does Gaxim send me all the way to Ironforge?",a="Gaxim claims that Lomac Gearstrip is the only person capable of synthesizing the specialized NG-5 compound necessary to power his experimental device.",al={"why travel to ironforge","why lomac","why go to tinker town"},it="motive"},{q="What happens after finding Lomac Gearstrip?",a="Once you confirm Gaxim's request with the suspicious Lomac, he presents you with the quest Ineptitude + Chemicals = Fun to gather the hazardous reagents required to mix the batch.",al={"next quest","what comes after an old colleague","followup quest"},it="next_step",gp=true},{q="Which faction can undertake this task?",a="This is strictly an Alliance quest, as it originates from an Alliance-aligned gnome in Stonetalon and concludes inside the Alliance capital of Ironforge.",al={"is this alliance only","horde version","can horde do this"},it="side",gp=true},{q="Why does Gaxim Rustfizzle need you instead of going to Ironforge himself?",a="Gaxim Rustfizzle is busy in the Stonetalon Mountains scouting and preparing the tactical placement for his experimental devices. Because fabricating the high-grade explosive Nitromirglyceronium requires a long trek back across the sea to Tinker Town in Ironforge, he relies on a capable traveler to handle the legwork while he stays on-site to ready the operation.",al={"why does gaxim need me","why send an adventurer to ironforge","why can't gaxim go to lomac"},it="why_me",add=true}},ang={["faction:Alliance"]="This task sends Alliance adventurers on a continent-spanning journey from the embattled crags of Kalimdor back to the safety of Ironforge.",["race:Gnome"]="A quintessential gnomish endeavor involving long-distance academic network ties, eccentric rivalries, and dangerously unstable explosive compounds.",["profession:Engineering"]="Engineers will appreciate Gaxim and Lomac's relentless pursuit of maximum firepower regardless of the hazardous logistics involved."},kw={"explosives","gaxim rustfizzle","ironforge","lomac gearstrip","ng-5","nitromirglyceronium","stonetalon","tinker town"},rel={"npc:gaxim-rustfizzle","npc:lomac-gearstrip","quest:1073","subzone:tinker-town","zone:ironforge","zone:stonetalon"},m={start="Gaxim Rustfizzle",["end"]="Lomac Gearstrip",level="21",faction="Alliance",id=1072},src={"An Old Colleague"}}
E["quest:1073"] = {t="quest",n="Ineptitude + Chemicals = Fun",z="stonetalon",s="Seeking an explosive countermeasure against the Venture Company's logging machines in the Stonetalon Mountains, Alliance adventurers are sent across the sea to Ironforge. There, the eccentric gnome Lomac Gearstrip agrees to brew his volatile invention, Nitromirglyceronium, provided you fetch the necessary alchemical reagents.",h="Seeking an explosive countermeasure against the Venture Company's logging machines in the Stonetalon...",sec={{t="A Volatile Solution",b="Gaxim Rustfizzle, stationed high in the craggy passes of the Stonetalon Mountains, found himself completely stymied by the sheer bulk and armor of goblin shredders. Rather than relying on simple steel or standard siege tactics, he turned to an eccentric former colleague living in Ironforge: Lomac Gearstrip. Lomac is the creator of Nitromirglyceronium, a substance so inherently unstable and destructive that he finds the prospect of anyone using it hilarious, regardless of who gets blown apart in the process.",sp=0},{t="Potions for Pyrotechnics",b="Despite Lomac's eagerness to see goblin machinery—and possibly the adventurer—blown into pieces, his workshop in Ironforge is entirely out of the finished compound. Before he will brew a fresh batch of Nitromirglyceronium, Lomac demands common alchemical draughts: Minor Mana Potions and Elixirs of Minor Fortitude. In his eyes, forcing an adventurer to gather these ingredients serves a dual purpose, ensuring he has the raw reagents needed for the reaction while proving they possess at least a shred of respect for the craft of alchemy.",sp=0}},faq={{q="Who is Lomac Gearstrip?",a="Lomac Gearstrip is an eccentric gnomish alchemist and tinkerer located in the dwarven capital of Ironforge. He is an old colleague of Gaxim Rustfizzle and the inventor of Nitromirglyceronium, an extraordinarily volatile explosive compound.",al={"lomac gearstrip","who is lomac","ironforge gnome"},it="identity"},{q="Why does Lomac want potions instead of standard engineering parts?",a="Lomac utilizes alchemy alongside his mechanical know-how to produce high-grade volatile reactions. The magical energy of Minor Mana Potions and the stabilizing bodily humors enhanced by Elixirs of Minor Fortitude serve as base reagents for his specialized Nitromirglyceronium mixture.",al={"why potions","alchemical ingredients","why mana potions"},it="item"},{q="Why send an adventurer all the way to Ironforge for this?",a="Gaxim Rustfizzle is isolated in the wilds of Stonetalon without access to heavy industrial or chemical workshops. Lomac Gearstrip in Ironforge is the only associate he trusts—or fears enough—to possess an explosive potent enough to crack Venture Company machinery.",al={"why ironforge","why travel so far","gaxim to ironforge"},it="why_here"},{q="What is Nitromirglyceronium?",a="Nitromirglyceronium is Lomac Gearstrip's proprietary explosive chemical brew. It is notoriously volatile, formulated specifically to generate enough concussive blast force to tear apart heavily fortified mechanical equipment.",al={"nitromirglyceronium","what is the explosive","gnome bomb juice"},it="origin"},{q="Is Lomac worried about the Venture Company or the forest?",a="Not in the slightest. Lomac openly laughs at the idea of using high explosives to save trees. His sole interest in handing over the compound is the chaotic prospect of watching either the goblins or the courier get blasted to pieces.",al={"does lomac care about nature","lomac motives"},it="side"},{q="Do you need to be an alchemist to complete this task?",a="No. While Lomac talks about testing your alchemical mettle, he accepts reagents acquired through trade, merchants, or other crafters just the same, so long as he gets the draughts required for his recipe.",al={"need alchemy","alchemy required"},gp=true},{q="Why does Lomac Gearstrip want this done?",a="Lomac cares little for the Venture Company, the fate of Stonetalon's forests, or his old acquaintance Gaxim Rustfizzle. What delights him is sheer chaos and explosive potential. He agrees to brew his volatile Nitromirglyceronium simply for the twisted amusement of watching either you or the goblins blow up into tiny pieces, provided you supply the reagents to replenish his stock.",al={"lomac gearstrip motive","why help lomac","why make nitromirglyceronium"},it="motive",add=true},{q="What is the Minor Mana Potion for?",a="The Minor Mana Potions are essential liquid reagents in Lomac's unstable concoction. Along with the fortitude elixirs, their magical energy serves as a vital catalyst required to synthesize a fresh batch of Nitromirglyceronium, his volatile and prideful alchemical invention.",al={"minor mana potion use","why minor mana potion","mana potion nitromirglyceronium"},it="item",add=true},{q="What is the Elixir of Minor Fortitude for?",a="Lomac requires the Elixirs of Minor Fortitude as key components for brewing Nitromirglyceronium. In his eccentric chemical recipe, the fortifying mixture forms part of the reactive base needed to create the explosive compound.",al={"elixir of minor fortitude use","why elixir of minor fortitude","fortitude elixir nitromirglyceronium"},it="item",add=true},{q="Why does Lomac need you to fetch the potions instead of getting them himself?",a="Lomac is completely out of supplies and feels no urgency to help you or Gaxim on his own dime. By making you fetch or brew the ingredients yourself, he forces you to prove your resourcefulness and alchemical competence before he entrusts you with his prized, dangerous creation.",al={"why does lomac need me","why do i need to get the potions","why cant lomac get his own potions"},it="why_me",add=true}},ang={["race:Gnome"]="Lomac represents the unrestrained, madcap fringe of gnomish ingenuity, prioritizing sheer chemical yield and theoretical application over safety or diplomatic caution.",["faction:Alliance"]="The long trek from Stonetalon to Ironforge highlights the logistical strain of supporting remote Alliance outposts scattered throughout hostile Kalimdor.",["profession:Engineering"]="Where standard blasting powder fails against Venture Company steel, combining esoteric alchemy with engineering principles produces far more catastrophic results."},kw={"elixir of minor fortitude","gaxim rustfizzle","ironforge","lomac gearstrip","mana potion","nitromirglyceronium","stonetalon","venture company"},rel={"npc:lomac-gearstrip","quest:1072","zone:stonetalon","zone:ironforge","topic:goblin"},m={start="Lomac Gearstrip",level="21",faction="Alliance",id=1073,ri={"Elixir of Minor Fortitude","Minor Mana Potion"}},src={"Ineptitude + Chemicals = Fun"}}
E["quest:1074"] = {t="quest",n="Ineptitude + Chemicals = Fun",z="stonetalon",s="This errand delivers a canister of volatile NG-5 from the tinker Lomac Gearstrip to Gaxim Rustfizzle in the Stonetalon Mountains. Gaxim requires this unstable chemical to create a potent igniter for several wagons packed with dynamite. The resulting blast forms a critical distraction for Alliance operations in the disputed crags.",h="This errand delivers a canister of volatile NG-5 from the tinker Lomac Gearstrip to Gaxim Rustfizzle in the...",sec={{t="A Volatile Delivery",b="Gnomish engineering often balances brilliance on the razor edge of catastrophe, and Nitromirglyceronium—or NG-5—is no exception. Lomac Gearstrip hands over the unstable compound with a stern warning: handle it with extreme care, or risk blowing yourself to pieces on the road back to Gaxim Rustfizzle.",sp=0},{t="A Recipe for Distraction",b="Upon receiving the canister intact, Gaxim Rustfizzle reveals the true scope of his handiwork. NG-5 is the essential catalyst needed to detonate entire wagons full of dynamite. By staging a colossal explosion, Gaxim hopes to sow chaos and misdirect enemies in Stonetalon while the Alliance pursues its regional goals.",sp=1}},faq={{q="What is NG-5?",a="NG-5, short for Nitromirglyceronium, is a highly volatile chemical compound concocted by Lomac Gearstrip. It serves as an unequivocal ignition catalyst for heavy ordnance.",al={"what is nitromirglyceronium","ng-5","what did lomac give me"},it="item"},{q="Who is Gaxim Rustfizzle?",a="Gaxim Rustfizzle is a gnome mage stationed in the Stonetalon Mountains, orchestrating Alliance demolition efforts and tactical distractions against regional threats.",al={"gaxim","who is gaxim rustfizzle"},it="identity"},{q="Who is Lomac Gearstrip?",a="Lomac Gearstrip is an engineer and associate of Gaxim Rustfizzle who prepares the dangerous NG-5 compound and entrusts it to reliable couriers.",al={"lomac","who is lomac gearstrip"},it="identity"},{q="Why does Gaxim need so much explosive power?",a="Gaxim has arranged multiple wagons loaded with dynamite. The NG-5 provides the reliable, massive spark required to detonate them all at once, creating an overwhelming diversion.",al={"why wagons of dynamite","gaxim plan","why the explosion"},it="motive"},{q="Is the chemical dangerous to transport?",a="Lomac explicitly warns that NG-5 is unstable and prone to catastrophic accidental detonation if mishandled, though a steady courier can deliver it safely to Gaxim.",al={"does ng5 explode","is ng-5 safe"},it="danger"},{q="Where does this delivery take place?",a="The delivery concludes at Gaxim Rustfizzle's post within the rugged passes of the Stonetalon Mountains.",al={"where is gaxim","stonetalon location"},it="place"},{q="Why does Lomac Gearstrip give you the NG-5?",a="Lomac is fulfilling a request from his associate Gaxim Rustfizzle, providing the volatile Nitromirglyceronium as asked. He does not pry into the details—if you truly are Gaxim's ally, he sends along his greetings, and if you are an imposter, he is content letting the explosive compound blow you to pieces.",al={"why does lomac help","lomac gearstrip motive","why give ng5"},it="motive",add=true}},ang={["race:Gnome"]="Only gnomish ambition would consider wagons of high explosives ignited by Nitromirglyceronium a reasonable distraction.",["profession:Engineering"]="Handling NG-5 requires an appreciation for volatile chemistry and a steady pair of hands to avoid early detonation.",["faction:Alliance"]="Stonetalon is a contested frontier; a massive explosion gives Alliance operatives the breathing room they desperately need."},kw={"dynamite","engineering","gaxim rustfizzle","gnome","lomac gearstrip","ng-5","nitromirglyceronium","stonetalon"},rel={"quest:1073","npc:gaxim-rustfizzle","npc:lomac-gearstrip","zone:stonetalon"},m={start="Lomac Gearstrip",["end"]="Gaxim Rustfizzle",level="21",faction="Alliance",id=1074},src={"Ineptitude + Chemicals = Fun (2)"}}
E["quest:1077"] = {t="quest",n="Special Delivery for Gaxim",z="stonetalon",s="Special Delivery for Gaxim represents the return leg of an Alliance courier mission between Stormwind City and the wilds of Kalimdor. Collin Mauren provides a specialized Scroll of Messaging to take back to the gnome tinkerer Gaxim Rustfizzle in the Stonetalon Mountains. The scroll contains the arcane component needed to construct a remote explosive against local deforestation efforts.",h="Special Delivery for Gaxim represents the return leg of an Alliance courier mission between Stormwind City...",sec={{t="Arcane Deliveries",b="Gaxim Rustfizzle's efforts to sabotage the destructive operations of the Venture Company require unconventional solutions. Having concocted an explosive compound called NG-5, the tinkerer found himself lacking a reliable means of remote detonation. Rather than turning to crude fuses, Gaxim enlisted help across the Great Sea, reaching out to Collin Mauren in the Mage Quarter of Stormwind to acquire an enchanted Scroll of Messaging.",sp=0},{t="A Remote Distraction",b="Upon receiving the scroll, Gaxim reveals the full scope of his eccentric engineering plan. The enchanted parchment does not serve merely to pass words across long distances; instead, its communicative magic can be tethered directly to the unstable NG-5 mixture. By triggering the detonation magically from afar, Gaxim intends to produce a devastating distraction that allows operatives to slip into the Venture Company compound undetected.",sp=1}},faq={{q="What is the Scroll of Messaging used for?",a="While originally designed as an arcane tool for conveying messages, Gaxim Rustfizzle combines the scroll with his volatile NG-5 compound. The messaging magic acts as a remote trigger, allowing him to detonate explosives safely from a distance.",al={"why scroll of messaging","what does the scroll do","scroll of messaging purpose"},it="purpose"},{q="Who is Collin Mauren?",a="Collin Mauren is an Alliance wizard based in the Mage Quarter of Stormwind City. He assists adventurers with arcane matters and crafts the enchanted scroll needed for Gaxim's plan in Stonetalon.",al={"collin mauren lore","who is collin"},it="identity"},{q="Why is Gaxim Rustfizzle sabotaging the Venture Company?",a="The Venture Company is ruthlessly clear-cutting the pristine forests of the Stonetalon Mountains. Gaxim aims to slow down their deforestation by causing chaos, destroying their operations, and stealing their proprietary engineering plans and correspondence.",al={"why attack venture co","gaxim motivation","venture co stonetalon"},it="conflict"},{q="Where does this delivery take the adventurer?",a="The delivery takes the courier from Stormwind City across the sea back to the Alliance camp in the crags of the Stonetalon Mountains on Kalimdor.",al={"delivery destination","where is gaxim","stonetalon location"},it="place",gp=true},{q="What happens after the scroll is delivered?",a="With both the scroll and NG-5 in hand, Gaxim prepares a remote explosive distraction, clearing the way for an operative to infiltrate the Windshear Crag operations to recover logging letters and schematics.",al={"next quest","what after delivery","venture co distraction"},sp=1,it="next_step"},{q="Why does Collin Mauren want this done?",a="Collin Mauren is acting as a helpful arcane colleague and friend to Gaxim Rustfizzle. While Collin remains safely in Stormwind conducting his magical studies, he is intrigued by Gaxim's daring scheme against the Venture Company in Kalimdor and gladly provides the necessary spell, looking forward to hearing all about the adventure once it is finished.",al={"collin mauren motive","why help gaxim collin","collin mauren why send scroll"},it="motive",add=true}},ang={["profession:Engineering"]="Gaxim's scheme highlights the quirky intersection of gnomish engineering and wizardry, pairing volatile NG-5 explosives with arcane triggers.",["class:Mage"]="Collin Mauren's craft demonstrates how simple parchment enchantments can be repurposed into functional arcane relays by clever tinkerers.",["faction:Alliance"]="This task demonstrates the logistical links connecting the human capital of Stormwind to remote Alliance outposts struggling against industrial exploitation in Kalimdor."},kw={"collin mauren","gaxim rustfizzle","ng-5","remote explosive","scroll of messaging","stonetalon","venture co"},rel={"npc:gaxim-rustfizzle","npc:collin-mauren","zone:stonetalon","quest:764"},m={start="Collin Mauren",["end"]="Gaxim Rustfizzle",level="21",faction="Alliance",id=1077},src={"Special Delivery for Gaxim"}}
E["quest:1078"] = {t="quest",n="Retrieval for Mauren",z="stonetalon",s="Retrieval for Mauren is a quest given by Collin Mauren in the Mage Quarter of Stormwind. Hearing tales of travelers venturing deep into Kalimdor, the wizard contracts Alliance adventurers to gather crystallised scales from basilisks dwelling in Stonetalon's Charred Vale. Mauren seeks these rare specimens to grind into dust as reagents for his personal spellcraft.",h="Retrieval for Mauren is a quest given by Collin Mauren in the Mage Quarter of Stormwind.",sec={{t="A Mage's Curious Reagents",b="Collin Mauren, a wizard residing in the Mage Quarter of Stormwind City, keeps an ear close to the chatter of wandering adventurers. Word has reached him that the distant Stonetalon Mountains in Kalimdor have become a burgeoning hotspot for travelers seeking wild wyverns, unruly elementals, or lucrative deals and clashes with the Venture Company. Rather than seeking riches or glory, Mauren's interest lies in the rare natural wonders reported from the region's harshest corners.",sp=0},{t="The Glassy Beasts of the Vale",b="Deep within Stonetalon lies the Charred Vale, an ash-choked expanse left scarred by the Venture Company's devastation. According to Mauren's studies, the basin was once known to house a peculiar breed of basilisk. When harvested and crushed into a fine powder, their scales form a potent catalyst for specialized arcane spells he has developed. Unsure whether the creatures managed to survive the harsh transformation of the Vale, Mauren relies on intrepid explorers to harvest a fresh batch of crystallised scales and confirm whether the breed endures.",sp=0}},faq={{q="Who is Collin Mauren?",a="Collin Mauren is an arcane practitioner found in the Mage Quarter of Stormwind. He studies esoteric spellcraft and frequently relies on adventurous travelers to procure rare magical reagents from distant lands.",al={"collin mauren","who gives retrieval for mauren","mauren stormwind"},it="identity"},{q="Why does Collin Mauren need basilisk scales?",a="Mauren grinds the crystallized scales into fine dust, utilizing their unique mineral composition as a catalyst reagent for original spells he has devised.",al={"why scales","what are scales for","crystallized scales use"},it="item"},{q="Where is the Charred Vale located?",a="The Charred Vale is a ruined, soot-covered basin located in the southwestern reaches of the Stonetalon Mountains on the continent of Kalimdor.",al={"where charred vale","find charred vale","charred vale location"},it="place",gp=true},{q="Why is the Charred Vale charred?",a="The Charred Vale was devastated by the Venture Company's goblins, whose destruction enraged the vale's spirits and loosed elementals, leaving the ground blackened, smoldering, and populated by hardy, twisted beasts.",al={"what happened to charred vale","charred vale fire","charred vale destruction"},it="history"},{q="What creatures drop the scales needed for this task?",a="The scales are gathered from the various basilisks prowling the smoldering wastes of the Charred Vale in Stonetalon Mountains.",al={"which basilisks","who drops crystallized scales","scale mobs"},it="target",gp=true},{q="Why send an adventurer all the way across the sea for this?",a="The specific crystalline properties Mauren requires are only found on the basilisks indigenous to the Charred Vale. Because crossing the Great Sea is perilous, Mauren enlists seasoned travelers already setting out for Kalimdor.",al={"why kalimdor","why stonetalon for scales"},it="why_me"},{q="Why does Collin Mauren want the basilisk scales?",a="Collin Mauren is an inventive mage residing in Stormwind who crafts his own original spells. He discovered that the crystallized scales of basilisks native to Stonetalon's Charred Vale, once ground into fine dust, serve as an ideal magical reagent. Because he remains in the city conducting arcane studies, he relies on venturing travelers to replenish his rare stock.",al={"collin mauren motive","why does mauren want scales","why collect scales for mauren"},it="motive",add=true},{q="What creatures are you hunting in the Charred Vale?",a="You are sent into the scorched depths of the Charred Vale to track down the local basilisks that dwell among the ash and elemental ruins. Mauren remembers their unique crystal-crusted hides from past reports, though he is uncertain whether the hardy beasts have survived the catastrophic burning of the valley.",al={"what basilisks in charred vale","who do i fight for mauren","stonetalon basilisk targets"},it="target",add=true}},ang={["class:Mage"]="Procuring esoteric reagents for fellow wizards is a hallmark of arcane research, illustrating how exotic magical wildlife fuels the development of new incantations.",["faction:Alliance"]="This task demonstrates how the Alliance's presence in Stormwind maintains active interests and supply lines reaching deep into the wild territories of Kalimdor."},kw={"basilisk scales","charred vale","collin mauren","crystallized scales","mage quarter","retrieval for mauren","stonetalon mountains","stormwind"},rel={"npc:collin-mauren","subzone:charred-vale","zone:stonetalon","topic:stormwind-kingdom","quest:764"},m={start="Collin Mauren",level="26",faction="Alliance",id=1078,ri={"Crystalized Scales"}},src={"Retrieval for Mauren"}}
E["quest:1079"] = {t="quest",n="Covert Ops - Alpha",z="stonetalon",s="Covert Ops - Alpha is an Alliance infiltration mission directed by the gnome tinker Gaxim Rustfizzle in the Stonetalon Mountains. While operating out of the peaks, operatives are tasked with penetrating the Venture Company's lumber mill in Windshear Crag to recover proprietary engineering schematics. Securing these blueprints allows the Alliance to decipher the mechanical vulnerabilities of goblin machinery while co-opting their logging technology.",h="Covert Ops - Alpha is an Alliance infiltration mission directed by the gnome tinker Gaxim Rustfizzle in the...",sec={{t="Sabotage and Espionage",b="Operating from Windshear Crag, Gaxim Rustfizzle conducts a persistent covert campaign to disrupt the aggressive logging operations of the Venture Company. While goblin deforesters fell the primeval timber south of Cragpool Lake, Gaxim recognizes that wanton destruction alone cannot halt the enterprise. Instead of merely detonating industrial hardware, Plan Alpha prioritizes intelligence gathering, requiring agents to slip past goblin loggers and overseers to seize their core technical schematics directly from the lumber mill.",sp=0},{t="Reverse Engineering",b="Gnomish interest in the Venture Company extends beyond ecological sympathy for the night elves. The recovered schematics detail the inner workings of heavy-duty goblin loggers, mechanical cutters, and mechanized transports. By studying these blueprints, Alliance engineers can expose critical structural flaws to dismantle future operations—while simultaneously borrowing refined goblin designs to enhance their own mechanical projects back in Ironforge and Gnomeregan.",sp=0}},faq={{q="What is the primary goal of Covert Ops - Alpha?",a="The primary objective is the recovery of the Venture Company's engineering plans from their lumber mill in Windshear Crag, located south of Cragpool Lake. While explosive devices are involved in the overall covert effort, securing these blueprints is the sole measure of the mission's success.",al={"what is covert ops alpha","alpha mission goal","what does gaxim want"},it="purpose"},{q="Who gives the quest Covert Ops - Alpha?",a="The mission is assigned by Gaxim Rustfizzle, an Alliance gnome tinker stationed in the Stonetalon Mountains overseeing covert sabotage operations against goblin industrial efforts.",al={"who starts covert ops alpha","gaxim rustfizzle quest","covert ops quest giver"},it="identity",gp=true},{q="Where are the engineering plans located?",a="The Venture Company Engineering Plans are kept inside the operational lumber mill in Windshear Crag, situated just south of Cragpool Lake amidst heavy goblin logging defenses.",al={"where are the venture co plans","engineering plans location","windshear crag lumber mill plans"},it="place",gp=true},{q="Why does Gaxim Rustfizzle want the Venture Co. blueprints?",a="Gaxim seeks the plans to study the structural vulnerabilities of goblin logging machines. Discovering their mechanical flaws allows the Alliance to sabotage future machinery more effectively, while also adopting practical goblin engineering designs for Alliance devices.",al={"why steal venture co plans","what will gaxim do with plans","reason for covert ops alpha"},it="motive"},{q="Is sheer destruction the point of the mission?",a="No. Gaxim explicitly reminds operatives that mission success does not depend on the amount of destruction inflicted, but rather on successfully extracting the schematics intact from the mill.",al={"do i blow up the mill","should i destroy machines","mission destruction focus"},it="purpose"},{q="Why is the Alliance fighting the Venture Company here?",a="The Venture Company is pillaging the natural resources of Stonetalon through unchecked deforestation and industrial pollution. Alliance operatives intervene to undermine their industrial footprint and preserve strategic territory in Kalimdor.",al={"why fight venture company in stonetalon","alliance venture co conflict","stonetalon logging war"},it="conflict"},{q="What are the Venture Co. Engineering Plans for?",a="These detailed schematics outline the internal mechanisms and layout of the Venture Company's heavy logging machinery in Windshear Crag. By recovering them, Gaxim Rustfizzle aims to pinpoint critical design flaws in their equipment to sabotage future operations, while also stealing their best concepts to improve Alliance engineering innovations.",al={"venture co engineering plans use","what are the blueprints for","engineering plans purpose"},it="item",add=true}},ang={["race:Gnome"]="For a gnome tinker, analyzing goblin blueprints is the ultimate prize: it offers the rare chance to mock goblin design oversights while stealing their most lucrative mechanical tricks.",["profession:Engineering"]="The recovered schematics expose the gritty, high-combustion mechanisms favored by the Venture Company, providing valuable technical insights into industrial motor works.",["race:NightElf"]="The Venture Company's deforestation in Windshear Crag wounds Stonetalon's ancient forests, making any sabotage of their logging infrastructure an urgent priority for the kaldorei.",["faction:Alliance"]="Securing footholds and curbing industrial extraction across Kalimdor ensures the Alliance maintains tactical parity against rival powers encroaching on contested wilderness."},kw={"alpha","covert ops","cragpool lake","engineering plans","gaxim rustfizzle","lumber mill","stonetalon","venture co","windshear crag"},rel={"npc:gaxim-rustfizzle","subzone:windshear-crag","subzone:cragpool-lake","zone:stonetalon","quest:764"},m={start="Gaxim Rustfizzle",level="22",faction="Alliance",id=1079,ri={"Venture Co. Engineering Plans"}},src={"Covert Ops - Alpha"}}
E["quest:1080"] = {t="quest",n="Covert Ops - Beta",z="stonetalon",s="Covert Ops - Beta is an Alliance mission organized by the gnome engineer Gaxim Rustfizzle in the Stonetalon Mountains. Building upon previous sabotage against the encroaching Venture Company, this operation sends an agent deep into Windshear Mine to trigger explosive diversions and extract vital operational letters. The retrieved intelligence serves both gnome curiosity and the territorial defense of the regional night elf Sentinels.",h="Covert Ops - Beta is an Alliance mission organized by the gnome engineer Gaxim Rustfizzle in the Stonetalon...",sec={{t="Sabotage in the Depths",b="Following initial strikes against the Venture Company's clear-cutting operations across Windshear Crag, Gaxim Rustfizzle devises a follow-up operation aimed directly at their logistical heart. Plan Beta follows the same fundamental logic as its predecessor: creating an explosive, chaotic diversion to scatter the goblin operators and mercenaries while an operative slips through the confusion to search the mines for written correspondence.",sp=0},{t="Eyes on Windshear Mine",b="Windshear Mine sits at the far eastern reaches of the crag, serving as the company's regional subterranean base. Digging through rock and harvesting timber, the goblins maintain strict ledgers and communications detailing their supply lines and executive directives. By sneaking inside, setting Gaxim's specialized explosive packs, and seizing the Venture Co. Letters, operatives dismantle the company's security while uncovering their wider ambitions in Kalimdor.",sp=0},{t="A Pragmatic Partnership",b="While Gaxim approaches the mission with typical gnomish delight for pyrotechnics and clever gadgetry, the mission has serious strategic implications for the night elves. The Sentinels in Stonetalon, led by commanders like Kaela Shadowspear, are hard-pressed battling both the Horde and ruthless industrial exploiters. The intelligence recovered from the mine directly assists the Sentinels in predicting and thwarting the defilement of their sacred woodlands.",sp=0}},faq={{q="What is the goal of Covert Ops - Beta?",a="The objective is to infiltrate Windshear Mine in eastern Windshear Crag, detonate explosive diversions using Gaxim Rustfizzle's pack, and steal the Venture Co. Letters outlining their regional operations.",al={"covert ops beta objective","what do i do in covert ops beta","plan beta goal"},it="purpose"},{q="Who is Gaxim Rustfizzle?",a="Gaxim Rustfizzle is a gnome engineer stationed in the Stonetalon Mountains. He uses his mechanical expertise and explosive inventions to assist the night elf Sentinels in combating the logging and mining ventures encroaching on the mountain.",al={"gaxim rustfizzle","who gives covert ops beta"},it="identity"},{q="Where is Windshear Mine located?",a="Windshear Mine is carved into the mountains at the eastern end of Windshear Crag, nestled deep inside the Venture Company's sprawling clear-cut deforestation zone.",al={"windshear mine location","where is the mine"},it="place",gp=true},{q="Why does Gaxim want the Venture Co. Letters?",a="The letters contain vital intelligence on the Venture Company's supply routes, leadership directives, and operational plans. Recovering them helps the Alliance and the Sentinels anticipate the company's next moves and disrupt their exploitation of the forest.",al={"why steal letters","what are the venture co letters"},it="motive"},{q="How does this mission benefit the night elves?",a="The night elf Sentinels lack the numbers to police every corner of Stonetalon against industrial desecration. Gaxim's explosive sabotage delays the logging efforts, while the recovered correspondence gives Sentinel commanders like Kaela actionable intelligence on their enemies.",al={"why do night elves care","sentinels covert ops"},it="ties"},{q="What was Plan Alpha?",a="Plan Alpha was Gaxim's preceding covert operation, establishing the tactic of planting engineering charges across Venture Company logging equipment in Windshear Crag to sow chaos and weaken their perimeter.",al={"plan alpha","covert ops alpha","previous mission"},it="history"},{q="What are the Venture Co. Letters for?",a="These documents contain vital communications and plans from the Venture Company's leadership inside Windshear Mine. By seizing them, Gaxim Rustfizzle and the local night elf Sentinels hope to uncover the defilers' operations, disrupt their aggressive logging and mining efforts across Stonetalon, and hand a critical tactical advantage back to Kaela's defenders.",al={"venture co letters use","why venture co letters","what are the letters"},it="item",add=true},{q="Who are you infiltrating at Windshear Mine?",a="You are striking at the Venture Company, an unscrupulous goblin-run commercial cartel infamous for ruthless resource exploitation. They have entrenched themselves within Windshear Crag, gouging out the earth, harvesting the sacred forests, and ignoring the sacred land claims of the night elves, turning the entire region into an industrial blight.",al={"windshear mine enemies","who is at windshear crag","venture co stonetalon"},it="target",add=true}},ang={["race:Gnome"]="Gaxim Rustfizzle's blend of high-yield explosives, meticulous planning, and covert intrusion represents quintessential gnomish ingenuity put to practical military use.",["race:NightElf"]="The Venture Company is stripping the ancient woods bare; supporting Gaxim's covert operations ensures that Sentinel commanders receive the intelligence needed to protect the mountain.",["profession:Engineering"]="The mission centers around Gaxim's specialized Covert Ops Pack, showing how clever pyrotechnic diversions can accomplish objectives that brute force alone cannot.",["faction:Alliance"]="Coordinating gnomish technology with night elf territorial defense strengthens the Alliance's fragile presence across central Kalimdor."},kw={"covert ops - beta","gaxim rustfizzle","sentinels","stonetalon mountains","venture co.","venture co. letters","windshear crag","windshear mine"},rel={"npc:gaxim-rustfizzle","subzone:windshear-crag","quest:764","topic:sentinels","zone:stonetalon"},m={start="Gaxim Rustfizzle",level="22",faction="Alliance",id=1080,ri={"Venture Co. Letters"}},src={"Covert Ops - Beta"}}
E["quest:1081"] = {t="quest",n="Reception from Tyrande",z="stonetalon",s="Reception from Tyrande is an Alliance quest that sends adventurers from the embattled slopes of the Stonetalon Mountains directly to the night elf capital of Darnassus. After aiding the Sentinels in securing their precarious foothold in Stonetalon against the Venture Company, you are sent by Sentinel Thenysil in Astranaar to receive formal recognition from High Priestess Tyrande Whisperwind herself in the Temple of the Moon.",h="Reception from Tyrande is an Alliance quest that sends adventurers from the embattled slopes of the...",sec={{t="A Foothold in Stonetalon",b="The night elven outposts scattered throughout the Stonetalon Mountains face intense pressure, particularly from the Venture Company ravaging the land. Sentinel Thenysil coordinates efforts from Astranaar, but sustaining these remote bases requires immense resilience. Securing supply lines and intelligence is vital to maintaining an Alliance presence in Kalimdor's interior, making outside aid profoundly impactful to the Sentinels stationed there.",sp=0},{t="Audience with the High Priestess",b="Recognizing that your assistance has actively bolstered the Sentinels' grip on the region, Sentinel Thenysil directs you to travel back to Teldrassil. At the Temple of the Moon in Darnassus, High Priestess Tyrande Whisperwind grants you a personal audience. Tyrande acknowledges your rising deeds across Kalimdor, welcoming you not merely as a wandering mercenary, but as an allied champion fighting alongside the kaldorei.",sp=0}},faq={{q="Where does this quest start?",a="The quest begins with Sentinel Thenysil in Astranaar in Ashenvale, immediately following the completion of 'Update for Sentinel Thenysil'.",al={"where do i get reception from tyrande","quest giver","sentinel thenysil location"},it="place",gp=true},{q="Where can I find Tyrande Whisperwind?",a="Tyrande Whisperwind resides within the Temple of the Moon, located in the central district of the night elf capital city of Darnassus on Teldrassil.",al={"where is tyrande","find tyrande","temple of the moon location"},it="place",gp=true},{q="Why does Tyrande want to see me?",a="Your efforts in Stonetalon have helped preserve the Kaldorei foothold in contested mountain territory. Sentinel Thenysil feels your contributions to the night elves warrant a personal token of appreciation from their spiritual and military leader.",al={"why tyrande wants to talk","purpose of audience"},it="motive"},{q="What is the strategic value of the Stonetalon Mountains?",a="Stonetalon forms a rugged buffer between Ashenvale and the southern plains of Kalimdor. With Horde forces pushing out from the Barrens, holding outposts here is crucial for the night elves to monitor enemy movements and safeguard sacred lands.",al={"why care about stonetalon","stonetalon lore"},it="place"},{q="Do other Alliance races get recognized here?",a="Yes. Any Alliance adventurer who assists Sentinel Thenysil can undertake this journey to Darnassus, symbolizing the growing mutual defense between the night elves and the broader Alliance.",al={"can non night elves do this","is this for humans"},it="allies"},{q="Is there a follow-up quest after meeting Tyrande?",a="This audience marks the culmination of the Stonetalon courier and support tasks for Sentinel Thenysil, serving as a formal conclusion and offering an opportunity to seek further orders in Darnassus.",al={"what comes next","next quest in chain"},it="next_step",gp=true},{q="Why does Sentinel Thenysil send you to Darnassus?",a="Sentinel Thenysil believes your efforts have laid the groundwork to secure the night elves' foothold in the embattled Stonetalon Mountains. Recognizing your dedication in standing against the atrocities unfolding in the peaks, she wants you to receive formal recognition and gratitude directly from the night elf leader, High Priestess Tyrande Whisperwind.",al={"why does thenysil send me","thenysil reason tyrande","why go to tyrande"},it="motive",add=true}},ang={["faction:Alliance"]="An audience with Tyrande Whisperwind serves as a meaningful bridge between Kalimdor's night elves and the broader Alliance, turning wilderness skirmishes into recognized service to Darnassus.",["race:NightElf"]="Reporting to High Priestess Tyrande Whisperwind inside the Temple of the Moon is a proud homecoming, proving your devotion to the defense of ancient ancestral grounds."},kw={"darnassus","kaldorei","reception from tyrande","sentinel thenysil","stonetalon mountains","teldrassil","temple of the moon","tyrande whisperwind"},rel={"npc:tyrande-whisperwind","npc:sentinel-thenysil","quest:1082","subzone:temple-of-the-moon","zone:darnassus","zone:stonetalon","quest:2519"},m={start="Sentinel Thenysil",["end"]="Tyrande Whisperwind",level="28",faction="Alliance",id=1081},src={"Reception from Tyrande"}}
E["quest:1082"] = {t="quest",n="Update for Sentinel Thenysil",z="stonetalon",s="This errand carries word of relief from the crags of Stonetalon back to the night elf outpost of Astranaar. Having aided Kaela Shadowspear and Gaxim Rustfizzle against the encroaching Venture Company, you are tasked with reassuring Sentinel Tara Thenysil that their outpost holds firm.",h="This errand carries word of relief from the crags of Stonetalon back to the night elf outpost of Astranaar.",sec={{t="A Dispatch from the Peaks",b="Stonetalon's jagged passes are an isolated and vulnerable frontier for the night elves. With goblin deforestation operations eating away at the crags and polluting the waterways, the outpost manned by Kaela Shadowspear and the gnome tinkerer Gaxim Rustfizzle operates under constant threat. Once the immediate dangers posed by the Venture Company are blunted, keeping the command hierarchy informed is essential. Kaela sends you northeast across the border back into Ashenvale to confirm their survival.",sp=0},{t="Relief in Astranaar",b="In the forested sanctuary of Astranaar, Sentinel Tara Thenysil maintains watch over Ashenvale's interior roads while worrying over scouts deployed into harsher territories. Receiving confirmation that both Kaela and her eccentric engineering partner are alive and actively healing the land offers a rare moment of good news. It proves that despite dwindling forces and multiple hostile fronts, cooperation with Alliance allies can stem the tide of ecological destruction.",sp=0}},faq={{q="Who is Sentinel Thenysil?",a="Tara Thenysil is an officer of the night elf Sentinels stationed in Astranaar, the primary Alliance hub in Ashenvale. She monitors the status of scouts and patrols sent into the surrounding wilds and adjacent regions.",al={"sentinel thenysil","tara thenysil","thenysil astranaar"},it="identity"},{q="Why is Kaela Shadowspear in Stonetalon Mountains?",a="Kaela Shadowspear was deployed to Stonetalon to monitor and combat the destructive environmental exploitation carried out by the Venture Company, working alongside the gnome Gaxim Rustfizzle to sabotage goblin machinery and restore the land.",al={"kaela shadowspear","kaela mission","why is kaela in stonetalon"},it="why_here"},{q="Who is Gaxim?",a="Gaxim Rustfizzle is an Alliance gnome engineer stationed alongside Kaela Shadowspear in Stonetalon. Though his noisy trade contrasts with traditional elven sensibilities, his technical expertise is crucial for disrupting goblin logging machinery.",al={"gaxim","gaxim rustfizzle","the gnome with kaela"},it="people"},{q="Where do I find Sentinel Thenysil?",a="Sentinel Thenysil is stationed in Astranaar, situated along the central road in Ashenvale, northeast of the path leading down from the Stonetalon Mountains.",al={"where is thenysil","thenysil location","where is astranaar"},it="place",gp=true},{q="What happens after reporting back to Sentinel Thenysil?",a="Reporting the success in Stonetalon to Sentinel Thenysil opens further opportunities within the night elf military and leads toward higher-level communications with Darnassus leadership.",al={"next quest after thenysil","where do i go next","reception from tyrande"},it="next_step"},{q="Why is the Venture Company a threat in Stonetalon?",a="The Venture Company is ruthlessly clear-cutting sacred groves, operating massive logging machinery, and poisoning the waterways in Stonetalon, posing a direct threat to the natural balance the night elves guard.",al={"venture co stonetalon","why fight venture co"},it="threat"},{q="Why does Kaela Shadowspear want this update delivered?",a="Operating deep within the contested Stonetalon Mountains, Kaela and Gaxim have been cut off while working to stop the Venture Company's environmental devastation. Kaela needs word carried back to Astranaar so the Sentinel leadership knows their mission is alive and succeeding, rather than lost to the wilderness or goblin machinery.",al={"why send update to thenysil","kaela shadowspear motive","why report to astranaar"},it="motive",add=true},{q="Why does Kaela send you instead of going herself?",a="Kaela and Gaxim cannot abandon their post. The Venture Company's deforestation and mining operations pose an active and immediate threat to the Crag and the surrounding peaks. Leaving now would surrender the hard-won ground you just helped secure, so they rely on an able traveler like you to carry the message north.",al={"why not send a sentinel","why can't kaela report back","why does kaela need me"},it="why_me",add=true}},ang={["race:NightElf"]="Delivering news of Kaela's survival reassures the Sentinels that their hold over Kalimdor's borderlands has not broken under industrial encroachment.",["race:Gnome"]="Even Sentinel Thenysil grudgingly acknowledges relief that Gaxim Rustfizzle is safe, demonstrating that gnomish ingenuity can earn respect even among traditionalist elves.",["faction:Alliance"]="Maintaining communication between the frontier posts of Stonetalon and the strongholds of Ashenvale helps secure the Alliance's presence in central Kalimdor."},kw={"ashenvale","astranaar","gaxim rustfizzle","kaela shadowspear","sentinel thenysil","stonetalon","update for sentinel thenysil","venture co"},rel={"npc:sentinel-thenysil","npc:kaela-shadowspear","subzone:astranaar","quest:1081","quest:764","zone:stonetalon","zone:ashenvale","topic:sentinels"},m={start="Kaela Shadowspear",["end"]="Sentinel Thenysil",level="22",faction="Alliance",id=1082},src={"Update for Sentinel Thenysil"}}
E["quest:1083"] = {t="quest",n="Enraged Spirits",z="stonetalon",s="Enraged Spirits is an Alliance quest given by Kaela Shadowspear in the Stonetalon Mountains. After the Venture Company laid waste to the Charred Vale with fire and heavy machinery, furious fire elementals broke free and overran the blighted basin. Alliance champions are asked to quell these roaming spirits of flame and stone so the wounded land might one day heal under Elune's grace.",h="Enraged Spirits is an Alliance quest given by Kaela Shadowspear in the Stonetalon Mountains.",sec={{t="A Scorched Tragedy",b="The Charred Vale was once a lush haven within Stonetalon, but the reckless greed of the Venture Company transformed it into an ashen wasteland. In their drive to log and strip the land of resources, the goblins deployed incendiary devices and heavy machinery that set the entire canopy ablaze. Their destructive meddling did not merely destroy trees; it shattered the fragile elemental balance beneath the earth.",sp=0},{t="Unleashed Fury",b="The venture did not go as planned for the goblins. The conflagration and deep excavation stirred ancient, dormant spirits of fire, stone, and fury from the depths. These enraged elementals swiftly turned on the trespassers, driving the Venture Company back and claiming the smoldering crater as their own. Kaela Shadowspear laments that until these chaotic elementals are culled, nature can never begin to recover.",sp=0}},faq={{q="Who gives the quest Enraged Spirits?",a="Kaela Shadowspear, a night elf sentinel stationed in the Stonetalon Mountains, gives this quest to Alliance adventurers seeking to aid the land.",al={"quest giver","where to get enraged spirits","who starts enraged spirits"},it="identity"},{q="Why are the fire elementals rampaging in the Charred Vale?",a="The Venture Company clear-cut and torched the forest using destructive machinery. Their invasive industrial methods disrupted the earth and unleashed dormant spirits of flame, stone, and rage that quickly overran the area.",al={"why are there elementals here","what caused the fire elementals","charred vale fire spirits"},it="origin"},{q="What happened to the Venture Company in the Charred Vale?",a="The goblins ignited the forest, but their carelessness unleashed elementals far more dangerous than anticipated. The furious fiery beings overwhelmed their operations, leaving behind ruined camps and blazing wreckage.",al={"venture co fate","did goblins die in charred vale","venture co charred vale"},it="history"},{q="What are Smoldering Embers?",a="Smoldering Embers are the burning remnants collected from destroyed fire elementals in the Charred Vale, brought back to Kaela Shadowspear as physical proof that their chaotic numbers have been culled.",al={"smoldering embers lore","what are embers for","embers of enraged spirits"},it="item"},{q="Can the Charred Vale ever recover?",a="Kaela Shadowspear believes the land has no chance of feeling Elune's blessing or recovering while hostile elementals wander the ashes. Removing these rampaging spirits is the first step toward any eventual healing.",al={"will charred vale heal","healing the charred vale","can the vale be saved"},it="today"},{q="Where is the Charred Vale located?",a="The Charred Vale lies in the southwestern region of the Stonetalon Mountains, marked by blackened earth, burned timber, and roaming elemental spirits.",al={"charred vale location","how to find charred vale","where are the elementals"},it="place",gp=true},{q="Why does Kaela Shadowspear want the enraged spirits culled?",a="The devastation of the Charred Vale breaks Kaela Shadowspear's heart. The reckless defilement unleashed violent burning spirits of flame, stone, and rage across the land. As a night elf, she believes the scarred earth has no hope of receiving Elune's grace or beginning to heal as long as these chaotic elemental forces roam free. Culling them is the first step toward restoring peace to the wounded vale.",al={"why cull the spirits","kaela shadowspear motive","why does kaela want this done"},it="motive",add=true},{q="What creatures are you fighting in the Charred Vale?",a="You are hunting the burning spirits—elementals born of fire, molten stone, and raw fury—that now haunt the scorched wasteland of the Charred Vale. Awakened and agitated when the Venture Company set the woodlands ablaze and tore the earth apart with machinery, these hostile entities violently overrun the ruins and attack anyone who dares approach.",al={"charred vale elementals","what are the burning spirits","who am i fighting enraged spirits"},it="target",add=true}},ang={["race:NightElf"]="For night elves, the devastation of the Charred Vale is a heartbreaking wound inflicted on Kalimdor's sacred wildlands by unchecked industrial avarice.",["class:Druid"]="Druids view the rampaging fire elementals as a catastrophic disruption of nature's equilibrium, requiring active intervention before life can return to the soil.",["class:Shaman"]="Shaman understand that the elementals' wrath is a direct, agonizing reaction to the reckless exploitation of the earth by mortal miners and loggers.",["faction:Alliance"]="The Alliance works through night elf sentinels in Stonetalon to contain the chaos caused by goblin cartels and restore safety to the mountain passes."},kw={"charred vale","elune","enraged spirits","fire elementals","kaela shadowspear","smoldering embers","stonetalon mountains","venture co"},rel={"subzone:charred-vale","npc:kaela-shadowspear","quest:764","zone:stonetalon","topic:elune"},m={start="Kaela Shadowspear",level="26",faction="Alliance",id=1083,ri={"Smoldering Embers"}},src={"Enraged Spirits"}}
E["quest:1084"] = {t="quest",n="Wounded Ancients",z="stonetalon",s="Wounded Ancients is an Alliance task given by Kaela Shadowspear in the Stonetalon Mountains. Suspecting that goblin munitions drove the local forest guardians mad, Kaela sends adventurers to recover shrapnel lodged in the corrupted treants so the gnome engineer Gaxim Rustfizzle can analyze the taint.",h="Wounded Ancients is an Alliance task given by Kaela Shadowspear in the Stonetalon Mountains.",sec={{t="Blighted Protectors",b="The forested groves of Stonetalon were long watched over by towering treants, gentle yet ferocious guardians bound to the health of the land. When the Venture Company moved in with buzzsaws, explosives, and strip-mining operations, nature fought back. The treants successfully repelled the invaders from parts of the vale, but victory came at an insidious cost. The defenders did not return to peaceful guardianship; instead, they devolved into hostile, maddened husks.",sp=0},{t="Gnomish Investigation",b="Kaela Shadowspear, an Alliance scout stationed in the mountains, believes the treants' decline is no natural sickness. The gnome engineer Gaxim Rustfizzle suspects the culprit lies in the chemical and mechanical arsenal used by the goblins during their chaotic retreat. By prying corroded shrapnel from the wounded wood-beasts, Gaxim hopes to determine whether Venture Company ordnance is actively poisoning Stonetalon's ancient protectors.",sp=0}},faq={{q="Who offers the quest Wounded Ancients?",a="Kaela Shadowspear gives the quest. She is an Alliance operative monitoring the escalating strife and ecological damage within the Stonetalon Mountains.",al={"wounded ancients questgiver","who gives wounded ancients","kaela shadowspear quest"},it="identity"},{q="Why are the treants corrupted?",a="Gaxim Rustfizzle suspects that toxic munitions and weaponry fired by the Venture Company during their chaotic retreat lodged in the treants, steadily poisoning and maddening the forest guardians.",al={"why are treants mad","stonetalon treants corrupted","treant corruption source"},it="threat"},{q="What item must be retrieved for this task?",a="You need to retrieve a piece of Corroded Shrapnel, embedded within the bark and flesh of the wounded treants wandering the area.",al={"wounded ancients item","corroded shrapnel quest"},it="item",gp=true},{q="Who is Gaxim Rustfizzle?",a="Gaxim is an Alliance-aligned gnome engineer assisting Kaela Shadowspear. He uses his mechanical expertise to inspect Venture Company technology and determine how their weapons corrupt natural life.",al={"gaxim","gnome in stonetalon","gaxim rustfizzle role"},it="allies"},{q="What is the Venture Company's presence in Stonetalon?",a="The Venture Company is a ruthless goblin logging and mining syndicate that invaded Stonetalon to clearcut sacred woodlands and plunder mineral deposits without regard for local balance.",al={"venture co stonetalon","why are goblins in stonetalon"},it="conflict"},{q="Does collecting the shrapnel heal the treants?",a="No. The retrieved shrapnel is purely an analytical sample intended for Gaxim to examine the nature and origin of the toxin rather than an immediate cure for the corrupted guardians.",al={"can you cure treants","do treants recover"}},{q="Why does Kaela Shadowspear want the corroded shrapnel?",a="Kaela is deeply troubled by the corruption warping the protectors of the Charred Vale. After the Venture Company was driven back, the ancient treants were left violent and maddened. She promised Gaxim Rustfizzle she would obtain a sample of the goblins' munitions embedded in the wounded ancients, hoping the gnome can study it and confirm whether the invaders' cruel weaponry is truly responsible for poisoning the land's defenders.",al={"kaela shadowspear motive","why help treants stonetalon","why does kaela want shrapnel"},it="motive",add=true},{q="What is the Corroded Shrapnel?",a="Corroded Shrapnel consists of jagged metal fragments fired into the treants by the retreating Venture Company. Gaxim Rustfizzle suspects the toxic or explosive residue clinging to the iron caused the ancients' tragic descent into madness. Kaela needs the specimen brought back so Gaxim can examine its chemical composition and devise a way forward.",al={"what is corroded shrapnel","corroded shrapnel stonetalon","shrapnel lore"},it="item",add=true},{q="Why are you sent against the wounded treants?",a="The wounded treants were once peaceful guardians of the Charred Vale before the Venture Company's logging operations and warfare devastated the valley. During their retreat, the goblins struck the defenders with foul munitions, leaving them scarred, maddened, and hostile to anyone who draws near. To recover the shrapnel lodged in their bark, you must confront these agonizingly corrupted creatures.",al={"why kill wounded treants","who are the wounded ancients","charred vale treants"},it="target",add=true}},ang={["race:NightElf"]="Watching ancient woodland defenders rot and twist under goblin industry is an outrage to any Kaldorei dedicated to safeguarding Kalimdor's wilderness.",["race:Gnome"]="Gaxim Rustfizzle's analytical eye demonstrates that mechanical craft can be wielded to understand and diagnose environmental crimes committed by irresponsible engineers.",["class:Druid"]="Treants represent the living pulse of nature; extracting the foreign metal poisoning their flesh is a grim necessity in confronting Venture Company destruction.",["profession:Engineering"]="The corroded metal recovered from the treants highlights the destructive, slapdash nature of Venture Company munitions compared to refined gnomish craftsmanship."},kw={"corroded shrapnel","corruption","gaxim rustfizzle","kaela shadowspear","stonetalon","treants","venture co","wounded ancients"},rel={"npc:kaela-shadowspear","zone:stonetalon","quest:764","topic:gnome","topic:goblin"},m={start="Kaela Shadowspear",level="28",faction="Alliance",id=1084,ri={"Corroded Shrapnel"}},src={"Wounded Ancients"}}
E["quest:1085"] = {t="quest",n="On Guard in Stonetalon",z="stonetalon",s="On Guard in Stonetalon directs Alliance travelers from Kaela Shadowspear to Gaxim Rustfizzle at their camp near Windshear Crag. Facing rampant despoilment by the Venture Company, an otherwise unlikely pair—a cautious night elf sentinel and an eccentric gnome tinkerer—join forces to safeguard the mountain pass.",h="On Guard in Stonetalon directs Alliance travelers from Kaela Shadowspear to Gaxim Rustfizzle at their camp...",sec={{t="An Unlikely Alliance",b="Night elves and gnomes rarely share common ground, especially when it comes to technology and the natural world. In the crags of Stonetalon Mountains, however, necessity bridges the cultural gulf. With the rapacious Venture Company carving out the wilderness and felling ancient trees, the sentinel Kaela Shadowspear has recognized that pure martial prowess alone cannot overcome industrialized pillaging. Welcoming gnome ingenuity into sacred Kaldorei territory demonstrates just how precarious the situation has become.",sp=0},{t="Gnomish Philosophy",b="Gaxim Rustfizzle represents the eccentric pragmatism of the Alliance's smaller allies. While night elf society famously turned its back on arcane excess millennia ago, Gaxim believes that abstaining from magic and technical innovation leaves them vulnerable. By pairing alchemy and engineering with a touch of arcane discipline, Gaxim aims to convince his Kaldorei hosts that practical science can defend nature just as effectively as bow and glaive.",sp=0}},faq={{q="Why are a night elf and a gnome working together here?",a="The Venture Company's destructive deforestation and resource extraction in Stonetalon are so severe that Kaela Shadowspear accepted outside aid. Gaxim brings engineering and alchemical expertise that the night elves typically lack, providing technical support to counter modern industrial machinery.",al={"why is gaxim with kaela","kaela and gaxim","gnome night elf alliance"},it="conflict"},{q="Who is Gaxim Rustfizzle?",a="Gaxim is an adventurous gnome engineer and tinkerer stationed at a camp near Windshear Crag. He believes strongly that the night elves' strict aversion to arcane magic leaves them disadvantaged, seeking to prove that combining engineering, alchemy, and controlled magic can solve even the direst threats.",al={"gaxim rustfizzle lore","who is gaxim","gnome at stonetalon peak"},it="identity"},{q="Who is Kaela Shadowspear?",a="Kaela Shadowspear is a night elf sentinel tasked with maintaining watch and defense over the Stonetalon Mountains. She serves as a regional commander coordinating resistance against the Venture Company.",al={"kaela shadowspear","who is kaela"},it="identity"},{q="What threat is the Venture Company posing in Stonetalon?",a="The Venture Company is an unscrupulous mercantile syndicate cutting down sacred forests, operating destructive drilling rigs, and polluting pristine lands across Stonetalon for rapid commercial profit.",al={"venture co stonetalon","why fight venture co"},it="threat"},{q="Who is Tara, mentioned by Kaela?",a="Tara is a night elf contact and quest giver stationed at Astranaar in Ashenvale, who originally dispatched Alliance messengers and scouts into Stonetalon to assess the situation.",al={"tara stonetalon","send you back to tara"},it="identity"},{q="Where does this task lead next?",a="After speaking with Gaxim Rustfizzle, he offers 'A Gnome's Respite,' enlisting your aid to secure local supplies and further test his technical solutions against the hazards of the region.",al={"quest after on guard in stonetalon","next quest after gaxim"},it="next_step"},{q="Why does Kaela Shadowspear want you to speak with Gaxim?",a="The Venture Company has severely devastated Stonetalon, consuming nearly all of Kaela's time and attention in an effort to curb their destruction. Desperate for assistance, she has set aside traditional night elf reluctance to ally with the gnome engineer Gaxim Rustfizzle. To mount an effective resistance and safeguard the mountains, she needs you to coordinate directly with Gaxim and lend your strength to their combined efforts.",al={"why talk to gaxim","kaela shadowspear motive","why does kaela send you to gaxim"},it="motive",add=true}},ang={["race:Gnome"]="Gaxim Rustfizzle proudly represents gnomish ingenuity in Kalimdor, using his presence to demonstrate that science, engineering, and magic can overcome challenges where ancient traditions falter.",["race:NightElf"]="For Kaldorei sentinels, trusting a gnome tinkerer who advocates combining engineering with magic requires swallowing considerable pride, reflecting just how devastating the Venture Company's logging operations have become.",["profession:Engineering"]="Gaxim's mission underscores the practical utility of engineering in frontline reconnaissance and ecosystem defense, proving that cogwheels can serve conservation when turned against unchecked exploitation.",["faction:Alliance"]="This partnership showcases the broader Alliance ethos in action, as Eastern Kingdoms expertise blends with Kalimdor sentinels to stem shared threats across the frontier."},kw={"engineering","gaxim rustfizzle","gnome","kaela shadowspear","night elf","stonetalon","stonetalon peak","venture co"},rel={"npc:gaxim-rustfizzle","npc:kaela-shadowspear","quest:1071","quest:1070","quest:764","zone:stonetalon","topic:gnome","topic:night-elf"},m={start="Kaela Shadowspear",["end"]="Gaxim Rustfizzle",level="21",faction="Alliance",id=1085},src={"On Guard in Stonetalon (2)"}}
E["quest:1086"] = {t="quest",n="The Flying Machine Airport",z="stonetalon",s="Tasked by Apothecary Zamah from Thunder Bluff, Horde adventurers hunt down a hidden Venture Company landing pad nestled above Stonetalon Mountains. Carrying an alchemical Toxic Fogger, operatives must slip into the heart of the goblin logging operations to gas their air transit hub. The mission strikes directly at the cartel's communications while underscoring the ruthless methods of the Royal Apothecary Society.",h="Tasked by Apothecary Zamah from Thunder Bluff, Horde adventurers hunt down a hidden Venture Company landing...",sec={{t="A Silent Delivery",b="While the tauren seek to protect Stonetalon from deforestation and ravaging machinery, the Forsaken bring an entirely different philosophy to the front. Apothecary Zamah crafts a lethal compound designed to disrupt the Venture Company's logistics. Rather than attacking foot soldiers or loggers directly, she targets the cartel's link to the outside world: a rumored copter pad used to ferry light cargo and messages between Stonetalon and distant corporate offices.",sp=0},{t="Cragpool's Sky Port",b="Hidden high in the Cragpool Lake area south of the great waterwheel sits the Venture Company's copter pad, perched above the soot and chopped timber. It is small, meant for lightweight flying machines rather than massive zeppelins. Setting off the Toxic Fogger directly upon the pad ensures that any pilot, courier, or mechanic operating the machinery is smothered in deadly vapor before they can alert their commanders.",sp=0},{t="Forsaken Pragmatism",b="Upon receiving news of the bombing, Apothecary Zamah makes no apology for utilizing chemical warfare against the goblins. In her eyes, the Venture Company deserves far worse for what they do to the land. More importantly, she offers the Horde a fundamental lesson from Undercity doctrine: never shy from dark paths if they lead toward ultimate victory.",sp=1}},faq={{q="Where is the flying machine airport located?",a="The Venture Company copter pad is located in the Cragpool Lake region of the Stonetalon Mountains. You will find the elevated wooden structure south of the massive industrial waterwheel, overlooking the lake's southern bend.",al={"where is the airport","copter pad location","where is sky port","venture co landing pad"},it="place",gp=true},{q="Why does Apothecary Zamah want this site poisoned?",a="Zamah wants to sever the Venture Company's communications and light supply lines between Stonetalon and their remote headquarters. By contaminating the copter pad, she hopes the toxin will cripple goblin flight crews and potentially hitch a ride back to their corporate leaders.",al={"why bomb the airport","why toxic fogger","zamah motive"},it="motive"},{q="Who is Apothecary Zamah?",a="Apothecary Zamah is an emissary of the Royal Apothecary Society stationed in the Pools of Vision beneath Thunder Bluff. She studies Kalimdor's flora and fauna while developing alchemical weapons on behalf of the Forsaken and the Horde.",al={"zamah identity","who is zamah","undead in thunder bluff"},it="identity"},{q="Why is the Horde using chemical weapons here?",a="The Forsaken fight with pragmatic ruthlessness. Although their tauren allies prefer spiritual healing and direct defense of the earth, Zamah believes the Venture Company's destructive greed warrants merciless tactics, teaching that victory matters above sentimental restraint.",al={"horde using plague","why poison goblins","is this plague"},it="purpose"},{q="What kind of aircraft does the Venture Company use here?",a="The platform is sized for small goblin flying machines and gyro-copters rather than full-sized zeppelins. These agile craft allow the cartel to quickly bypass Stonetalon's rugged mountain passes to haul high-priority messages and cargo.",al={"venture co copters","what flying machine","goblin aircraft stonetalon"}},{q="What happens after the fogger is deployed?",a="Once you release the fogger at the top of the pad, you flee before the vapors overtake you. Zamah considers the deployment a success and anticipates that the poison will severely disrupt goblin logistics.",al={"fogger outcome","after placing fogger"},sp=1,it="next_step"},{q="Who are you targeting at the airport and why are they here?",a="You are targeting the Venture Company, a ruthless goblin cartel strip-mining and clear-cutting Stonetalon Mountains for profit. They operate a clandestine sky port to ferry messages and light cargo back to their distant headquarters. By striking their landing pad with Apothecary Zamah's toxic fogger, the Horde aims to cut off their logistical lifeline and spread the poison directly back to their leadership.",al={"venture company airport target","who are we attacking in stonetalon","why is the venture co here"},it="target",add=true}},ang={["race:Undead"]="For the Forsaken, deploying the Toxic Fogger in Stonetalon is business as usual, demonstrating to Kalimdor that Undercity's alchemical genius can solve problems brute force cannot.",["race:Tauren"]="While your people abhor the Venture Company's destruction of Stonetalon, utilizing chemical toxins under the advice of a Forsaken apothecary tests the balance between earth-mother reverence and harsh battlefield pragmatism.",["profession:Engineering"]="The goblin copter pad displays the crude, utilitarian engineering that powers the Venture Company's rapid transit across rugged mountain ranges.",["faction:Horde"]="Securing Stonetalon requires cutting off the Venture Company from external aid, and striking their air transit is a critical logistical blow."},kw={"airport","apothecary zamah","copter pad","cragpool lake","flying machine","stonetalon","thunder bluff","toxic fogger","venture co"},rel={"quest:1067","quest:853","subzone:cragpool-lake","topic:venture-company","zone:stonetalon","zone:thunderbluff","topic:forsaken","topic:goblin"},m={start="Apothecary Zamah",level="23",faction="Horde",id=1086},src={"The Flying Machine Airport"}}
E["quest:1087"] = {t="quest",n="Cenarius' Legacy",z="stonetalon",s="Cenarius' Legacy is a Horde task handed out by Braelyn Firehand near Sun Rock Retreat in the Stonetalon Mountains. Frustrated by the natural wards maintained by the night elves and the children of Cenarius, the blood elf mage seeks to cull their numbers at Stonetalon Peak to restore the raw flow of magic. For the Horde, striking at the Cenarion defenders also weakens the regional Alliance presence.",h="Cenarius' Legacy is a Horde task handed out by Braelyn Firehand near Sun Rock Retreat in the Stonetalon...",sec={{t="Stifled Currents",b="Braelyn Firehand resides in the hills near Sun Rock Retreat, festering with frustration at Stonetalon's natural environment. According to her, the druids of the Cenarion Circle and the demigod Cenarius's offspring actively suppress and choke the arcane currents of the land. Describing the process of channeling power here as drawing water with a perforated bucket, she hungers to strip away their natural defenses so raw magical energy can surge unimpeded once again.",sp=0},{t="A Strike at Stonetalon Peak",b="To weaken this verdant stranglehold, Braelyn enlists Horde champions to venture north to Stonetalon Peak. There, around the ancient kaldorei groves and temple grounds, patrol the Cenarion Botanists alongside the proud Sons and Daughters of Cenarius. Striking down these wardens serves a dual purpose: it dismantles the wards muffling Braelyn's spellcraft and deals a bloody blow to the night elf enclave threatening the Horde's foothold in the mountains.",sp=0},{t="Ties to the Shadow Council",b="While Braelyn presents her grievance as an issue of magical convenience, her true loyalties lie in darker corners. She longs to return to Jaedenar, the corrupted stronghold of the Shadow Council concealed in Felwood to the north, but notes that her unseen master forbids her return until her work in Stonetalon is complete. The Horde aids her out of territorial expediency, often unaware of the sinister cult pulling her strings.",sp=1}},faq={{q="Who is Braelyn Firehand?",a="Braelyn Firehand is a blood elf spellcaster camped in the crags near Sun Rock Retreat. Though she accepts assistance from the Horde to clear out the night elf presence in Stonetalon, she serves a hidden master based out of Jaedenar in Felwood.",al={"braelyn firehand lore","who is the quest giver","braelyn"},sp=1,it="identity"},{q="Why does Braelyn want the children of Cenarius dead?",a="She claims that the druidic magic practiced by the kaldorei botanists and Cenarius's offspring actively suppresses the flow of raw arcane power across the mountains. Eliminating them weakens the grove's wards and allows magic to flow freely into her grasp.",al={"why kill sons of cenarius","why hate cenarion botanists","why does braelyn hate them"},it="motive"},{q="Where are the targets located?",a="The Sons of Cenarius, Daughters of Cenarius, and Cenarion Botanists are concentrated far to the north at Stonetalon Peak, guarding the ancestral ruins, groves, and moonwells maintained by the night elves.",al={"where are sons of cenarius","stonetalon peak mob locations","where to find cenarion botanists"},it="target",gp=true},{q="What is Jaedenar, which Braelyn mentions?",a="Jaedenar is a deep canyon and cave complex located in Felwood, heavily corrupted by the Burning Legion and currently serving as the central base of operations for the Shadow Council in Kalimdor.",al={"what is jaedenar","braelyn master jaedenar","jaedenar connection"},it="place"},{q="Why is the Horde willing to help Braelyn attack Cenarion defenders?",a="The night elves at Stonetalon Peak are directly aligned with the Alliance and contest the Horde's expansion throughout the Stonetalon Mountains. Weakening their grove secures the region for the Horde, regardless of Braelyn's personal motives.",al={"why does horde kill cenarion circle","horde conflict stonetalon peak"},it="side"},{q="What happens after completing Cenarius' Legacy?",a="Once the initial wardens fall, Braelyn sends you back to Stonetalon Peak to assassinate Keeper Ordanus, the powerful keeper of the grove overseeing the sanctuary.",al={"quest after cenarius legacy","what is next in the chain","ordanus questline"},sp=1,it="next_step"},{q="Who are you sent to kill in Cenarius' Legacy?",a="Braelyn sends you against the Sons and Daughters of Cenarius, along with the Cenarion botanists stationed atop Stonetalon Peak. These keepers, dryads, and night elf caretakers tend to the sacred grove and work tirelessly to cultivate the land, shielding the region from the chaotic, burning arcane magic that Braelyn seeks to harness.",al={"cenarius legacy targets","who do you kill cenarius legacy","who are the sons and daughters of cenarius"},it="target",add=true}},ang={["class:Druid"]="For Tauren druids, butchering Cenarius's offspring and Cenarion Circle botanists is an uncomfortable and deeply divisive act, underscoring the tragic friction between faction loyalty and the sacred ways of nature.",["class:Mage"]="Braelyn's complaints strike a chord with arcane practitioners who recognize the friction between ancient kaldorei warding and free-flowing ley energies, even if her reckless zeal verges on obsession.",["faction:Horde"]="Stonetalon Peak represents the largest bastion of Alliance and kaldorei strength in the mountain chain; clearing out its defenders is vital for safeguarding Sun Rock Retreat and the Greatwood Vale."},kw={"braelyn firehand","cenarion botanist","cenarius' legacy","daughter of cenarius","jaedenar","ordanus","son of cenarius","stonetalon peak","sun rock retreat"},rel={"npc:braelyn-firehand","quest:1088","quest:1089","subzone:stonetalon-peak","subzone:sun-rock-retreat","subzone:jaedenar","topic:cenarius","zone:stonetalon"},m={start="Braelyn Firehand",level="25",faction="Horde",id=1087},src={"Cenarius' Legacy"}}
E["quest:1088"] = {t="quest",n="Ordanus",z="stonetalon",s="Braelyn Firehand at Sunrock Retreat uses her arcane sight to track down Keeper Ordanus, an elder son of Cenarius who fled Stonetalon Peak. Believing his people desecrated ancient Highborne ruins, she sends Horde champions across the border into Ashenvale to take his head.",h="Braelyn Firehand at Sunrock Retreat uses her arcane sight to track down Keeper Ordanus, an elder son of...",sec={{t="A Hunt Driven by Ancient Grudges",b="Braelyn Firehand arrived in Stonetalon Mountains on orders from her master to reclaim the sacred ruins of Azshara's ancient temples. She found the night elves already occupying the peak, treating the relics of her Highborne forebears as wilderness to be contained. Her chief target, Keeper Ordanus, fled before she could corner him, slipping across the border into Ashenvale. Using her arcane vision, Braelyn scried his hiding place high in a wooden refuge at Raynewood Retreat and enlisted the Horde to finish the hunt.",sp=0},{t="The Scion of the Forest God",b="Ordanus is counted among the eldest sons of Cenarius, possessing deep ties to the wild magics of Kalimdor. Night elf guardians moved him from Stonetalon Peak to Raynewood Retreat, seeking to protect him from the arcane forces encroaching upon sacred groves. Defended by loyal Cenarion Vindicators and summoned woodland treants, the keeper represents both the ancient authority of the forest demigod and a living obstacle to Braelyn's vengeance.",sp=0},{t="Highborne Vengeance",b="For Braelyn Firehand, claiming Ordanus's head is deeply personal rather than merely tactical. She openly recalls knowing him centuries ago, remembering the arrogance with which Cenarius's offspring looked down upon the Highborne and their mastery of the arcane. Severing his head serves to avenge ancient slights and clear the path for her master's deeper designs in Kalimdor's wilderness.",sp=1}},faq={{q="Who is Keeper Ordanus?",a="Ordanus is a keeper of the grove and one of the eldest sons of the demigod Cenarius. He was initially stationed near Stonetalon Peak before fleeing into Ashenvale to escape Highborne vengeance.",al={"ordanus lore","who is ordanus","who is keeper ordanus"},it="target"},{q="Where can Keeper Ordanus be found?",a="Ordanus resides at the top of a massive hollow tree structure in Raynewood Retreat, located along the road through central Ashenvale.",al={"ordanus location","where is ordanus","raynewood retreat tree"},gp=true},{q="Why does Braelyn Firehand want Ordanus dead?",a="Braelyn views night elf presence in Stonetalon as a desecration of ancient Highborne temple ruins. She also holds a long-standing personal hatred toward Ordanus, remembering him as arrogant and dismissive of her people in ages past.",al={"why kill ordanus","braelyn grudge","why does braelyn want ordanus"},it="motive"},{q="Who is Braelyn Firehand's master?",a="Braelyn speaks of serving a master who directed her to the peak of Stonetalon to reclaim the ancient temple ruins of Azshara, though she keeps the master's exact identity guarded.",al={"braelyn master","who sent braelyn","braelyns master"},it="identity"},{q="How does this conflict fit into the Horde's presence in Stonetalon?",a="Horde forces stationed at Sunrock Retreat frequently clash with night elf sentinels and Cenarion protectors for territory and resources across Stonetalon and Ashenvale, making Braelyn's strike against a Cenarion leader mutually beneficial.",al={"why does horde help braelyn","stonetalon horde motives"},it="conflict"},{q="What happens after Ordanus is slain?",a="Once Ordanus is dead, Braelyn rewards the champion and directs them toward The Den, delving further into the surrounding threats across the Stonetalon peaks.",al={"what next after ordanus","quest after ordanus","the den next"},sp=1,it="next_step"},{q="What is Ordanus' Head for?",a="Braelyn Firehand demands the head of Keeper Ordanus as absolute proof of his demise and to satisfy an ancient grudge. Having once known Ordanus long ago, Braelyn despises the keeper's arrogance and his belief that his kind stood above even the Highborne. Bringing his severed head not only confirms that the night elves' defenses in Ashenvale have suffered a critical blow, but also humbles the son of Cenarius precisely as Braelyn envisioned.",al={"why ordanus head","ordanus head purpose","what does braelyn do with ordanus head"},it="item",add=true}},ang={["faction:Horde"]="Striking down an elder son of Cenarius weakens night elf authority across the Ashenvale-Stonetalon border, aiding Horde expansion into contested timberlands.",["class:Mage"]="Braelyn Firehand represents the unyielding arcane pride of the Highborne, asserting arcane supremacy over Cenarion natural philosophy.",["class:Druid"]="Horde druids face a grim dilemma in this task, taking the life of a direct son of Cenarius to fulfill a blood elf's ancient feud."},kw={"ashenvale","braelyn firehand","cenarius","highborne","ordanus","raynewood retreat","stonetalon","sunrock retreat"},rel={"npc:braelyn-firehand","quest:1087","quest:1089","subzone:raynewood-retreat","zone:ashenvale","zone:stonetalon","topic:cenarius","topic:highborne"},m={start="Braelyn Firehand",level="29",faction="Horde",id=1088,ri={"Ordanus' Head"}},src={"Ordanus (quest)"}}
E["quest:1089"] = {t="quest",n="The Den",z="stonetalon",s="The Den is the culmination of a Horde infiltration campaign against night elf druids entrenched on Stonetalon Peak. Directed by the blood elf operative Braelyn Firehand, champions delve into the Talon Den's subterranean barrow chambers to crack a layered security system and plunder the druids' hidden relics.",h="The Den is the culmination of a Horde infiltration campaign against night elf druids entrenched on Stonetalon...",sec={{t="Subterranean Secrets",b="Perched upon the highest reaches of the Stonetalon Mountains, the Talon Den serves as an underground redoubt for night elf druids. Carved deep into living stone, these barrow halls are designed to shield meditating guardians and shelter sacred treasures away from prying eyes. Knowing the strategic and arcane value of what rests within, Braelyn Firehand interrogates a captured druid to pry loose the secrets of their defenses.",sp=0},{t="The Layered Locks",b="To safeguard their most potent relics, the druids devised an intricate mechanism rather than trusting a single door. At the threshold of the barrow chambers, hidden inside a humble lantern, lies the Gatekeeper's Key. This initial key unlocks three dispersed caches deeper in the complex—yielding the Sleepers' Key, the Claw Key, and the Barrow Key. Only when all three carved stones are turned in the central hoard do the druidic seals dissolve, surrendering their ancient items to Horde hands.",sp=1}},faq={{q="What is the Talon Den?",a="The Talon Den is a subterranean night elf barrow complex carved into the heights of Stonetalon Peak. It serves as both a meditation sanctuary for resting druids and a secure repository for their sacred relics.",al={"where is talon den","what is the den","stonetalon barrow den"},it="place"},{q="Who orders the infiltration of the Talon Den?",a="Braelyn Firehand, a Sin'dorei operative working alongside the Horde in the Stonetalon Mountains, orchestrates the raid. Having extracted crucial intel from an unfortunate druid captive, she directs Horde agents to bypass the sanctuary's wards and loot its hoard.",al={"who gives the den quest","braelyn firehand purpose","who sent me to the den"},it="in_charge"},{q="How do the keys inside the Den work?",a="A primary Gatekeeper's Key is stashed inside a lantern near the entrance. That key opens three scattered caches inside the barrow, yielding the Sleepers' Key, Claw Key, and Barrow Key. When inserted together into the carved stone hoard, the wards dispel.",al={"how to open talon den hoard","gatekeepers key use","three keys stonetalon"},gp=true},{q="Why are the druids on Stonetalon Peak being targeted?",a="Braelyn Firehand wants the flow of magic in the area restored, and she blames the druids of Stonetalon Peak and the sons of Cenarius for blocking it. She has them slain, along with their leader Keeper Ordanus, whom she claims to have known once, and then sends you to strip the Den of its powerful items.",al={"why attack stonetalon druids","horde reason for killing ordanus","why loot the den"},it="conflict"},{q="What is inside the Talon Den Hoard?",a="The hoard contains powerful relics and treasures gathered by the night elf druids. Sealed beneath layered wards, these items were kept safe from foreign intrusion until their security sequence was coerced by Braelyn.",al={"talon den hoard loot lore","what is in the hoard","what did the druids hide"},it="purpose"},{q="What happened right before this quest?",a="Before breaking into the Den, Horde adventurers are tasked with investigating the night elf presence in Cenarius' Legacy and assassinating the keeper Ordanus to fracture the defenders' command.",al={"den quest chain","what leads to the den","prerequisites for the den"},it="history"},{q="Why does Braelyn Firehand want the hoard plundered?",a="Braelyn Firehand wants the flow of magic around Stonetalon Peak restored, and she blames the druids and the sons of Cenarius for blocking it. Having seen Keeper Ordanus slain and extracted the secrets of the Den's wards from one of the druids, she sends you to strip the Talon Den of the powerful items they keep hidden there.",al={"braelyn motive","why rob the den","why steal from talon den"},it="motive",add=true},{q="What is the Sleepers' Key for?",a="The Sleepers' Key is one of three enchanted keys crafted by the night elf druids to safeguard their most prized relics. Stashed away in a cache deep within the subterranean burrows of the Talon Den, it represents the slumbering druids of the wild. Along with its sister keys, it must be slotted into the ancient stone locking mechanism to unseal the Talon Den Hoard.",al={"sleepers key use","sleepers key purpose","what does sleepers key open"},it="item",add=true},{q="What is the Claw Key for?",a="The Claw Key is an ornate ward fashioned in honor of the Druids of the Claw. Night elf sentinels concealed it inside a hidden cache near the den's passages, shielded from outsiders by the Gatekeeper's seal. It serves as the second component of the threefold lock securing the central Talon Den Hoard.",al={"claw key use","claw key purpose","what does claw key open"},it="item",add=true},{q="What is the Barrow Key for?",a="The Barrow Key is the third piece of the elaborate security scheme devised by the Stonetalon druids. Hidden within a torch cache among the deep roots and barrows, it works in tandem with the Claw and Sleepers' keys to dispel the protective enchantments surrounding the hoard's chest.",al={"barrow key use","barrow key purpose","what does barrow key open"},it="item",add=true}},ang={["faction:Horde"]="Raiding the Talon Den breaks the night elves' defensive spine atop Stonetalon Peak, securing the mountain approaches and seizing potent magical relics for the Horde.",["race:NightElf"]="The desecration of the Talon Den marks a grim violation of sacred barrow sanctuaries, seeing the ancient sleep of Cenarion guardians disrupted and their ward-locked relics plundered.",["class:Druid"]="Tauren druids of the Horde face a bitter irony here, turning keys designed around traditional barrow architecture—named for Sleepers, Claws, and Barrows—against fellow Cenarion keepers.",["class:Rogue"]="Navigating the shadowy halls of the barrow to lift keys from hidden lanterns and torch brackets calls on keen infiltration and subterfuge."},kw={"barrow key","braelyn firehand","cenarius' legacy","claw key","gatekeeper's key","ordanus","sleepers' key","stonetalon peak","talon den","talon den hoard"},rel={"quest:1088","quest:1087","npc:braelyn-firehand","subzone:stonetalon-peak","zone:stonetalon","topic:druid","topic:cenarius"},m={start="Braelyn Firehand",["end"]="Talon Den Hoard",level="29",faction="Horde",id=1089,ri={"Barrow Key","Claw Key","Sleepers' Key"}},src={"The Den (quest)"}}
E["quest:1090"] = {t="quest",n="Gerenzo's Orders",z="stonetalon",s="At the Venture Company dig site in Stonetalon Mountains, an ousted goblin named Piznik schemes to expose his new boss, Gerenzo. By defending Piznik from camp patrols while he extracts a strange gold-green ore, adventurers help uncover the lucrative secrets behind the company's aggressive excavation.",h="At the Venture Company dig site in Stonetalon Mountains, an ousted goblin named Piznik schemes to expose his...",sec={{t="Corporate Betrayal in the Crag",b="The Venture Company's massive operations within Stonetalon rely on cutthroat competition, where promotions are won through ruthlessness rather than loyalty. Piznik once enjoyed the status of being second-in-command at the excavation until Gerenzo seized power, ousted supervisor Ziz Fizziks, and demoted Piznik to swinging a pick in the dirt. Rather than walking away, Piznik stayed on as an informant under Ziz's instructions, watching Gerenzo's every move and biding his time to strike back at his treacherous new supervisor.",sp=0},{t="Unearthing the Gold-Green Vein",b="Gerenzo's sudden takeover is driven by an obsession with a mysterious gold-green ore running through the Stonetalon rocks. Believing the mineral holds extraordinary commercial value, Gerenzo ordered miners to rip massive quantities out of the earth. Suspecting that Ziz Fizziks's mysterious new employer will pay handsomely for information on the venture, Piznik risks discovery to dig up a pristine sample while reliant on an ally to fend off aggressive diggers, vermin, and overseers who police the operation.",sp=0}},faq={{q="Who is Piznik?",a="Piznik is a goblin laborer at the Windshear Crag operation in the Stonetalon Mountains. He was once the second most important manager at the dig site under Ziz Fizziks, but after Gerenzo seized control, Piznik was demoted to working the mines as simple labor.",al={"piznik","who is the goblin miner","piznik stonetalon"},it="identity"},{q="Why is Piznik mining this ore secretly?",a="Piznik is secretly gathering a sample of a strange gold-green mineral that Gerenzo has ordered harvested in huge quantities. His former boss, Ziz Fizziks, promised that his new employer will pay generously for intelligence on whatever valuable operation Gerenzo is running.",al={"why mine ore","mysterious ore","gold green ore"},it="motive"},{q="Who is Gerenzo?",a="Gerenzo is the ruthless Venture Company supervisor who took control of the Stonetalon excavation by firing Ziz Fizziks. He immediately redirected company resources toward aggressively excavating an unfamiliar, valuable gold-green ore found throughout the crag.",al={"gerenzo","who is gerenzo","gerenzo venture co"}},{q="Who does Ziz Fizziks work for now?",a="After getting fired by Gerenzo, Ziz Fizziks allied with new backers interested in monitoring Venture Company activities in the region. He pays operatives and informants like Piznik to sabotage Gerenzo and uncover what the Venture Company is unearthing.",al={"ziz new boss","who hired ziz","ziz employer"},it="allies"},{q="What attacks Piznik while he digs?",a="The noise and illicit activity quickly attract local cave vermin, Windshear diggers, geomancers, and company overseers who patrol the dig site to prevent theft and keep laborers under tight control.",al={"piznik ambush","who attacks piznik","windshear patrols"},it="threat"},{q="What happens once the sample is mined?",a="Once Piznik successfully extracts the ore sample, he gives it to his protector to deliver directly to Ziz Fizziks, hoping it provides the leverage needed to thwart Gerenzo's ambitious plans.",al={"where to take ore","what to do with the sample"},it="next_step"},{q="Why does Piznik need your help rather than mining the ore himself?",a="Piznik cannot swing a pickaxe and defend his back at the same time. The Windshear Crag crannies crawl with aggressive vermin, and Gerenzo's goblin overseers and diggers patrol the tunnels constantly. If Piznik is caught pilfering the mysterious ore, his undercover days are finished—so he needs an armed guard to fend off encroaching beasts and suspicious mine workers while he chips out a sample.",al={"why does piznik need me","why help piznik","why can't piznik mine alone"},it="why_me",add=true}},ang={["profession:Mining"]="The strange gold-green ore discovered by Venture Company miners in Stonetalon does not match conventional iron or tin veins, piquing the curiosity of any prospector interested in rare minerals.",["faction:Horde"]="The Venture Company's reckless, invasive mining despoils Stonetalon's natural landscape, making any effort to monitor, disrupt, or exploit their operations useful to Horde forces nearby."},kw={"gerenzo","gold-green ore","mysterious ore","piznik","stonetalon mountains","venture company","windshear crag","ziz fizziks"},rel={"npc:piznik","quest:1483","zone:stonetalon"},m={start="Piznik",level="22",id=1090},src={"Gerenzo's Orders"}}
E["quest:1091"] = {t="quest",n="Kaela's Update",z="stonetalon",s="Kaela's Update is an Alliance dispatch in the Stonetalon Mountains, carrying captured correspondence between frontline operatives. The gnome mage Gaxim Rustfizzle sends the adventurer back to Kaela Shadowspear with intercepted Venture Company letters. The intelligence helps the night elf Sentinels track the goblin cartel's destructive expansion across sacred lands.",h="Kaela's Update is an Alliance dispatch in the Stonetalon Mountains, carrying captured correspondence between...",sec={{t="A Messenger in the Mountains",b="After assisting the gnome mage Gaxim Rustfizzle in uncovering the movements of the Venture Company, he compiles recovered letters detailing the cartel's operations. Not one to pass up credit, Gaxim sends the player directly back to Kaela Shadowspear, the night elf Sentinel coordinator stationed near Windshear Crag. He makes sure to remind the courier to mention how his magical prowess made the investigation a success.",sp=0},{t="Eyes of the Sentinels",b="The Sentinels stationed in Stonetalon watch the crags with growing concern. While Horde forces contest the lower trails, the Venture Company's clear-cutting and mining apparatus pose an immediate ecological and tactical threat. The letters recovered by Gaxim grant Kaela valuable insights into the cartel's internal communications, bolstering the Alliance's defensive planning along the ridges.",sp=0}},faq={{q="Who is Kaela Shadowspear?",a="Kaela Shadowspear is an Alliance-aligned night elf Sentinel officer stationed at a camp near Windshear Crag. She oversees scouting and defensive efforts against both the encroaching Horde and the destructive ventures of goblin mining companies in the mountains.",al={"kaela shadowspear","who is kaela","kaela stonetalon"},it="identity"},{q="Who is Gaxim Rustfizzle?",a="Gaxim Rustfizzle is an energetic gnome mage based in the Stonetalon Mountains. He uses his arcane skills to investigate and disrupt Venture Company operations, cooperating closely with the local night elf Sentinels.",al={"gaxim","gaxim rustfizzle","gnome mage stonetalon"},it="identity"},{q="What is in the Venture Company letters?",a="The letters contain internal Venture Company communications intercepted during operations against their camps. They provide Kaela Shadowspear and the Sentinels with crucial intelligence on the cartel's local logistics, excavations, and resource stripping.",al={"venture co letters","what are the letters","letters for kaela"},it="item"},{q="Why are the Sentinels concerned about the Venture Company?",a="The Venture Company clear-cuts sacred forests and scars the earth with reckless mining machinery. To the Sentinels, this relentless industrialization is an affront to nature and a direct threat to the sanctity of Stonetalon.",al={"why care about goblins","sentinels venture co","venture company stonetalon"},it="conflict"},{q="Where does this quest start and end?",a="The quest begins with Gaxim Rustfizzle along the mountain pathways and finishes with Kaela Shadowspear at her camp near Windshear Crag.",al={"quest location","turn in kaela update","where is kaela"},it="place",gp=true},{q="Does this quest lead to further investigations?",a="Delivering the letters keeps the Sentinels informed of the cartel's activities, allowing Kaela to plan further military responses and reconnaissance throughout the Stonetalon range.",al={"next quest","what comes after kaela update","follow up quest"},it="next_step",gp=true},{q="Why does Gaxim Rustfizzle want you to deliver the letters?",a="Gaxim wants to ensure the night elf Sentinels are informed about the Venture Company's plans, but he is equally eager to take credit for the success. He urges you to tell Kaela Shadowspear that the mission succeeded thanks to his magical tinkering.",al={"why deliver letters","gaxim rustfizzle motive","why send letters to kaela"},it="motive",add=true}},ang={["faction:Alliance"]="Delivering intercepted Venture Company correspondence bolsters the fragile Alliance foothold in Stonetalon against corporate pillaging.",["race:NightElf"]="Every scrap of intelligence gathered against the Venture Company helps the Sentinels protect Kalimdor's scarred wilderness from industrial defilement.",["race:Gnome"]="Gaxim Rustfizzle proudly represents gnomish arcane ingenuity, making certain his night elf allies recognize the indispensable value of gnome magic."},kw={"gaxim rustfizzle","kaela shadowspear","kaela's update","letters","sentinels","stonetalon peak","venture co"},rel={"npc:gaxim-rustfizzle","npc:kaela-shadowspear","quest:764","topic:sentinels","zone:stonetalon"},m={start="Gaxim Rustfizzle",["end"]="Kaela Shadowspear",level="22",faction="Alliance",id=1091},src={"Kaela's Update"}}
E["quest:1092"] = {t="quest",n="Gerenzo's Orders",z="stonetalon",s="Having fought off the dig site's patrols and secured a sample of the strange ore Gerenzo ordered mined, Piznik dispatches adventurers to take the specimen to his contact, Ziz Fizziks. The delivery wraps up a risky act of corporate espionage deep in the Venture Company operations of Windshear Crag.",h="Having fought off the dig site's patrols and secured a sample of the strange ore Gerenzo ordered mined...",sec={{t="A Ticket Out",b="With his cover blown by the fight at the dig site, Piznik knows his time among the Venture Company crew at Windshear Crag has expired. Corporate management in Undermine does not take kindly to internal sabotage, prompting the nervous goblin to orchestrate his escape. Before slipping away to seek a new employer, he entrusts the Unidentified Ore mined under Gerenzo's orders to an outsider, ensuring the prized specimen gets delivered safely without drawing suspicion to himself.",sp=0},{t="Corporate Curiosities",b="The ore's destination is Ziz Fizziks, who has established a secretive outpost on the western rim of Windshear Crag. Ziz recognizes the strategic value of the mineral, intending to send it south to Undermine engineers while quietly skimming a valuable fraction off the top for personal profit. Such self-serving pragmatism highlights the cutthroat nature of trade and engineering disputes simmering beneath the peaks of the Stonetalon Mountains.",sp=1}},faq={{q="Why does Piznik need to flee Windshear Crag?",a="Piznik was caught by the site's overseers while secretly mining an ore sample for Ziz, blowing his cover as an informant. He knows that once the Venture Company's higher-ups catch wind of the incident, retribution will be swift, so he must sneak away and secure new employment.",al={"why is piznik leaving","piznik runaway","why piznik scared"},it="motive"},{q="Who is Ziz Fizziks?",a="Ziz Fizziks is a goblin operator camped on the western ridge of Windshear Crag. He planted Piznik inside the Venture Company to steal corporate intelligence and rare mineral samples.",al={"who is ziz","ziz fizziks role","where is ziz"},it="identity"},{q="What is the Unidentified Ore?",a="It is a sample of the mysterious gold-green ore that Chief Engineer Gerenzo ordered mined in large amounts. Ziz Fizziks intends to send it to researchers and engineers in Undermine to analyze its industrial applications.",al={"unidentified ore lore","what is the ore","gerenzo ore"},it="item"},{q="Where can Ziz Fizziks be found?",a="Ziz Fizziks hides at a small encampment perched along the western edge overlooking Windshear Crag in the Stonetalon Mountains.",al={"ziz fizziks location","find ziz","where to turn in gerenzo orders"},it="place",gp=true},{q="What happens to the ore once Ziz receives it?",a="Ziz plans to forward the bulk of the ore sample to Undermine engineers for profit and reputation, while pocketing a small shard for himself without his employers' knowledge.",al={"what does ziz do with the ore","ziz keep the ore"},it="next_step"},{q="Is Piznik loyal to the Venture Company?",a="Piznik worked under the Venture Company only long enough to serve Ziz's interests. He shows no loyalty to the syndicate and actively fears retribution from its leadership.",al={"piznik faction","is piznik venture co","who does piznik work for"},it="ties"},{q="Why does Piznik have you deliver the ore instead of taking it himself?",a="Piznik cannot leave immediately because he needs time to cover his tracks and clean up the mess left behind before sneaking away from the Venture Company. Since word of the incident will reach his superiors quickly, he entrusts the Unidentified Ore to you so it safely reaches Ziz Fizziks without delay.",al={"why piznik send me","why cant piznik deliver the ore","why me piznik"},it="why_me",add=true}},ang={["profession:Mining"]="The Unidentified Ore mined on Gerenzo's orders reveals that the Venture Company's deforesting operations in Windshear Crag are equally focused on scouring the mountains for unknown subterranean wealth.",["profession:Engineering"]="Goblin engineers in Undermine pay handsomely for unrefined, exotic ores capable of powering volatile new mechanisms and prototypes."},kw={"gerenzo's orders","piznik","stonetalon","undermine","unidentified ore","venture company","windshear crag","ziz fizziks"},rel={"quest:1090","quest:1483","npc:piznik","subzone:windshear-crag","zone:stonetalon"},m={start="Piznik",["end"]="Ziz Fizziks",level="22",faction="Neutral",id=1092},src={"Gerenzo's Orders (2)"}}
E["quest:1093"] = {t="quest",n="Super Reaper 6000",z="stonetalon",s="Super Reaper 6000 is a quest offered by the disgruntled goblin tinkerer Ziz Fizziks in the Windshear Crag of the Stonetalon Mountains. Looking to curry favor with his new boss Sputtervalve, Ziz hires adventurers to infiltrate the local Venture Company logging operation and steal the schematic blueprints for a colossal woodcutting machine designed by his rival, the gnome Gerenzo Wrenchwhistle.",h="Super Reaper 6000 is a quest offered by the disgruntled goblin tinkerer Ziz Fizziks in the Windshear Crag of...",sec={{t="Industrial Espionage in Windshear Crag",b="The Venture Trading Company has carved an industrial scar straight into the heart of the Stonetalon Mountains, ruthlessly deforesting Windshear Crag. Yet beneath the smog and spinning blades lies petty corporate rivalry. Ziz Fizziks, a goblin engineer recently cast out of the Venture Company's ranks, has found employment with Sputtervalve. Eager to cement his position and show off his value, Ziz seeks to procure the Venture Company's most prized mechanical asset: the blueprints for their massive automated lumber engine, the Super Reaper 6000.",sp=0},{t="Goblins vs. Gnomish Engineering",b="Part of Ziz's burning resentment stems from pride. The Venture Company, nominally a goblin-dominated syndicate, broke tradition by putting a gnome, Gerenzo Wrenchwhistle, in charge of local engineering efforts. After the schematics are pried from the hands of the Venture Company machine operators, Ziz finds himself exasperated: the overly convoluted, perfectionist design philosophy of gnomish drafting is almost entirely incomprehensible to a goblin engineer used to brute force, cheap parts, and volatile combustion.",sp=1}},faq={{q="Who is Ziz Fizziks?",a="Ziz Fizziks is a goblin engineer dwelling in the Stonetalon Mountains. Recently fired by the Venture Company, he was quickly recruited by Sputtervalve, an influential associate in the area, and now seeks payback against his former employers.",al={"ziz fizziks","who is the quest giver","ziz"},it="identity"},{q="What is the Super Reaper 6000?",a="The Super Reaper 6000 is an enormous, mechanical woodcutting machine designed by Gerenzo Wrenchwhistle for the Venture Company's logging operations in Windshear Crag.",al={"super reaper 6000","what is the super reaper","what machine is this"},it="threat"},{q="Who designed the Super Reaper 6000?",a="It was designed by Gerenzo Wrenchwhistle, a gnome tinkerer hired by the Venture Company, a fact that deeply offends the goblin engineers who used to run the site.",al={"who made the super reaper","who built the machine","gerenzo wrenchwhistle"},it="origin"},{q="Why does Sputtervalve want the blueprints?",a="Sputtervalve wants access to the cutting-edge heavy logging technology developed by the Venture Company, and Ziz Fizziks is eager to provide them to prove his usefulness to his new employer.",al={"why steal the plans","sputtervalve blueprints"},it="why_wanted"},{q="Where are the blueprints found?",a="The schematics are carried by the Venture Company machine operators supervising the harvesting machinery in Windshear Crag.",al={"where do i find the plans","who drops the blueprints"},gp=true},{q="Why does Ziz struggle to read the blueprints once retrieved?",a="Goblin and gnomish engineering philosophies are notoriously incompatible. Ziz finds the meticulous, intricate diagrams of Gerenzo Wrenchwhistle overly confusing and impossible to decipher at a glance.",al={"why cant ziz read the plans","gnome blueprints goblin"},sp=1},{q="Why does Ziz Fizziks want this done?",a="Ziz was recently kicked out of the Venture Company, but Sputtervalve hired him right afterward. By securing the blueprints to the Venture Company's massive new woodcutting machine, Ziz hopes to prove his loyalty to his new employer and convince Sputtervalve to finally put his engineering genius to use.",al={"why does Ziz want the blueprints","Ziz Fizziks motive","why help Sputtervalve"},it="motive",add=true},{q="What are the Super Reaper 6000 Blueprints for?",a="The blueprints detail the inner workings and design of the Super Reaper 6000, an immense woodcutting machine engineered for the Venture Company's logging operations. Sputtervalve wants them stolen to understand the technology, and Ziz needs to study them to deliver on that contract.",al={"what are the blueprints for","Super Reaper 6000 Blueprints purpose","why steal the blueprints"},it="item",add=true},{q="Why can't Ziz Fizziks steal the blueprints himself?",a="Ziz is a persona non grata at the Venture Company's logging grounds. Their head engineer, a gnome named Gerenzo Wrenchwhistle, has ordered him killed on sight. Walking into the camp himself would mean immediate execution, making a capable adventurer the only viable option for the heist.",al={"why doesn't Ziz steal them","why does Ziz need me","why can't Ziz go"},it="why_me",add=true},{q="Who is carrying the Super Reaper blueprints?",a="The Venture Company operators overseeing the logging operation carry the schematics. These workers operate the machinery and direct the clear-cutting efforts in the Cragpool Lake area under Gerenzo Wrenchwhistle's direction, keeping the plans close at hand to manage and maintain the reapers.",al={"who has the blueprints","who do I fight for the blueprints","who carries the super reaper plans"},it="target",add=true}},ang={["profession:Engineering"]="This quest highlights the eternal rivalry between goblin pragmatism—explosive, fast, and rough—and gnomish design, which prizes over-engineered complexity and precision.",["race:Gnome"]="Ziz expresses utter disbelief that a goblin syndicate would trust a gnome to build their flagship machinery, only to find himself thoroughly baffled by the gnome's technical genius.",["race:NightElf"]="The Super Reaper 6000 represents the pinnacle of mortal disregard for nature, clear-cutting ancient trees in Stonetalon to feed the maw of industrial profit."},kw={"blueprints","gerenzo wrenchwhistle","sputtervalve","stonetalon mountains","super reaper 6000","venture company","windshear crag","ziz fizziks"},rel={"npc:sputtervalve","quest:1483","quest:1094","topic:venture-company","topic:goblin","topic:gnome","zone:stonetalon"},m={start="Ziz Fizziks",level="21",id=1093,ri={"Super Reaper 6000 Blueprints"}},src={"Super Reaper 6000 (quest)"}}
E["quest:1094"] = {t="quest",n="Further Instructions",z="stonetalon",s="Further Instructions is a delivery task connecting the chaotic logging operations of the Stonetalon Mountains to the trade hub of Ratchet. The disgruntled tinkerer Ziz Fizziks sends a courier with stolen blueprints and internal documents to his counterpart, Sputtervalve, aiming to turn corporate espionage into personal advantage.",h="Further Instructions is a delivery task connecting the chaotic logging operations of the Stonetalon Mountains...",sec={{t="Corporate Espionage",b="When Ziz Fizziks was booted out of the Venture Company's logging operations in the Windshear Crag, he did not leave empty-handed. Bitter over his dismissal, Fizziks snatched up an assortment of sensitive documents, internal manuals, and technical schematics, culminating in the prized blueprints for the experimental Super Reaper 6000. Desperate to find a buyer or ally willing to exploit the data, he sealed the gathered secrets into an envelope marked for Ratchet.",sp=0},{t="The Ratchet Connection",b="The recipient of the stolen documents is Sputtervalve, an engineer stationed within the neutral port of Ratchet in the Barrens. While Sputtervalve harbors little personal affection or trust for Fizziks, the rivalry with the Venture Company makes the offering impossible to refuse. The Steamwheedle-aligned goblins are constantly looking for ways to diminish their ruthless competitor's footprint while happily reverse-engineering any superior mechanical innovations they stumble across.",sp=0}},faq={{q="What is inside the Sealed Envelope?",a="The envelope contains internal Venture Company documents, technical manuals, and blueprints for the Super Reaper 6000 that Ziz Fizziks stole when he was ousted from their logging operation.",al={"envelope contents","what is fizziks sending","stolen documents"},it="item"},{q="Who is Sputtervalve?",a="Sputtervalve is a goblin engineer residing in Ratchet in the Barrens. Though he does not fully trust Ziz Fizziks, he is eager to weaken the Venture Company and examine their mechanical advancements.",al={"sputtervalve identity","who is the recipient","ratchet engineer"},it="identity"},{q="Why is Ziz Fizziks working against the Venture Company?",a="Fizziks was unceremoniously kicked out of the Venture Company's ranks in Stonetalon. Spiteful and out for revenge, he began leaking their trade secrets to rivals.",al={"why fizziks betrayed venture co","fizziks motive"},it="motive"},{q="Where can Sputtervalve be found?",a="Sputtervalve is stationed in the neutral port town of Ratchet, located along the eastern coast of the Barrens.",al={"where is sputtervalve","sputtervalve location","find sputtervalve"},it="place",gp=true},{q="Does Sputtervalve trust Ziz Fizziks?",a="No, Sputtervalve openly admits he does not trust Fizziks, but the value of the technical manuals and blueprints outweighs his wariness of the messenger.",al={"does sputtervalve trust fizziks","fizziks and sputtervalve relationship"},it="ties"},{q="What is the Super Reaper 6000?",a="It is an advanced industrial shredder developed by the Venture Company to clear forests and process lumber at high speed, making its blueprints highly coveted.",al={"super reaper 6000","what is the machine","venture co reaper"}},{q="Why does Ziz Fizziks need an adventurer to deliver the envelope?",a="Ziz Fizziks is in hiding in Stonetalon Mountains after being cast out by the Venture Company. Stripped of his position and surrounded by hostile former colleagues and the dangers of the Crag, he cannot safely make the journey across Kalimdor to Ratchet himself. Entrusting the sensitive blueprints and stolen documents to an able traveler ensures the information reaches Sputtervalve without risking his own neck.",al={"why me further instructions","why does ziz need me","why can't ziz deliver the envelope"},it="why_me",add=true}},ang={["profession:Engineering"]="The envelope represents classic goblin industry at work: ruthless corporate espionage, patent theft, and reverse-engineering complex lumber harvesters.",["faction:Horde"]="Running stolen Venture Company plans to Ratchet helps fuel the simmering trade wars that undermine dangerous industrial encroachment near Horde territories."},kw={"barrens","further instructions","ratchet","sputtervalve","stonetalon","super reaper 6000","venture company","ziz fizziks"},rel={"quest:1093","npc:sputtervalve","subzone:ratchet","zone:barrens","topic:venture-company","zone:stonetalon","quest:1483"},m={start="Ziz Fizziks",["end"]="Sputtervalve",level="21",id=1094},src={"Further Instructions"}}
E["quest:1095"] = {t="quest",n="Further Instructions",z="stonetalon",s="Further Instructions marks an escalation in goblin corporate politics, ordering the assassination of a rogue gnome engineer hired by Mogul Razdunk. Sputtervalve delivers directives originating from high within Undermine, commanding Ziz Fizziks to eliminate Gerenzo Wrenchwhistle in the Stonetalon Mountains.",h="Further Instructions marks an escalation in goblin corporate politics, ordering the assassination of a rogue...",sec={{t="Corporate Disapproval",b="The Venture Company operates under ruthless profit motives, but hiring outsider talent can spark fierce internal friction. When Mogul Razdunk brought the gnome engineer Gerenzo into the fold, word reached Undermine and ruffled feathers among the ruling Trade Princes. Director Riddlevox instructed Sputtervalve to intervene and handle the situation quietly. Sputtervalve, deducing that the order stems from the highest trade authorities, passes down the dirty work to the operative closest to the scene: Ziz Fizziks.",sp=0},{t="Secrets of Dun Morogh",b="Upon receiving the assassination order, Ziz Fizziks eagerly embraces the mission. Goblin engineers harbor natural disdain for gnome rivals, but Gerenzo's personal history makes him an especially volatile figure. Before joining the Venture Company, Gerenzo was a head engineer in Gnomeregan involved in a top-secret endeavor that Undermine spies failed to fully uncover. That project reportedly ended in catastrophe, an explosive failure that sent Gerenzo fleeing across the sea to sell his dangerous expertise in Kalimdor.",sp=1}},faq={{q="Who is Sputtervalve?",a="Sputtervalve is a goblin operative working under Director Riddlevox. Acting on directives from Undermine, he coordinates field operations and passes contracts down to ground agents like Ziz Fizziks.",al={"sputtervalve","who gives quest","quest giver sputtervalve"},it="identity"},{q="Why do the Trade Princes care about Gerenzo?",a="The Trade Princes of Undermine strongly disapprove of Mogul Razdunk consorting with outside gnome engineers. Hiring high-profile non-goblins threatens internal goblin industrial dominance and invites unwelcome scrutiny.",al={"why do trade princes care","undermine anger","gerenzo trade princes"}},{q="What secret project did Gerenzo work on?",a="Gerenzo was a lead engineer in Gnomeregan working on a classified project that goblin spies could never penetrate. Whatever he built reportedly ended in catastrophic disaster, literally exploding in the faces of the engineers involved.",al={"gerenzo secret project","gnomeregan explosion","gerenzo past"},it="history"},{q="Where is Ziz Fizziks located?",a="Ziz Fizziks is stationed in the Stonetalon Mountains, keeping watch over local Venture Company logging and mining efforts while carrying out corporate contracts.",al={"ziz fizziks location","where is ziz","where to deliver orders"},it="place",gp=true},{q="Why is Ziz Fizziks eager to kill Gerenzo?",a="Beyond goblin professional hatred for gnomes, Fizziks recognizes Gerenzo as a hazardous rival whose botched experiments in Dun Morogh make him dangerous to everyone around him.",al={"why ziz hate gerenzo","fizziks reaction","why kill gerenzo"},it="wants"},{q="Who is Mogul Razdunk?",a="Mogul Razdunk is the chief executive of the Venture Company. His decision to hire Gerenzo directly defied conventional trade etiquette in Undermine, triggering the Trade Princes to push for Gerenzo's elimination.",al={"mogul razdunk","who is razdunk","venture company boss"},it="identity"},{q="Why does Sputtervalve want this done?",a="Sputtervalve received directives straight from Director Riddlevox, who is answering pressure from Undermine's Trade Princes. Mogul Razdunk's decision to hire the gnome Gerenzo Wrenchwhistle has scandalized goblin leadership. To protect his own standing and fulfill his superiors' demands, Sputtervalve must see Gerenzo eliminated, and he views dispatching the orders to Ziz Fizziks as the ideal way to carry out Undermine's will while testing Fizziks's capabilities.",al={"why send orders","sputtervalve motive","why kill gerenzo"},it="motive",add=true}},ang={["race:Gnome"]="The goblin operatives mention Gerenzo's past as a senior engineer in Gnomeregan whose secret experiment detonated catastrophically, hinting at the lingering fallout that contributed to the tinker city's downfall.",["profession:Engineering"]="The cutthroat rivalry between gnome and goblin engineering takes a literal turn here, shifting from design patent debates into outright corporate assassination."},kw={"further instructions","gerenzo wrenchwhistle","gnomeregan","razdunk","riddlevox","sputtervalve","stonetalon","undermine","venture company","ziz fizziks"},rel={"quest:1483","quest:1094","npc:sputtervalve","zone:stonetalon","topic:venture-company","zone:gnomeregan","zone:dunmorogh","topic:gnome"},m={start="Sputtervalve",["end"]="Ziz Fizziks",level="27",id=1095},src={"Further Instructions (2)"}}
E["quest:1096"] = {t="quest",n="Gerenzo Wrenchwhistle",z="stonetalon",s="This bounty tasks adventurers with eliminating Gerenzo Wrenchwhistle, a rogue gnome overseer perched high above Cragpool Lake in the Stonetalon Mountains. Gerenzo has heavily augmented his decaying flesh with gears, clockwork machinery, and artificial limbs. The goblin engineer Ziz Fizziks seeks his mechanical arm as indisputable proof of his demise to earn a coveted promotion from his superiors.",h="This bounty tasks adventurers with eliminating Gerenzo Wrenchwhistle, a rogue gnome overseer perched high...",sec={{t="A Monstrous Hybrid",b="Gerenzo Wrenchwhistle is infamous even among veteran tinkerers for his gruesome physical transformations. By the account of those who have seen him, his natural flesh appears to be rotting away, patched over by grafted gears, iron plating, and whirring clockwork prosthetics. Perched near the massive water wheel perched high above Cragpool Lake, the gnome watches over operations with mechanical precision and an unsettling disregard for his own mortal biology.",sp=0},{t="Goblin Ambitions",b="Ziz Fizziks, a goblin operating on behalf of Sputtervalve, sees Gerenzo's downfall as his golden ticket out of Stonetalon's backwaters. Lacking the physical prowess to fight up the cliffs or defeat the augmented overseer himself, Ziz enlists an adventurer to take Gerenzo down and recover his mechanical arm. Armed with this trophy, Ziz hopes to demonstrate his worth and secure a transfer to the prestigious Tinkers' Union workshops in Gadgetzan or Undermine.",sp=0},{t="Clashing Philosophies",b="The recovery of Gerenzo's mechanical arm highlights the profound ideological divide between goblin and gnome engineering traditions. While Gerenzo took the extreme gnomish step of amputating failing flesh to integrate complex prosthetics, goblins find the sacrifice baffling. As Ziz points out, true goblin ingenuity wouldn't discard a biological limb—it would simply mount an explosive third arm alongside the other two.",sp=0}},faq={{q="Who is Gerenzo Wrenchwhistle?",a="Gerenzo Wrenchwhistle is a renegade gnome overseer in the Stonetalon Mountains. He is infamous for replacing portions of his decaying flesh and limbs with mechanical prosthetics and gears, maintaining watch over industrial operations high above Cragpool Lake.",al={"gerenzo","who is gerenzo","gerenzo lore"},it="target"},{q="Where can Gerenzo Wrenchwhistle be found?",a="Gerenzo is located northeast of Ziz Fizziks' position, elevated high above the waters of Cragpool Lake near a large industrial water wheel.",al={"gerenzo location","find gerenzo","where is gerenzo"},gp=true},{q="Why does Ziz Fizziks want Gerenzo dead?",a="Ziz Fizziks is acting under orders from Sputtervalve. Eliminating Gerenzo proves Ziz's competence, which he hopes will earn him a transfer to a major Tinkers' Union workshop in Gadgetzan or Undermine.",al={"why kill gerenzo","ziz motive","ziz fizziks goal"},it="motive"},{q="What proof does Ziz require?",a="Ziz requires Gerenzo's grafted mechanical arm as tangible, undeniable proof that the cyborg overseer has been permanently decommissioned.",al={"what proof","gerenzo proof","quest objective item"},it="item"},{q="Why is Gerenzo partly mechanical?",a="Gerenzo's organic flesh appeared to be rotting away, prompting him to graft gears, iron plates, and mechanical limbs directly onto his body to sustain and augment himself.",al={"why is gerenzo a cyborg","gerenzo robot","gerenzo body"}},{q="Who is Sputtervalve?",a="Sputtervalve is a prominent goblin supervisor who oversees operations and directs underlings like Ziz Fizziks from elsewhere in Kalimdor.",al={"sputtervalve","who is sputtervalve"}},{q="Why does Ziz Fizziks need you to deal with Gerenzo?",a="Ziz Fizziks is an engineer, not a frontline fighter. Gerenzo Wrenchwhistle is holed up high above Cragpool Lake, surrounded by the Venture Company's logging operations and machinery. Ziz admits he stands no chance of fighting through the hostile logging site on his own, much less defeating the heavily augmented gnome atop the works. He needs a capable adventurer to cut through the defenses and finish the job.",al={"why me gerenzo","why doesnt ziz kill gerenzo","why hire an adventurer"},it="why_me",add=true}},ang={["profession:Engineering"]="The gruesome construction of Gerenzo's mechanical arm serves as an unsettling extreme of gnomish bionic engineering, contrasting sharply with goblin practical design.",["race:Gnome"]="Gerenzo represents an eccentric and macabre departure from standard gnomish ingenuity, adopting radical self-augmentation to preserve his failing body.",["faction:Horde"]="Assisting goblin contractors in Stonetalon helps secure valuable resources and territory while disrupting dangerous rogue engineers in the crags."},kw={"cragpool lake","cyborg","gerenzo","mechanical arm","sputtervalve","stonetalon","wrenchwhistle","ziz fizziks"},rel={"npc:sputtervalve","quest:1483","quest:1094","subzone:cragpool-lake","zone:stonetalon","topic:gnome","subzone:gadgetzan"},m={start="Ziz Fizziks",level="27",id=1096,ri={"Gerenzo's Mechanical Arm"}},src={"Gerenzo Wrenchwhistle (quest)"}}
E["quest:1483"] = {t="quest",n="Ziz Fizziks",z="stonetalon",s="This quest sends Horde travelers to check on Ziz Fizziks, a disgruntled goblin engineer stationed on the western ridge of Windshear Crag. Offended when the Venture Company hired a gnome engineer over him, Ziz defected to the Tinkers' Union under Sputtervalve's demanding direction.",h="This quest sends Horde travelers to check on Ziz Fizziks, a disgruntled goblin engineer stationed on the...",sec={{t="A Matter of Professional Pride",b="The Venture Company relies on ruthless exploitation and mechanical innovation, but it crossed a line for Ziz Fizziks when it brought on a gnome engineer named Gerenzo Wrenchwhistle. Deeply insulted by having to work alongside a gnomish rival, Ziz immediately sought a way out. He reached out to Sputtervalve, a contact representing the Tinkers' Union, begging for a transfer away from Gerenzo's oversight.",sp=0},{t="Out of the Frying Pan",b="Securing a new position with the Tinkers' Union did not grant Ziz the easy life he anticipated. Stationed on the western edge of Windshear Crag, he quickly discovered that Sputtervalve is just as much of a slave driver as any Venture Company foreman. Even so, Ziz considers heavy labor under a demanding goblin superior far preferable to sharing an engineering workshop with a gnome.",sp=0}},faq={{q="Who is Ziz Fizziks?",a="Ziz Fizziks is a goblin engineer formerly employed by the Venture Company in Stonetalon Mountains. He defected to join the Tinkers' Union after his former employers hired a gnomish engineer.",al={"who is ziz","ziz fizziks npc","about ziz fizziks"},it="identity"},{q="Why did Ziz Fizziks leave the Venture Company?",a="He walked out in protest after the Venture Company hired a gnome engineer, Gerenzo Wrenchwhistle. Refusing to work alongside a gnomish rival, Ziz begged Sputtervalve for new employment.",al={"why did ziz quit","why leave venture co","ziz venture co"},it="motive"},{q="Where can Ziz Fizziks be found?",a="He is located along the western edge of Windshear Crag in the Stonetalon Mountains, overlooking the Venture Company logging and excavation operations.",al={"ziz fizziks location","where is ziz","find ziz fizziks"},it="place",gp=true},{q="Who is Sputtervalve?",a="Sputtervalve is a goblin operative affiliated with the Tinkers' Union who poaches skilled engineers away from the Venture Company, putting them to work on competitive projects.",al={"who is sputtervalve","sputtervalve role"},it="identity"},{q="Who is Gerenzo Wrenchwhistle?",a="Gerenzo is a gnome engineer brought into Windshear Crag by the Venture Company, an appointment that outraged Ziz and spurred fierce professional rivalry.",al={"gerenzo wrenchwhistle","who is the gnome engineer"},it="identity"},{q="What is the Tinkers' Union?",a="The Tinkers' Union is an established goblin engineering trade association. They actively compete with rivals like the Venture Company and recruit or reclaim top talent whenever possible.",al={"tinkers union","goblin tinkers union"},it="history"},{q="Why does Sputtervalve want you to check on Ziz Fizziks?",a="The Venture Company routinely poaches top goblin talent, but Sputtervalve jumped at the chance to win an engineer back when Ziz quit in protest over the hiring of a gnome rival. Now representing the Tinkers' Union, Sputtervalve put Ziz straight to work out in Windshear Crag. He wants to ensure their newly acquired tinkerer is actually delivering results rather than foundering alone in hostile territory.",al={"why check on ziz fizziks","sputtervalve motive","why send to ziz"},it="motive",add=true}},ang={["profession:Engineering"]="The fierce feud between Ziz and Gerenzo perfectly reflects the long-standing, volatile rivalry between goblin and gnomish engineering philosophies.",["faction:Horde"]="Horde adventurers operating in Stonetalon Mountains often assist Tinkers' Union operatives like Sputtervalve and Ziz to disrupt Venture Company dominance in Windshear Crag."},kw={"gerenzo wrenchwhistle","sputtervalve","stonetalon","tinkers union","venture company","windshear crag","ziz fizziks"},rel={"npc:sputtervalve","subzone:windshear-crag","zone:stonetalon","quest:1096","topic:venture-company","topic:goblin","topic:gnome"},m={start="Sputtervalve",["end"]="Ziz Fizziks",level="21",id=1483},src={"Ziz Fizziks (quest)"}}
E["quest:1510"] = {t="quest",n="News of Dogran",z="stonetalon",s="This quest sends Horde adventurers deep into the foothills of the Stonetalon Mountains to contact the Darkspear troll Ken'zigla at Malaka'jin. An injured grunt from Camp Taurajo named Dogran lies wounded, and the first runner sent to fetch a lifesaving herbal draught never returned.",h="This quest sends Horde adventurers deep into the foothills of the Stonetalon Mountains to contact the...",sec={{t="A Plea Across the Frontier",b="Dogran, a Horde grunt stationed at Camp Taurajo in the southern Barrens, was grievously wounded during a skirmish against entrenched quilboar. His fellow grunts managed to hold him in place, but festering injuries meant any rough transport back across the plains would kill him. Desperate for a potent remedy, Taurajo sent word north toward Stonetalon, hoping to procure a traditional healing draught prepared by the jungle trolls of Malaka'jin.",sp=0},{t="Bloodshed at Malaka'jin",b="When travelers arrive at the crags of Malaka'jin, they discover that the relief mission collapsed almost immediately. The first courier sent to collect the medicine was ambushed and killed by local Venture Company goblins before ever securing the draught. Ken'zigla still possesses the remedy Dogran needs, but securing it requires dealing with the volatile frontier dangers bordering the Stonetalon passes.",sp=1}},faq={{q="Who is Dogran and why is he hurt?",a="Dogran is an orc grunt stationed at Camp Taurajo. While leading a squad to clear out aggressive quilboar encampments in the southern Barrens, he suffered brutal, festering wounds that made it impossible to transport him without immediate medical treatment.",al={"who is dogran","why is dogran hurt","dogran story"},it="identity"},{q="Where is Malaka'jin located?",a="Malaka'jin is a small Darkspear troll outpost nestled in the rocky base of the Stonetalon Mountains, just past the northwestern border of the Barrens.",al={"malakajin location","where is malakajin","find ken'zigla"},it="place",gp=true},{q="What happened to the first messenger sent for the draught?",a="The initial courier dispatched from Taurajo to retrieve Ken'zigla's draught was ambushed and slain by Venture Company goblins operating along the road near the Stonetalon foothills.",al={"first runner","what happened to the messenger","dead courier"}},{q="Why do warlock trainers care about Dogran's fate?",a="Warlock initiates are directed toward Dogran's plight under the guise of an errand for Blind Cazul and Gazrog, but the ordeal ultimately leads them to an artifact steeped in love and heartbreak required to summon and bind a succubus.",al={"warlock quest connection","succubus dogran","why warlocks do this"},sp=1,it="ties"},{q="Who is Ken'zigla?",a="Ken'zigla is a Darkspear troll alchemist and herbalist residing at the Malaka'jin settlement in Stonetalon, knowledgeable in brewing potent wilderness draughts.",al={"who is kenzigla","kenzigla stonetalon","ken'zigla"},it="target"},{q="Why could Dogran not be moved directly to a city?",a="Dogran's wounds became severely festered following the fight with the quilboar. His fellow soldiers feared that hauling him across the rough roads of the Barrens to a major healer would kill him before he arrived.",al={"why not move dogran","dogran wounds","why camp taurajo left him"}},{q="Why does Gazrog want this done?",a="Gazrog is responsible for coordinating the defense and troops across the Barrens. Dogran was wounded fighting quilboar near Camp Taurajo, and his festering injuries make moving him impossible without aid. With the first messenger sent to Malaka'jin overdue, Gazrog needs you to secure the troll healing draught before Dogran succumbs to his wounds.",al={"gazrog motive","why help dogran gazrog","why send to malakajin"},it="motive",add=true},{q="Why does Gazrog send an adventurer instead of his own grunts?",a="The Horde's forces in the Barrens are stretched thin holding back constant quilboar raids and securing outpost routes. Gazrog already dispatched one messenger to the Stonetalon foothills who failed to return, leaving him with no spare soldiers to risk on another errand when an able adventurer is right in front of him.",al={"why me news of dogran","why not send a guard gazrog","why gazrog needs me"},it="why_me",add=true}},ang={["class:Warlock"]="What appears to be a standard military mercy mission is actually a pivotal trial set by Cazul and the warlocks of Orgrimmar, steering you toward the emotional resonance required to bind a succubus.",["faction:Horde"]="This leg of the journey illustrates the thin, fragile supply chains connecting remote outposts like Camp Taurajo to isolated camps such as Malaka'jin in the face of quillboar and goblin hostility."},kw={"camp taurajo","dogran","gazrog","ken'zigla","malaka'jin","quilboar","stonetalon"},rel={"quest:1509","quest:1511","npc:gazrog","subzone:malaka-jin","subzone:camp-taurajo","zone:stonetalon","npc:cazul","quest:1471"},m={start="Gazrog",["end"]="Ken'zigla",level="20",faction="Horde",id=1510},src={"News of Dogran (2)"}}
E["quest:1511"] = {t="quest",n="Ken'zigla's Draught",z="stonetalon",s="Ken'zigla's Draught is an urgent courier task in the Horde warlock chain to summon a succubus. Entrusted with a potent medicinal concoction from Malaka'jin in the Stonetalon Mountains, the warlock must rush across Kalimdor to Camp Taurajo to save an operative named Dogran.",h="Ken'zigla's Draught is an urgent courier task in the Horde warlock chain to summon a succubus.",sec={{t="A Life-Saving Brew",b="In the crags of the Stonetalon Mountains, the troll apothecary Ken'zigla anticipated trouble. Knowing that an earlier emissary sent to secure medicine for the missing scout Dogran never made it back, Ken'zigla prepared a second dose of his potent restorative draught. The concoction is volatile and powerful: half a dose grants a mortally wounded soldier the vigor to move without causing his injuries to hemorrhage, while the rest must be withheld until the next day to complete recovery.",sp=0},{t="Rendezvous at Camp Taurajo",b="Carrying the draught out of the mountains and into the southern Barrens, the warlock is directed to Grunt Logmar at Camp Taurajo. Logmar holds vital intelligence on Dogran's whereabouts, but his garrison is stripped bare by foraging expeditions. With Dogran trapped and bleeding in hostile territory, delivery of the draught to Taurajo marks the final preparations before staging a rescue operation.",sp=1}},faq={{q="What is Ken'zigla's Draught meant to do?",a="It is a potent medicinal brew crafted by Ken'zigla to revive the injured orc operative Dogran. Given in split doses, the first half grants a wounded fighter enough strength to move without reopening mortal wounds, while the second completes the healing process.",al={"what is the draught","kenziglas draught purpose","why make draught"},it="item"},{q="Who is Ken'zigla?",a="Ken'zigla is a troll apothecary situated in the Stonetalon Mountains. He provides specialized alchemical mixtures and concoctions to Horde agents operating in the region.",al={"kenzigla lore","who is kenzigla"},it="identity"},{q="Why is Grunt Logmar waiting at Camp Taurajo?",a="Grunt Logmar is stationed at Camp Taurajo in the southern Barrens. He monitors local scout movements and holds the last known intelligence on where Dogran disappeared, but lacks the grunts to mount a rescue on his own.",al={"who is grunt logmar","logmar taurajo","grunt logmar role"},it="why_here"},{q="How does this quest connect to summoning a succubus?",a="To summon and bind a succubus, Horde warlocks in Orgrimmar require Dogran's pendant, an artifact suffused with passion and devotion. Securing the pendant requires finding Dogran and saving his life with Ken'zigla's draught.",al={"why succubus quest draught","succubus chain dogran"},it="purpose"},{q="Why didn't the first courier bring the draught?",a="The original messenger dispatched to Stonetalon never completed the mission, prompting Ken'zigla to prepare a backup dose for the next adventurer tracking Dogran down.",al={"what happened to first messenger","previous courier"},it="history"},{q="Where does the trail go after Camp Taurajo?",a="Upon receiving the draught, Grunt Logmar points the warlock toward Dogran's captors in the southern Barrens, where the dying scout is held hostage.",al={"where is dogran","next step after logmar"},sp=1,it="next_step"},{q="Why does Ken'zigla want this done?",a="Ken'zigla already prepared the restorative brew anticipating another courier would arrive on Dogran's behalf. As an herbalist living in the harsh crags of the Stonetalon Mountains, brewing potent remedies is her trade, and she has no desire to see an injured warrior succumb when a simple draught could save him.",al={"kenzigla motive","why make the draught","why does kenzigla help"},it="motive",add=true},{q="Why does Ken'zigla need you to deliver the draught?",a="Ken'zigla is an apothecary stationed up in the Sun Rock Retreat, far removed from the Barrens. Delivering the brew down through the mountains to Camp Taurajo is a long and perilous trek that she cannot make herself, especially while Dogran's life hangs by a thread.",al={"why send me","why not deliver draught herself","why must player deliver draught"},it="why_me",add=true}},ang={["class:Warlock"]="This leg of your journey is a test of patience and resourcefulness; to command a creature of raw desire and seduction, you must first mend the broken mortal who holds the token of binding.",["faction:Horde"]="Shows the logistical stretch of the young Horde across central Kalimdor, where isolated outposts in Stonetalon and the Barrens rely on travelers to bridge critical communications and medical aid."},kw={"barrens","dogran","draught","ken'zigla","logmar","stonetalon","succubus","taurajo"},rel={"npc:grunt-logmar","quest:1509","quest:1515","quest:1512","quest:1471","quest:1472","subzone:camp-taurajo","zone:stonetalon"},m={start="Ken'zigla",["end"]="Grunt Logmar",level="20",faction="Horde",id=1511},src={"Ken'zigla's Draught (quest)"}}
E["quest:5881"] = {t="quest",n="Calling in the Reserves",z="stonetalon",s="\"Calling in the Reserves\" is a Horde courier task entrusted to adventurers resting at Sun Rock Retreat. Maggran Earthbinder sends you south to the edge of the Barrens with orders to relieve an exhausted sentry watching the Great Lift.",h="\"Calling in the Reserves\" is a Horde courier task entrusted to adventurers resting at Sun Rock Retreat.",sec={{t="A Long-Awaited Relief",b="Even in an era of relative prosperity following the Third War, maintaining garrisons across central Kalimdor tests the Horde's resources. At Sun Rock Retreat in the Stonetalon Mountains, Maggran Earthbinder oversees logistics and troop welfare. Recognizing that seasoned soldiers wear thin under endless watch duty, Maggran dispatches a letter of reassignment south to the Great Lift, where a young sentry named Grish Longrunner has been standing guard far from home.",sp=0},{t="Watching the Lift",b="The Great Lift serves as the singular engineering artery linking the high plateaus of the southern Barrens down into the wind-carved canyons of Thousand Needles. Handing the letter over to Grish relieves him of an isolated and monotonous watch over the lift mechanisms, clearing the way for him to finally return to his family and allowing fresh reserves to step in.",sp=0}},faq={{q="Who starts this quest?",a="Maggran Earthbinder gives the quest at Sun Rock Retreat, nestled high within the Stonetalon Mountains.",al={"quest giver","where to get calling in the reserves","maggran earthbinder location"},gp=true},{q="Where do I deliver Maggran's letter?",a="You must take Maggran's Reserve Letter south through the Barrens all the way to the Great Lift, the massive wooden elevator structure perched on the border overlooking Thousand Needles.",al={"grish longrunner location","where is grish","where is the great lift"},it="place",gp=true},{q="Why does Grish Longrunner need relief?",a="Grish has spent extended duty stationed alone guarding the lift mechanisms. He submitted a formal request some time ago to be relieved so he could travel home and visit his family.",al={"grish backstory","why grish leaves","great lift sentry duty"},it="purpose"},{q="Is there any combat required for this quest?",a="No combat is required. It is purely a messenger task intended to steer travelers south toward Thousand Needles.",al={"do i have to fight","peaceful quest","courier task"},gp=true},{q="Which faction gains reputation from completing this?",a="Delivering the letter to Grish grants reputation with Thunder Bluff, reflecting the tauren presence and administration over the route.",al={"rep reward","what rep does this give","thunder bluff rep"},it="allies",gp=true},{q="Where does this quest lead next?",a="The delivery brings you right to the top of the Great Lift, positioning you to ride the elevators down into the canyons of Thousand Needles to explore further Horde outposts.",al={"next quest","where to go after","thousand needles breadcrumb"},it="next_step",gp=true},{q="Why does Maggran Earthbinder want this done?",a="Maggran takes pride in the Horde's prosperity and its dedication to rotating and refreshing its soldiers. Grish Longrunner requested leave some time ago to return to his family, and Maggran finally has a reserve warrior prepared to replace him at his remote post atop the Great Lift.",al={"why send the letter","maggran reserve letter purpose","why send relief to grish"},it="motive",add=true}},ang={["faction:Horde"]="The mission illustrates how Horde commanders manage their forces across the Kalimdor frontier, rotating sentries to keep morale and watchposts steady.",["race:Tauren"]="Helping rotate sentries at the Great Lift supports the vital passage connecting the southern reaches of Kalimdor toward Thunder Bluff's broader territories."},kw={"calling in the reserves","great lift","grish longrunner","maggran earthbinder","stonetalon mountains","sun rock retreat","the barrens","thousand needles"},rel={"npc:maggran-earthbinder","npc:grish-longrunner","subzone:sun-rock-retreat","subzone:great-lift","zone:stonetalon","zone:barrens","zone:thousandneedles","topic:horde"},m={start="Maggran Earthbinder",["end"]="Grish Longrunner",level="28",faction="Horde",id=5881},src={"Calling in the Reserves"}}
E["quest:6282"] = {t="quest",n="Harpies Threaten",z="stonetalon",s="Harpies Threaten is a Horde quest offered by Maggran Earthbinder at Sun Rock Retreat in the Stonetalon Mountains. Fulfilling the tauren calling as stewards of the land, adventurers are directed south into the devastated Charred Vale to cull the surging ranks of the Bloodfury harpy coven.",h="Harpies Threaten is a Horde quest offered by Maggran Earthbinder at Sun Rock Retreat in the Stonetalon...",sec={{t="Protectors of the Land",b="The tauren of Sun Rock Retreat hold a profound duty to safeguard Stonetalon, maintaining natural balance and shielding peaceful travelers from the region's hazards. Maggran Earthbinder, the elder leader of the retreat, observes with growing alarm the relentless rise of the local harpy population. The Bloodfury coven has spread across the scorched wastes of the Charred Vale, harassing passing beasts and choking off travel routes. Left unchecked, their predatory flocks threaten to isolate Sun Rock Retreat entirely.",sp=0},{t="Scouring the Charred Vale",b="South of Sun Rock Retreat lies the Charred Vale, a desolate wasteland of ash, scorched earth, and smoldering trees left behind after catastrophic fires. Here, nesting high in the charred remnants of ancient woods, the Bloodfuries have established a stronghold. Maggran tasks Horde warriors with venturing into this hostile caldera to cull dozens of harpy ambushers, slayers, and roguefeathers. Thinning the flock shatters the immediate grip the coven holds over the vale and clears the path to confront their matriarchal lineage directly.",sp=0}},faq={{q="Who gives the quest Harpies Threaten?",a="The quest is given by Maggran Earthbinder, a tauren located near the central pool of water in Sun Rock Retreat in the Stonetalon Mountains.",al={"quest giver harpies threaten","where to pick up harpies threaten","maggran earthbinder quest"},it="identity",gp=true},{q="Where are the Bloodfury harpies located?",a="The Bloodfury harpies dwell throughout the Charred Vale, a burnt expanse located directly south of Sun Rock Retreat. A mountain path behind Sun Rock leads straight down into the vale.",al={"where are bloodfury harpies","bloodfury harpy location","charred vale harpies"},it="place",gp=true},{q="Why do the tauren want the harpies culled?",a="The tauren consider themselves guardians of Stonetalon's natural balance. Maggran Earthbinder fears the Bloodfuries are expanding aggressively across Kalimdor, attacking innocents and preventing living creatures from freely traveling through the land.",al={"why kill harpies","tauren harpy conflict","why maggran hates harpies"},it="motive"},{q="What comes after completing Harpies Threaten?",a="Completing Harpies Threaten unlocks the follow-up quest, Bloodfury Bloodline, in which Maggran Earthbinder sends you to eliminate the ruling leadership of the Bloodfury coven.",al={"next quest harpies threaten","harpies threaten follow up","what after harpies threaten"},it="next_step",gp=true},{q="Is this quest Horde only?",a="Yes. The quest is offered exclusively to the Horde from the settlement of Sun Rock Retreat.",al={"can alliance do harpies threaten","harpies threaten horde only","alliance harpies threaten"},it="side",gp=true},{q="What kinds of harpies must be slain?",a="You must slay seven Bloodfury Harpies, seven Bloodfury Ambushers, seven Bloodfury Slayers, and seven Bloodfury Roguefeathers across the Charred Vale.",al={"which harpies to kill","harpy types charred vale","harpies threaten objectives"},it="target",gp=true},{q="Who are the Bloodfury harpies and why are they a threat?",a="The Bloodfuries are a vicious coven of harpies infesting the Charred Vale. According to Maggran Earthbinder, they are the driving source behind the surging harpy populations throughout Kalimdor. Their aggressive expansion encroaches upon the surrounding wilderness and traps innocent travelers and wildlife within their boundaries.",al={"bloodfury harpies","who are bloodfuries","why kill bloodfury harpies"},it="target",add=true}},ang={["race:Tauren"]="For tauren characters, culling the encroaching Bloodfuries is an honorable duty to fulfill their ancestral promise as protectors of Kalimdor's wilderness.",["faction:Horde"]="Clearing the skies of the Charred Vale strengthens the Horde's foothold at Sun Rock Retreat against dangerous wild factions inhabiting Stonetalon.",["class:Druid"]="The twisted presence of the Bloodfury coven desecrates the already fragile, fire-ravaged ecology of the Charred Vale.",["class:Shaman"]="Working at the behest of Maggran Earthbinder, shaman answer the call to purge aggressive defilers who upset the natural elemental balance."},kw={"ambushers","bloodfury","charred vale","coven","harpies threaten","maggran earthbinder","roguefeathers","slayers","stonetalon mountains","sun rock retreat"},rel={"quest:6283","subzone:charred-vale","subzone:sun-rock-retreat","npc:maggran-earthbinder","topic:harpy","topic:tauren","zone:stonetalon","quest:6301"},m={start="Maggran Earthbinder",level="26",faction="Horde",id=6282},src={"Harpies Threaten"}}
E["quest:6283"] = {t="quest",n="Bloodfury Bloodline",z="stonetalon",s="Bloodfury Bloodline is a Horde task issued by Maggran Earthbinder at Sun Rock Retreat to strike down the leader of the Bloodfury harpies. Culminating Maggran's efforts to cleanse the Charred Vale, the hunt aims to break the flock's ferocious hold over the scarred wilderness.",h="Bloodfury Bloodline is a Horde task issued by Maggran Earthbinder at Sun Rock Retreat to strike down the...",sec={{t="Striking the Matron",b="Culling lesser harpies along the edge of the Charred Vale provides only temporary relief for Sun Rock Retreat. Maggran Earthbinder believes that the only lasting way to curb their aggression is to eliminate their matriarch, Bloodfury Ripper. Revering her as something akin to a queen, the flock draws its ruthless coordination and boldness directly from her leadership along the craggy western ridge.",sp=0},{t="Peace in the Earth",b="Once Bloodfury Ripper falls and her remains are presented as proof, the immediate threat to the retreat subsides. With their brood queen destroyed, the disorganized harpies become far easier to keep at bay. The victory also lifts a spiritual burden from Maggran himself, freeing his thoughts from bitter vigilance so he can return to the customary tauren pursuit of harmony and balance.",sp=0}},faq={{q="Who gives the quest Bloodfury Bloodline?",a="The quest is provided by Maggran Earthbinder, a tauren shaman located near the pool of water inside Sun Rock Retreat.",al={"quest giver bloodfury bloodline","who starts bloodfury bloodline","maggran earthbinder quest"},gp=true},{q="What prerequisite must be finished before this hunt unlocks?",a="You must complete 'Harpies Threaten', where Maggran first sends you into the Charred Vale to thin the general ranks of the Bloodfury harpies.",al={"bloodfury bloodline prequest","prereq for bloodfury bloodline","harpies threaten follow up"},gp=true},{q="Where is Bloodfury Ripper located?",a="She stalks the rocky hills along the northwestern edge of the Charred Vale. She can be distinguished from her flock by her distinct blue coloration.",al={"where is bloodfury ripper","find bloodfury ripper","bloodfury ripper spawn"},it="target",gp=true},{q="Why does Maggran want Bloodfury Ripper dead?",a="Maggran recognizes Bloodfury Ripper as the guiding queen behind the flock's ferocious territorial expansion. Slaying her splinters their leadership and permanently weakens their grip on the vale.",al={"why kill bloodfury ripper","harpy leader charred vale lore","maggran earthbinder motive"},it="motive"},{q="How does Bloodfury Ripper's death affect the tauren of Sun Rock Retreat?",a="Her death brings Maggran peace of mind, freeing him from the lingering anger and constant dread of an impending attack so he can redirect his focus toward healing the land.",al={"stonetalon harpy threat lore","what happens when bloodfury ripper dies","maggran reaction"},sp=1},{q="What is the quickest path to reach the Charred Vale from Sun Rock Retreat?",a="A mountain trail leads directly out the back of Sun Rock Retreat, bypassing the winding main roads of Stonetalon and descending straight into the Charred Vale.",al={"how to get to charred vale from sun rock","sun rock retreat back way","charred vale shortcut"},gp=true},{q="What are Bloodfury Ripper's Remains for?",a="Maggran Earthbinder asks for Bloodfury Ripper's physical remains purely as proof of your deed. Because the harpy queen commands the Bloodfury flock from deep within the Charred Vale, Maggran needs tangible evidence that she has truly fallen before he can rest easy knowing the threat to Sun Rock Retreat has ended.",al={"bloodfury ripper remains purpose","why keep harpy remains","bloodfury remains use"},it="item",add=true},{q="Who is Bloodfury Ripper?",a="Bloodfury Ripper is the leader and matriarch of the Bloodfury harpies roosting among the western hills of the Charred Vale. Treated as a queen by her flock, she directs the vicious creatures menacing Stonetalon Mountains, ensuring their aggression persists despite the Horde's efforts to cull their numbers.",al={"who is the bloodfury leader","bloodfury ripper lore","bloodfury queen"},it="target",add=true}},ang={["race:Tauren"]="Stonetalon's scarred landscape pains the tauren, and removing the violent harpy queen allows local shamans like Maggran to turn their minds back to harmony and healing.",["faction:Horde"]="Securing the perimeter around Sun Rock Retreat safeguards the Horde's solitary haven nestled deep within the contested Stonetalon Mountains."},kw={"bloodfury bloodline","bloodfury ripper","charred vale","harpies","maggran earthbinder","stonetalon","sun rock retreat"},rel={"quest:6282","npc:maggran-earthbinder","subzone:charred-vale","subzone:sun-rock-retreat","zone:stonetalon","topic:tauren"},m={start="Maggran Earthbinder",level="26",faction="Horde",id=6283,ri={"Bloodfury Ripper's Remains"}},src={"Bloodfury Bloodline"}}
E["quest:6284"] = {t="quest",n="Arachnophobia",z="stonetalon",s="Arachnophobia is a Horde bounty quest targeting Besseleth, an ancient and colossal predator haunting southern Stonetalon Mountains. Posted on a roadside notice near Windshear Crag, the bounty directs adventurers into Sishir Canyon to claim the spider matriarch's fang for Maggran Earthbinder at Sun Rock Retreat. Putting an end to her reign makes the mountain roads safer for night travelers.",h="Arachnophobia is a Horde bounty quest targeting Besseleth, an ancient and colossal predator haunting southern...",sec={{t="The Roadside Warning",b="Travelers along the main thoroughfare south of Windshear Crag will spot a weathered wanted poster warning of the dangers to the west. Sishir Canyon and Webwinder Path have been completely overrun by eight-legged predators. At the heart of this webbed menace sits Besseleth, an unusually large, orange-hued spider who commands her brood and ambushes anyone daring to stray off the path after sunset.",sp=0},{t="The Earthbinder's Grievance",b="The bounty on Besseleth is offered by Maggran Earthbinder, a tauren resident of Sun Rock Retreat. Maggran has a personal score to settle with the matriarch: during a previous encounter, he was nearly killed when struck by Besseleth's massive two-foot fang. Though he managed to fight her off and limp to safety, the lingering wound serves as a constant reminder of the danger lurking in the canyon shadows. By having an adventurer claim Besseleth's Fang, Maggran hopes to secure the passes so trade and travel to Sun Rock Retreat can flourish without fear.",sp=0}},faq={{q="Where does the quest Arachnophobia begin?",a="The quest is started by inspecting a wanted poster posted along the west side of the main road in the Stonetalon Mountains, just south of the entrance to Windshear Crag.",al={"where to get arachnophobia","wanted poster besseleth location","how to start arachnophobia"},it="arrival",gp=true},{q="Where can Besseleth be found?",a="Besseleth lairs inside Sishir Canyon, located just west of the roadside wanted poster. She roams among her spider offspring across the canyon's web-choked ground.",al={"besseleth location","where is besseleth","find besseleth spider"},it="target",gp=true},{q="Who is Maggran Earthbinder?",a="Maggran Earthbinder is a tauren situated at Sun Rock Retreat in the Stonetalon Mountains. He personally survived a venomous strike from Besseleth and posted the bounty to rid the canyon of her menace.",al={"who is maggran","maggran earthbinder role","who turned in arachnophobia"},it="people"},{q="Why is Besseleth such a threat to the region?",a="Besseleth is an exceptionally large and ruthless spider who stalks Sishir Canyon and the neighboring Webwinder Path. She and her brood prey upon travelers under the cover of night, threatening anyone attempting to reach Sun Rock Retreat.",al={"why kill besseleth","what did besseleth do"},it="threat"},{q="What proof is required to claim the bounty?",a="You must slay Besseleth and sever one of her enormous two-foot fangs. Presenting Besseleth's Fang to Maggran Earthbinder at Sun Rock Retreat completes the bounty.",al={"besseleth proof","besseleth quest item","what drops from besseleth"},it="item",gp=true},{q="Is this quest available to the Alliance?",a="No. The bounty poster awards credit to Maggran Earthbinder at Sun Rock Retreat, which is a Horde encampment, making Arachnophobia exclusive to the Horde.",al={"can alliance do arachnophobia","alliance arachnophobia quest"},gp=true},{q="Why is a bounty placed on Besseleth?",a="Besseleth and her brood have overrun Sishir Canyon, preying upon innocent travelers who venture along the nearby paths at night. Maggran Earthbinder himself was attacked and wounded by her fangs, barely escaping with his life. He posted the bounty to eliminate the threat so travelers can reach Sun Rock Retreat safely.",al={"why kill besseleth","why does maggran want besseleth dead","besseleth bounty motive"},it="motive",add=true},{q="What is Besseleth's Fang used for?",a="The fang serves as undeniable physical proof of the giant spider's demise. Maggran Earthbinder requires you to bring back this venomous trophy before he will grant you the bounty reward and declare you a champion of the forest.",al={"besseleths fang purpose","why collect besseleths fang","what is the fang for"},it="item",add=true},{q="Why does Maggran Earthbinder need an adventurer to hunt Besseleth?",a="Maggran already attempted to face the great spider himself and was nearly killed, suffering a lingering wound from her venomous bite. Nursing his injuries at Sun Rock Retreat, he posted an open bounty along the road in hopes that a capable hunter could succeed where he failed.",al={"why doesn't maggran kill besseleth","why me arachnophobia","why hire an adventurer"},it="why_me",add=true}},ang={["faction:Horde"]="Clearing out Besseleth stabilizes travel into Sun Rock Retreat, protecting the Horde's vital foothold in the central crags of Stonetalon.",["race:Tauren"]="Maggran Earthbinder bears the painful scar of Besseleth's venom, making the hunt a matter of honoring and assisting a fellow son of the earth.",["class:Hunter"]="Tracking down an elusive, colossal arachnid within the shadowed crags of Sishir Canyon offers a true test of mountain stalking."},kw={"arachnophobia","besseleth","bounty","maggran earthbinder","sishir canyon","spider","stonetalon mountains","sun rock retreat","webwinder path"},rel={"subzone:sishir-canyon","npc:maggran-earthbinder","subzone:sun-rock-retreat","subzone:webwinder-path","zone:stonetalon","subzone:windshear-crag"},m={start="Wanted Poster: Besseleth",["end"]="Maggran Earthbinder",level="21",faction="Horde",id=6284,ri={"Besseleth's Fang"}},src={"Arachnophobia (quest)"}}
E["quest:6301"] = {t="quest",n="Cycle of Rebirth",z="stonetalon",s="Cycle of Rebirth is a Horde task assigned by Tammra Windfield at Sun Rock Retreat to gather rare Gaea seeds from the shores of Mirkfallon Lake. Distressed by the toll of industrial greed and ongoing warfare across Stonetalon, Tammra seeks to bless these resilient kernels with shamanic power to revive the mountain's ravaged soil. It forms the essential first step in a restoration effort aimed at healing the scarred wilderness.",h="Cycle of Rebirth is a Horde task assigned by Tammra Windfield at Sun Rock Retreat to gather rare Gaea seeds...",sec={{t="A Scarred Wilderness",b="The peaks of Stonetalon bear deep wounds from both commercial exploitation and relentless regional conflict. Between aggressive logging operations and clashes between rival factions, entire swaths of forest have been scorched, clear-cut, or reduced to ash. For the tauren stationed at Sun Rock Retreat, witnessing this rapid destruction of the natural world is a grievous wound. Rather than merely fighting to hold ground, shamans like Tammra Windfield look toward the ancient natural order, striving to enact the Earthmother's restorative cycle.",sp=0},{t="The Seeds of Mirkfallon",b="Restoring life to barren ground demands extraordinary vitality, which Tammra finds in the rare Gaea seeds found around Mirkfallon Lake. Situated to the north of Sun Rock Retreat, the lake's banks nurture these sturdy seed pods along the water's edge. Though the surrounding region is steeped in danger, these seeds hold an innate resilience unique to Stonetalon. Once retrieved, Tammra channels ancestral shamanistic blessings into each kernel, awakening their latent power to accelerate their growth for the work ahead.",sp=0}},faq={{q="What is the purpose of collecting Gaea seeds?",a="Gaea seeds possess an exceptional natural vitality that makes them uniquely suited for restoring desolated land. Tammra Windfield gathers them so she can imbue them with Earthmother blessings and shamanistic power, preparing them to rapidly sprout and replenish parts of Stonetalon ruined by industry and war.",al={"why gaea seeds","what are gaea seeds for","cycle of rebirth purpose"},it="item"},{q="Where are the Gaea seeds located?",a="Gaea seeds can be found lying along the shoreline of Mirkfallon Lake, situated directly north of Sun Rock Retreat in the Stonetalon Mountains. They rest in the dirt near the water's edge all around the perimeter of the lake.",al={"gaea seed location","where to find gaea seeds","mirkfallon lake seeds"},it="place",gp=true},{q="Who is Tammra Windfield?",a="Tammra Windfield is a tauren shaman residing at Sun Rock Retreat. Deeply pained by the deforestation and devastation inflicted on Stonetalon by wartime conflict and logging syndicates, she devotes herself to healing the land through Earthmother blessings.",al={"who is tammra","tammra windfield lore"},it="identity"},{q="What does Tammra do once the seeds are returned?",a="Upon receiving the ten Gaea seeds, Tammra begins a sacred chant to infuse the kernels with shamanistic energy, quickening their natural growth potential so they can be planted in devastated zones.",al={"what happens to seeds","turn in cycle of rebirth"},it="next_step"},{q="What quest follows Cycle of Rebirth?",a="Cycle of Rebirth leads directly into the quest 'New Life', where the empowered seeds are carried into the devastated Charred Vale to begin re-establishing plant life.",al={"cycle of rebirth follow up","next quest after cycle of rebirth","what is after cycle of rebirth"},it="next_step"},{q="Why is the land of Stonetalon in need of healing?",a="The Stonetalon Mountains have suffered severe environmental damage from continuous warfare and extensive clear-cutting by industrial lumber ventures, leaving scorched wastelands and scarred valleys that struggle to regrow naturally.",al={"why is stonetalon ruined","what happened to stonetalon"},it="threat"},{q="Why does Tammra Windfield want Gaea seeds collected?",a="Tammra is deeply pained by the relentless destruction wrought by industrial greed and warfare across the Stonetalon Mountains. Loggers and battle have scarred the landscape, and she believes only the Earthmother's restorative power can heal such deep wounds. By gathering and blessing the seeds, she hopes to renew the natural cycle of rebirth and replenish the broken wilderness.",al={"tammra motive","why collect seeds tammra","tammra windfield reason"},it="motive",add=true}},ang={["class:Shaman"]="Tammra's effort reflects the shamanic calling to mend ecological imbalance, showing that the spirits and the Earthmother can restore what industrial exploitation tears down.",["race:Tauren"]="For the Shu'halo, healing the wounded soil of Stonetalon is an act of spiritual duty to the Earthmother, answering the devastation caused by reckless logging and factional warfare.",["class:Druid"]="Druids will appreciate the parallel focus on natural cycles and seed cultivation, as restoring barren earth directly echoes Cenarion stewardship."},kw={"charred vale","cycle of rebirth","earthmother","gaea seed","mirkfallon lake","new life","stonetalon mountains","sun rock retreat","tammra windfield"},rel={"npc:tammra-windfield","quest:6381","subzone:sun-rock-retreat","subzone:mirkfallon-lake","subzone:charred-vale","zone:stonetalon"},m={start="Tammra Windfield",level="23",faction="Horde",id=6301,ri={"Gaea Seed"}},src={"Cycle of Rebirth"}}
E["quest:6381"] = {t="quest",n="New Life",z="stonetalon",s="New Life is a restorative Horde quest offered by Tammra Windfield in Sun Rock Retreat. Following the collection of enchanted seeds, the player journeys west into the ashen ruins of the Charred Vale to sow them into fertile earth. This ritual effort aims to spark the land's recovery amidst hostile elementals and harpies.",h="New Life is a restorative Horde quest offered by Tammra Windfield in Sun Rock Retreat.",sec={{t="Healing the Scorched Earth",b="The Charred Vale stands as a tragic testament to recent devastation, choked by soot, furious fire elementals, and scavenging harpies. Tammra Windfield refuses to let the region surrender to ruin. Relying on the ancient resilience of the Earth Mother, she dispatches travelers into the heart of the blackened valley to seek out Gaea Dirt Mounds—patches of fertile topsoil that survived the inferno.",sp=0},{t="A Foothold for the Future",b="The enchanted Gaea seeds planted in the scorched soil are bred to withstand lingering elemental corruption. By taking root, they begin weaving a vital ecological anchor that can resist decay and invite flora back into the valley. Tammra envisions a long-term healing process: as living roots slowly reclaim the basin, the agitated fire spirits will settle, the harpies will lose their desolate roost, and the Venture Company's rapacious logging operations will eventually be driven out.",sp=0}},faq={{q="What is the purpose of planting the Gaea seeds?",a="The enchanted Gaea seeds are designed to take root in the scarred earth of the Charred Vale. They resist corruption and establish an initial foothold of vibrant plant life, setting the foundation for the forest to gradually regrow and heal.",al={"why plant seeds","new life purpose","what do gaea seeds do"},it="purpose"},{q="Where do I need to go to plant the seeds?",a="You must travel west from Sun Rock Retreat into the Charred Vale. The seeds are planted into small Gaea Dirt Mounds scattered across the blackened basin.",al={"where is charred vale","where do i plant gaea seeds","seed locations"},it="place",gp=true},{q="Who is Tammra Windfield?",a="Tammra Windfield is a tauren naturalist residing in Sun Rock Retreat within the Stonetalon Mountains. She is dedicated to soothing the wounded spirits of the land and rehabilitating areas ravaged by elemental fury and industrial greed.",al={"who gives new life","tammra quest giver","tammra windfield lore"},it="identity"},{q="What threats roam the Charred Vale while planting?",a="The Charred Vale is inhabited by rogue fire elementals stirred up by the recent devastation, as well as aggressive Bloodfury harpies that nest amidst the burnt trees.",al={"charred vale enemies","what attacks in charred vale","dangers in charred vale"},it="threat"},{q="What quest comes before New Life?",a="New Life directly follows the quest Cycle of Rebirth, in which you help Tammra collect the vital materials required to prepare the enchanted Gaea seeds.",al={"new life prerequisite","cycle of rebirth quest","what leads to new life"},gp=true},{q="What does Tammra hope will happen to Stonetalon long term?",a="Tammra hopes the regrowing land will eventually calm the enraged fire elementals, crowd out the predatory harpies, and outlast the logging operations of the Venture Company, restoring the mountains to a lush and peaceful forest.",al={"future of stonetalon","tammra goal","what happens to charred vale"},it="motive"},{q="What is the Gaea Dirt Mound for?",a="These mounds are patches of fertile soil scattered across the otherwise scorched and blackened earth of the Charred Vale. Tammra Windfield needs you to bury the Enchanted Gaea Seeds within them so the seeds can take root, resist the local corruption, and spark new vegetation to slowly reclaim the ruined wasteland.",al={"gaea dirt mound purpose","what are gaea dirt mounds","why plant in dirt mounds"},it="item",add=true}},ang={["race:Tauren"]="For the tauren, sowing enchanted seeds into scarred soil is an act of spiritual communion with the Earth Mother, fulfilling their sacred duty to heal wounded lands.",["class:Druid"]="Druids share a close kinship with Tammra's mission, viewing the renewal of the Charred Vale as an essential restoration of nature's delicate balance.",["class:Shaman"]="Shaman understand that the agitated fire elementals roaming the Vale will never find peace until the battered land itself begins to heal.",["profession:Herbalism"]="Herbalists appreciate the profound power of resilient seeds to bring forth thriving vegetation out of completely deadened soil."},kw={"bloodfury harpies","charred vale","cycle of rebirth","dirt mounds","fire elementals","gaea seeds","stonetalon mountains","sun rock retreat","tammra windfield"},rel={"quest:6301","npc:tammra-windfield","subzone:charred-vale","subzone:sun-rock-retreat","zone:stonetalon","quest:6282","quest:764"},m={start="Tammra Windfield",level="25",faction="Horde",id=6381,ri={"Gaea Dirt Mound"}},src={"New Life"}}
E["quest:6401"] = {t="quest",n="Kaya's Alive",z="stonetalon",s="Kaya's Alive is a short Horde quest in the Stonetalon Mountains that concludes the rescue of Kaya Flathoof. After escorting the young tauren safely past hostile Grimtotem bandits, you are sent to carry the joyful news of her survival to her worried aunt, Tammra Windfield, in Sun Rock Retreat.",h="Kaya's Alive is a short Horde quest in the Stonetalon Mountains that concludes the rescue of Kaya Flathoof.",sec={{t="A Breath of Relief",b="The mountains of Stonetalon are fraught with danger, especially along the contested trails where the Grimtotem tribe strikes without mercy. When their village fell under a brutal attack, young Kaya Flathoof was feared dead or captured by the renegades. Her survival and subsequent rescue provide a rare moment of triumph and relief amidst the ongoing tribal conflicts in the crags.",sp=0},{t="Reaching Sun Rock Retreat",b="Once Kaya is guided to safety, Makaba Flathoof charges you with carrying the word directly to Sun Rock Retreat. There, Kaya's aunt, Tammra Windfield, waits anxiously for news from the trails. Delivering word of Kaya's safety offers the fractured family solace and reinforces the vital role traveling champions play in keeping the remote Horde outposts connected.",sp=0}},faq={{q="Who is Kaya Flathoof?",a="Kaya Flathoof is a young tauren who was separated and endangered following a violent assault on her settlement by rogue Grimtotem forces in Stonetalon Mountains.",al={"who is kaya","kaya flathoof","kaya"},it="identity"},{q="Who is Tammra Windfield?",a="Tammra Windfield is Kaya's aunt, residing at Sun Rock Retreat in the Stonetalon Mountains. She had feared her niece perished in the Grimtotem attack.",al={"tammra windfield","who is tammra","kaya aunt"},it="identity"},{q="Who attacked Kaya's village?",a="Kaya's village was ambushed by the aggressive Grimtotem clan, an isolationist tauren faction notorious for preying on both rival tribes and traveling wayfarers across the mountains.",al={"who attacked kaya","village attack","grimtotem attack"},it="threat"},{q="What comes before this quest?",a="This quest immediately follows 'Protect Kaya', an escort mission where you defend Kaya Flathoof as she flees her captors and returns to safety.",al={"prerequisite","protect kaya","escort quest"},it="history",gp=true},{q="Where is Sun Rock Retreat located?",a="Sun Rock Retreat is nestled high in the central Stonetalon Mountains, accessed by following the main road westward and through a narrow mountain defile into a sheltered basin.",al={"sun rock retreat location","where is sun rock","find sun rock retreat"},it="place",gp=true},{q="Why does Makaba Flathoof send you instead of going himself?",a="Makaba remains at his camp near the southeastern edge of Stonetalon, relying on an able-bodied runner to swiftly reassure their family in Sun Rock Retreat.",al={"why makaba stays","why send me"},it="why_me"},{q="Why does Makaba Flathoof want this news delivered?",a="Their village suffered a brutal attack, and the survivors believed young Kaya Flathoof had been lost in the slaughter. Now that she is safe, Makaba wants word sent immediately to relieve the grief of Kaya's aunt, Tammra Windfield, who is waiting anxiously at Sun Rock Retreat without knowing her niece survived.",al={"why send news to tammra","makaba flathoof motive","why deliver the news"},it="motive",add=true}},ang={["faction:Horde"]="Stonetalon is a contested wilderness where Horde lines are stretched thin; delivering news of survivors helps maintain unity among scattered encampments.",["race:Tauren"]="The threat of the Grimtotem is a painful internal rift for the Shu'halo, making the preservation of innocent family members like Kaya deeply personal."},kw={"flathoof","grimtotem","kaya","makaba","protect kaya","stonetalon","sun rock retreat","tammra","tauren","windfield"},rel={"quest:6523","npc:makaba-flathoof","npc:tammra-windfield","subzone:sun-rock-retreat","zone:stonetalon"},m={start="Makaba Flathoof",["end"]="Tammra Windfield",level="18",faction="Horde",id=6401},src={"Kaya's Alive"}}
E["quest:6421"] = {t="quest",n="Boulderslide Ravine",z="stonetalon",s="Deep in the Boulderslide Ravine of the Stonetalon Mountains, local kobolds have begun frantically mining a rare subterranean mineral known as Resonite. Sensing a growing tension in the earth, the tauren Mor'rogal sends Horde adventurers to explore the ravine's cave system and retrieve mineral samples to uncover what lies buried beneath the rock.",h="Deep in the Boulderslide Ravine of the Stonetalon Mountains, local kobolds have begun frantically mining a...",sec={{t="Tension in the Stone",b="From his post at Sun Rock Retreat, the tauren Mor'rogal watches the peaks of the Stonetalon Mountains with deep concern. The land itself feels disturbed, an unnatural agitation radiating from the southeast. There, within the crags of Boulderslide Ravine, the local kobolds have abandoned their ordinary foraging to aggressively excavate a rare, subterranean mineral known as Resonite. To determine why these superstitious vermin are mining with such desperate frenzy, Mor'rogal enlists Horde scouts to push past their defenses, plumb the lowest depths of the cavern, and bring back unrefined mineral samples.",sp=0},{t="Awakening the Ancients",b="When the raw Resonite is inspected, its true nature becomes clear: the crystals hum with ancient Earthen magic. Kobolds digging blindly into the deep stone have breached an ancient layer of the world and unearthed an Earthen, one of the primordial stone-beings shaped by the Titans to sculpt the subterranean foundations of Kalimdor. What the kobolds treat as mere quarry has disturbed a relic of primordial history, forcing the tauren to intervene before whatever lies buried breaks free.",sp=1}},faq={{q="Where is Boulderslide Ravine located?",a="Boulderslide Ravine cuts into the mountains southeast of Sun Rock Retreat in the Stonetalon Mountains. The ravine leads into a winding cave system overrun with Boulderslide kobolds.",al={"boulderslide ravine location","where is boulderslide ravine","how to find boulderslide ravine"},it="place",gp=true},{q="Who gives the quest Boulderslide Ravine?",a="The quest is given by Mor'rogal, a tauren located at Sun Rock Retreat, the primary Horde outpost in the Stonetalon Mountains.",al={"who starts boulderslide ravine","quest giver boulderslide ravine","mor'rogal quest"},it="identity",gp=true},{q="What are Resonite Crystals?",a="Resonite is a rare mineral found deep within the Boulderslide cave system. It carries lingering traces of Titan-forged Earthen magic, indicating that the crystals were formed in close proximity to subterranean Earthen relics.",al={"what is resonite","resonite lore","resonite crystals"},sp=1,it="item"},{q="Why are the kobolds mining Resonite so frantically?",a="The kobolds stumbled upon Resonite while digging and, in their voracious search for shiny ores, penetrated deep beneath the mountains until they disturbed an ancient Earthen buried in the rock.",al={"why are kobolds mining","boulderslide kobolds goal","kobold plot stonetalon"},sp=1,it="wants"},{q="What is an Earthen according to tauren lore?",a="According to ancient lore recalled by Mor'rogal, the Earthen are stone-hewn creatures forged by the Titans long ago to carve and shape the very bedrock of the world.",al={"what are earthen","earthen titan connection","who are earthen"},it="history"},{q="What happens after completing this quest?",a="Upon identifying the Earthen magic within the Resonite crystals, Mor'rogal prepares an enchanted countermeasure and offers the follow-up quest 'Earthen Arise', sending you back into the cavern to confront the awakened threat.",al={"next quest after boulderslide ravine","what follows boulderslide ravine","boulderslide ravine follow up"},sp=1,it="next_step",gp=true},{q="Why does Mor'rogal want this investigated?",a="Mor'rogal senses an uneasy tension brewing in the Stonetalon Mountains and fears an unknown evil stirs beneath the peaks. The kobolds have begun frantically digging out strange Resonite crystals, and Mor'rogal needs samples and reconnaissance from the cavern depths to understand what ancient forces they might be disturbing.",al={"why investigate boulderslide ravine","mor'rogal motive","why does morrogal care"},it="motive",add=true},{q="Who are you sent against in Boulderslide Ravine?",a="You are sent against the Boulderslide kobolds infesting the ravine southeast of Sun Rock Retreat. Normally mere scavengers, these kobolds have been overtaken by a frantic obsession, tirelessly delving deep underground to mine Resonite ore for reasons that threaten the peace of the crags.",al={"who is in boulderslide ravine","boulderslide ravine enemies","kobolds in boulderslide ravine"},it="target",add=true}},ang={["race:Tauren"]="For tauren who revere the Earth Mother, unearthing ancient Titan workings beneath the mountains signals a dangerous disturbance in the natural balance of Stonetalon.",["class:Shaman"]="Shaman who listen to the earth can sense the unnatural resonance vibrating through the rock as the kobolds unseal relics of primordial Titan elemental crafting.",["profession:Mining"]="The Resonite mined by the Boulderslide kobolds is not ordinary ore; its matrix is infused with ancient arcane residue left by subterranean builders of old."},kw={"boulderslide ravine","earthen","kobold","mor'rogal","resonite","resonite crystal","stonetalon","sun rock retreat","titan"},rel={"npc:mor-rogal","quest:6481","subzone:sun-rock-retreat","zone:stonetalon","topic:kobold","topic:titan","zone:thunderbluff"},m={start="Mor'rogal",level="18",faction="Horde",id=6421,ri={"Resonite Crystal"}},src={"Boulderslide Ravine (quest)"}}
E["quest:6461"] = {t="quest",n="Blood Feeders",z="stonetalon",s="Blood Feeders is a Horde hunting contract given by Xen'Zilla in the Darkspear settlement of Malaka'jin. The local trolls have found plentiful game along the slopes of Stonetalon, but the scent of their butchered meat has drawn swarms of predatory Deepmoss spiders down into their camps.",h="Blood Feeders is a Horde hunting contract given by Xen'Zilla in the Darkspear settlement of Malaka'jin.",sec={{t="Unwanted Dinner Guests",b="The trolls who established the frontier outpost of Malaka'jin in southeastern Stonetalon Mountains came seeking good hunting. The craggy slopes proved bountiful, but the meat and game they brought back soon drew the attention of nocturnal predators. Deepmoss spiders, aggressive arachnids native to the crags and canyons to the north, began slipping into the camp under cover of dark, seeking to scavenge their caches or turn the hunters into prey.",sp=0},{t="Clearing the Crags",b="To keep the encampment safe and protect their supplies, Xen'Zilla asks adventurers to track the predators north into the mountain passes. The infestation of Deepmoss Creepers and Venomspitters is thickest around the rocky ravines and webs of the Cleft. Thinning their numbers pushes the brood back from Malaka'jin's borders and ensures the village can rest without fearing ambush from the shadows.",sp=0}},faq={{q="Who offers the quest Blood Feeders?",a="Xen'Zilla, a Darkspear troll residing in the village of Malaka'jin in the southeastern Stonetalon Mountains, offers the task to traveling Horde champions.",al={"who gives blood feeders","blood feeders quest giver","xen'zilla quest"},gp=true},{q="Why are the spiders attacking Malaka'jin?",a="The trolls at Malaka'jin hunt the local game extensively. The scent of fresh kills and drying meat draws the Deepmoss spiders down from the mountain passes at night to steal provisions and hunt the villagers.",al={"why spiders attack","spider attacks malakajin","why are spiders invading"},it="motive"},{q="Where are the Deepmoss spiders located?",a="Deepmoss Creepers and Venomspitters roam the central passes and crags north of Malaka'jin, with a particularly dense concentration dwelling within the web-strewn ravine known as the Cleft.",al={"where are deepmoss spiders","deepmoss creepers location","deepmoss venomspitter location"},it="place",gp=true},{q="What is Malaka'jin?",a="Malaka'jin is a Darkspear troll encampment located at the southern entrance of the Stonetalon Mountains, near the border with the Barrens, serving as a frontier hunting base and Horde outpost.",al={"what is malaka'jin","malakajin lore","troll village stonetalon"},it="place"},{q="Is there a greater threat tied to these spiders?",a="Deep inside the Cleft among the webs lives a massive, lethal spider matriarch. A warning signpost outside the canyon warns travelers of the danger and encourages groups to bring her down.",al={"big spider stonetalon","cleft elite spider","spider matriarch stonetalon"},it="danger"},{q="What happens after the spiders are culled?",a="Culling the Creepers and Venomspitters gives Malaka'jin breathing room, allowing the troll hunters to secure their meat stores and walk their camps at night without constant ambush.",al={"blood feeders aftermath","does malakajin become safe"},it="next_step"},{q="What are the Deepmoss spiders doing in Stonetalon Mountains?",a="The Deepmoss creepers and venomspitters are native arachnids prowling the crags and canyons of the Stonetalon Mountains. Though they have always inhabited the crags, the scent of fresh game brought into Malaka'jin by troll hunters has lured them closer to civilization. Now emboldened, these aggressive predators actively stalk out of the craggy hills to raid the village camps under the cover of darkness.",al={"deepmoss spiders stonetalon","deepmoss creepers venomspitters","why are spiders here"},it="target",add=true}},ang={["race:Troll"]="The hunters of Malaka'jin are kin, striving to carve out self-sufficient territory in Kalimdor's rugged highlands without succumbing to the wilderness.",["faction:Horde"]="Malaka'jin anchors the Horde's access route into the Stonetalon Mountains from the northern Barrens; safeguarding the village secures the entire southern pass.",["class:Hunter"]="Tracking dangerous predators that out-hunt and harass friendly settlements is natural work for skilled trackers moving through the crags."},kw={"blood feeders","cleft","deepmoss creeper","deepmoss venomspitter","malaka'jin","spiders","stonetalon","xen'zilla"},rel={"subzone:malaka-jin","zone:stonetalon","subzone:cleft","quest:6284","topic:troll"},m={start="Xen'Zilla",level="19",faction="Horde",id=6461},src={"Blood Feeders"}}
E["quest:6481"] = {t="quest",n="Earthen Arise",z="stonetalon",s="Deep within Boulderslide Ravine, the shaman Mor'rogal discovers a slumbering Earthen named Goggeroc sealed inside a Resonite cask. Fearing the raw destructive power an ancient being of stone could unleash upon Kalimdor, he sends a champion to shatter the cask and strike Goggeroc down before the creature can recover its full strength.",h="Deep within Boulderslide Ravine, the shaman Mor'rogal discovers a slumbering Earthen named Goggeroc sealed...",sec={{t="A Slumber in Stone",b="While investigating the vermin infestation in Boulderslide Ravine, scouts discovered a strange relic nestled among the kobolds: a Resonite cask radiating unearthly force. Mor'rogal, a tauren shaman stationed in the Stonetalon Mountains, recognized the container for what it truly was—a prison and sanctuary housing Goggeroc, a dormant Earthen. These primordial creations of stone possess strength that outmatches mortal warriors, making the prospect of Goggeroc roaming free an existential threat to the region.",sp=0},{t="The Resonite Crystal",b="Awakening an Earthen at full power would spell disaster for Stonetalon. To tilt the odds, Mor'rogal altered the mixture of resonite crystals brought to him, infusing them with shamanistic magic. The resulting enchanted crystal is designed to shatter the Resonite cask with enough force to shock Goggeroc awake in an acutely weakened state. It falls to the Horde's warriors to smash the container and strike down the disoriented titan-forged being before he can shake off centuries of torpor.",sp=1}},faq={{q="Who is Mor'rogal?",a="Mor'rogal is a tauren shaman stationed in the Stonetalon Mountains. He studies the disturbances in the region and uses his elemental magic to assess the bizarre ancient artifacts and threats unearthed by the local vermin.",al={"mor rogal","who is questgiver","orc shaman morrogal"},it="identity"},{q="What is an Earthen?",a="Earthen are ancient beings forged from living stone, creations left behind by the Titans in the world's dawn. Imbued with deep ties to the earth and staggering physical might, they have slept buried across Kalimdor and the Eastern Kingdoms for millennia.",al={"what is earthen","earthen lore","who are earthen"},it="people"},{q="Why does Mor'rogal want Goggeroc dead?",a="Mor'rogal fears that the unmatched strength of an active Earthen would bring catastrophe to Stonetalon and all of Kalimdor. Because such primordial beings are unpredictable and immensely powerful, he believes destroying Goggeroc while he is weakened from his slumber is the only way to safeguard the land.",al={"why kill goggeroc","is goggeroc evil","why slay earthen"},it="motive"},{q="Where is Goggeroc located?",a="Goggeroc is entombed inside a Resonite cask deep within the caves of Boulderslide Ravine, located in southeastern Stonetalon Mountains, surrounded by the Boulderslide kobolds who dig through the caverns.",al={"where is cask","goggeroc location","find resonite cask"},it="target",gp=true},{q="How do you awaken Goggeroc?",a="You use the Enchanted Resonite Crystal provided by Mor'rogal directly on the Resonite cask in the cave. The magically altered crystal fractures the container and forces the slumbering Earthen out into the open.",al={"how to summon goggeroc","use enchanted resonite crystal","open cask"},gp=true},{q="What happens after Goggeroc is slain?",a="Returning to Mor'rogal with news of Goggeroc's death relieves the shaman's deep dread. He hails you as a hero whose deed has averted a monumental disaster, earning you great honor and standing among the Tauren of Thunder Bluff.",al={"quest reward story","morrogal reaction","turn in earthen arise"},sp=1,it="next_step"},{q="Who is Goggeroc and why is he in Stonetalon?",a="Goggeroc is an ancient Earthen, a being of living stone forged by the Titans long ago. Sealed within a Resonite cask deep inside the Boulderslide Ravine cave, he has rested in slumber beneath Stonetalon Mountains. Mor'rogal warns that should an Earthen awaken with full power, his unmatched might would pose a catastrophic threat to Stonetalon and all of Kalimdor. Smashing the cask catches him while still disoriented and weak from his long sleep, granting you the only chance to vanquish him.",al={"who is goggeroc","goggeroc lore","what is goggeroc"},it="target",add=true},{q="Why does Mor'rogal need you to defeat Goggeroc instead of facing him himself?",a="Mor'rogal must focus his shamanistic powers at Malaka'jin to alter and enchant the Resonite crystals you gathered. His ritual prepares the only catalyst strong enough to fracture the enchanted cask housing Goggeroc. Because the slumbering Earthen will be vulnerable only for the briefest moment immediately after the seal breaks, he relies on a proven champion already attuned to the caves to strike without hesitation.",al={"why doesn't mor'rogal fight goggeroc","why me","why send me against goggeroc"},it="why_me",add=true}},ang={["class:Shaman"]="Mor'rogal channels shamanistic power to manipulate the resonite crystals and disrupt the elemental balance preserving the Earthen inside his cask.",["race:Tauren"]="Stonetalon is sacred ancestral hunting ground for the tribes of Thunder Bluff, and neutralizing an ancient destructive entity deep within its peaks protects the land from ruination.",["faction:Horde"]="By eliminating Goggeroc, Horde champions secure their presence in the contested crags of Stonetalon while earning the enduring respect of Thunder Bluff's leadership."},kw={"boulderslide ravine","earthen","earthen arise","goggeroc","mor'rogal","resonite cask","shaman","stonetalon mountains"},rel={"npc:mor-rogal","quest:6421","zone:stonetalon","zone:thunderbluff","topic:kobold"},m={start="Mor'rogal",level="20",faction="Horde",id=6481},src={"Earthen Arise"}}
E["quest:6523"] = {t="quest",n="Protect Kaya",z="stonetalon",s="Protect Kaya is a Horde escort quest in the Stonetalon Mountains. After discovering Kaya Flathoof held captive by hostile Grimtotem tauren, adventurers guide her through dangerous mountain trails to reach Camp Aparaje. Returning word of her survival brings immense relief to her anxious father, Makaba Flathoof.",h="Protect Kaya is a Horde escort quest in the Stonetalon Mountains.",sec={{t="A Captive in the Crags",b="The Stonetalon Mountains harbor bitter rivalries among the tauren, none sharper than the tension surrounding the treacherous Grimtotem clan. Deep within hostile territory, Kaya Flathoof was captured and held prisoner. Escaping on foot requires navigating winding trails flanked by opportunistic predators and watchful enemies, making an armed escort her only realistic hope of reaching friendly soil.",sp=0},{t="Flight to Camp Aparaje",b="Camp Aparaje lies in the eastern Stonetalon Mountains, and Kaya knows her way home from there. She aims for the camp, confident that once she reaches it she can find her own way. Guiding her through the ambush-heavy paths ensures she avoids recapture before her captors realize she slipped away.",sp=0},{t="A Father's Relief",b="Awaiting news near the southeastern border of Stonetalon, Makaba Flathoof fears the absolute worst for his missing daughter. When runners arrive to deliver confirmation that Kaya safely reached Camp Aparaje, Makaba's despair turns to overwhelming gratitude toward the champions who stood between his child and her captors.",sp=1}},faq={{q="Who is Kaya Flathoof?",a="Kaya Flathoof is a young tauren who was captured by hostile Grimtotem forces in the Stonetalon Mountains. She relies on passing Horde adventurers to break her out and shepherd her to safe ground.",al={"who is kaya","kaya flathoof lore","kaya"},it="identity"},{q="Where does Kaya need to be escorted?",a="Kaya must be escorted safely along the trails leading to Camp Aparaje in eastern Stonetalon, from where she knows her own way home.",al={"kaya escort destination","where to take kaya","where does kaya go"},it="place"},{q="Who is Makaba Flathoof?",a="Makaba Flathoof is Kaya's father, waiting anxiously near the southeastern entrance of the Stonetalon Mountains. He despairs over his missing child until adventurers bring word of her rescue.",al={"who is makaba","makaba flathoof lore","kaya's father"},it="people"},{q="Who captured Kaya?",a="Kaya was taken prisoner by hostile Grimtotem tauren who maintain camps and ambushes across the crags of Stonetalon.",al={"who took kaya","who kidnapped kaya","kaya kidnappers"},it="threat"},{q="What happens after Kaya reaches Camp Aparaje?",a="Once Kaya reaches Camp Aparaje, she can find her own way, and the player is tasked with returning to Makaba Flathoof to deliver the joyful news that she survived.",al={"after protect kaya","what next after escort","protect kaya follow up"},it="next_step"},{q="Is this quest available to Alliance players?",a="No. The Flathoof family belongs to the peaceful tauren aligned with the Horde, making this rescue mission exclusive to Horde adventurers.",al={"can alliance do protect kaya","is kaya horde only"},gp=true},{q="Why does Kaya Flathoof need your protection?",a="Kaya has just broken free from her captors, but she remains trapped behind hostile lines in the mountains. If her captors notice her escape before she reaches safe ground, she will be recaptured or killed. Reaching Camp Aparaje is her only chance to find safety and send word to her father, Makaba, who fears the worst for her survival.",al={"why protect kaya","kaya flathoof motive","why does kaya need escort"},it="motive",add=true},{q="Why can't Kaya Flathoof escape on her own?",a="Kaya is weakened, unarmed, and completely surrounded by enemy territory. Without a capable fighter to shield her from roaming patrols while she flees, she cannot safely make the trek down the road toward Camp Aparaje before her absence is discovered.",al={"why does kaya need me","why can't kaya leave alone","why need escort"},it="why_me",add=true}},ang={["race:Tauren"]="Rescuing Kaya directly aids fellow kin torn apart by the aggressive aggression of the Grimtotem clan.",["faction:Horde"]="Ensuring the safety of traveling families reinforces the Horde's hard-won footholds and supply routes in Stonetalon."},kw={"camp aparaje","escort","grimtotem","kaya flathoof","makaba flathoof","protect kaya","stonetalon","tauren"},rel={"quest:6401","npc:makaba-flathoof","subzone:camp-aparaje","zone:stonetalon"},m={start="Kaya Flathoof",["end"]="Makaba Flathoof",level="18",faction="Horde",id=6523},src={"Protect Kaya"}}
E["quest:6542"] = {t="quest",n="Report to Kadrak",z="stonetalon",s="This military dispatch directs Horde warriors from Malaka'jin in the Stonetalon Mountains to Kadrak's watch post on the border of the northern Barrens. It marks the transition from defending the crags to reinforcing the Horde's contentious military campaign inside Ashenvale. By reporting to Kadrak, soldiers are marshaled to support forward encampments like Splintertree Post and the Zoram Strand.",h="This military dispatch directs Horde warriors from Malaka'jin in the Stonetalon Mountains to Kadrak's watch...",sec={{t="A Call to the Northern Front",b="In the craggy pass of Malaka'jin, the orc Darn Talongrip keeps an eye on the Horde's southern and mountain frontiers. Yet the greatest military pressure lies northward in the ancient forests of Ashenvale, where night elf sentinels clash incessantly with Warsong lumber gatherers. Recognizing blooded fighters passing through Stonetalon, Darn directs capable recruits toward the northern Barrens watch tower to assist with ongoing campaigns.",sp=0},{t="Kadrak's Watch",b="Positioned squarely upon the northern threshold where the arid savannah meets the verdant canopy of Ashenvale, the orc Kadrak oversees Horde troop movement into contested territory. The Horde is aggressively securing its foothold, maintaining outposts at both the western Zoram Strand and Splintertree Post to the north. Kadrak serves as the vital junction for coordinating supplies, troops, and urgent reports across these embattled forest lines.",sp=0}},faq={{q="Who sends you to Kadrak from Stonetalon?",a="Darn Talongrip, an orc stationed at the Horde outpost of Malaka'jin in the Stonetalon Mountains, offers this dispatch to capable adventurers heading toward the forest border.",al={"quest giver report to kadrak","who starts report to kadrak stonetalon","darn talongrip quest"},it="identity"},{q="Where is Kadrak located?",a="Kadrak is stationed at the northern watch tower in the Barrens, guarding the primary road that crosses northward into Ashenvale.",al={"kadrak location","where is kadrak","find kadrak"},it="place",gp=true},{q="Why is the Horde recruiting warriors for Ashenvale?",a="The Horde needs lumber to sustain Orgrimmar and has established fortified positions such as the Zoram Strand and Splintertree Post. Because these efforts face intense resistance from the native night elves, commanders require constant reinforcements to secure the territory.",al={"why go to ashenvale","horde ashenvale campaign","why fight in ashenvale"},it="purpose"},{q="What happens after reporting to Kadrak?",a="Kadrak will brief you on the strategic situation in Ashenvale and task you with delivering and collecting military reports across the forest's contested outposts via The Warsong Reports.",al={"what next after kadrak","the warsong reports","kadrak follow up quest"},it="next_step"},{q="Is this quest different from the Barrens version?",a="Both are breadcrumb quests leading to Kadrak at the Ashenvale border. One is offered in the Barrens (at Crossroads) and this one in the Stonetalon Mountains; completing either one directs you into the Ashenvale storyline.",al={"barrens vs stonetalon kadrak","two report to kadrak quests","kadrak breadcrumb duplicate"},gp=true},{q="What is the Zoram Strand mentioned in the briefing?",a="The Zoram Strand is a coastal region in northwestern Ashenvale along the Veiled Sea. The Horde has established a fortified beach outpost there to support tactical movements and secure naval access.",al={"what is zoram strand","zoram strand outpost","ashenvale beach base"},it="place"},{q="Why does Darn Talongrip want you to report to Kadrak?",a="The Horde has expanded into the ancient forests of Ashenvale, establishing a fresh foothold along the Zoram Strand. Holding these newly won frontiers requires constant reinforcements, and Darn Talongrip is scouting capable adventurers passing through Sun Rock Retreat to bolster their frontline ranks.",al={"why does darn send me to kadrak","darn talongrip motive","why report to kadrak"},it="motive",add=true}},ang={["faction:Horde"]="This order integrates you into the Warchief's broader war effort, funneling frontier veterans into the active struggle for Ashenvale's resources.",["race:Orc"]="The campaign in Ashenvale is crucial for the Warsong clan and the survival of Durotar, making Kadrak's post a proving ground for young orc warriors.",["race:Tauren"]="Horde lookouts like the orc Darn Talongrip guide travelers safely across the mountain borders, keeping the lines of communication open between bloodhoof lands and the Warchief's northern front."},kw={"ashenvale","barrens","darn talongrip","kadrak","splintertree","stonetalon mountains","warsong reports","zoram strand"},rel={"npc:kadrak","npc:darn-talongrip","quest:6543","zone:ashenvale","zone:stonetalon","subzone:zoram-strand","quest:6541","topic:horde"},m={start="Darn Talongrip",["end"]="Kadrak",level="19",faction="Horde",id=6542},src={"Report to Kadrak (Stonetalon Mountains)"}}
E["quest:6548"] = {t="quest",n="Avenge My Village",z="stonetalon",s="Makaba Flathoof barely survived a vicious assault when raiders from the Grimtotem clan fell upon his village in the southeastern Stonetalon Mountains. Cut off from his kin and surrounded by the dead, he asks Horde travelers to strike back at the encampment of Grimtotem ruffians and hired sellswords to avenge his fallen people.",h="Makaba Flathoof barely survived a vicious assault when raiders from the Grimtotem clan fell upon his village...",sec={{t="Blood in the Crags",b="Near the border between the Barrens and the red stone passes of Stonetalon, Makaba Flathoof stands as a lone survivor of a brutal massacre. Raiders flying the dark banners of the Grimtotem clan descended without warning, slaughtering nearly everyone in his settlement. Though Makaba fought back fiercely and brought down several of the attackers, he was eventually driven into hiding with little more than his life and his wrath.",sp=0},{t="The Grimtotem Menace",b="The Grimtotem have long been an unruly, aggressive thorn in the side of the tauren tribes united under High Chieftain Cairne Bloodhoof. Unlike the peaceful nomads wandering Mulgore, Grimtotem warbands frequently employ ruthless ruffians and opportunistic mercenaries to carve out territory and strike at isolated settlements. For Makaba, diplomacy or tribal kinship holds no meaning now; only blood repaid with blood can bring measure to his grief.",sp=0}},faq={{q="Who gave this quest?",a="Makaba Flathoof is a tauren survivor encamped near the southeastern pass into the Stonetalon Mountains. He survived the violent sacking of his nearby village by the Grimtotem clan and seeks retribution against the raiders.",al={"quest giver","makaba flathoof","who is makaba"},it="identity"},{q="Why are the Grimtotem attacking other tauren?",a="The Grimtotem clan has never truly embraced the unity of the Horde or Cairne Bloodhoof's vision of peace. Fiercely territorial, xenophobic, and aggressive, they openly raid rival settlements, kill outsiders, and use armed thugs and hired mercenaries to claim dominion over regions like Stonetalon.",al={"why grimtotem hostile","tauren attacking tauren","grimtotem clan lore"},it="conflict"},{q="Where are the Grimtotem attackers located?",a="The Grimtotem ruffians and mercenaries are stationed in an encampment just west of Makaba Flathoof's position in southeastern Stonetalon, set among the rocky hills overlooking the pass.",al={"where are the mobs","grimtotem camp location","where to find ruffians"},it="place",gp=true},{q="Who are the Grimtotem Mercenaries?",a="The Grimtotem Clan frequently supplements its own warriors by hiring ruthless fighters and sellswords to bolster their warbands, ensuring they have sufficient muscle to terrorize and overrun isolated settlements.",al={"mercenaries","grimtotem sellswords","who are the mercs"},it="identity"},{q="What happens after this quest?",a="After cutting down the frontline ruffians and mercenaries, Makaba asks you to strike at the leader behind the massacre, Grundig Darkcloud, in the follow-up quest 'Kill Grundig Darkcloud'.",al={"next quest","what follows avenge my village","kill grundig darkcloud"},sp=1,it="next_step",gp=true},{q="Where was Makaba's village located?",a="Makaba's settlement was an isolated tauren encampment situated near the border passes of southeastern Stonetalon. It was thoroughly wiped out by the Grimtotem raid, leaving Makaba as one of the few known survivors.",al={"flathoof village","where was the village","what village was destroyed"},it="place"},{q="Why does Makaba Flathoof want the Grimtotem killed?",a="Makaba Flathoof seeks vengeance after the Grimtotem Clan launched a brutal raid on his village, slaughtering nearly everyone who lived there. Having lost his home and his people, all that drives him now is retribution against the clan that massacred his family and neighbors.",al={"makaba flathoof motive","why avenge village","why does makaba want revenge"},it="motive",add=true},{q="Who are the Grimtotem targeting this area?",a="You are sent against the Grimtotem Ruffians and Mercenaries encamped to the west. The Grimtotem are an aggressive, isolationist tauren clan known for hostility toward other tribes and the Horde alike, raiding local settlements to expand their foothold in Stonetalon Mountains.",al={"grimtotem ruffians and mercenaries","who are you sent to kill","who attacked makaba village"},it="target",add=true},{q="Why does Makaba Flathoof need your help?",a="Makaba fought desperately during the raid and killed as many Grimtotem as he could, but he barely escaped with his own life. Wounded, isolated, and left without allies or village guards to rally, he cannot face the remaining raiders alone.",al={"why cant makaba fight","why ask me","why does makaba need help"},it="why_me",add=true}},ang={["race:Tauren"]="The Grimtotem clan's treachery hits tauren travelers hardest. Seeing fellow shu'halo butchered by their own kind reinforces the grim reality of clan division and the danger the Grimtotem pose to Cairne's united people.",["faction:Horde"]="The Horde relies on open, secure passes between the Barrens and Stonetalon. A rogue Grimtotem band murdering travelers and allied villages threatens the Warchief's supply lines through the mountains."},kw={"avenge my village","grimtotem","grimtotem mercenary","grimtotem ruffian","grundig darkcloud","makaba flathoof","stonetalon mountains"},rel={"npc:makaba-flathoof","quest:6629","zone:stonetalon"},m={start="Makaba Flathoof",level="18",faction="Horde",id=6548},src={"Avenge My Village"}}
E["quest:6629"] = {t="quest",n="Kill Grundig Darkcloud",z="stonetalon",s="Kill Grundig Darkcloud is a Horde quest given by Makaba Flathoof along the southeastern path of Stonetalon Mountains. After culling the Grimtotem ruffians and mercenaries, Makaba directs you to strike down the leader responsible for sacking his home: Grundig Darkcloud. Eliminating Grundig and his retinue of brutes delivers justice for the devastated settlement.",h="Kill Grundig Darkcloud is a Horde quest given by Makaba Flathoof along the southeastern path of Stonetalon...",sec={{t="The Butcher of the Path",b="Makaba Flathoof managed to survive the sudden, violent assault on his settlement along the Stonetalon trail, but his sorrow remains raw. After testing your capability against the Grimtotem's foot soldiers, he points you toward the mastermind behind the bloodshed: Grundig Darkcloud. Unlike mere opportunistic raiders, Grundig commands a devoted retinue of brutes and spearheaded the slaughter that leveled the village.",sp=0},{t="Strike at Grimtotem Post",b="Grundig makes his camp at Grimtotem Post, situated further up the mountain road to the west. To avenge Makaba's kin and secure the pass from further violence, travelers must ascend into the stronghold, carve through Darkcloud's inner circle of brutes, and put an end to Grundig himself before his raiding party can descend upon other vulnerable camps.",sp=0}},faq={{q="Who is Grundig Darkcloud?",a="Grundig Darkcloud is a violent Grimtotem commander based out of Grimtotem Post in southeastern Stonetalon Mountains. He directly orchestrated and led the brutal attack that destroyed Makaba Flathoof's village.",al={"grundig darkcloud","who is grundig","grimtotem leader"},it="target"},{q="Where can Grundig Darkcloud be found?",a="Grundig Darkcloud is located at Grimtotem Post, perched along the mountain trail just up the path to the west of Makaba Flathoof's camp near the Barrens border.",al={"grundig location","where is grundig","grimtotem post location"},it="place",gp=true},{q="What is Makaba Flathoof's motive for this task?",a="Makaba watched his home and clanmates slaughtered by the Grimtotem. Having already exacted preliminary vengeance on their ruffians and mercenaries, he asks for the head of the ringleader, Grundig Darkcloud, to bring true closure and retribution.",al={"why kill grundig","makaba story","makaba revenge"},it="motive"},{q="Why are the Grimtotem attacking peaceful settlements here?",a="The Grimtotem clan holds fierce disdain for the other tauren tribes, particularly those who have allied with the Horde or embrace gentler paths. They routinely use ambushes, raiding, and sheer brutality to drive competing clans off lands they wish to dominate.",al={"why grimtotem attack","grimtotem hostility"},it="conflict"},{q="What comes after killing Grundig Darkcloud?",a="Killing Grundig Darkcloud and his brutes is the conclusion of Makaba Flathoof's short vengeance chain. With the butcher slain, Makaba can at last mourn his village knowing justice was served.",al={"what next after grundig","flathoof chain continuation"},it="next_step",gp=true},{q="What is the prerequisite quest for this task?",a="You must first complete 'Avenge My Village,' in which Makaba Flathoof tests your resolve by having you strike down the Grimtotem ruffians and mercenaries camped just to the west.",al={"prereq kill grundig","quest before grundig"},gp=true},{q="Why does Makaba Flathoof need your help instead of fighting Grundig himself?",a="Makaba Flathoof is a lone survivor stranded on the mountain road, devastated by the butchery of his village. Grundig Darkcloud commands Grimtotem Post flanked by a personal vanguard of savage brutes, far too heavily defended for a solitary, wounded tauren to challenge directly. Having seen you cut down the rank-and-file raiders, Makaba places his hope for retribution entirely in your fighting prowess.",al={"why me makaba","why doesn't makaba flathoof fight grundig","why send me kill grundig darkcloud"},it="why_me",add=true}},ang={["race:Tauren"]="The Grimtotem clan continues to sow discord among the tauren people, demonstrating through Grundig's slaughter that unity under the Horde will always be opposed by their cutthroat extremism.",["faction:Horde"]="Stonetalon is vital ground for the Horde's expansion into Kalimdor, and aggressive Grimtotem warlords like Grundig threaten supply routes linking the Barrens to Sun Rock Retreat."},kw={"brute","darkcloud","flathoof","grimtotem","grundig","makaba","post","stonetalon"},rel={"npc:makaba-flathoof","quest:6548","zone:stonetalon"},m={start="Makaba Flathoof",level="18",faction="Horde",id=6629},src={"Kill Grundig Darkcloud"}}
E["subzone:blackwolf-river"] = {t="subzone",n="Blackwolf River",z="stonetalon",s="Blackwolf River is a waterway flowing out of Cragpool Lake down through Windshear Crag in the Stonetalon Mountains. Once a clean mountain stream, its waters have become thoroughly polluted by the Venture Company's aggressive logging and industrial operations.",h="Blackwolf River is a waterway flowing out of Cragpool Lake down through Windshear Crag in the Stonetalon...",sec={{t="Industrial Runoff",b="Descending from Cragpool Lake, the Blackwolf River cuts across the basin of Windshear Crag. What should be a pristine alpine tributary has instead borne the brunt of unchecked goblin enterprise. As the Venture Company clears the surrounding woodlands with heavy machinery and buzzsaws, sludge, oil, and logging waste leach steadily into the current. The despoiled river stands as a vivid example of the commercial plunder threatening Stonetalon's wilderness.",sp=0}},faq={{q="Where does the Blackwolf River start and lead?",a="The river flows down out of Cragpool Lake in the upper reaches of the mountains and winds through the logged basin of Windshear Crag.",al={"blackwolf river source","where is blackwolf river","blackwolf river location"},it="place"},{q="Why is the river water polluted?",a="The Venture Company operates massive deforestation and mechanical logging rigs throughout Windshear Crag. Runoff from their steam machinery, waste, and clear-cutting drains directly into the watercourse.",al={"why is blackwolf river dirty","blackwolf river pollution","venture company pollution"},it="ruin"},{q="Who is currently operating along the river?",a="The Venture Company dominates the riverbank, utilizing the surrounding valley for heavy lumber harvesting and mechanical operations despite resistance from local wildlife and native inhabitants.",al={"who controls blackwolf river","who is at blackwolf river","enemies near blackwolf river"},it="residents"},{q="What is the history of the Blackwolf River?",a="The Blackwolf River once ran clear through the heart of the Stonetalon Mountains, flowing out from Cragpool Lake across Windshear Crag. That balance shattered when the Venture Company moved heavy industry into the crag. Their aggressive deforestation and mechanized logging quickly poisoned the waterway, turning a pristine mountain stream into a toxic, sludge-choked runoff for goblin industry.",al={"blackwolf river lore","history of blackwolf river","what happened to blackwolf river"},it="history",add=true},{q="Is the Blackwolf River dangerous?",a="Yes, both the water and its banks pose serious hazards. The river itself carries toxic industrial runoff from Venture Company logging operations upstream. Furthermore, the surrounding crag is swarming with aggressive Venture Company laborers, loggers, and mechanized shredders fiercely guarding their machinery and clearing timber with no regard for anyone passing through.",al={"is blackwolf river safe","blackwolf river dangers","dangers of blackwolf river"},it="danger",add=true}},ang={["class:Druid"]="The desecration of Blackwolf River by goblin timber operations is a sharp affront to the Cenarion Circle and all who revere the untamed waters of Kalimdor.",["race:Tauren"]="Seeing the earth scarred and the waters fouled by profit-driven interlopers reinforces the tauren resolve to cleanse Stonetalon of reckless industrial blight."},kw={"blackwolf river","cragpool lake","logging","pollution","stonetalon mountains","venture co","venture company","windshear crag"},rel={"subzone:windshear-crag","subzone:cragpool-lake","topic:venture-company","zone:stonetalon","quest:764"},src={"Blackwolf River"}}
E["subzone:boulderslide-cavern"] = {t="subzone",n="Boulderslide Cavern",z="stonetalon",s="Boulderslide Cavern is a subterranean warren tucked at the deepest end of Boulderslide Ravine in the Stonetalon Mountains. It serves as the primary den and excavation site for the local Boulderslide kobolds, who obsessively tunnel in search of glowing mineral formations.",h="Boulderslide Cavern is a subterranean warren tucked at the deepest end of Boulderslide Ravine in the...",sec={{t="The Resonite Dig",b="The Boulderslide kobolds have burrowed deep into the crags of Stonetalon, establishing Boulderslide Cavern as their stronghold. Unlike ordinary vermin merely seeking shelter, these kobolds mine frantically for resonite, a rare glowing purple crystal embedded throughout the stone. The crystals pulse with lingering earthen magic, driving the creatures into a defensive frenzy against any intruders who approach their dig.",sp=0},{t="The Slumbering Giant",b="Deeper inside the caverns, reckless excavation has breached ancient secrets. Embedded in the subterranean rock lies a resonite cask containing Goggeroc, a slumbering earthen from ages past. The kobolds' relentless digging around this mystical relic risks awakening a being imbued with primordial stone magic, posing a sudden danger to the entire ravine.",sp=1}},faq={{q="What are the kobolds mining here?",a="The kobolds are mining resonite, a rare purple crystal found embedded in the cavern's rock walls. The mineral hums with faint traces of earthen magic, making it a valuable prize and causing the kobolds to guard their caches fanatically.",al={"what is resonite","purple crystals stonetalon","why are kobolds mining"},it="purpose"},{q="Who is Goggeroc?",a="Goggeroc is an ancient earthen who lies dormant within a resonite cask deep inside the cavern. The kobolds' excavation around his resting place risks disturbing his centuries-long slumber.",al={"goggeroc lore","earthen in boulderslide","sleeping giant in cave"},it="identity"},{q="Where is Boulderslide Cavern located?",a="The cavern entrance sits at the far end of Boulderslide Ravine, nestled in the craggy mountains of southern Stonetalon Mountains, just northeast of the path toward the Barrens.",al={"boulderslide cavern location","how to find boulderslide cavern","where is the cave"},it="place",gp=true},{q="Why is the Horde interested in this cavern?",a="The Horde keeps watch on the cavern to curb the aggressive kobold infestation spilling into the ravine, and out of interest in the magical properties of the resonite crystals they mine.",al={"horde quests boulderslide","why send me to boulderslide"},it="motive"},{q="What is Boulderslide Cavern?",a="Boulderslide Cavern is a subterranean mine nestled deep at the end of Boulderslide Ravine in the Stonetalon Mountains. It serves as an active nesting ground and extensive dig site for local kobolds, who relentlessly excavate rare magical resonite crystals from its stony depths.",al={"what is boulderslide cavern","boulderslide cavern lore","about boulderslide cavern"},it="place",add=true},{q="Who lives in Boulderslide Cavern?",a="The cavern is inhabited entirely by the Boulderslide kobolds. These aggressive subterranean diggers have built their warrens here, working feverishly to extract resonite while violently defending their tunnels from any intruders who dare approach.",al={"who lives in boulderslide cavern","boulderslide cavern inhabitants","who is in boulderslide cavern"},it="residents",add=true},{q="Is Boulderslide Cavern dangerous?",a="Yes, it is extremely dangerous. The kobolds inside guard their mining operations with their lives and will swarm anyone trespassing in their warrens. Furthermore, their deep excavations have reached ancient relics, including a dormant earthen slumbering deep within the mine.",al={"is boulderslide cavern dangerous","danger boulderslide cavern","boulderslide cavern threats"},it="danger",add=true}},ang={["profession:Mining"]="The cavern is intensely worked by the Boulderslide clan, who tunnel relentlessly to uncover glowing veins of magical resonite.",["class:Shaman"]="The resonite crystals and the slumbering earthen Goggeroc both resonate with primordial earth magic, an echo of the world's ancient stone shapers."},kw={"boulderslide","cavern","earthen","goggeroc","kobold","resonite","stonetalon"},rel={"zone:stonetalon","quest:6421","quest:6481","topic:kobold"},src={"Boulderslide Cavern"}}
E["subzone:boulderslide-ravine"] = {t="subzone",n="Boulderslide Ravine",z="stonetalon",s="Boulderslide Ravine is a rugged, secluded canyon tucked away in the central peaks of the Stonetalon Mountains, reached via Webwinder Path. Largely spared from the direct clashes between the Horde and Alliance, it serves as the rocky approach to Boulderslide Cavern and remains home to wild mountain beasts.",h="Boulderslide Ravine is a rugged, secluded canyon tucked away in the central peaks of the Stonetalon...",sec={{t="A Quiet Mountain Pass",b="Tucked away off Webwinder Path, Boulderslide Ravine is a narrow cut of rock in the Stonetalon heights. While loggers, night elves, and the Horde battle over timber and sacred glades throughout the region, this craggy pass remains relatively undisturbed by military forces. Wild mountain rams and roaming crag beasts like Cliff Stormers make up the local fauna, navigating the treacherous ledges and sheer stone walls. Prospectors also keep an eye on the ravine, as rich mineral veins frequently crop up along the rocky slopes leading deeper toward the cavern network.",sp=0},{t="Traces in the Stone",b="Opposite the entrance to Boulderslide Cavern lies a small, quiet cave overlooking the ravine. Lit by rough torches and stacked with weathered supply barrels, the shelter contains primitive tribal paintings across its interior walls. The crude artwork bears a striking resemblance to ancient tauren designs, suggesting that native tribes traveled or sought temporary shelter in these crags long before modern conflict swept into the mountains.",sp=0}},faq={{q="Where is Boulderslide Ravine located?",a="Boulderslide Ravine is located in the Stonetalon Mountains. It is reached by traveling along Webwinder Path into the higher crags.",al={"boulderslide ravine location","how to get to boulderslide ravine","where is boulderslide ravine"},it="place",gp=true},{q="What creatures inhabit Boulderslide Ravine?",a="The ravine is mainly populated by local wildlife, particularly mountain rams and dangerous crag stalkers such as Cliff Stormers.",al={"boulderslide ravine mobs","what is in boulderslide ravine"},it="residents"},{q="What is the abandoned cave across from Boulderslide Cavern?",a="Facing the cavern entrance is a small alcove lit by torches and stocked with old barrels. Its stone walls display tribal pictographs that resemble traditional tauren art, pointing to past use by local wanderers or hunters.",al={"abandoned cave boulderslide","cave in boulderslide ravine","tauren cave stonetalon"}},{q="Why is Boulderslide Ravine significant?",a="It serves as the natural approach to Boulderslide Cavern, a subterranean lair deep in the mountains, and offers valuable mineral outcroppings for travelers passing through.",al={"what is boulderslide ravine for","boulderslide ravine purpose"},it="purpose"},{q="What is Boulderslide Ravine?",a="Boulderslide Ravine is a rugged canyon nestled in the mountains of Stonetalon, accessed by way of Webwinder Path. It serves primarily as the approach to the deeper Boulderslide Cavern. While war between the Horde and Alliance consumes much of the surrounding peaks, this tucked-away ravine remains largely isolated from the clashes.",al={"what is boulderslide ravine","boulderslide ravine overview","boulderslide ravine lore"},it="place",add=true},{q="Why is the cave in Boulderslide Ravine abandoned?",a="Opposite the cavern entrance sits a secluded, abandoned shelter lit by crude torches and stocked with old barrels. Its walls bear faded tribal art reminiscent of tauren crafts, suggesting local tribes or wandering hunters once made camp here before vacating the ravine to wild beasts.",al={"why is the cave abandoned","boulderslide abandoned cave","who abandoned the cave"},it="ruin",add=true},{q="Is Boulderslide Ravine dangerous?",a="While spared from organized military skirmishes, the ravine is far from safe. Native rams graze along the steep trails, and volatile elemental Cliff Stormers prowl the crags, making careless passage risky for travelers seeking its mining veins or heading toward the cavern.",al={"is boulderslide ravine dangerous","dangers in boulderslide ravine","boulderslide threats"},it="danger",add=true}},ang={["profession:Mining"]="The steep rock walls of the ravine are a reliable place to spot mineral veins exposed by the mountain's shifting stone.",["race:Tauren"]="The faded art inside the small side cave bears the distinct touch of tauren tribal markers, hinting at ancestral paths through the Stonetalon heights."},kw={"boulderslide cavern","boulderslide ravine","cliff stormer","rams","stonetalon","webwinder path"},rel={"subzone:boulderslide-cavern","subzone:webwinder-path","quest:6421","zone:stonetalon","topic:tauren"},src={"Boulderslide Ravine"}}
E["subzone:camp-aparaje"] = {t="subzone",n="Camp Aparaje",z="stonetalon",s="Camp Aparaje was once a peaceful tauren village nestled in the eastern heights of the Stonetalon Mountains. Today, it lies overrun and occupied by the hostile Grimtotem tribe, who slaughtered the original settlers and took the outpost for themselves.",h="Camp Aparaje was once a peaceful tauren village nestled in the eastern heights of the Stonetalon Mountains.",sec={{t="A Tragic Downfall",b="Perched along the crags of the Stonetalon Mountains, Camp Aparaje was established by peaceful tauren looking to live quietly in the highlands. That tranquility was shattered when raiders from the nearby Grimtotem Post, led by Grundig Darkcloud, launched a brutal and unprovoked assault. The villagers were butchered or driven away, and survivors such as Makaba Flathoof were left mourning the destruction of their home while dreading the fate of captive kin.",sp=0},{t="Under Grimtotem Sway",b="Now completely occupied by Grimtotem warriors, Camp Aparaje serves as a forward base of operations for the aggressive tribe in the region. Unlike typical Grimtotem settlements that fly blue markings, the great totem standing in Aparaje is carved with deep crimson paint, marking the bloody nature of its capture and the grim dominion of Grundig Darkcloud's brutes over the captured village.",sp=0}},faq={{q="Who used to live at Camp Aparaje?",a="Camp Aparaje was inhabited by peaceful tauren affiliated with the Horde and Bloodhoof tribe, including Makaba Flathoof and his daughter Kaya, before the settlement was invaded.",al={"who lived here","camp aparaje original villagers","makaba flathoof village"},it="people"},{q="Why is the camp hostile to Horde players?",a="The village was violently seized by the Grimtotem tribe, a xenophobic and treacherous tauren clan that refuses allegiance to Cairne Bloodhoof and actively attacks outsiders, including members of the Horde.",al={"why are tauren attacking me","who controls camp aparaje","why is camp aparaje red"},it="hostile"},{q="Who led the assault on Camp Aparaje?",a="The raid was spearheaded by Grundig Darkcloud, a brutal Grimtotem chieftain operating out of Grimtotem Post who seeks to expand his tribe's violent grip over Stonetalon.",al={"who attacked aparaje","grundig darkcloud","who is the leader here"},it="threat"},{q="What happened to the surviving villagers?",a="Most inhabitants were killed during the raid. A few managed to flee, while others, like young Kaya Flathoof, were captured by the Grimtotem and held captive at the nearby Grimtotem Post.",al={"kaya flathoof","where are the survivors","are there survivors"}},{q="What is Camp Aparaje?",a="Camp Aparaje was once a peaceful tauren settlement tucked into the eastern heights of the Stonetalon Mountains. It served as a home for quiet families like Makaba Flathoof and his daughter, but that tranquil existence was shattered when violent Grimtotem raiders swept down from their stronghold to seize the village by force.",al={"camp aparaje overview","what is this camp","tell me about camp aparaje"},it="place",add=true},{q="What happened at Camp Aparaje?",a="Hostile Grimtotem warriors launched a sudden, brutal assault on the village from nearby Grimtotem Post. Led by Grundig Darkcloud, the attackers drove out or slaughtered the resident tauren, capturing those who could not escape in time and claiming the outpost entirely for their own treacherous tribe.",al={"what happened here","camp aparaje history","how was camp aparaje destroyed"},it="history",add=true},{q="Who controls Camp Aparaje now?",a="The camp is currently held by occupying Grimtotem raiders under the command of Grundig Darkcloud. Having displaced the original inhabitants, these hostile tauren now use the village as an active encampment, maintaining sentries and keeping prisoners under guard.",al={"who lives in camp aparaje","who holds camp aparaje","who is in camp aparaje"},it="residents",add=true},{q="Why was Camp Aparaje abandoned by its original people?",a="The peaceful villagers had no chance against the surprise assault mounted by the Grimtotem. Those who survived the initial massacre, such as Makaba Flathoof, were forced to flee for their lives into the surrounding wilderness, leaving their homes and belongings behind to be ransacked by their conquerors.",al={"why is camp aparaje ruined","why was the village lost","why did the villagers leave"},it="ruin",add=true},{q="Is Camp Aparaje dangerous?",a="Yes. The settlement is heavily occupied by aggressive Grimtotem warriors who will attack anyone approaching the camp on sight, regardless of your standing with the rest of the Horde. Wandering into its borders invites immediate combat with Grundig Darkcloud's hardened raiders.",al={"is camp aparaje safe","danger at camp aparaje","camp aparaje threats"},it="danger",add=true}},ang={["race:Tauren"]="The ruins of Camp Aparaje serve as a bitter reminder of the cruelty of Magatha's Grimtotem tribe, proving that not all children of the Earth Mother share Cairne Bloodhoof's vision of honor and peace.",["faction:Horde"]="Clearing the Grimtotem from Camp Aparaje is a matter of vengeance and defense, ensuring the treacherous tribe is punished for butchering innocent Horde subjects in Stonetalon."},kw={"camp aparaje","grimtotem","grimtotem post","grundig darkcloud","kaya flathoof","makaba flathoof","stonetalon"},rel={"quest:6548","quest:6629","quest:6523","npc:makaba-flathoof","topic:grimtotem-tribe","zone:stonetalon","topic:tauren","topic:horde"},src={"Camp Aparaje"}}
E["subzone:charred-vale"] = {t="subzone",n="Charred Vale",z="stonetalon",s="The Charred Vale is a smoldering valley in southwestern Stonetalon Mountains, devastated by the reckless deforestation and machinery of the Venture Company. Once a thriving haven for treants and chimaeras, it is now engulfed in flames, roving elementals, and hostile harpies.",h="The Charred Vale is a smoldering valley in southwestern Stonetalon Mountains, devastated by the reckless...",sec={{t="A Scorched Woodland",b="Not long ago, this southwest basin was a flourishing alpine wood guarded by majestic treants and inhabited by native chimaeras and harpies. Its ruin began with the arrival of the Venture Company. The greedy goblin outfit clear-cut the forest with explosive machinery, corrupting the guardians and awakening chaotic fire elementals. Though the treants eventually forced the goblins back, the land was left broken, scarred by fire, and tainted by whatever foul devices the retreating loggers deployed.",sp=0},{t="Struggles of Renewal",b="Today, blackened ancients wander blindly through smoke and ash alongside enraged elementals. Bloodfury harpies roost in the skeletal snags, defending what remains of their territory. Despite the hostility of the valley, druids from Sun Rock Retreat refuse to abandon the region, dispatching travelers to sow enchanted seeds and tend the corrupted ancients in a persistent campaign to reclaim the scorched earth.",sp=0}},faq={{q="Why is the Charred Vale on fire?",a="The devastation was caused by the Venture Company's ruthless logging operations. Their destructive machinery and aggressive deforestation enraged the primal spirits of the land and unleashed destructive fire elementals that spread across the valley.",al={"why is it burning","who burned charred vale","what happened to charred vale"},it="ruin"},{q="Can the forest in the Charred Vale ever recover?",a="Tauren druids from nearby Sun Rock Retreat believe it can. They task travelers with soothing the maddened treants and planting enchanted earthen seeds amidst the ash, hoping to coax green shoots from the ruined soil.",al={"is charred vale healing","druids charred vale"}},{q="What creatures inhabit the Charred Vale?",a="The basin is crawling with hostile elemental fire spirits, blackened and vengeful ancients, Scorched Basilisks, and wild chimaeras. It is also plagued by Bloodfury harpies.",al={"monsters in charred vale","what lives in charred vale"},it="residents"},{q="What was the Charred Vale called before it burned?",a="Its original name has been lost to time, but it was renowned as a lush woodland sanctuary long before goblin axes arrived.",al={"charred vale old name","original name of charred vale"},it="name"},{q="What is the Charred Vale?",a="The Charred Vale is a vast, smoldering valley in southwestern Stonetalon Mountains. Once a lush, verdant woodland watched over by ancient treants, it has been reduced to ash, lava fissures, and blazing stumps following devastating industrial exploitation.",al={"what is charred vale","charred vale overview","about charred vale"},it="place",add=true},{q="What happened at the Charred Vale?",a="The goblins of the Venture Company swept through the valley, clear-cutting the forest and burning the land. When the ancient tree-guardians rose up to defend the woods and drive the loggers out, the conflict enraged the local nature spirits, shattered the earth, and unleashed volatile fire elementals. As the goblins retreated, their toxic weaponry corrupted the surviving ancients into blackened, maddened husks.",al={"charred vale history","what happened in charred vale","how was charred vale destroyed"},it="history",add=true},{q="Is the Charred Vale dangerous?",a="It is one of the most hostile places in Stonetalon. Beyond the open lava fissures and choking smoke, you face fiery elementals, feral Bloodfury harpies, aggressive chimaeras, and maddened blackened ancients. Deep within the smoldering basin, black whelps and dangerous black drakes also stalk the scorched slopes.",al={"is charred vale dangerous","charred vale threats","dangers of charred vale"},it="danger",add=true}},ang={["class:Druid"]="The devastation here serves as a harsh warning of what happens when natural balance is shattered by uncontrolled greed, making the valley a key focus for reclamation efforts.",["faction:Horde"]="Operating out of Sun Rock Retreat, Horde forces work closely with Cenarion allies to contain the elemental unrest and push back the corruptive lingering aftermath of the Venture Company."},kw={"blackened ancient","bloodfury","charred vale","chimaera","fire elemental","stonetalon","sun rock retreat","venture company"},rel={"zone:stonetalon","subzone:sun-rock-retreat","topic:venture-company","quest:1083","quest:1084","quest:6381","quest:1844","topic:druid"},src={"Charred Vale"}}
E["subzone:cragpool-lake"] = {t="subzone",n="Cragpool Lake",z="stonetalon",s="Cragpool Lake is a body of water tucked inside Windshear Crag in the Stonetalon Mountains. Looming above its dark waters sits a massive timber structure erected by the Venture Company, while the depths below harbor a notoriously aggressive beast.",h="Cragpool Lake is a body of water tucked inside Windshear Crag in the Stonetalon Mountains.",sec={{t="Industrial Encroachment and Deadly Depths",b="Nestled deep within Windshear Crag, Cragpool Lake lies directly beneath the towering logging apparatus built by the Venture Company. An enormous wooden structure spans above the water, once serving as the prime vantage point from which Gerenzo Wrenchwhistle commanded clear-cutting operations across the mountain valley. While much of the syndicate has scaled back their presence in the crag, holdouts and sentries linger across the catwalks and platforms overhead. Down below, the lake has been declared strictly off-limits by the goblins due to the arrival of Cragjaw, a massive and predatory fish prowling the murky water beneath the gears.",sp=0}},faq={{q="What is the massive wooden structure hanging over the lake?",a="It is an industrial superstructure erected by the Venture Company to manage their extensive logging and mining efforts in Windshear Crag. It connects platforms and heavy machinery spanning directly over the lake.",al={"venture co platform","cragpool scaffolding","cragpool bridge"},it="place"},{q="Who oversees the operations at Cragpool Lake?",a="Gerenzo Wrenchwhistle, a key operative for the Venture Company, established his perch atop the high scaffolding to supervise the deforestation and resource extraction throughout Windshear Crag.",al={"who leads venture co here","who is the boss here","gerenzo wrenchwhistle"},it="in_charge"},{q="Why is swimming in Cragpool Lake dangerous?",a="The lake was declared off-limits due to Cragjaw, an enormous, aggressive predatory fish that took up residence in the waters beneath the goblin scaffolding, attacking anything foolish enough to enter.",al={"why off limits","lake monster","what is in cragpool lake","cragjaw"},it="danger"},{q="Has the Venture Company abandoned Cragpool Lake?",a="Although the bulk of the syndicate's broader force has withdrawn from parts of Windshear Crag, a stubborn contingent of armed overseers and operators remains firmly entrenched on the scaffolding above the water.",al={"is venture company gone","who lives at cragpool lake"},it="ruin"},{q="What is Cragpool Lake?",a="Cragpool Lake is a small body of water nestled within Windshear Crag in the Stonetalon Mountains. It is dominated by a sprawling, elevated wooden superstructure built across its waters by the Venture Company to support their logging and excavation machinery in the valley.",al={"what is cragpool lake","cragpool lake lore","cragpool lake stonetalon"},it="place",add=true},{q="What happened at Cragpool Lake?",a="Cragpool Lake once served as a primary operations hub for the Venture Company's clear-cutting efforts in Windshear Crag, with their supervisor Gerenzo Wrenchwhistle coordinating exploitation from the towering wooden scaffolding above. As operations dwindled and the company scaled back its presence across the crag, the lake itself fell into neglect and was condemned entirely when a monstrous predatory fish took over the waters.",al={"cragpool lake history","what happened at cragpool lake","cragpool lake past"},it="history",add=true}},ang={["profession:Engineering"]="The towering timber scaffolding and cantilevered machinery above Cragpool Lake offer a textbook display of goblin industrial expediency—built quickly, heavily loaded, and indifferent to natural terrain.",["class:Druid"]="The runoff, timber platforms, and disruption around Cragpool Lake stand as an ugly scar in Stonetalon, warping the local ecosystem and displacing its native wildlife."},kw={"cragjaw","cragpool lake","gerenzo wrenchwhistle","stonetalon","venture company","windshear crag"},rel={"subzone:windshear-crag","zone:stonetalon","quest:1096","topic:venture-company"},src={"Cragpool Lake"}}
E["subzone:greatwood-vale"] = {t="subzone",n="Greatwood Vale",z="stonetalon",s="Greatwood Vale is a forested valley nestled in the eastern foothills of the Stonetalon Mountains, reached via the perilous Webwinder Path. Recently, the hostile Grimtotem tribe seized the vale, using it as a staging ground for bloody assaults on neighboring settlements.",h="Greatwood Vale is a forested valley nestled in the eastern foothills of the Stonetalon Mountains, reached via...",sec={{t="A Contested Valley",b="Tucked away off the Webwinder Path, Greatwood Vale has become a violent frontier. The Grimtotem tribe, under the ruthless leadership of Grundig Darkcloud, has moved into the vale in force, cutting off safe passage and bringing terror to the surrounding foothills.",sp=0},{t="The Scourge of Camp Aparaje",b="The Grimtotem did not merely occupy Greatwood Vale; they used it to orchestrate the butchery of nearby Camp Aparaje. Sweeping out of the woods, Darkcloud's raiders slaughtered nearly every tauren inhabiting the encampment. Makaba Flathoof, one of the few survivors who managed to flee the carnage, now directs vengeful Horde warriors straight into the heart of Greatwood Vale to cut down the renegade Grimtotem and put an end to Grundig Darkcloud.",sp=0}},faq={{q="Who controls Greatwood Vale right now?",a="The valley is occupied by the hostile Grimtotem tribe, led locally by Grundig Darkcloud. They hold the woods with warbands and spellcasters, menacing anyone attempting to travel the region.",al={"who lives in greatwood vale","greatwood vale enemies","grimtotem in greatwood vale"},it="residents"},{q="What happened at Camp Aparaje?",a="The Grimtotem launched a surprise attack from Greatwood Vale upon Camp Aparaje, massacring most of its peaceful tauren residents. Makaba Flathoof survived the slaughter and now seeks vengeance against the raiders and their leader.",al={"camp aparaje lore","what happened to aparaje","why did grimtotem attack"},it="history"},{q="Why is the Horde fighting the Grimtotem here?",a="Although the Grimtotem are nominally part of the Horde through Thunder Bluff, their aggressive splinter factions attack fellow Horde members without hesitation. After the slaughter at Camp Aparaje, the Horde sanctions open warfare against Darkcloud's band in the vale.",al={"why kill grimtotem","makaba flathoof quest","avenge my village"},it="conflict"},{q="What is Greatwood Vale?",a="Greatwood Vale is a secluded, wooded valley nestled among the southeastern foothills of the Stonetalon Mountains. Connected to the lower crags by the Webwinder Path, it sits right along the frontlines of the region, positioned directly between the troll outpost of Malaka'jin to the south and human expeditionary forces to the north.",al={"greatwood vale","what is this place","stonetalon vale"},it="place",add=true},{q="Is Greatwood Vale dangerous?",a="Yes, Greatwood Vale is exceptionally hostile. Aside from venomous webwood spiders infesting the approach along the Webwinder Path, the valley has fallen into the hands of renegade Grimtotem tauren. Led by warlord Grundig Darkcloud, these raiders actively hunt down any outsiders who venture into the woods.",al={"greatwood vale danger","is it safe here","threats in greatwood vale"},it="danger",add=true}},ang={["race:Tauren"]="The Grimtotem's treacherous slaughter of fellow tauren at Camp Aparaje makes the cleansing of Greatwood Vale a deeply personal, sorrowful duty for Thunder Bluff's loyal children.",["faction:Horde"]="Securing Greatwood Vale is essential to protect the fragile southern outpost of Malaka'jin from sudden flank attacks by rogue Grimtotem."},kw={"camp aparaje","greatwood vale","grimtotem","grundig darkcloud","makaba flathoof","malaka'jin","stonetalon","webwinder path"},rel={"zone:stonetalon","subzone:camp-aparaje","npc:makaba-flathoof","quest:6548","quest:6629","topic:grimtotem-tribe","subzone:malaka-jin","subzone:webwinder-path"},src={"Greatwood Vale"}}
E["subzone:malaka-jin"] = {t="subzone",n="Malaka'jin",z="stonetalon",s="Malaka'jin is a small Horde encampment nestled in the lower hills of the Stonetalon Mountains, just south of the Grimtotem Post. Inhabited primarily by Darkspear troll hunters, the settlement serves as a rustic waystation and hunting outpost for travelers ascending into the rugged peaks from the Barrens.",h="Malaka'jin is a small Horde encampment nestled in the lower hills of the Stonetalon Mountains, just south of...",sec={{t="A Hunters' Refuge",b="Tucked away near the main path into the Stonetalon Mountains, Malaka'jin provides a welcome sanctuary for Horde wanderers venturing into contested heights. The village is home to a band of rugged troll hunters who eke out a living off the crags and scrublands. While living modestly, these hunters offer supplies, trade their fresh game to weary adventurers, and keep a wary eye on the hostile mountain wildlife and the belligerent Grimtotem tauren lurking further up the trails.",sp=0},{t="A Foothold in the Heights",b="Perched precariously near the boundary of the Barrens, Malaka'jin marks one of the earliest Horde presences established in Stonetalon. Though small and quiet compared to the major fortress at Sun Rock Retreat further north, it functions as a vital logistical anchor, allowing Horde trackers to monitor tribal unrest and secure the winding roads against encroaching threats.",sp=0}},faq={{q="What is Malaka'jin?",a="Malaka'jin is a small Horde village and outpost in the southern Stonetalon Mountains. It is inhabited by a community of Darkspear troll hunters who provide shelter, trade, and supplies to travelers climbing up from the Barrens.",al={"where is malakajin","what is this place","malakajin stonetalon"},it="place"},{q="Who lives in Malaka'jin?",a="The settlement is populated almost entirely by troll hunters. They sustain themselves by hunting the mountain game and trading meat and leather with passing adventurers.",al={"malakajin npcs","who is here","trolls in stonetalon"},it="residents"},{q="What threats face the camp?",a="Aside from fierce mountain predators, the village is situated directly south of the hostile Grimtotem Post, leaving the small troll camp constantly vigilant against aggression from the antagonistic tauren tribe.",al={"malakajin enemies","who attacks malakajin"},it="danger"},{q="Is there a flight master here?",a="No. In this era, Malaka'jin has no flight master. Adventurers traveling through the Stonetalon Mountains must rely on the flight master at Sun Rock Retreat further northwest or traverse the road on foot.",al={"malakajin flight path","fly to malakajin"},gp=true}},ang={["race:Troll"]="For Darkspear trolls, Malaka'jin is a proud demonstration of troll self-reliance and tracking prowess, carving out a home in the rugged heights far from Kalimdor's tropical shores.",["faction:Horde"]="Malaka'jin serves as the Horde's southernmost threshold in Stonetalon, offering a vital waystation on the trail between the Barrens and the northern mountain strongholds."},kw={"darkspear","grimtotem","horde","hunters","malaka'jin","outpost","stonetalon","trolls"},rel={"zone:stonetalon","topic:horde","topic:troll","topic:grimtotem-tribe"},src={"Malaka'jin"}}
E["subzone:mirkfallon-lake"] = {t="subzone",n="Mirkfallon Lake",z="stonetalon",s="Mirkfallon Lake sits in a central highland basin in the Stonetalon Mountains, nestled beneath the sheer cliffs of Windshear Crag. Its waters and surrounding banks teem with native wildlife, including aggressive slimes, roaming thunder lizards, and descending wyverns.",h="Mirkfallon Lake sits in a central highland basin in the Stonetalon Mountains, nestled beneath the sheer...",sec={{t="A Highland Basin",b="Positioned at the geographic center of the Stonetalon range, Mirkfallon Lake rests between the mountain passes leading south toward the Webwinder Path and north toward Cliffwalker Post and Stonetalon Peak. Fed by highland runoff, the lake offers a fertile oasis amidst the craggy peaks, drawing thunder lizards down to drink and wyverns from their roosts high above. The waters are also inhabited by strange, bubbling slimes, turning an otherwise serene mountain tarn into a hazardous crossing for lone travelers.",sp=0},{t="Crossroads of the Crag",b="Paths crisscross the lake basin in all directions. To the east, rocky tracks ascend into Windshear Crag and the logging operations running deep into the forested valleys. Travelers pressing north past the lake climb toward night elven sanctums and tauren heights, while those skirting south must contend with venomous spider hollows. As a result, the shores of Mirkfallon Lake often serve as an unpredictable crossing point for explorers and scouts navigating the contested mountains.",sp=0}},faq={{q="What creatures live around Mirkfallon Lake?",a="The lake and its shoreline are home to roaming thunder lizards, noxious ooze slimes in the shallow waters, and mountain wyverns that hunt around the surrounding basin and nest in the heights overhead.",al={"mirkfallon lake beasts","mirkfallon wildlife","what is at mirkfallon lake"},it="residents"},{q="Where does the lake lead?",a="Climbing north leads past Cliffwalker Post toward Stonetalon Peak. Heading south descends through Webwinder Path, while the rocky ascents to the east wind up into Windshear Crag.",al={"mirkfallon paths","where does mirkfallon go","mirkfallon lake directions"},it="place",gp=true},{q="Is Mirkfallon Lake safe to fish in?",a="The lake is rich with sagefish and floating salvage, making it tempting for anglers. However, aggressive beasts such as slimes and wyverns frequent the shoreline, making undisturbed fishing difficult.",al={"fishing mirkfallon lake","can i fish in mirkfallon"},it="danger",gp=true},{q="What is Mirkfallon Lake?",a="Mirkfallon Lake is a prominent body of water resting near the center of the Stonetalon Mountains. Nestled amid the crags and mountain trails connecting Stonetalon Peak to the surrounding peaks, the lake serves as a wild watering hole and basin in the heart of this rugged land.",al={"what is mirkfallon lake","mirkfallon lake overview","mirkfallon lake lore"},it="place",add=true},{q="Is Mirkfallon Lake dangerous?",a="Yes, travelers should stay on guard. The lake and its shores are inhabited by aggressive wildlife, including wandering thunder lizards, foul slimes crawling along the shallows, and wild wyverns that nest in the surrounding heights and descend to hunt.",al={"is mirkfallon lake safe","dangers of mirkfallon lake","mirkfallon lake monsters"},it="danger",add=true}},ang={["class:Druid"]="The wild beasts around Mirkfallon Lake represent the delicate balance of Stonetalon's wilderness, situated uncomfortably close to the encroaching mechanical axes in the crag above."},kw={"mirkfallon","mirkfallon lake","stonetalon lake","stonetalon thunder lizards","windshear lake"},rel={"zone:stonetalon","subzone:windshear-crag","subzone:webwinder-path","subzone:stonetalon-peak"},src={"Mirkfallon Lake"}}
E["subzone:sishir-canyon"] = {t="subzone",n="Sishir Canyon",z="stonetalon",s="Sishir Canyon is a rugged gorge in the Stonetalon Mountains, carving an eastward path through the craggy heights. Thickly swarmed by monstrous Deepmoss spiders and choked in webbing, it serves as the dangerous approach to the Ruins of Eldre'thar. Travelers who brave its tangled depths must contend with venomous arachnids and their brooding matriarch.",h="Sishir Canyon is a rugged gorge in the Stonetalon Mountains, carving an eastward path through the craggy...",sec={{t="The Webbed Pass",b="Branching off the mountain roads of the Stonetalon range, Sishir Canyon is a treacherous natural corridor cutting toward the ancient Ruins of Eldre'thar. Rather than a quiet mountain trail, the gorge has been thoroughly overrun by Deepmoss spiders. Their sticky silken sheets and clusters of egg sacs smother the stony ground and rock walls, transforming the ravine into a living nest. Travelers and sentinels seeking the night elven ruins beyond must cut their way through swarms of aggressive webspinners.",sp=0},{t="Besseleth's Domain",b="Lurking in the deepest recess of the canyon is Besseleth, the massive and deadly matriarch of the Deepmoss brood. Her venom and monstrous size make her a terror to anyone attempting to secure the pass. Local forces in Stonetalon keep a wary watch on the canyon, warning adventurers that venturing into the webbed recesses means facing not just scattered spiders, but an apex predator fiercely guarding her brood.",sp=0}},faq={{q="What is Sishir Canyon?",a="Sishir Canyon is a spider-infested gorge in the Stonetalon Mountains that winds from the main mountain paths toward the ancient Ruins of Eldre'thar.",al={"where is sishir canyon","sishir canyon location"},it="place"},{q="What creatures live in the canyon?",a="The canyon is thoroughly claimed by predatory Deepmoss spiders. The arachnids have coated the ravine in dense webbing and egg sacs, preying on anything that enters their territory.",al={"monsters in sishir canyon","spiders in stonetalon canyon"},it="residents"},{q="Who is Besseleth?",a="Besseleth is the formidable spider matriarch dwelling deep within Sishir Canyon. She leads the Deepmoss brood and poses the greatest threat to travelers passing through the area.",al={"besseleth location","giant spider sishir canyon"}},{q="Where does Sishir Canyon lead?",a="Following the canyon eastward leads directly out to the Ruins of Eldre'thar, an ancient night elven site tucked high in the mountains.",al={"what is at the end of sishir canyon","path through sishir canyon"}},{q="Is Sishir Canyon dangerous?",a="Sishir Canyon is extremely perilous for any traveler unprepared for arachnids. The ravine is entirely overrun by aggressive Deepmoss spiders that string thick webs across the rocky walls and guard clutches of eggs. Venturing too deeply puts you in path of their monstrous broodmother, Besseleth.",al={"sishir canyon danger","is sishir canyon safe","sishir canyon threats"},it="danger",add=true}},ang={["race:NightElf"]="The overrun canyon cuts off easy, safe passage to the ancestral Ruins of Eldre'thar, requiring Kaldorei sentinels and scholars to fight through dense spider nests to reach their heritage.",["class:Hunter"]="The dangerous webbing and venomous Deepmoss spiders make Sishir Canyon a demanding testing ground for hunters tracking and trapping wild beasts in tight ravine quarters."},kw={"besseleth","deepmoss","eldre'thar","sishir canyon","spiders","stonetalon","webbing"},rel={"zone:stonetalon"},src={"Sishir Canyon"}}
E["subzone:stonetalon-peak"] = {t="subzone",n="Stonetalon Peak",z="stonetalon",s="Stonetalon Peak is an ancient night elven sanctuary tucked into a verdant alpine valley at the northwestern edge of the Stonetalon Mountains. Sacred to the kaldorei and cared for by local druids, it serves as the primary bastion of the Alliance in these craggy heights.",h="Stonetalon Peak is an ancient night elven sanctuary tucked into a verdant alpine valley at the northwestern...",sec={{t="A Sacred Mountain Vale",b="Perched high above the arid dust of the lower ranges, Stonetalon Peak opens into a lush, mist-shrouded sanctuary. Long considered sacred and steeped in ancient magic, the valley holds ruins dating back millennia to when the region housed temples honoring Queen Azshara before the Great Sundering. In the modern era, kaldorei Sentinels and druids have restored a measure of peaceful stewardship here, maintaining a tranquil refuge complete with a barrow den and a vital Alliance flight roost.",sp=0},{t="Crossroads of Destiny",b="Beyond its idyllic forests and ancient ruins, Stonetalon Peak holds historic weight from the Third War. Guided by the visions of Medivh, both Jaina Proudmoore's human expedition and Thrall's Horde scaled these perilous heights in search of the elusive Oracle dwelling within the mountain's deep caverns. That fateful encounter forced mortal enemies to set aside their blades, laying the foundation for the uneasy pact that stood against the Burning Legion at Mount Hyjal. Today, the peak remains firmly under Sentinel watch, though Horde incursions in the lowlands keep the defenders vigilant.",sp=0}},faq={{q="Why is Stonetalon Peak so green compared to the rest of the mountains?",a="Stonetalon Peak rests within a sheltered high-altitude basin suffused with ancient magic. The dedicated care of the night elves and the druids of the nearby Talon Den has preserved a vibrant, forested sanctuary where vegetation flourishes in sharp contrast to the charred, jagged cliffs below.",al={"why is stonetalon peak green","why forest in stonetalon peak","stonetalon peak weather"}},{q="What happened here during the Third War?",a="Led by the Prophet Medivh's prophetic warnings, both Jaina Proudmoore and Thrall traveled to Stonetalon Peak in search of the Oracle within the mountain's caverns. Their meeting deep inside the stone led them to forge a historic truce, uniting humans and orcs to confront the Burning Legion.",al={"what happened at stonetalon peak warcraft 3","jaina and thrall stonetalon","the oracle stonetalon"},it="history"},{q="Who controls Stonetalon Peak right now?",a="The peak is an Alliance outpost, protected and maintained by night elf Sentinels and druids. It serves as the primary safe haven, quest hub, and flight master connection for Alliance adventurers operating in the Stonetalon Mountains.",al={"is stonetalon peak alliance or horde","who lives at stonetalon peak","stonetalon peak faction"},it="residents"},{q="What ancient ruins are located here?",a="The crumbling pillars and marble structures scattered through the vale are remnants of the ancient night elven empire, having once served as temple grounds dedicated to Queen Azshara before her descent into madness and the Great Sundering.",al={"stonetalon peak ruins","old temple stonetalon","azshara temple stonetalon peak"}},{q="What is Stonetalon Peak?",a="Stonetalon Peak is a verdant mountain valley and night elven settlement nestled at the far northwestern end of the Stonetalon Mountains. Sacred to local cultures and suffused with ancient magic, this lush sanctuary stands in stark contrast to the barren crags below. It serves as a vital northern bastion for the night elves and their Alliance allies in central Kalimdor.",al={"what is stonetalon peak","stonetalon peak overview","about stonetalon peak"},it="place",add=true},{q="Is Stonetalon Peak dangerous?",a="While the grove itself is a fortified haven for the Alliance, the surrounding peaks harbor severe perils. Aggressive harpies roost in the crags, hostile Venture Company loggers despoil the nearby forests, and the Horde contests the mountain passes. Travelers climbing toward the peak must remain constantly vigilant against ambushes along the narrow trails.",al={"is stonetalon peak safe","threats in stonetalon peak","stonetalon peak dangers"},it="danger",add=true}},ang={["faction:Alliance"]="Stonetalon Peak is your sole fortified foothold in the western mountains, offering vital respite, flight paths, and questing aid amidst hostile territory.",["class:Druid"]="The sanctuary is deeply intertwined with Cenarion history and the sacred Talon Den, making it an essential place of pilgrimage and defense for wardens of the wild."},kw={"jaina","kaldorei","night elf","oracle","sentinels","stonetalon","stonetalon peak","talon den","thrall"},rel={"zone:stonetalon","topic:night-elf","topic:sentinels","topic:druid","topic:third-war","npc:thrall","npc:jaina-proudmoore","quest:1088"},src={"Stonetalon Peak"}}
E["subzone:sun-rock-retreat"] = {t="subzone",n="Sun Rock Retreat",z="stonetalon",s="Sun Rock Retreat is a hidden Horde sanctuary nestled high within the central peaks of the Stonetalon Mountains, just south of Mirkfallon Lake. Dominated by tauren and orcish forces, it serves as the Horde's primary staging ground and supply post in the region. Beyond its strategic utility, the settlement rests upon sacred ground long revered by the tauren for its deep spiritual resonance.",h="Sun Rock Retreat is a hidden Horde sanctuary nestled high within the central peaks of the Stonetalon...",sec={{t="A Sacred Haven in the Peaks",b="Tucked away in a mountain basin south of Mirkfallon Lake, Sun Rock Retreat has long held spiritual importance for the tauren. According to ancient tradition, An'she, the Sun, kissed the very mountain peak where the village stands. For generations before the Horde's arrival, tauren shamans and pilgrims journeyed here to perform rituals bridging the mortal veil, drawing strength from the land's strong bond to the spirit world.",sp=0},{t="Frontier Outpost",b="Today, Sun Rock Retreat serves as the Horde's principal base of operations across the Stonetalon Mountains. Orcs and tauren work side by side to establish a secure foothold against hostile harpy broods, local night elf sentinels, and the industrial pillaging of the Venture Company. As a central hub connecting trade and flight routes between Thunder Bluff, the Crossroads, and the borders of Ashenvale, the retreat provides shelter, provisions, and spiritual guidance to those braving the crags.",sp=0}},faq={{q="What is Sun Rock Retreat?",a="Sun Rock Retreat is the primary Horde outpost in the Stonetalon Mountains. Inhabited mainly by tauren and orcs, it acts as a peaceful sanctuary, trading station, and command post for Horde champions working in the region.",al={"what is sun rock","sun rock retreat info","who runs sun rock retreat"},it="place"},{q="Why is this place sacred to the tauren?",a="Tauren legend holds that An'she, the Sun, touched the mountain where the retreat now stands. The land has an enduring connection to the spirit world, making it an ancient pilgrimage site for vision quests and communion with ancestors.",al={"why is sun rock sacred","anshe stonetalon","tauren sun rock lore"},it="origin"},{q="What threats does the retreat face?",a="The retreat contends with aggressive territorial harpies, hostile night elves guarding the sacred woods, and the destructive mining and logging efforts of the Venture Company, which ravages the natural landscape.",al={"sun rock threats","who is attacking sun rock","stonetalon enemies"},it="threat"},{q="Where does the local flight master connect?",a="Sun Rock Retreat provides wind rider service connecting travelers directly to major central Kalimdor locations, including the Crossroads in the Barrens and the tauren capital of Thunder Bluff.",al={"sun rock flight paths","flying to sun rock retreat","sun rock flight master"},gp=true},{q="What happened at Sun Rock Retreat in the past?",a="For generations, Sun Rock Retreat served as a sacred destination for tauren pilgrims. Because of the land's deep and enduring connection to the spirit realm, travelers came from across the plains to conduct solemn rituals that allowed them to cross over into the world of the spirits. In recent times, the Horde established a permanent presence here, turning the secluded haven into an active base dedicated to protecting the mountains from environmental devastation.",al={"sun rock retreat history","past of sun rock retreat","history of sun rock retreat"},it="history",add=true},{q="Who lives in Sun Rock Retreat?",a="Sun Rock Retreat is populated by a dedicated contingent of Horde forces, predominantly tauren and orcs. Alongside the spiritual shamans and druids who honor the sanctified grounds, warriors and laborers work together to heal the scars carved into the Stonetalon peaks by reckless exploiters like the Venture Company.",al={"who lives in sun rock retreat","sun rock retreat residents","who runs sun rock retreat"},it="residents",add=true},{q="Is Sun Rock Retreat dangerous?",a="The retreat itself is a secure haven guarded by vigilant Horde defenders, offering safety to travelers and pilgrims. However, the wilderness surrounding it is perilous. Aggressive beasts, territorial harpies, and the destructive mercenaries of the Venture Company infest the nearby crags and ravines, meaning you should remain watchful the moment you leave the camp's borders.",al={"is sun rock retreat safe","how dangerous is sun rock retreat","sun rock retreat danger"},it="danger",add=true},{q="Why is it called Sun Rock Retreat?",a="The settlement draws its name from ancient tauren mythology. According to their legends, An'she—the sun in tauren belief—once leaned down and personally kissed the mountain peak where the village now rests, blessing the stone and infusing the area with divine warmth and spiritual power.",al={"why is it called sun rock","sun rock retreat name origin","meaning of sun rock retreat"},it="name",add=true}},ang={["race:Tauren"]="Sun Rock Retreat is more than an outpost to the shu'halo; it is sacred ground blessed by An'she, where shamans have walked the spirit realm for centuries.",["faction:Horde"]="As the Horde's main staging hub in the Stonetalon Mountains, Sun Rock Retreat offers a vital resupply post and flight hub amidst contested peaks."},kw={"an'she","mirkfallon lake","stonetalon mountains","sun rock retreat","sunrock","tauren","venture company"},rel={"zone:stonetalon","zone:thunderbluff","subzone:crossroads","topic:tauren","topic:horde","topic:venture-company","subzone:mirkfallon-lake","zone:ashenvale"},src={"Sun Rock Retreat"}}
E["subzone:talondeep-path"] = {t="subzone",n="Talondeep Path",z="stonetalon",s="Talondeep Path is a winding underground tunnel boring through the mountain ridge between Ashenvale and the Stonetalon Mountains. Devoid of hostile creatures or travelers, it serves as a tranquil, natural subterranean passage connecting Mystral Lake to Windshear Crag.",h="Talondeep Path is a winding underground tunnel boring through the mountain ridge between Ashenvale and the...",sec={{t="A Quiet Mountain Pass",b="Hidden beneath the rugged ridgeline separating Ashenvale and the Stonetalon Mountains lies Talondeep Path, a quiet subterranean route. The passage links the forests just west of Mystral Lake directly to the northwestern reaches of Windshear Crag. Unlike the dangerous surface trails haunted by predators and warring factions, the tunnel interior remains eerily calm, free of hostile beasts or encampments, though riddled with twisting side pockets, crevices, and natural alcoves in the rock. Above ground, faint remnants of an ancient surface road still linger, hinting that travelers once scaled the high peaks before this sheltered cave became the preferred route through the stone.",sp=0}},faq={{q="Where does the Talondeep Path lead?",a="The tunnel connects southwestern Ashenvale to northeastern Stonetalon Mountains. Its northern entrance sits just west of Mystral Lake, while its southern mouth opens into the northwestern side of Windshear Crag.",al={"where does talondeep path go","talondeep path connections","talondeep tunnel exits"},it="purpose"},{q="Are there monsters or enemies inside the tunnel?",a="No. The interior of the cavern is uniquely peaceful and completely barren of hostile monsters, beasts, or friendly NPCs, making it a safe passageway for travelers traversing the mountain divide.",al={"is talondeep path safe","talondeep path mobs","talondeep path threats"},it="danger"},{q="What are the ruins above the cavern?",a="Remnants of an overgrown surface road run along the mountain ridge directly above the cavern. It suggests an older, treacherous overland route across the crags predated the passage through the hollowed interior.",al={"road above talondeep path","overland path stonetalon"}},{q="Is Talondeep Path an Alliance or Horde tunnel?",a="Neither faction holds the tunnel. It is entirely unfortified and neutral wilderness, allowing safe foot passage for travelers of any allegiance moving between the contested forest and the mountains.",al={"who controls talondeep path","talondeep path faction"},it="side"},{q="What is Talondeep Path?",a="Talondeep Path is a winding underground tunnel carved straight through the peaks, providing a crucial shortcut between the lush forests of Ashenvale and the rugged heights of the Stonetalon Mountains. Entering from the west of Mystral Lake in Ashenvale, travelers emerge near the northwestern reaches of Windshear Crag in Stonetalon. Inside, the cavern branches into curious nooks and dead ends, yet remains one of the quietest mountain crossings in Kalimdor.",al={"what is talondeep path","talondeep path tunnel","about talondeep path"},it="place",add=true}},ang={["profession:Mining"]="The cavern's winding rock alcoves cut straight through the deep stone foundation of the mountain range, making it a natural landmark when navigating between mineral-rich Ashenvale and Stonetalon."},kw={"ashenvale","cave","mystral lake","stonetalon","talondeep","talondeep path","tunnel","windshear crag"},rel={"zone:stonetalon","zone:ashenvale","subzone:windshear-crag","subzone:mystral-lake"},src={"Talondeep Path"}}
E["subzone:webwinder-path"] = {t="subzone",n="Webwinder Path",z="stonetalon",s="Webwinder Path is a winding mountainous road in the Stonetalon Mountains connecting the troll outpost of Malaka'jin to Mirkfallon Lake. It cuts through rugged crags and dense highland woods inhabited by aggressive arachnids and native beasts.",h="Webwinder Path is a winding mountainous road in the Stonetalon Mountains connecting the troll outpost of...",sec={{t="A Treacherous Thoroughfare",b="Running from the Horde settlement of Malaka'jin toward Mirkfallon Lake, Webwinder Path serves as one of the primary roadways carving through the lower Stonetalon Mountains. True to its name, the route is notorious for the thick cobwebs strung high among the canopy and jagged cliff sides. Travelers along this winding stretch must constantly watch their step, sharing the beaten path with prowling mountain spiders, aggressive thunder lizards, and territorial rams.",sp=0}},faq={{q="Where does Webwinder Path lead?",a="Webwinder Path stretches between the Darkspear troll outpost of Malaka'jin in the south and Mirkfallon Lake further up the mountain to the north.",al={"webwinder path location","where is webwinder path","what does webwinder path connect"},it="place"},{q="Why is it called Webwinder Path?",a="The road earns its name from the sheer abundance of arachnids inhabiting the region. Spiders spin vast labyrinths of glittering silk high in the trees and along rocky ledges flanking the roadway.",al={"why webwinder","why is it called webwinder"},it="name"},{q="What creatures wander the path?",a="Aside from the venomous spiders that weave webs above the road, travelers frequently encounter roaming thunder lizards, highland rams, and ordinary mountain critters.",al={"what lives here","webwinder path beasts","mobs on webwinder path"},it="threat"},{q="Is Webwinder Path safe to travel?",a="It is far from safe. The local predators are fierce and territorial, and the road passes directly past the Horde camp at Malaka'jin, making it perilous for Alliance wayfarers venturing up from the Barrens.",al={"is webwinder path dangerous","can alliance travel webwinder path"},it="danger"},{q="What is Webwinder Path?",a="Webwinder Path is a winding mountainous road in Stonetalon Mountains, cutting a critical route from the troll outpost of Malaka'jin toward Mirkfallon Lake. Running through craggy peaks and web-draped canopies, it serves as a vital thoroughfare for travelers journeying deeper into the range, bordered by rugged wilderness and aggressive native beasts.",al={"what is webwinder path","webwinder path lore","webwinder path stonetalon"},it="place",add=true}},ang={["faction:Horde"]="The path is a crucial overland artery right on the doorstep of Malaka'jin, connecting your scouts to the deeper valleys of Stonetalon.",["class:Hunter"]="The path is home to robust thunder lizards, sturdy mountain rams, and venomous web-spinners, making it an excellent trail for scouting and taming Stonetalon beasts."},kw={"malaka'jin","mirkfallon lake","road","spiders","stonetalon","webwinder","webwinder path"},rel={"subzone:malaka-jin","subzone:mirkfallon-lake","zone:stonetalon","topic:horde","topic:alliance"},src={"Webwinder Path"}}
E["subzone:windshear-crag"] = {t="subzone",n="Windshear Crag",z="stonetalon",s="Windshear Crag is a heavily despoiled valley in the central Stonetalon Mountains, stripped of its ancient timber by the Venture Company. Once a lush forest, the region is now an industrial wasteland dominated by whirring shredders, murky runoff, and aggressive logging crews. In the shadows of the machinery, local kobolds burrow for ore while mountain passes connect the scarred landscape to Ashenvale.",h="Windshear Crag is a heavily despoiled valley in the central Stonetalon Mountains, stripped of its ancient...",sec={{t="Industrial Devastation",b="Not long ago, Windshear Crag was a thick, old-growth woodland flanking the slopes of Stonetalon. That tranquil wilderness vanished when the Venture Company arrived in search of profit. Today, the basin is filled with severed stumps, acrid smog, and clanking machinery. The entire logging enterprise is overseen by Gerenzo Wrenchwhistle, a leper gnome whose engineering genius produced the Super Reaper 6000—a mechanical terror capable of reducing massive trunks to kindling in moments. From an elevated platform above the polluted Cragpool Lake, Gerenzo directs an unchecked operation that strips the mountain bare, earning the hostility of rival engineers and local inhabitants alike.",sp=0},{t="Mines and Mountain Passes",b="Beyond the active timberyards, Windshear Crag holds other hazards and crossroads. To the southeast lies Windshear Mine, where territorial kobolds dig through the rock for Smoky Iron Ingots, fiercely attacking anyone who nears their haul. In the crag's northeast reaches, travelers can find the Talondeep Path, an underground cavern tunnel threading straight beneath the ridges into Ashenvale. Stationed near this shadowed portal stands the tauren elder Braug Dimspirit, who tests the historical wisdom and resolve of Horde wayfarers venturing through the contested peaks.",sp=0}},faq={{q="Who is running the logging operation here?",a="The logging venture is commanded on-site by Gerenzo Wrenchwhistle, a brilliant but contaminated leper gnome engineer. Operating under contract with the Venture Company, he watches over the crag from a timber platform raised directly over Cragpool Lake.",al={"who leads venture co here","who is the boss of windshear","gerenzo wrenchwhistle lore"},it="in_charge"},{q="What is the Super Reaper 6000?",a="The Super Reaper 6000 is an advanced mechanical logging prototype engineered by Gerenzo Wrenchwhistle. Designed to clear timber at unprecedented speeds, it can grind ancient mountain trees into sawdust within moments, accelerating the company's clear-cutting.",al={"super reaper 6000","what is the big shredder","venture co reaper"},it="item"},{q="Why is the Undermine Tinkers' Union targeting Gerenzo?",a="Director Riddlevox of the Tinkers' Union in Undermine wants Gerenzo dead, and the goblin Ziz Fizziks, who already helped steal the Super Reaper 6000 blueprints, puts out the order. The trade princes of Undermine disapprove of the Venture Company consorting with the gnome.",al={"why kill gerenzo","ziz fizziks motives","tinkers union vendetta"},it="conflict"},{q="Where does the cave in the northeast lead?",a="The cave in the northeast corner is the Talondeep Path. It cuts through the subterranean roots of the mountains, providing a foot route between Windshear Crag and the dense forests of Ashenvale.",al={"talondeep path destination","windshear cave exit","tunnel in windshear crag"},it="place"},{q="Who are the kobolds digging in the southeast?",a="The Windshear kobolds have overrun the local mine in the southeastern corner of the crag. They vigorously defend their subterranean claim, excavating deposits of Smoky Iron Ingots used by regional smiths.",al={"windshear mine kobolds","why are kobolds here","smoky iron ingots"},it="residents"},{q="What is Windshear Crag?",a="Windshear Crag is a deep valley in the Stonetalon Mountains, once famed for its towering, ancient forest. Today, relentless clear-cutting has turned the green woodlands into a scarred landscape of jagged tree stumps, churning mud, and noxious run-off.",al={"what is this place","windshear crag lore","windshear crag stonetalon"},it="place",add=true},{q="What happened to Windshear Crag?",a="In the years following the Third War, the Venture Company moved into the valley with heavy industrial machinery. Led by the leper gnome Gerenzo Wrenchwhistle, their destructive logging operations and massive shredders have virtually wiped out the old-growth timber, polluting the local waters and stripping the crag bare for timber and profit.",al={"history of windshear crag","why is windshear crag deforested","what happened here"},it="history",add=true},{q="Is Windshear Crag dangerous?",a="Very dangerous. The Venture Company employs aggressive loggers, mechanics, and merciless shredders that attack anyone intruding on their claim. To the southeast, hostile kobolds defend the Windshear Mine, making the entire basin hostile to wandering travelers.",al={"is windshear crag safe","threats in windshear crag","windshear crag dangers"},it="danger",add=true}},ang={["profession:Engineering"]="The industrial equipment throughout the crag showcases cutthroat goblin trade secrets and Gerenzo Wrenchwhistle's lethal Super Reaper designs.",["faction:Horde"]="Horde travelers heading toward Ashenvale encounter Braug Dimspirit near the Talondeep Path, where he tests their knowledge of Kalimdor's history."},kw={"braug dimspirit","cragpool lake","gerenzo wrenchwhistle","super reaper 6000","talondeep path","venture company","windshear crag","windshear mine","ziz fizziks"},rel={"zone:stonetalon","topic:venture-company","subzone:cragpool-lake","subzone:talondeep-path","quest:1096","quest:1093","quest:1483","quest:1152"},src={"Windshear Crag"}}
E["zone:stonetalon"] = {t="zone",n="Stonetalon Mountains",z="stonetalon",s="The Stonetalon Mountains are a rugged, wind-carved chain of craggy peaks bordering Ashenvale, the Barrens, and Desolace. Revered by both the night elves and the tauren as a sacred sanctuary, the region's sacred heights stand in sharp contrast to the smoke and machinery choking its lower canyons. Today, the mountains are torn by deforestation, volatile elemental devastation, and simmering border hostilities.",h="The Stonetalon Mountains are a rugged, wind-carved chain of craggy peaks bordering Ashenvale, the Barrens...",sec={{t="The Ill Winds and the Peaks",b="Rising sharply out of central Kalimdor, the Stonetalon range catches the moisture drifting from the western seas, giving birth to sudden downpours and treacherous, rain-slick sandstone trails. The dominant feature of the lower valleys is the incessant scouring gale known as the Ill Winds, capable of blinding travelers with grit or throwing the careless straight off sheer cliffsides. Higher up, evergreen forests mantle the ridges surrounding Stonetalon Peak, where the night elves tend ancestral barrows and glades, watching over the sacred roosts of wyverns and hippogryphs that nest along Mirkfallon Lake.",sp=0},{t="Industry and Intrusion",b="The peaceful solitude of the range has been violently disrupted by the arrival of the Venture Company. Setting up sprawling logging camps and digging deep strip mines in Windshear Crag, the goblins—aided by the deranged leper gnome Gerenzo Wrenchwhistle—have clear-cut old-growth timber, blackened the skies with furnace smoke, and poured industrial sludge into the mountain runoff. Their greed has provoked swift retaliation: local shamans from Orgrimmar answered the agonized cries of the mountain spirits, while small Alliance camps stationed nearby fight back against the defilers to protect what remains of the highlands.",sp=0},{t="Scars of the Past",b="To the south lies the Charred Vale, once a blossoming wilderness, now reduced to an ash-covered wasteland churning with rogue fire elementals, black dragonspawn, and harpies. While the peaks were the historic site where the Horde and Alliance forged an uneasy truce during the Third War under the guidance of the mysterious Oracle, current relations are fraying. Renegade Grimtotem tauren operate out of seized encampments, and Darkspear trolls in Malaka'jin clash with Alliance incursions pushing outward from the Barrens and Ashenvale.",sp=0}},faq={{q="How do I get to the Stonetalon Mountains?",a="Most travelers enter via the Talondeep Pass, a mountain trail cutting into the range from southwestern Ashenvale. There are also high trails leading south into Desolace and routes descending eastward directly into the northern expanses of the Barrens.",al={"stonetalon entrance","how to get to stonetalon","stonetalon road"},it="arrival",gp=true},{q="Why is the Charred Vale burned and ruined?",a="The Charred Vale was once a lush haven, but cataclysmic devastation consumed the valley in flames. It has been reduced to a smoldering ruin crawling with aggressive fire elementals, rogue drakes, and deadly harpies.",al={"charred vale fire","what happened to charred vale","why charred vale burnt"},it="ruin"},{q="What is the Venture Company doing in Windshear Crag?",a="The Venture Company is ruthlessly clear-cutting timber and drilling deep into the mountainside for mineral wealth. Their operations have fouled Cragpool Lake with engine grease, stripped the valleys bare, and enraged the local spirits and native inhabitants.",al={"venture co stonetalon","windshear crag goblins","why are goblins cutting trees"},it="threat"},{q="Where are the main flight masters located?",a="Alliance heroes use the flight master perched at the high sanctuary of Stonetalon Peak in the north, while Horde adventurers base themselves in the central mountain village of Sun Rock Retreat.",al={"stonetalon flight path","where is flight point stonetalon","stonetalon fp"},gp=true},{q="What happened at Stonetalon Peak during the Third War?",a="Guided by visions of the Prophet Medivh, Thrall and Jaina Proudmoore climbed the caverns of Stonetalon Peak in search of the Oracle. There, the two faction leaders forged the historic temporary alliance that united against the Burning Legion at Mount Hyjal.",al={"stonetalon peak lore","the oracle stonetalon","third war stonetalon"},it="history"},{q="Who are the Grimtotem in Stonetalon?",a="The Grimtotem are a ruthless, renegade tauren tribe hostile to outsider influence. In the Stonetalons, they have occupied a mountain post near the border of the Barrens, terrorizing local travelers and taking prisoners.",al={"grimtotem post","grimtotem stonetalon"},it="threat"},{q="What is Stonetalon Mountains?",a="The Stonetalon Mountains are a rugged, wind-carved range in central Kalimdor, situated west of the Barrens, south of Ashenvale, and north of Desolace. Known for extreme winds, deep chasms, and sheer sandstone peaks created during the Great Sundering, the region forms a historical borderland where night elves and tauren have coexisted for generations. Its high, sacred summits remain lush with evergreens, while lower valleys are dry, rocky, and heavily scarred by industry.",al={"stonetalon mountains zone","what is stonetalon","about stonetalon mountains"},it="place",add=true,nx={9}},{q="Is Stonetalon Mountains dangerous?",a="Yes, travelers face both natural perils and fierce hostiles. Violent gales and sudden rain can make the high sandstone cliffs slick enough to send people tumbling to their deaths. Beyond the weather, the mountains crawl with aggressive Bloodfury harpies, predatory wyverns, spiders, kobolds, and enraged elementals. Furthermore, the ruthless machinery and armed enforcers of the Venture Company make contested valleys like Windshear Crag exceptionally perilous.",al={"stonetalon danger","is stonetalon safe","hazards of stonetalon"},it="danger",add=true},{q="Who lives in Stonetalon Mountains?",a="The region is home to scattered factions rather than a single governing power. The night elves hold Stonetalon Peak and guard sacred sites across the heights, while the Horde maintains settlements at Sun Rock Retreat and the troll village of Malaka'jin. Native Bloodfury harpies roost in the crags, hostile Grimtotem tauren occupy nearby posts, and the goblin-run Venture Company occupies deforested tracts around Windshear Crag.",al={"who lives in stonetalon","stonetalon factions","inhabitants of stonetalon"},it="residents",add=true},{q="Why is the Venture Company logging in Windshear Crag?",a="The Venture Company is a ruthless merchant conglomerate seeking profit through unconstrained resource stripping. In Windshear Crag, they clear-cut ancient forests using heavy machinery like the Super Reaper 6000 and blast the earth for precious ore. Their disregard for nature fills the air with soot and poisons local waters with sludge and oil, earning the furious opposition of both local druids and the Horde.",al={"venture company logging","why are goblins cutting trees","venture co lumber stonetalon"},it="threat",add=true,nx={11}},{q="Who runs the Venture Company in Windshear Crag?",a="The local logging and mining operations in Windshear Crag are directed by a leper gnome named Gerenzo Wrenchwhistle. Overseeing the clear-cutting from a platform built high above Cragpool Lake, Gerenzo employs his mechanical expertise to maximize destruction. His rogue operations have even drawn the ire of rival goblin inventors from the Tinkers' Union, who seek to eliminate him.",al={"who runs windshear crag","gerenzo wrenchwhistle","venture company leader stonetalon"},it="leader",add=true},{q="Who are the Bloodfury harpies?",a="The Bloodfury harpies are a vicious tribe of bird-women native to the Stonetalon Mountains. Historically, these mountains were their ancestral heartland before they spread into the Barrens and beyond. They aggressively defend their territory from outsiders, capturing local beasts and clashing violently with both tauren pilgrims and encroaching goblin machines in places like the Charred Vale.",al={"bloodfury harpies","stonetalon harpies","who are the harpies here"},it="threat",add=true},{q="What is Sun Rock Retreat?",a="Sun Rock Retreat is a peaceful Horde settlement nestled in a secluded mountain valley south of Mirkfallon Lake. It serves as the primary base for tauren and orcs in the region, housing shamans and druids dedicated to restoring the land from Venture Company pollution and combating the threats encroaching upon the sacred mountains.",al={"sun rock retreat lore","what is sunrock retreat","sun rock tauren"},it="place",add=true,nx={14}},{q="Why did the tauren settle Sun Rock Retreat?",a="For generations, the tauren have revered this valley as a place with a profound connection to the spirit realm. Ancient legends say the sun god An'she kissed the peak upon which the retreat stands. Tauren long made sacred pilgrimages here to commune with spirits and light great ritual bonfires to illuminate the shadowed mountains.",al={"why tauren settle sun rock","history of sun rock retreat","an'she sun rock"},it="history",add=true},{q="What is Windshear Crag?",a="Windshear Crag was once a verdant old-growth forest, but it has been devastated by industrial exploitation. The Venture Company clear-cut the valley into a barren sprawl of stumps, dirt, and smoking machinery. Between the Venture Company's deforestation, foul runoff in Cragpool Lake, and kobolds infesting the local mine, it stands as a ruined monument to unchecked greed.",al={"about windshear crag","windshear crag zone","windshear crag lore"},it="place",add=true,nx={16}},{q="What is in Windshear Mine?",a="Windshear Mine, located in the southeastern cliffs of Windshear Crag, is overrun by aggressive Windshear kobolds. Driven out or abandoned by regular miners, the kobolds now furiously excavate veins of Smoky Iron Ingots, fiercely attacking anyone who attempts to intrude on their subterranean diggings.",al={"windshear mine kobolds","what is in windshear mine","windshear mine smoky iron"},it="threat",add=true},{q="What is the Talon Den on Stonetalon Peak?",a="The Talon Den is an ancient night elven barrow den carved into the heights of Stonetalon Peak. It is maintained by Cenarion druids who commune with the spirits of nature and the Emerald Dream. Deep within, druids have traditionally slept in sacred contemplation, guarded by dryads, keepers, and the peak's magical protections.",al={"talon den","the den stonetalon peak","barrow den stonetalon"},it="place",add=true},{q="Does Ashenvale connect to Stonetalon Mountains?",a="Yes. The rugged Talondeep Path directly connects southwestern Ashenvale to northeastern Stonetalon Mountains through a cavernous mountain passage. Travelers and adventurers frequently pass between the pristine, contested forests of Ashenvale and the barren heights of Stonetalon while tracking threats from the Venture Company or the ongoing faction conflicts.",al={"how does ashenvale connect to stonetalon","talondeep path ashenvale","ashenvale border stonetalon"},it="ties",add=true},{q="How did I end up in Stonetalon Mountains?",a="Most travelers reach these jagged heights through the Talondeep Path, an ancient mountain tunnel carved into southwestern Ashenvale. Other wanderers climb up along the rugged trails leading west out of the Barrens, ascending the windswept passes into the rocky crags. Whether sent south by night elven commanders in Astranaar or dispatched west across the scorched border from the Crossroads, the high canyons and howling Ill Winds greet anyone making the arduous trek into the range.",al={"how did i get here","how do i get to stonetalon","arrival in stonetalon"},it="arrival",add=true},{q="What am I supposed to be doing in Stonetalon Mountains?",a="You are here to confront the mounting threats despoiling these sacred heights. At Windshear Crag, the ruthless goblins of the Venture Company tear down ancient forests and pollute the rivers with machinery, drawing the wrath of both factions. Meanwhile, the Grimtotem tribe causes strife along the eastern border, while vicious harpies and raging fire elementals infest the scorched basin of the Charred Vale. You must assist your allies in driving back these polluters and monsters to safeguard the land.",al={"what should i do here","why am i here","what is my mission in stonetalon"},it="purpose",add=true}},ang={["faction:Horde"]="Horde adventurers rely on the secluded refuge of Sun Rock Retreat and the southern troll post of Malaka'jin to curb Venture Company industrial pollution and root out treacherous Grimtotem outlaws.",["faction:Alliance"]="Stationed high atop Stonetalon Peak and in hidden camps around Windshear Crag, the Alliance defends ancient kaldorei barrows from goblin machines and encroaching territorial rivals.",["class:Druid"]="The desecration of Windshear Crag and the scorched corruption of the Charred Vale serve as a grave summons for druids seeking to soothe enraged nature spirits and protect sacred roosts.",["class:Shaman"]="The cry of the mountain spirits under assault by goblin drills can be heard as far as Orgrimmar, calling shamans to quell rampaging rock elementals and restore balance to the peaks."},kw={"charred vale","gerenzo wrenchwhistle","malaka'jin","stonetalon","stonetalon peak","sun rock retreat","talondeep pass","windshear"},rel={"subzone:stonetalon-peak","subzone:sun-rock-retreat","subzone:windshear-crag","subzone:charred-vale","subzone:malaka-jin","zone:ashenvale","zone:barrens","zone:desolace"},m={levels="15-27"},src={"Stonetalon Mountains (Classic)","Stonetalon Mountains"}}
